// FRESH INSTALL GUARD — Hapus config Firebase saat install baru
// Setiap pembeli wajib isi Firebase config sendiri
// ===========================================================
;(function(){
  const APP_INSTANCE_ID = "ASTROPHILE_V24_BUILD_001"  // ganti setiap rilis baru
  const savedId = localStorage.getItem("_app_instance_id")

  if(savedId !== APP_INSTANCE_ID){
    // Install baru atau versi berbeda — hapus semua config sensitif
    const keysToReset = [
      "integrasi_firebase_config",  // config Firebase pembeli sebelumnya
      "integrasi_fonnte_token"       // token WhatsApp pembeli sebelumnya
      // _cached_users, ps_owner_pin dll TIDAK direset
      // agar PIN default 9999 tetap bisa login
    ]
    keysToReset.forEach(k => localStorage.removeItem(k))
    localStorage.setItem("_app_instance_id", APP_INSTANCE_ID)
    console.log("[Astrophile] Fresh install terdeteksi — config direset")
  }
})()

