// ============================================================
// LOADING SCREEN CONTROLLER
// ============================================================
;(function(){
  let _pct = 0

  function setBar(pct, text){
    const bar = document.getElementById('loadProgressBar')
    const txt = document.getElementById('loadStatusText')
    if(bar){
      // Smooth CSS transition
      bar.style.transition = 'width 0.8s cubic-bezier(0.25,0.46,0.45,0.94)'
      bar.style.width = pct + '%'
    }
    if(txt && text) txt.textContent = text
    _pct = pct
  }

  // Text milestones
  const milestones = [
    [3,  'INISIALISASI SISTEM...'],
    [15, 'MEMUAT KONFIGURASI...'],
    [30, 'MEMUAT DATA BILLING...'],
    [46, 'MEMUAT RIWAYAT TRANSAKSI...'],
    [60, 'MEMERIKSA MEMBER & POIN...'],
    [73, 'MENYIAPKAN DASHBOARD...'],
    [83, 'MENGHITUNG OMZET...'],
    [90, 'HAMPIR SIAP...'],
  ]
  let mIdx = 0

  function tick(){
    if(_pct >= 91) return   // berhenti di 91, tunggu hideLoadingScreen

    // Increment kecil & makin kecil mendekati 91
    const gap       = 91 - _pct
    const increment = Math.max(0.15, gap * 0.045)
    const next      = Math.min(91, _pct + increment)

    // Update teks di milestone
    while(mIdx < milestones.length && next >= milestones[mIdx][0]){
      setBar(next, milestones[mIdx][1]); mIdx++
    }
    if(mIdx === 0) setBar(next, null)

    // Interval: semakin lambat semakin bar mendekati 91
    // mulai ~100ms, naik ke ~320ms di dekat 91%
    const delay = 100 + Math.pow(next / 91, 2.5) * 260
    setTimeout(tick, delay)
  }

  setTimeout(tick, 200)   // mulai setelah 200ms (beri waktu render)

  window.hideLoadingScreen = function(){
    const el = document.getElementById('appLoadingScreen')
    if(!el || el.style.display==='none') return
    setBar(100, 'SIAP!')
    setTimeout(()=>{
      el.style.transition = 'opacity 0.55s ease'
      el.style.opacity    = '0'
      setTimeout(()=>{ el.style.display='none'; el.style.opacity='1' }, 580)
    }, 350)
  }
})()
