;(function(){

  // Salt: XOR-obfuscated (key=0x5A), tidak pernah ada sebagai string plain di source
  var _xb = [27,9,14,8,21,104,106,104,108,121,24,22,29,123,34,17,99]
  var _xk = 0x5A
  var _SALT = _xb.map(function(b){ return String.fromCharCode(b ^ _xk) }).join('')
  _xb = null  // hapus array setelah decode

  // FNV-1a 32-bit hash
  function _hash(str){
    var h = 0x811c9dc5
    for(var i = 0; i < str.length; i++){
      h ^= str.charCodeAt(i)
      h = (h * 0x01000193) >>> 0
    }
    return h.toString(16).toUpperCase().padStart(8,'0')
  }

  // Buat / ambil Device ID unik per install
  function _getDeviceId(){
    var did = localStorage.getItem("_lic_did")
    if(!did){
      var raw = Date.now().toString(36) + Math.random().toString(36).slice(2,8)
      did = (_hash(raw + _SALT) + _hash(_SALT + raw)).slice(0,12).toUpperCase()
      localStorage.setItem("_lic_did", did)
    }
    return did
  }

  // Format Device ID: XXXX-XXXX-XXXX
  function _fmtId(id){
    return id.replace(/(.{4})(?=.)/g,'$1-')
  }

  // Validasi key
  function _validateKey(key, deviceId){
    var raw = key.replace(/-/g,'').toUpperCase()
    if(raw.length < 28) return { ok:false, reason:"Key tidak valid" }
    if(!raw.startsWith("ASTO")) return { ok:false, reason:"Key tidak valid" }

    var devPart    = raw.slice(4,12)
    var expiryPart = raw.slice(12,20)
    var checkPart  = raw.slice(20,28)

    if(devPart !== _hash(deviceId + _SALT).slice(0,8))
      return { ok:false, reason:"Key tidak cocok dengan device ini" }

    if(checkPart !== _hash(devPart + expiryPart + _SALT).slice(0,8))
      return { ok:false, reason:"Key rusak / tidak valid" }

    if(expiryPart !== "00000000"){
      // ── Format TEST: M + 7 hex digits = expiry dalam Unix-minutes ──
      if(expiryPart[0] === 'M'){
        var expMin = parseInt(expiryPart.slice(1), 16)
        var nowMin = Math.floor(Date.now() / 60000)
        if(nowMin > expMin)
          return { ok:false, reason:"Key TEST expired", expired:true }
        var sisaMenit = expMin - nowMin
        return { ok:true, permanent:false, expiry:expiryPart, sisaHari:0, sisaMenit:sisaMenit, isTestKey:true }
      }
      // ── Format normal: YYYYMMDD ──
      var yr  = parseInt(expiryPart.slice(0,4))
      var mo  = parseInt(expiryPart.slice(4,6)) - 1
      var dy  = parseInt(expiryPart.slice(6,8))
      var exp = new Date(yr, mo, dy, 23, 59, 59)
      if(isNaN(exp.getTime())) return { ok:false, reason:"Format tanggal key salah" }
      if(new Date() > exp){
        var tgl = expiryPart.slice(0,4)+'-'+expiryPart.slice(4,6)+'-'+expiryPart.slice(6,8)
        return { ok:false, reason:"Key expired pada " + tgl, expired:true }
      }
      var sisa = Math.ceil((exp - new Date())/(1000*60*60*24))
      return { ok:true, permanent:false, expiry:expiryPart, sisaHari:sisa }
    }
    return { ok:true, permanent:true }
  }

  // ── Simpan key ke blacklist Firebase saat expired ──────────
  // Dipanggil saat key berhasil divalidasi (ok:true) — catat key agar tidak bisa dipakai ulang setelah expired

  // Kode darurat — PRIVATE, tidak diekspos ke window
  function _emergencyCode(){
    var did = _getDeviceId()
    return _hash(did + 'RESET' + _SALT).slice(0,8).toUpperCase()
  }

  // Cek apakah sudah berlisensi
  function _isLicensed(){
    var saved = localStorage.getItem("_lic_key")
    if(!saved) return false
    return _validateKey(saved, _getDeviceId()).ok
  }

  // Public API — salt dan hash TIDAK diekspos
  window._LIC = {
    getDeviceId   : _getDeviceId,
    fmtId         : _fmtId,
    validate      : _validateKey,
    isLicensed    : _isLicensed,
    emergencyCode : _emergencyCode   // hanya hasilnya, bukan salt/hash
  }

})()

// Helper global: cek apakah licensed
function _isProLicensed(){
  return !!(window._LIC && window._LIC.isLicensed && window._LIC.isLicensed())
}

// Helper global: cek apakah user sedang di mode Free (bukan PRO)
// Jika belum licensed DAN belum pilih free → anggap sama seperti free (blokir PRO menu)
function _isFreeMode(){
  if(_isProLicensed()) return false
  return true   // semua state non-licensed = blokir fitur PRO
}

// ============================================================
// LICENSE EXPIRY MONITOR — Warning banner + countdown + popup
// ============================================================
function _getLicenseExpiryInfo(){
  if(!window._LIC || !window._LIC.isLicensed()) return null
  const key = localStorage.getItem('_lic_key')
  if(!key) return null
  try{
    const res = window._LIC.validate(key, window._LIC.getDeviceId())
    if(!res.ok) return null
    if(res.permanent) return { permanent: true }
    if(res.isTestKey) return { isTestKey:true, sisaMenit:res.sisaMenit, sisaHari:0 }
    return { sisaHari: res.sisaHari }
  }catch(e){ return null }
}

function _updateLicenseExpiryBanner(){
  const banner = document.getElementById('licExpiryBanner')
  if(!banner) return

  const info = _getLicenseExpiryInfo()

  if(!info || info.permanent){
    banner.style.display = 'none'
    return
  }

  let teks = '', warna = '', glow = '', icon = ''

  if(info.isTestKey){
    const m = info.sisaMenit
    if(m <= 0){
      // Expired — reload untuk kunci fitur
      banner.style.display = 'none'
      location.reload()
      return
    }
    icon  = '⏱️'
    teks  = `KEY TEST — Expired dalam <strong>${m} menit</strong>`
    warna = 'rgba(255,100,0,0.18)'
    glow  = 'rgba(255,120,0,0.35)'
    banner.style.borderColor = 'rgba(255,120,0,0.45)'
    banner.style.color       = '#ff8844'
  } else {
    const d = info.sisaHari
    if(d <= 0){
      banner.style.display = 'none'
      location.reload()
      return
    }
    if(d <= 3){
      icon  = '🚨'
      teks  = `License expired dalam <strong>${d} hari!</strong> Segera perpanjang.`
      warna = 'rgba(255,26,80,0.14)'
      glow  = 'rgba(255,26,80,0.30)'
      banner.style.borderColor = 'rgba(255,26,80,0.45)'
      banner.style.color       = '#ff4466'
    } else if(d <= 7){
      icon  = '⚠️'
      teks  = `License akan expired dalam <strong>${d} hari</strong>`
      warna = 'rgba(255,170,0,0.12)'
      glow  = 'rgba(255,200,0,0.25)'
      banner.style.borderColor = 'rgba(255,190,0,0.40)'
      banner.style.color       = '#ffcc44'
    } else {
      banner.style.display = 'none'
      return
    }
  }

  banner.style.display    = 'flex'
  banner.style.background = warna
  banner.style.boxShadow  = `0 0 12px ${glow}`
  banner.querySelector('.lic-exp-icon').textContent = icon
  banner.querySelector('.lic-exp-text').innerHTML   = teks
}

function _showLicenseExpiryPopup(){
  const info = _getLicenseExpiryInfo()
  if(!info || info.permanent) return

  let msg = '', days = 0, isUrgent = false

  if(info.isTestKey){
    msg      = `⏱️ KEY TEST aktif — expired dalam <strong>${info.sisaMenit} menit</strong>`
    isUrgent = info.sisaMenit <= 1
  } else {
    days     = info.sisaHari
    isUrgent = days <= 3
    if(days > 7) return  // tidak perlu popup
    msg = isUrgent
      ? `🚨 License akan expired dalam <strong>${days} hari!</strong><br>Hubungi developer untuk perpanjang.`
      : `⚠️ License akan expired dalam <strong>${days} hari</strong>`
  }

  showPopup({
    typeNotif: isUrgent ? 'error' : 'warning',
    message: msg
  })
}

let _licExpiryInterval = null

function initLicenseExpiryMonitor(){
  if(!_isProLicensed()) return

  // Update banner segera
  _updateLicenseExpiryBanner()

  // Popup sekali per sesi jika hampir expired
  const _popupShownKey = '_lic_exp_popup_' + new Date().toDateString()
  if(!sessionStorage.getItem(_popupShownKey)){
    const info = _getLicenseExpiryInfo()
    if(info && !info.permanent){
      const needPopup = info.isTestKey || (info.sisaHari !== undefined && info.sisaHari <= 7)
      if(needPopup){
        sessionStorage.setItem(_popupShownKey, '1')
        setTimeout(_showLicenseExpiryPopup, 1800)
      }
    }
  }

  // Interval: tiap 30 detik untuk test key, tiap 5 menit untuk normal
  if(_licExpiryInterval) clearInterval(_licExpiryInterval)
  const info = _getLicenseExpiryInfo()
  const interval = (info && info.isTestKey) ? 30000 : 300000
  _licExpiryInterval = setInterval(_updateLicenseExpiryBanner, interval)
}

// Aktifkan free mode secara eksplisit (simpan flag, reload)
function continueFreeMode(){
  localStorage.setItem('_lic_free_mode', '1')
}

