const _FB_SYNC_KEYS = {
  // TV & Harga
  'ps_tv_names':       'settings/tvNames',
  'ps_tv_tarif':       'settings/tvTarif',
  'ps_units':          'settings/totalTV',
  'ps_prices':         'settings/prices',
  'ps_lockedTVs':      'settings/lockedTVs',

  // Member & Data
  'ps_members':        'settings/members',
  'ps_hutang':         'settings/hutang',
  'ps_saved_times':    'settings/savedTimes',
  'ps_pengeluaran':    'pengeluaran',
  'ps_pemasukan_tambahan': 'pemasukanTambahan',
  'pgl_templates':     'settings/pglTemplates',
  'pgl_budget_bulan':  'settings/pglBudget',

  // Kantin — Menu makanan & minuman
  'ps_saldo_waktu':    'saldoWaktu',
  'ps_makanan':        'kantin/makanan',

  // Pengaturan lama (dipertahankan untuk kompatibilitas)
  'ps_poin_konfig':    'settings/poinKonfig',
  'ps_diskon_konfig':  'settings/diskonKonfig',
  'ps_hadiah_turna':   'settings/hadiahTurna',
  'ps_absensi':        'settings/absensi',
  'ps_lang':           'settings/lang',
  'ps_font_size':      'settings/fontSize',
  'integrasi_fonnte_token': 'settings/fonnteToken',

  // DP & Booking
  'dp_nominal':        'settings/dpNominal',
  'booking_site_nama': 'settings/bookingSiteNama',
  'booking_site_subtitle': 'settings/bookingSiteSubtitle',
  'booking_site_tagline':  'settings/bookingSiteTagline',
  'booking_site_wa':       'settings/bookingSiteWa',
  'booking_site_wa_nama':  'settings/bookingSiteWaNama',
  'booking_online_status': 'settings/bookingOnline',
  'qris_image_url':    'settings/qrisImageUrl',

  // WA Template
  'wa_template_setujui': 'settings/waTemplate/setujui',
  'wa_template_tolak':   'settings/waTemplate/tolak',
  'wa_template_batal':   'settings/waTemplate/batal',

  // Users (PIN, dll)
  // PENTING: '_cached_users' TIDAK di-sync via auto-sync karena akan menyimpan
  // JSON string ke Firebase path 'users', yang merusak struktur object user.
  // Users sudah di-sync via dedicated listener _fbDb.ref('users').on(...)
  // '_cached_users': 'users',  // ← DIHAPUS — ini penyebab bug "username tidak ditemukan"
}

function _fbSyncSave(localKey, value){
  if(!window._fbDb) return
  const fbPath = _FB_SYNC_KEYS[localKey]
  if(!fbPath) return
  window._fbDb.ref(fbPath).set(value !== null && value !== undefined ? value : null)
}

function _fbSyncLoadAll(){
  if(!window._fbDb) return

  // ── Saat Firebase pertama connect: cek key tersimpan, tandai expired di Firebase ──
  const savedKey = localStorage.getItem('_lic_key')
  if(savedKey && window._LIC?.validate && window._LIC?.markExpired){
    const res = window._LIC.validate(savedKey, window._LIC.getDeviceId())
    if(!res.ok && res.expired){
      // Key sudah expired — tandai di Firebase agar tidak bisa dipakai lagi di device manapun
      window._LIC.markExpired(savedKey)
    }
  }
  Object.entries(_FB_SYNC_KEYS).forEach(([localKey, fbPath]) => {
    window._fbDb.ref(fbPath).on('value', snap => {
      const val = snap.val()
      if(val !== null && val !== undefined){
        const current = localStorage.getItem(localKey)
        const newVal  = typeof val === 'string' ? val : JSON.stringify(val)
        if(current !== newVal){
          // Pakai _origSetItem — BUKAN localStorage.setItem (override)
          // Mencegah _fbSyncSave terpanggil lagi → circular write ke Firebase
          _origSetItem(localKey, newVal)
          // Trigger UI refresh untuk data tertentu
          if(localKey === 'ps_tv_names')    { try{ const t=JSON.parse(newVal); Object.keys(t).forEach(i=>{ const els=document.querySelectorAll('[data-tvname="'+i+'"]'); els.forEach(el=>el.textContent=t[i]) }) }catch(e){} }
          if(localKey === 'ps_members')     { try{ members=JSON.parse(newVal) }catch(e){} }
          if(localKey === 'ps_hutang')      { try{ hutangList=JSON.parse(newVal) }catch(e){} }
          if(localKey === 'ps_pengeluaran') { try{ const p=JSON.parse(newVal); pengeluaranList=Array.isArray(p)?p:Object.values(p||{}) }catch(e){} }
          if(localKey === 'ps_pemasukan_tambahan') { try{ const p=JSON.parse(newVal); pemasukanList=Array.isArray(p)?p:Object.values(p||{}) }catch(e){} }
          if(localKey === 'pgl_templates')  { try{ pglTemplates=JSON.parse(newVal) }catch(e){} }
          if(localKey === 'ps_saved_times') {  }
          if(localKey === 'ps_prices')      { try{ prices=JSON.parse(newVal); if(!pendingTransaction) createUI() }catch(e){} }
          if(localKey === 'ps_units')       { try{ units=JSON.parse(newVal);  if(!pendingTransaction) createUI() }catch(e){} }
          if(localKey === 'ps_lang')        { try{ if(typeof applyLang==='function') applyLang(newVal) }catch(e){} }
          if(localKey === 'ps_font_size')   { try{ if(typeof applyFontSize==='function') applyFontSize(newVal) }catch(e){} }
          // Kantin — update in-memory list
          if(localKey === 'ps_minuman')     { try{ minumanList = JSON.parse(newVal); if(typeof refreshTVMenuDropdowns==='function') refreshTVMenuDropdowns() }catch(e){} }
          if(localKey === 'ps_makanan')     { try{ makananList = JSON.parse(newVal); if(typeof refreshTVMenuDropdowns==='function') refreshTVMenuDropdowns() }catch(e){} }
          if(localKey === 'ps_saldo_waktu') { try{ const p=JSON.parse(newVal); saldoWaktuList=Array.isArray(p)?p:Object.values(p||{}) }catch(e){} }
        }
      }
    })
  })
  console.log('✅ Firebase sync aktif untuk', Object.keys(_FB_SYNC_KEYS).length, 'key')
}

// Override localStorage.setItem untuk auto-sync ke Firebase
const _origSetItem = localStorage.setItem.bind(localStorage)
localStorage.setItem = function(key, value){
  _origSetItem(key, value)
  _fbSyncSave(key, value)
}

