// ── ESP32 IR Helper ──────────────────────────────────────
// Cache lokal ESP32 IPs (sync dari Firebase)
window._esp32IPs = JSON.parse(localStorage.getItem('ps_esp32_ip')||'{}')

function getEsp32IP(i){
  return window._esp32IPs[i] || ''
}
function setEsp32IP(i, ip){
  if(ip) window._esp32IPs[i] = ip.trim()
  else delete window._esp32IPs[i]
  localStorage.setItem('ps_esp32_ip', JSON.stringify(window._esp32IPs))
  // Sync ke Firebase
  if(window._fbDb){
    window._fbDb.ref('settings/esp32IPs/' + i).set(ip ? ip.trim() : null)
  }
}
function loadEsp32IPsFromFirebase(){
  if(!window._fbDb) return
  window._fbDb.ref('settings/esp32IPs').on('value', snap => {
    const data = snap.val() || {}
    window._esp32IPs = data
    localStorage.setItem('ps_esp32_ip', JSON.stringify(data))
  })
  // Trigger device monitoring setelah Firebase siap
  setTimeout(()=>{ if(typeof initDeviceMonitoring==='function') initDeviceMonitoring() }, 800)
}
// ── Pindahkan IP ke slot TV yang benar jika Unit ID tidak cocok ──
function pindahEsp32IP(dariSlot, keSlot, ip){
  const totalTV = window.units || parseInt(localStorage.getItem('ps_total_units')||'0') || 10
  if(keSlot < 1 || keSlot > totalTV){
    showToast('⚠️ Slot TV ' + keSlot + ' tidak ada (total: ' + totalTV + ')'); return
  }
  // Kosongkan slot asal
  setEsp32IP(dariSlot, null)
  const elDari = document.getElementById('esp32ip'+dariSlot)
  if(elDari) elDari.value = ''
  const stDari = document.getElementById('esp32status'+dariSlot)
  if(stDari) stDari.innerHTML = '⚫ Belum diset'

  // Set ke slot yang benar
  setEsp32IP(keSlot, ip)
  const elKe = document.getElementById('esp32ip'+keSlot)
  if(elKe) elKe.value = ip
  showToast('✅ IP ' + ip + ' dipindah ke slot TV ' + keSlot)

  // Verifikasi ulang di slot baru
  setTimeout(()=>{ cekEsp32(keSlot) }, 300)
}

function matikanTV(i){
  const ip = getEsp32IP(i)
  if(!ip){ showToast('⚠️ IP ESP32 unit ini belum diset'); return }
  fetch('http://'+ip+'/power', {signal: AbortSignal.timeout(5000)})
    .then(r=>r.json())
    .then(d=>{ if(d.ok){ showToast('📺 TV unit '+i+' dimatikan!') } else { showToast('⚠️ ESP32: '+d.msg) } })
    .catch(()=>showToast('❌ ESP32 unit '+i+' tidak terhubung'))
}
// ──────────────────────────────────────────────────────────
function cekEsp32(n, silent){
  const ipEl  = document.getElementById('esp32ip'+n)
  const statEl = document.getElementById('esp32status'+n)
  const input  = ipEl ? ipEl.value.trim() : getEsp32IP(n)
  if(!input){
    if(statEl) statEl.innerHTML = '⚫ Belum diset'
    return
  }
  if(statEl) statEl.innerHTML = '🔄 Mengecek...'
  fetch('http://'+input+'/status', {signal: AbortSignal.timeout(5000)})
    .then(r=>r.json())
    .then(d=>{
      if(d.ok){
        const realIP   = d.ip || input
        const unitResp = parseInt(d.unit)  // TV_UNIT_ID dari firmware ESP32

        // ── Validasi Unit ID ──────────────────────────────────
        // Jika ESP32 punya field 'unit' dan tidak cocok dengan slot TV ini
        if(!isNaN(unitResp) && unitResp !== n){
          if(statEl) statEl.innerHTML =
            '<span style="color:#ffaa44;">⚠️ Unit ID tidak cocok! ' +
            'ESP32 ini adalah <b>TV ' + unitResp + '</b>, bukan TV ' + n + '.' +
            '</span>' +
            '<div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;">' +
            '<button onclick="pindahEsp32IP(' + n + ',' + unitResp + ',\'' + input + '\')" ' +
            'style="font-size:10px;padding:5px 10px;margin:0;width:auto;' +
            'background:rgba(0,245,255,0.08);border:1px solid rgba(0,245,255,0.25);' +
            'border-radius:8px;color:#00f5ff;">' +
            '📦 Pindah ke slot TV ' + unitResp + '</button>' +
            '<span style="font-size:9px;color:rgba(168,200,240,0.40);align-self:center;">' +
            'atau ganti TV_UNIT_ID=' + n + ' di firmware</span>' +
            '</div>'
          return
        }

        // ── Auto update IP jika berubah (misal mDNS) ──────────
        if(realIP && ipEl && input !== realIP){
          ipEl.value = realIP
          setEsp32IP(n, realIP)
          const ips = window._esp32IPs || {}
          ips[n] = realIP
          window._esp32IPs = ips
          localStorage.setItem('ps_esp32_ip', JSON.stringify(ips))
          if(window._fbDb) window._fbDb.ref('settings/esp32IPs/'+n).set(realIP)
        } else {
          setEsp32IP(n, realIP)
        }

        // ── Tampilkan status lengkap ───────────────────────────
        const rssiText = typeof d.wifi_rssi === 'number'
          ? ' · RSSI ' + d.wifi_rssi + ' dBm' : ''
        const uptimeText = typeof d.uptime === 'number'
          ? ' · ⏱' + Math.floor(d.uptime/60) + 'm' : ''
        if(statEl) statEl.innerHTML =
          '<span style="color:#00ff88;">🟢 Online — Unit TV ' + n +
          (d.hasSignal ? ' · Sinyal ✅' : ' · <span style=\'color:#ffaa44;\'>Belum direkam</span>') +
          rssiText + uptimeText +
          ' <span style="color:rgba(168,200,240,0.40);font-size:9px;">(' + realIP + ')</span>' +
          '</span>'
      } else {
        if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">🔴 Error dari ESP32</span>'
      }
    })
    .catch(()=>{
      if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">🔴 Offline / Tidak terhubung</span>'
    })
}


function rekamRemoteEsp32(n){
  const ip = document.getElementById('esp32ip'+n)?.value.trim() || getEsp32IP(n)
  if(!ip){ showToast('⚠️ Isi IP ESP32 dulu!'); return }

  const statEl   = document.getElementById('esp32status'+n)
  const rekamBtn = document.getElementById('rekambtn'+n)

  if(statEl)   statEl.innerHTML  = '🔄 Mempersiapkan...'
  if(rekamBtn) rekamBtn.disabled = true

  // Step 1: Hapus sinyal lama dulu
  fetch('http://'+ip+'/clear', {signal: AbortSignal.timeout(5000)})
    .then(()=>{
      // Step 2: Mulai rekam
      return fetch('http://'+ip+'/startrecord', {signal: AbortSignal.timeout(5000)})
    })
    .then(r=>r.json())
    .then(d=>{
      if(!d.ok){
        if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">❌ '+d.msg+'</span>'
        if(rekamBtn) rekamBtn.disabled = false
        return
      }
      if(statEl) statEl.innerHTML = '<span style="color:#ffc800;">🎙️ Tekan tombol POWER di remote sekarang!</span>'

      // Step 3: Auto cek setiap 1.5 detik max 20x (30 detik)
      let tries = 0
      const interval = setInterval(()=>{
        tries++
        fetch('http://'+ip+'/status', {signal: AbortSignal.timeout(3000)})
          .then(r=>r.json())
          .then(s=>{
            if(s.hasSignal && s.rawLen > 0){
              clearInterval(interval)
              if(statEl) statEl.innerHTML = '<span style="color:#00ff88;">✅ Remote berhasil direkam!</span>'
              if(rekamBtn) rekamBtn.disabled = false
              showToast('✅ Remote TV '+n+' berhasil direkam!')
            } else if(tries >= 20){
              clearInterval(interval)
              if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">⏱️ Timeout — coba lagi</span>'
              if(rekamBtn) rekamBtn.disabled = false
            } else {
              // Update countdown
              const sisa = 30 - Math.floor(tries * 1.5)
              if(statEl && sisa > 0) statEl.innerHTML = '<span style="color:#ffc800;">🎙️ Tekan POWER di remote... ('+sisa+'s)</span>'
            }
          })
          .catch(()=>{
            // ESP32 sedang rekam IR — server sibuk, lanjut cek
            if(tries >= 20){
              clearInterval(interval)
              if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">⏱️ Timeout — coba lagi</span>'
              if(rekamBtn) rekamBtn.disabled = false
            }
          })
      }, 1500)
    })
    .catch(()=>{
      if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">🔴 Offline / Tidak terhubung</span>'
      if(rekamBtn) rekamBtn.disabled = false
    })
}

function hapusSinyalEsp32(n){
  const ip = document.getElementById('esp32ip'+n)?.value.trim() || getEsp32IP(n)
  if(!ip){ showToast('⚠️ Isi IP ESP32 dulu!'); return }
  if(!confirm('Hapus sinyal remote TV '+n+'?')) return

  const statEl = document.getElementById('esp32status'+n)
  if(statEl) statEl.innerHTML = '🔄 Menghapus...'

  fetch('http://'+ip+'/clear', {signal: AbortSignal.timeout(5000)})
    .then(r=>r.json())
    .then(d=>{
      if(statEl) statEl.innerHTML = '<span style="color:#ffaa44;">🗑️ Sinyal dihapus — perlu rekam ulang</span>'
      showToast('🗑️ Sinyal remote TV '+n+' dihapus!')
    })
    .catch(()=>{
      if(statEl) statEl.innerHTML = '<span style="color:#ff5555;">🔴 Offline / Tidak terhubung</span>'
    })
}

function saveEsp32Settings(){
  const btn = document.querySelector('[onclick="saveEsp32Settings()"]')
  if(btn){ btn.textContent = '⏳ Menyimpan...'; btn.disabled = true }

  const ips = {}
  for(let n = 1; n <= units; n++){
    const el = document.getElementById('esp32ip'+n)
    if(!el) continue
    const val = el.value.trim()
    if(val) ips[n] = val
  }
  window._esp32IPs = ips
  localStorage.setItem('ps_esp32_ip', JSON.stringify(ips))

  // Simpan lokal dulu — langsung selesai
  if(btn){ btn.textContent = '✅ Tersimpan!'; btn.style.color = '#00ff88'; btn.disabled = false }
  setTimeout(()=>{
    if(btn){ btn.innerHTML = '💾 SIMPAN SEMUA'; btn.style.color = '' }
  }, 2000)
  showToast('✅ Setting ESP32 disimpan!')

  // Firebase sync di background — tidak blokir UI
  if(window._fbDb){
    window._fbDb.ref('settings/esp32IPs').set(Object.keys(ips).length ? ips : null).catch(()=>{})
  }
}


