function closeSuperAdminPopup(){
  const popup = document.getElementById("superAdminPopup")
  const input = document.getElementById("superAdminPinInput")
  const msg = document.getElementById("superAdminPinMsg")

  if(popup) popup.style.display = "none"
  if(input) input.value = ""
  if(msg) msg.innerText = ""

  pendingCategoryId = null
  pendingCategoryBtn = null
  pendingProtectedMenu = null
}

function openSuperAdminProtectedMenu(menuName){
  if(superAdminUnlocked){
    openMenu(menuName)
    return
  }

  pendingProtectedMenu = menuName
  openSuperAdminPopup("__protected_menu__", null)
}

function submitSuperAdminPin(){

  const input = document.getElementById("superAdminPinInput")
  const msg = document.getElementById("superAdminPinMsg")

  if(!input) return

  const enteredPin = input.value
  const targetId = pendingCategoryId
  const targetBtn = pendingCategoryBtn
  const protectedMenu = pendingProtectedMenu

  if(enteredPin === SUPER_ADMIN_PIN){

    superAdminUnlocked = true
    updateAdminStatusIndicator()
    clearAutoLock()
    closeSuperAdminPopup()

    // jika request membuka menu owner yang dikunci
    if(protectedMenu){
      openMenu(protectedMenu)
      return
    }

    // jika request membuka kategori yang dikunci
    if(targetId && targetBtn){
      toggleCategory(targetId, targetBtn)
      closeSidebar()
      return
    }

    showPopup({
      typeNotif:"success",
      message:"Akses Super Admin berhasil dibuka"
    })

  }else{
    if(msg) msg.innerText = "PIN Super Admin salah"
    input.value = ""
  }
}

function openSuperAdminBackupMenu(){
  openSuperAdminPopup("__backup_superadmin__", null)
}



