let printerStatusState = (() => {
  try{
    const saved = JSON.parse(localStorage.getItem(PRINTER_STATUS_KEY) || "null")
    if(saved && typeof saved === "object"){
      return saved
    }
  }catch(err){}
  return {
    mac: localStorage.getItem(PRINTER_MAC_KEY) || "",
    bluetooth: false,
    paired: false,
    connected: false,
    deviceName: "",
    source: "web",
    message: "Belum dicek"
  }
})()

function normalizePrinterMac(mac){
  let raw = String(mac || "").trim().toUpperCase().replace(/-/g, ":")
  const hex = raw.replace(/[^0-9A-F]/g, "")
  if(hex.length === 12){
    return hex.match(/.{1,2}/g).join(":")
  }
  return raw.replace(/[^0-9A-F:]/g, "")
}

function isValidPrinterMac(mac){
  return /^[0-9A-F]{2}(:[0-9A-F]{2}){5}$/.test(normalizePrinterMac(mac))
}

function getSavedPrinterMac(){
  return normalizePrinterMac(localStorage.getItem(PRINTER_MAC_KEY) || "")
}

function persistPrinterMac(mac){
  const normalized = normalizePrinterMac(mac)
  if(normalized){
    localStorage.setItem(PRINTER_MAC_KEY, normalized)
  }else{
    localStorage.removeItem(PRINTER_MAC_KEY)
  }
  return normalized
}

function savePrinterStatusState(){
  localStorage.setItem(PRINTER_STATUS_KEY, JSON.stringify(printerStatusState))
}

function setPrinterStatusState(patch = {}){
  printerStatusState = {
    ...printerStatusState,
    ...patch
  }
  savePrinterStatusState()
  refreshPrinterStatusUI()
  return printerStatusState
}

function getAndroidBridge(){
  if(typeof window === "undefined") return null
  if(window.Android) return window.Android
  if(window.Sketchware) return window.Sketchware
  if(window.AppBridge) return window.AppBridge
  return null
}

function bridgeHas(method){
  const bridge = getAndroidBridge()
  return !!(bridge && typeof bridge[method] === "function")
}

function callBridge(method, ...args){
  const bridge = getAndroidBridge()
  if(!bridge || typeof bridge[method] !== "function") return null
  try{
    return bridge[method](...args)
  }catch(err){
    console.log("Bridge error:", method, err)
    return null
  }
}

function encodeBase64Utf8(text){
  try{
    return btoa(unescape(encodeURIComponent(String(text))))
  }catch(err){
    try{
      return btoa(String(text))
    }catch(error){
      return ""
    }
  }
}

function trySyncPrinterMacToBridge(mac){
  const normalized = normalizePrinterMac(mac || getSavedPrinterMac())
  if(!normalized) return false

  const candidates = [
    ["setPrinterMac", [normalized]],
    ["savePrinterMac", [normalized]],
    ["updatePrinterMac", [normalized]],
    ["setMacAddress", [normalized]]
  ]

  for(const [method, args] of candidates){
    if(bridgeHas(method)){
      callBridge(method, ...args)
      return true
    }
  }

  return false
}

function tryLoadPrinterMacFromBridge(){
  const candidates = ["getPrinterMac", "loadPrinterMac", "getSavedPrinterMac", "getMacAddress"]
  for(const method of candidates){
    if(bridgeHas(method)){
      const result = callBridge(method)
      const mac = normalizePrinterMac(result || "")
      if(isValidPrinterMac(mac)){
        persistPrinterMac(mac)
        setPrinterStatusState({
          mac,
          source: "android",
          message: "MAC printer tersinkron dari Android"
        })
        return mac
      }
    }
  }
  return ""
}

function parsePrinterBridgeStatus(result, fallbackMac){
  const mac = normalizePrinterMac(fallbackMac || getSavedPrinterMac())
  if(result === true){
    return {
      mac,
      bluetooth: true,
      paired: true,
      connected: true,
      source: "android",
      message: "Printer terhubung"
    }
  }
  if(result === false || result == null){
    return {
      mac,
      bluetooth: false,
      paired: false,
      connected: false,
      source: "android",
      message: "Printer belum terhubung"
    }
  }

  if(typeof result === "string"){
    const text = result.trim()
    if(!text){
      return {
        mac,
        bluetooth: false,
        paired: false,
        connected: false,
        source: "android",
        message: "Status printer kosong"
      }
    }
    try{
      const parsed = JSON.parse(text)
      if(parsed && typeof parsed === "object"){
        return {
          mac: normalizePrinterMac(parsed.mac || parsed.address || mac),
          bluetooth: !!parsed.bluetooth,
          paired: !!parsed.paired,
          connected: !!parsed.connected,
          deviceName: parsed.deviceName || parsed.name || "",
          source: "android",
          message: parsed.message || "Status printer diterima"
        }
      }
    }catch(err){}
    return {
      mac,
      bluetooth: /bluetooth\s*(aktif|on|ready|true)/i.test(text),
      paired: /paired|terpasang|dipasangkan|true/i.test(text),
      connected: /connect|terhubung|ready|ok|success|berhasil/i.test(text),
      source: "android",
      message: text
    }
  }

  if(typeof result === "object"){
    return {
      mac: normalizePrinterMac(result.mac || result.address || mac),
      bluetooth: !!result.bluetooth,
      paired: !!result.paired,
      connected: !!result.connected,
      deviceName: result.deviceName || result.name || "",
      source: "android",
      message: result.message || "Status printer diterima"
    }
  }

  return {
    mac,
    bluetooth: false,
    paired: false,
    connected: false,
    source: "android",
    message: "Status printer tidak dikenali"
  }
}

function getPrinterStatusBadge(stateObj = printerStatusState){
  if(stateObj.connected){
    return { cls: "ok", text: "TERHUBUNG" }
  }
  if(stateObj.bluetooth || stateObj.paired){
    return { cls: "warn", text: "SIAP PARSIAL" }
  }
  return { cls: "off", text: "BELUM TERHUBUNG" }
}

function refreshPrinterStatusUI(){
  const macInput = document.getElementById("printerMacInput")
  if(macInput && !document.activeElement?.isSameNode(macInput)){
    macInput.value = getSavedPrinterMac()
  }

  const currentMacEl = document.getElementById("printerCurrentMac")
  if(currentMacEl) currentMacEl.innerText = getSavedPrinterMac() || "Belum disimpan"

  const sourceEl = document.getElementById("printerStatusSource")
  if(sourceEl) sourceEl.innerText = printerStatusState.source || "web"

  const bluetoothEl = document.getElementById("printerBluetoothState")
  if(bluetoothEl) bluetoothEl.innerText = printerStatusState.bluetooth ? "Aktif" : "Tidak terdeteksi"

  const pairedEl = document.getElementById("printerPairedState")
  if(pairedEl) pairedEl.innerText = printerStatusState.paired ? "Sudah paired" : "Belum paired"

  const connectedEl = document.getElementById("printerConnectedState")
  if(connectedEl) connectedEl.innerText = printerStatusState.connected ? "Terhubung" : "Belum terhubung"

  const deviceEl = document.getElementById("printerDeviceName")
  if(deviceEl) deviceEl.innerText = printerStatusState.deviceName || "-"

  const msgEl = document.getElementById("printerStatusMessage")
  if(msgEl) msgEl.innerText = printerStatusState.message || "Belum dicek"

  const badgeWrap = document.getElementById("printerStatusBadgeWrap")
  if(badgeWrap){
    const badge = getPrinterStatusBadge()
    badgeWrap.innerHTML = `<span class="printer-status-pill ${badge.cls}">${badge.text}</span>`
  }
}

function savePrinterMacFromWeb(){
  const input = document.getElementById("printerMacInput")
  const mac = normalizePrinterMac(input ? input.value : getSavedPrinterMac())

  if(!isValidPrinterMac(mac)){
    showPopup({
      typeNotif:"warning",
      message:"Format MAC address tidak valid. Contoh: 66:32:A1:12:34:56"
    })
    return
  }

  persistPrinterMac(mac)
  const synced = trySyncPrinterMacToBridge(mac)

  setPrinterStatusState({
    mac,
    source: synced ? "android" : "web",
    message: synced
      ? "MAC printer disimpan dan dikirim ke Android"
      : "MAC printer disimpan di web. Tambahkan bridge Android agar sinkron penuh."
  })

  showPopup({
    typeNotif:"success",
    message:"MAC printer berhasil disimpan"
  })
}

function syncPrinterMacFromAndroid(showMessage = true){
  const mac = tryLoadPrinterMacFromBridge()
  if(mac){
    if(showMessage){
      showPopup({
        typeNotif:"success",
        message:"MAC printer berhasil diambil dari Android"
      })
    }
    return
  }

  if(showMessage){
    showPopup({
      typeNotif:"warning",
      message:"Bridge Android belum menyediakan fungsi baca MAC printer"
    })
  }
}

function checkPrinterConnectionFromWeb(){
  const mac = getSavedPrinterMac()

  if(!isValidPrinterMac(mac)){
    showPopup({
      typeNotif:"warning",
      message:"Simpan MAC printer dulu sebelum cek koneksi"
    })
    return
  }

  trySyncPrinterMacToBridge(mac)

  setPrinterStatusState({
    mac,
    source: "android",
    message: "Sedang mengecek koneksi printer..."
  })

  const bridgeCandidates = [
    ["checkPrinterConnection", [mac]],
    ["checkPrinterStatus", [mac]],
    ["probePrinter", [mac]],
    ["testPrinterConnection", [mac]],
    ["getPrinterStatus", [mac]]
  ]

  for(const [method, args] of bridgeCandidates){
    if(bridgeHas(method)){
      const result = callBridge(method, ...args)
      const parsed = parsePrinterBridgeStatus(result, mac)
      setPrinterStatusState(parsed)

      showPopup({
        typeNotif: parsed.connected ? "success" : "warning",
        message: parsed.message || (parsed.connected ? "Printer terhubung" : "Printer belum terhubung")
      })
      return
    }
  }

  setPrinterStatusState({
    mac,
    source: "web",
    message: "Bridge Android untuk cek koneksi belum dipasang"
  })

  showPopup({
    typeNotif:"warning",
    message:"Cek koneksi butuh bridge Android. Tambahkan method checkPrinterConnection di Sketchware."
  })
}

