function testPrinterFromWeb(){
  const mac = getSavedPrinterMac()
  if(!isValidPrinterMac(mac)){
    showPopup({
      typeNotif:"warning",
      message:"Simpan MAC printer yang valid dulu sebelum test print"
    })
    return
  }

  trySyncPrinterMacToBridge(mac)

  const text = buildTestPrinterText()
  const base64Text = encodeBase64Utf8(text)

  const bridgeCandidates = [
    ["bluetoothPrintBase64", ["TES_PRINTER_ASTROPHILE", base64Text]],
    ["bluetoothPrintText", ["TES_PRINTER_ASTROPHILE", text]],
    ["printBluetoothReceipt", ["TES_PRINTER_ASTROPHILE", base64Text]],
    ["printBluetoothText", ["TES_PRINTER_ASTROPHILE", text]],
    ["printEscPos", [text]]
  ]

  for(const [method, args] of bridgeCandidates){
    if(bridgeHas(method)){
      callBridge(method, ...args)
      setPrinterStatusState({
        mac,
        source: "android",
        message: "Perintah test print dikirim ke printer"
      })
      showPopup({
        typeNotif:"success",
        message:"Perintah test print berhasil dikirim"
      })
      return
    }
  }

  showPopup({
    typeNotif:"warning",
    message:"Bridge print Bluetooth belum terhubung. Tambahkan method print di Sketchware."
  })
}

function setCurrentStrukPayload(title, htmlContent, textContent){
  currentStrukTitle = title || "struk_astrophile"
  currentStrukHtml = htmlContent || ""
  currentStrukText = textContent || ""
}

function tryNativePrint(title, htmlContent, textContent){
  const mac = getSavedPrinterMac()
  if(mac){
    trySyncPrinterMacToBridge(mac)
  }

  const base64Html = encodeBase64Utf8(htmlContent || "")
  const base64Text = encodeBase64Utf8(textContent || "")

  const bridgeCandidates = [
    ["bluetoothPrintBase64", [title, base64Text]],
    ["bluetoothPrintText", [title, textContent || ""]],
    ["printBluetoothReceipt", [title, base64Text]],
    ["printBluetoothText", [title, textContent || ""]],
    ["printEscPos", [textContent || ""]],
    ["printHtml", [title, base64Html]],
    ["printReceipt", [title, base64Text, base64Html]],
    ["shareReceipt", [title, base64Text]],
    ["printText", [title, textContent || ""]]
  ]

  for(const [method, args] of bridgeCandidates){
    if(bridgeHas(method)){
      callBridge(method, ...args)
      return true
    }
  }

  return false
}

function handlePrintStruk(){
  if(tryNativePrint(currentStrukTitle, currentStrukHtml, currentStrukText)){
    setPrinterStatusState({
      mac: getSavedPrinterMac(),
      source: "android",
      message: "Struk dikirim ke modul print Android"
    })
    showPopup({ typeNotif:"success", message:"Struk dikirim ke modul print Android" })
    return
  }

  try{
    window.print()
  }catch(err){
    showPopup({
      typeNotif:"warning",
      message:"Bridge Bluetooth / print Android belum terhubung"
    })
  }
}

