function renderEditStrukTemplatePage(){
  closeSidebar()

  // Load saved extra lines
  let savedLines = []
  try { savedLines = JSON.parse(localStorage.getItem('ps_struk_extra_lines')||'[]') } catch(e){}
  window._struktLines = savedLines

  // Load saved header/footer overrides
  const savedHeader   = localStorage.getItem('ps_struk_header')   || (localStorage.getItem('ps_title_top')||'ASTROPHILE') + '\n' + (localStorage.getItem('ps_title_bottom')||'PLAYSTATION BILLING')
  const savedFooter   = localStorage.getItem('ps_struk_footer')   || 'Terima kasih 🙏'
  const savedSeparator= localStorage.getItem('ps_struk_separator')|| '--------------------------------'

  function buildExtraLinesUI(){
    if(!window._struktLines.length) return `<div style="font-size:11px;color:rgba(168,200,240,0.30);text-align:center;padding:10px 0;">Belum ada baris tambahan</div>`
    return window._struktLines.map((l,i)=>`
      <div style="display:flex;align-items:center;gap:8px;padding:8px 12px;
        background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.12);
        border-radius:10px;margin-bottom:6px;">
        <div style="flex:1;font-size:12px;color:#e8f4ff;font-family:'Courier New',monospace;">${l.label}${l.nilai?' · <span style="color:#00ff88;">'+l.nilai+'</span>':''}</div>
        <div style="display:flex;gap:4px;">
          <button onclick="_struktMoveUp(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:12px;">↑</button>
          <button onclick="_struktMoveDown(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:12px;">↓</button>
          <button onclick="_struktRemoveLine(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,26,80,0.10);border:1px solid rgba(255,26,80,0.25);color:#ff4d6d;font-size:12px;">✕</button>
        </div>
      </div>`).join('')
  }

  function buildPreview(header, footer, sep){
    const h = header||''; const f = footer||''; const s = sep||'---'
    const sampleData = {
      tv:2, mode:'countdown', type:'PS4', namaPelanggan:'Pelanggan',
      date: new Date().toLocaleString(),
      totalMain:20000, totalTambahan:5000, total:25000,
      items:[{nama:'Aqua',harga:5000}], paymentMethod:'cash', cashAmount:30000,
      diskon:0, potongPoin:0
    }
    const extraRows = (window._struktLines||[]).map(l=>{
      if(l.type==='separator') return s
      return l.label + (l.nilai?' : '+l.nilai:'')
    }).join('\n')
    const lines = [
      ...h.split('\n'),
      s,
      'TV: '+sampleData.tv,
      'PELANGGAN: '+sampleData.namaPelanggan,
      'MODE: '+sampleData.mode.toUpperCase(),
      'TIPE: '+sampleData.type,
      'TANGGAL: '+sampleData.date,
      s,
      'Main: Rp 20.000',
      'Tambahan: Rp 5.000',
      s,
      ...(extraRows ? extraRows.split('\n') : []),
      'TOTAL BAYAR: Rp 25.000',
      'PEMBAYARAN: Cash',
      'UANG BAYAR: Rp 30.000',
      'KEMBALIAN: Rp 5.000',
      s,
      ...f.split('\n')
    ]
    return lines.map(ln=>{
      const t=ln.trim()
      if(!t) return `<div style="height:3px;"></div>`
      if(t.match(/^-{3,}$/) || t.match(/^={3,}$/)) return `<div style="border-top:1px dashed #999;margin:4px 0;"></div>`
      const isTotalLine = t.match(/^TOTAL BAYAR/i)
      if(t.includes(':')){
        const [k,...v]=t.split(':')
        return `<div style="display:flex;justify-content:space-between;font-size:${isTotalLine?'13':'11'}px;font-weight:${isTotalLine?'900':'normal'};margin:2px 0;${isTotalLine?'border-top:1px dashed #999;padding-top:4px;':''}">`
          +`<span>${k}</span><span>${v.join(':')}</span></div>`
      }
      return `<div style="text-align:center;font-size:12px;font-weight:700;margin:2px 0;">${t}</div>`
    }).join('')
  }

  const html = `
    <style>
      .struk-section{ background:rgba(0,0,0,0.25);border:1px solid rgba(0,245,255,0.12);border-radius:14px;padding:16px;margin-bottom:14px; }
      .struk-section-label{ font-size:9px;letter-spacing:2px;color:rgba(0,245,255,0.55);margin-bottom:10px; }
      .struk-textarea{ width:100%;padding:10px 12px;border-radius:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(0,245,255,0.18);color:#e8f4ff;font-size:12px;font-family:'Courier New',monospace;line-height:1.6;outline:none;resize:vertical;box-sizing:border-box; }
      .struk-textarea:focus{ border-color:rgba(0,245,255,0.45); }
    </style>

    <!-- ① Header & Footer -->
    <div class="struk-section">
      <div class="struk-section-label">① HEADER STRUK (baris paling atas)</div>
      <textarea id="struktHeaderTA" class="struk-textarea" rows="3" oninput="_struktRefreshPreview()">${savedHeader}</textarea>
      <div style="font-size:10px;color:rgba(168,200,240,0.35);margin-top:5px;">Satu baris = satu baris di struk. Contoh: ASTROPHILE PS &#10;Jl. Sudirman No. 12</div>
    </div>

    <!-- ② Karakter garis pemisah -->
    <div class="struk-section">
      <div class="struk-section-label">② KARAKTER GARIS PEMISAH</div>
      <input id="struktSepInput" type="text" value="${savedSeparator}"
        oninput="_struktRefreshPreview()"
        style="width:100%;padding:9px 12px;border-radius:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(0,245,255,0.18);color:#e8f4ff;font-family:'Courier New',monospace;font-size:13px;outline:none;box-sizing:border-box;">
      <div style="font-size:10px;color:rgba(168,200,240,0.35);margin-top:5px;">Gunakan karakter seperti - = * atau campuran</div>
    </div>

    <!-- ③ Baris tambahan custom -->
    <div class="struk-section">
      <div class="struk-section-label">③ BARIS TAMBAHAN (tampil sebelum TOTAL)</div>
      <div id="_struktExtraWrap" style="margin-bottom:10px;">${buildExtraLinesUI()}</div>
      <!-- Input baris baru -->
      <div style="display:grid;grid-template-columns:1fr auto auto auto;gap:6px;align-items:center;margin-bottom:6px;">
        <input id="_struktNewLabel" type="text" placeholder="Label (mis: No. HP, IG, Promo...)"
          style="padding:9px 10px;border-radius:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(0,245,255,0.16);color:#e8f4ff;font-size:12px;outline:none;box-sizing:border-box;"
          onkeydown="if(event.key==='Enter') _struktAddLine()">
        <input id="_struktNewNilai" type="text" placeholder="Nilai (opsional)"
          style="width:110px;padding:9px 8px;border-radius:10px;background:rgba(0,0,0,0.35);border:1px solid rgba(0,245,255,0.16);color:#e8f4ff;font-size:12px;outline:none;box-sizing:border-box;"
          onkeydown="if(event.key==='Enter') _struktAddLine()">
        <button onclick="_struktAddSeparator()"
          style="padding:9px 10px;border-radius:10px;cursor:pointer;background:rgba(255,204,0,0.08);border:1px solid rgba(255,204,0,0.22);color:#ffcc00;font-size:11px;font-weight:700;white-space:nowrap;">─ Garis</button>
        <button onclick="_struktAddLine()"
          style="padding:9px 14px;border-radius:10px;cursor:pointer;background:rgba(0,245,255,0.10);border:1px solid rgba(0,245,255,0.28);color:#00f5ff;font-size:14px;font-weight:700;">＋</button>
      </div>
    </div>

    <!-- ④ Footer -->
    <div class="struk-section">
      <div class="struk-section-label">④ FOOTER STRUK (baris paling bawah)</div>
      <textarea id="struktFooterTA" class="struk-textarea" rows="3" oninput="_struktRefreshPreview()">${savedFooter}</textarea>
    </div>

    <!-- ⑤ Live Preview -->
    <div class="struk-section">
      <div class="struk-section-label">⑤ PREVIEW STRUK</div>
      <div id="_struktPreviewBox"
        style="background:#fff;color:#000;padding:16px;border-radius:10px;font-family:'Courier New',monospace;font-size:11px;line-height:1.7;min-height:80px;">
      </div>
      <div style="font-size:10px;color:rgba(168,200,240,0.30);margin-top:6px;text-align:center;">Preview menggunakan data contoh. Data nyata dari setiap transaksi.</div>
    </div>

    <!-- Simpan -->
    <div style="display:grid;grid-template-columns:1fr 2fr;gap:10px;margin-bottom:24px;">
      <button onclick="showDashboardView()"
        style="padding:13px;border-radius:12px;cursor:pointer;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:13px;font-weight:600;">
        ← Kembali
      </button>
      <button onclick="_struktSimpanTemplate()"
        style="padding:13px;border-radius:12px;cursor:pointer;
        background:linear-gradient(135deg,rgba(0,255,136,0.18),rgba(0,200,100,0.10));
        border:1.5px solid rgba(0,255,136,0.40);color:#00ff88;
        font-family:'Orbitron',monospace;font-size:11px;font-weight:700;letter-spacing:1.5px;">
        💾 SIMPAN TEMPLATE
      </button>
    </div>`

  showInternalPage('✏️ Edit Template Struk', 'Atur tampilan struk cetak', html)
  setTimeout(_struktRefreshPreview, 100)
}

// ── Helper: refresh preview ──
function _struktRefreshPreview(){
  const header = document.getElementById('struktHeaderTA')?.value||''
  const footer = document.getElementById('struktFooterTA')?.value||''
  const sep    = document.getElementById('struktSepInput')?.value||'---'
  const box    = document.getElementById('_struktPreviewBox')

  const sampleLines = [
    ...header.split('\n'),
    sep,
    'TV: 2',
    'PELANGGAN: Contoh Pelanggan',
    'MODE: COUNTDOWN',
    'TIPE: PS4',
    'TANGGAL: ' + new Date().toLocaleString(),
    sep,
    'Main: Rp 20.000',
    'Tambahan: Rp 5.000',
    sep,
    ...(window._struktLines||[]).map(l=> l.type==='separator' ? sep : l.label+(l.nilai?' : '+l.nilai:'')),
    'TOTAL BAYAR: Rp 25.000',
    'PEMBAYARAN: Cash',
    sep,
    ...footer.split('\n')
  ]

  if(box) box.innerHTML = sampleLines.map(ln=>{
    const t=ln.trim()
    if(!t) return `<div style="height:3px;"></div>`
    if(t.match(/^-{3,}$/) || t.match(/^={3,}$/) || t.match(/^\*{3,}$/)) return `<div style="border-top:1px dashed #999;margin:4px 0;"></div>`
    const isTotal = /TOTAL BAYAR/i.test(t)
    if(t.includes(':')){
      const [k,...v]=t.split(':')
      return `<div style="display:flex;justify-content:space-between;font-size:${isTotal?13:11}px;font-weight:${isTotal?900:'normal'};margin:2px 0;${isTotal?'border-top:1px dashed #999;padding-top:4px;':''}">`
        +`<span>${k}</span><span>${v.join(':')}</span></div>`
    }
    return `<div style="text-align:center;font-size:12px;font-weight:700;margin:2px 0;">${t}</div>`
  }).join('')
}

// ── Helper: tambah baris ──
function _struktAddLine(){
  const label = (document.getElementById('_struktNewLabel')?.value||'').trim()
  const nilai  = (document.getElementById('_struktNewNilai')?.value||'').trim()
  if(!label) return
  window._struktLines = window._struktLines||[]
  window._struktLines.push({ type:'text', label, nilai })
  document.getElementById('_struktNewLabel').value=''
  document.getElementById('_struktNewNilai').value=''
  _struktRenderExtra(); _struktRefreshPreview()
  document.getElementById('_struktNewLabel')?.focus()
}
function _struktAddSeparator(){
  window._struktLines = window._struktLines||[]
  window._struktLines.push({ type:'separator', label:'---', nilai:'' })
  _struktRenderExtra(); _struktRefreshPreview()
}
function _struktRemoveLine(i){ window._struktLines.splice(i,1); _struktRenderExtra(); _struktRefreshPreview() }
function _struktMoveUp(i){ if(i>0){[window._struktLines[i-1],window._struktLines[i]]=[window._struktLines[i],window._struktLines[i-1]];_struktRenderExtra();_struktRefreshPreview()} }
function _struktMoveDown(i){ if(i<window._struktLines.length-1){[window._struktLines[i],window._struktLines[i+1]]=[window._struktLines[i+1],window._struktLines[i]];_struktRenderExtra();_struktRefreshPreview()} }
function _struktRenderExtra(){
  const wrap=document.getElementById('_struktExtraWrap')
  if(!wrap) return
  if(!(window._struktLines||[]).length){ wrap.innerHTML=`<div style="font-size:11px;color:rgba(168,200,240,0.30);text-align:center;padding:10px 0;">Belum ada baris tambahan</div>`; return }
  wrap.innerHTML = window._struktLines.map((l,i)=>`
    <div style="display:flex;align-items:center;gap:8px;padding:8px 12px;
      background:${l.type==='separator'?'rgba(255,204,0,0.04)':'rgba(0,245,255,0.04)'};
      border:1px solid ${l.type==='separator'?'rgba(255,204,0,0.14)':'rgba(0,245,255,0.12)'};
      border-radius:10px;margin-bottom:6px;">
      <div style="flex:1;font-size:12px;color:${l.type==='separator'?'#ffcc00':'#e8f4ff'};font-family:'Courier New',monospace;">
        ${l.type==='separator'?'── Garis pemisah':l.label+(l.nilai?` <span style="color:#00ff88;">· ${l.nilai}</span>`:'')}
      </div>
      <div style="display:flex;gap:4px;">
        <button onclick="_struktMoveUp(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:12px;">↑</button>
        <button onclick="_struktMoveDown(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:12px;">↓</button>
        <button onclick="_struktRemoveLine(${i})" style="width:26px;height:26px;border-radius:6px;cursor:pointer;background:rgba(255,26,80,0.10);border:1px solid rgba(255,26,80,0.25);color:#ff4d6d;font-size:12px;">✕</button>
      </div>
    </div>`).join('')
}

// ── Simpan template ──
function _struktSimpanTemplate(){
  const header = document.getElementById('struktHeaderTA')?.value||''
  const footer = document.getElementById('struktFooterTA')?.value||''
  const sep    = document.getElementById('struktSepInput')?.value||'--------------------------------'
  localStorage.setItem('ps_struk_header',    header)
  localStorage.setItem('ps_struk_footer',    footer)
  localStorage.setItem('ps_struk_separator', sep)
  localStorage.setItem('ps_struk_extra_lines', JSON.stringify(window._struktLines||[]))
  // Update title top/bottom untuk kompatibilitas
  const headerLines = header.split('\n').filter(Boolean)
  if(headerLines[0]) localStorage.setItem('ps_title_top',    headerLines[0])
  if(headerLines[1]) localStorage.setItem('ps_title_bottom', headerLines[1])
  showPopup({typeNotif:'success',message:'✅ Template struk disimpan!\nAkan dipakai di semua struk berikutnya.'})
}


// ── Helper: warna badge per mode ──
function _modeBadgeStyle(mode){
  switch((mode||'').toLowerCase()){
    case 'billing':
      return 'background:rgba(255,154,60,0.18);color:#ff9a3c;border:1px solid rgba(255,154,60,0.45);'
    case 'countdown':
      return 'background:rgba(0,255,136,0.12);color:#00ff88;border:1px solid rgba(0,255,136,0.35);'
    case 'top_up_saldo':
      return 'background:rgba(0,245,255,0.15);color:#00f5ff;border:1px solid rgba(0,245,255,0.35);'
    default:
      return 'background:rgba(119,0,255,0.12);color:#aa66ff;border:1px solid rgba(119,0,255,0.30);'
  }
}
function _modeBadgeLabel(mode){
  switch((mode||'').toLowerCase()){
    case 'billing':    return '💰 BILLING'
    case 'countdown':  return '⏱ COUNTDOWN'
    case 'top_up_saldo': return '🎫 TOP UP'
    default: return String(mode||'-').toUpperCase()
  }
}

function buildReceiptTextFromData(data){
  if(!data) return ""

  const savedHeader = localStorage.getItem('ps_struk_header')
  const savedFooter = localStorage.getItem('ps_struk_footer')
  const savedSep    = localStorage.getItem('ps_struk_separator')
  const savedExtra  = (() => { try{ return JSON.parse(localStorage.getItem('ps_struk_extra_lines')||'[]') }catch(e){return []} })()

  const titleTop    = savedHeader ? savedHeader.split('\n')[0] : (localStorage.getItem("ps_title_top") || "ASTROPHILE")
  const titleBottom = savedHeader ? (savedHeader.split('\n')[1]||'') : (localStorage.getItem("ps_title_bottom") || "PLAYSTATION BILLING")
  const sep         = savedSep || "--------------------------------"
  const footer      = savedFooter || "Terima kasih"

  const items = Array.isArray(data.items) ? data.items : []
  const paymentLabel = data.paymentMethod ? getPaymentLabel(data.paymentMethod) : "Cash"

  const lines = [
    titleTop,
    ...(titleBottom ? [titleBottom] : []),
    sep,
    "TV: " + (data.tv || "-"),
    ...(data.namaPelanggan ? ["PELANGGAN: " + data.namaPelanggan] : []),
    "MODE: " + String(data.mode || "-").toUpperCase(),
    "TIPE: " + (data.type || "-"),
    "TANGGAL: " + (data.date || "-"),
    sep,
    "Main: " + formatRupiah(data.totalMain || data.total || 0),
    "Tambahan: " + formatRupiah(data.totalTambahan || 0),
    sep,
    "Item Tambahan:"
  ]

  if(items.length){
    items.forEach(item => {
      lines.push("- " + (item.nama || "-") + " | " + formatRupiah(item.harga || 0))
    })
  }else{
    lines.push("Tidak ada tambahan")
  }

  // Baris extra dari template
  if(savedExtra.length){
    lines.push(sep)
    savedExtra.forEach(l=>{
      if(l.type==='separator') lines.push(sep)
      else lines.push(l.label + (l.nilai ? ': ' + l.nilai : ''))
    })
  }

  lines.push(sep)

  if((data.diskon||0) > 0 || (data.potongPoin||0) > 0){
    lines.push("SUBTOTAL: " + formatRupiah(data.totalSebelumDiskon||data.total))
    if(data.diskon > 0)     lines.push("DISKON: -" + formatRupiah(data.diskon))
    if(data.potongPoin > 0) lines.push("TUKAR POIN: -" + formatRupiah(data.potongPoin))
  }

  lines.push("TOTAL BAYAR: " + formatRupiah(data.total || 0))
  lines.push("PEMBAYARAN: " + paymentLabel)

  if(data.paymentMethod === "cash" && Number(data.cashAmount) > 0){
    lines.push("UANG BAYAR: " + formatRupiah(data.cashAmount))
    lines.push("KEMBALIAN: " + formatRupiah(Math.max(0, Number(data.cashAmount || 0) - Number(data.total || 0))))
  }

  if(data.memberNama){
    lines.push(sep)
    lines.push("MEMBER: " + data.memberNama)
    if(data.poinDapat > 0)   lines.push("POIN DAPAT: +" + data.poinDapat + " poin")
    if(data.poinDipakai > 0) lines.push("POIN DITUKAR: -" + data.poinDipakai + " poin")
  }

  lines.push(sep)
  lines.push(...footer.split('\n'))
  lines.push("")

  return lines.join("\n")
}

function receivePrinterStatus(status){
  const parsed = parsePrinterBridgeStatus(status, getSavedPrinterMac())
  setPrinterStatusState(parsed)
}

window.receivePrinterStatus = receivePrinterStatus
window.onPrinterStatus = receivePrinterStatus
window.setPrinterStatusFromAndroid = receivePrinterStatus

// -- Native countdown background alarm helpers --
function callNativeCountdownBridge(method, ...args){
  const candidates = {
    schedule: ["scheduleCountdownAlarm", "setCountdownAlarm", "scheduleNativeCountdownAlarm"],
    cancel: ["cancelCountdownAlarm", "clearCountdownAlarm", "cancelNativeCountdownAlarm"],
    stopTone: ["stopNativeAlarmTone", "stopBackgroundAlarmTone", "stopCountdownAlarmTone"],
    isToneActive: ["isNativeAlarmRinging", "isBackgroundAlarmToneActive", "isCountdownAlarmToneActive"],
    canExact: ["canScheduleExactCountdownAlarms", "canScheduleExactAlarms", "canUseExactCountdownAlarm"],
    requestExact: ["requestExactCountdownAlarmPermission", "requestExactAlarmPermission", "openExactAlarmSettings"],
    setVisible: ["setCountdownPageForeground", "setPageForeground", "setNativePageForeground"]
  }

  const methods = candidates[method] || []
  for(const name of methods){
    if(bridgeHas(name)){
      return callBridge(name, ...args)
    }
  }
  return null
}

function getCountdownFinishAt(i){
  if(!state[i] || state[i].mode !== "countdown" || !state[i].start || !state[i].duration){
    return 0
  }
  // Tidak cek expired - biarkan alarm native tetap terdaftar meski timer UI sudah habis
  return Number(state[i].start || 0) + (Number(state[i].duration || 0) * 1000)
}

function isPageForeground(){
  try{
    if(typeof document !== "undefined" && document.visibilityState === "hidden") return false
  }catch(err){}

  try{
    if(typeof document !== "undefined" && typeof document.hasFocus === "function"){
      return document.hasFocus()
    }
  }catch(err){}

  return true
}

function scheduleNativeCountdownForUnit(i){
  const finishAt = getCountdownFinishAt(i)
  if(!finishAt){
    callNativeCountdownBridge("cancel", String(i))
    return false
  }
  maybeRequestExactAlarmPermissionOnce()
  callNativeCountdownBridge("schedule", String(i), String(finishAt))
  return true
}

function cancelNativeCountdownForUnit(i, stopTone = false){
  callNativeCountdownBridge("cancel", String(i))
  if(stopTone){
    callNativeCountdownBridge("stopTone")
  }
}

function pushNativePageVisibility(){
  callNativeCountdownBridge("setVisible", isPageForeground() ? "true" : "false")
}

function syncNativeCountdownAlarms(){
  let hasActiveCountdown = false

  pushNativePageVisibility()

  for(let i = 1; i <= units; i++) {
    const scheduled = scheduleNativeCountdownForUnit(i)
    if(scheduled){
      hasActiveCountdown = true
    }
  }

  if(!hasActiveCountdown || isPageForeground()){
    callNativeCountdownBridge("stopTone")
  }
}

function stopNativeAlarmTone(){
  callNativeCountdownBridge("stopTone")
}

function isNativeAlarmToneActive(){
  const result = callNativeCountdownBridge("isToneActive")
  return result === true || String(result || "").toLowerCase() === "true"
}

function maybeRequestExactAlarmPermissionOnce(){
  try{
    const canExact = callNativeCountdownBridge("canExact")
    const exactAllowed = canExact === true || String(canExact || "").toLowerCase() === "true"
    if(exactAllowed){
      localStorage.setItem("ps_exact_alarm_permission_prompted", "1")
      return true
    }

    if(localStorage.getItem("ps_exact_alarm_permission_prompted") === "1"){
      return false
    }

    localStorage.setItem("ps_exact_alarm_permission_prompted", "1")
    callNativeCountdownBridge("requestExact")
  }catch(err){}
  return false
}

// -- Native backup / restore bridge helpers for Sketchware Pro --
function decodeBase64Utf8(base64){
  try{
    return decodeURIComponent(escape(atob(String(base64 || ""))))
  }catch(err){
    try{
      return atob(String(base64 || ""))
    }catch(error){
      return ""
    }
  }
}

function nativeSaveFile(filename, content, mimeType){
  const base64 = encodeBase64Utf8(content)
  const candidates = [
    ["saveFileBase64", [filename, mimeType || "application/octet-stream", base64]],
    ["saveBackupFile", [filename, mimeType || "application/octet-stream", base64]],
    ["nativeSaveFile", [filename, mimeType || "application/octet-stream", base64]],
    ["downloadBase64", [filename, mimeType || "application/octet-stream", base64]]
  ]

  for(const [method, args] of candidates){
    if(bridgeHas(method)){
      callBridge(method, ...args)
      return true
    }
  }
  return false
}

function requestNativeRestoreFile(kind){
  const candidates = [
    ["pickRestoreFile", [kind]],
    ["requestRestoreFile", [kind]],
    ["openRestoreFile", [kind]],
    ["pickJsonFile", [kind]]
  ]

  for(const [method, args] of candidates){
    if(bridgeHas(method)){
      callBridge(method, ...args)
      return true
    }
  }
  return false
}

function restorePinOperatorFromText(rawText){
  try{
    let data = JSON.parse(rawText)

    if(data.admin_pin){
      LOCK_PIN = decodePIN(data.admin_pin)
      localStorage.setItem("ps_lock_pin", encodePIN(LOCK_PIN))
      showPopup({ typeNotif:"success", message:"PIN Operator berhasil dipulihkan" })
    }else{
      showPopup({ typeNotif:"warning", message:"File backup operator tidak valid" })
    }
  }catch(err){
    showPopup({ typeNotif:"warning", message:"File backup operator rusak" })
  }
}

function restoreSuperAdminPinFromText(rawText){
  try{
    let data = JSON.parse(rawText)

    if(data.superadmin_pin){
      SUPER_ADMIN_PIN = decodePIN(data.superadmin_pin)
      localStorage.setItem("ps_superadmin_pin", encodePIN(SUPER_ADMIN_PIN))
      showPopup({ typeNotif:"success", message:"PIN Super Admin berhasil dipulihkan" })
    }else{
      showPopup({ typeNotif:"warning", message:"File backup Super Admin tidak valid" })
    }
  }catch(err){
    showPopup({ typeNotif:"warning", message:"File backup Super Admin rusak" })
  }
}

function restoreHistoryFromText(rawText){
  try{
    const data = JSON.parse(rawText)

    if(!Array.isArray(data)){
      showPopup({ typeNotif:"warning", message:"File backup transaksi tidak valid" })
      return
    }

    history = [...history, ...data]
    save()
    resetHistoryHarian()

    showPopup({ typeNotif:"success", message:"Backup transaksi berhasil dipulihkan" })

    renderHistoryPage("all")
  }catch(error){
    showPopup({ typeNotif:"warning", message:"File backup transaksi rusak atau format salah" })
  }
}

function restoreAllDataFromText(rawText){
  try{
    const parsed = JSON.parse(rawText)
    let storageMap = null

    if(parsed && typeof parsed === "object" && parsed.storage && typeof parsed.storage === "object"){
      storageMap = parsed.storage
    }else if(parsed && typeof parsed === "object"){
      storageMap = {}
      if(parsed.units !== undefined) storageMap.ps_units = JSON.stringify(parsed.units)
      if(parsed.prices !== undefined) storageMap.ps_prices = JSON.stringify(parsed.prices)
      if(parsed.state !== undefined) storageMap.ps_state = JSON.stringify(parsed.state)
      if(parsed.history !== undefined) storageMap.ps_history = JSON.stringify(parsed.history)
    }

    if(!storageMap || typeof storageMap !== "object"){
      showPopup({ typeNotif:"warning", message:"File backup semua data tidak valid" })
      return
    }

    applyRestoredStorageMap(storageMap)

    showPopup({
      typeNotif:"success",
      message:"Restore semua data berhasil. Aplikasi akan dimuat ulang."
    })

    setTimeout(() => {
      location.reload()
    }, 1200)
  }catch(error){
    showPopup({ typeNotif:"warning", message:"File restore semua data rusak atau format salah" })
  }
}

function handleNativeRestoreFile(kind, base64Content){
  const text = decodeBase64Utf8(base64Content)

  if(!text){
    showPopup({ typeNotif:"warning", message:"File restore kosong atau gagal dibaca" })
    return
  }

  switch(String(kind || "")){
    case "pin_operator":
      restorePinOperatorFromText(text)
      break
    case "pin_superadmin":
      restoreSuperAdminPinFromText(text)
      break
    case "history":
      restoreHistoryFromText(text)
      break
    case "all_data":
      restoreAllDataFromText(text)
      break
    default:
      showPopup({ typeNotif:"warning", message:"Jenis restore tidak dikenali" })
  }
}

