// -- Android-compatible universal downloader (#2) --
function androidDownload(filename, content, mimeType){
  if(nativeSaveFile(filename, content, mimeType)){
    return
  }

  try {
    const blob = new Blob([content], { type: mimeType })
    const url  = URL.createObjectURL(blob)
    const a    = document.createElement("a")
    a.href     = url
    a.download = filename
    a.style.display = "none"
    document.body.appendChild(a)
    a.click()
    setTimeout(() => { URL.revokeObjectURL(url); a.remove() }, 500)
  } catch(err) {
    try {
      const encoded = encodeURIComponent(content)
      const a = document.createElement("a")
      a.href = "data:" + mimeType + "," + encoded
      a.download = filename
      document.body.appendChild(a)
      a.click()
      setTimeout(() => a.remove(), 500)
    } catch(e2) {
      showPopup({ typeNotif:"warning", message:"Gagal mengunduh. Coba simpan secara manual." })
    }
  }
}

function exportHistoryFile(type = "json"){
  const mode = document.getElementById("historyModeInput")?.value || "all"
  const data = mode === "today" ? historyToday : history

  if(!Array.isArray(data) || data.length === 0){
    showPopup({
      typeNotif:"warning",
      message:"Tidak ada data untuk diexport"
    })
    return
  }

  if(type === "json"){
    const content = JSON.stringify(data, null, 2)
    const fname   = mode === "today" ? "transaksi_hari_ini.json" : "riwayat_transaksi.json"
    androidDownload(fname, content, "application/json")
    return
  }

  const header = ["TV","Mode","Tipe","Tanggal","Total Main","Total Tambahan","Grand Total"]
  const rows = data.map(item => [
    item.tv, item.mode, item.type, item.date,
    item.totalMain || 0, item.totalTambahan || 0, item.total || 0
  ])
  const csv = [header, ...rows]
    .map(row => row.map(val => `"${String(val).replace(/"/g, '""')}"`).join(","))
    .join("\n")
  const fname = mode === "today" ? "transaksi_hari_ini.csv" : "riwayat_transaksi.csv"
  androidDownload(fname, csv, "text/csv;charset=utf-8;")
}

function exportHistoryToExcel(){
  const startDate = document.getElementById("historyStartDate")?.value || ""
  const endDate = document.getElementById("historyEndDate")?.value || ""

  let data = [...history]

  if(startDate){
    const start = new Date(startDate)
    start.setHours(0,0,0,0)
    data = data.filter(item => {
      const d = new Date(item.date)
      return !isNaN(d) && d >= start
    })
  }

  if(endDate){
    const end = new Date(endDate)
    end.setHours(23,59,59,999)
    data = data.filter(item => {
      const d = new Date(item.date)
      return !isNaN(d) && d <= end
    })
  }

  if(!data.length){
    showPopup({
      typeNotif:"warning",
      message:"Tidak ada data transaksi untuk diexport ke Excel"
    })
    return
  }

  const header = ["TV","Mode","Tipe","Tanggal","Total Main","Total Tambahan","Grand Total"]
  const rows = data.map(item => [
    item.tv,
    item.mode,
    item.type,
    item.date,
    item.totalMain || 0,
    item.totalTambahan || 0,
    item.total || 0
  ])

  const csv = [header, ...rows]
    .map(row => row.map(val => `"${String(val).replace(/"/g, '""')}"`).join(","))
    .join("\n")

  androidDownload("riwayat_transaksi.xls", csv, "application/vnd.ms-excel;charset=utf-8;")
}

