function simpanEditHistory(index, mode){
  const source = mode === "today" ? historyToday : history
  const item = source[index]
  if(!item) return

  const newType = document.getElementById("editType")?.value || item.type
  const newDate = document.getElementById("editDate")?.value || item.date
  const newMain = Number(document.getElementById("editTotalMain")?.value)
  const newTambahan = Number(document.getElementById("editTotalTambahan")?.value)

  if(!Number.isFinite(newMain) || newMain < 0 || !Number.isFinite(newTambahan) || newTambahan < 0){
    showPopup({ typeNotif:"warning", message:"Nilai tidak valid" })
    return
  }

  item.type = newType
  item.date = newDate
  item.totalMain = newMain
  item.totalTambahan = newTambahan
  item.total = newMain + newTambahan

  if(mode === "today"){
    const hi = history.findIndex(x => x.tv === item.tv && x.date === item.date && x.mode === item.mode)
    if(hi !== -1) history[hi] = { ...item }
  }

  save()
  hitungOmzet()
  addOperatorLog(_getCurrentRole(), 'edit_transaksi', 'TV ' + (item.tv||'?') + ' · ' + (item.type||'-') + ' · Rp ' + (item.total||0).toLocaleString('id-ID') + (item.id ? ' · ' + item.id : ''))
  closePopup()
  renderHistoryPage(mode)
  showPopup({ typeNotif:"success", message:"Transaksi berhasil diedit" })
}

let _pendingDeleteHistory = null

function showDeleteHistoryModal(index, mode){
  const source = mode === "today" ? historyToday : history
  const item = source[index]
  if(!item) return

  _pendingDeleteHistory = { index, mode }

  const label = `TV ${item.tv || '?'} · ${item.type || '-'} · Rp ${(item.total || 0).toLocaleString('id-ID')}`
  const textEl = document.getElementById("deleteModalHistoryText")
  if(textEl) textEl.textContent = `Hapus transaksi: ${label}?`

  const modal = document.getElementById("deleteModalHistory")
  if(modal) modal.classList.add("show")
}

function closeDeleteModalHistory(){
  const modal = document.getElementById("deleteModalHistory")
  if(modal) modal.classList.remove("show")
  _pendingDeleteHistory = null
}

function confirmDeleteHistory(){
  if(!_pendingDeleteHistory){
    closeDeleteModalHistory()
    return
  }
  const { index, mode } = _pendingDeleteHistory
  closeDeleteModalHistory()
  deleteHistoryItem(index, mode)
}

function deleteHistoryItem(index, mode = "all"){
  if(mode === "today"){
    const item = historyToday[index]
    if(!item) return

    addOperatorLog(_getCurrentRole(), 'hapus_transaksi', 'TV ' + (item.tv||'?') + ' · ' + (item.type||'-') + ' · Rp ' + (item.total||0).toLocaleString('id-ID') + (item.id ? ' · ' + item.id : ''))

    historyToday.splice(index, 1)

    const historyIndex = history.findIndex(x =>
      x.tv === item.tv &&
      x.date === item.date &&
      x.total === item.total
    )

    if(historyIndex !== -1){
      history.splice(historyIndex, 1)
    }

    save()
    renderHistoryPage("today")
    hitungOmzet()
    return
  }

  if(!history[index]) return

  const _delItem = history[index]
  addOperatorLog(_getCurrentRole(), 'hapus_transaksi', 'TV ' + (_delItem.tv||'?') + ' · ' + (_delItem.type||'-') + ' · Rp ' + (_delItem.total||0).toLocaleString('id-ID') + (_delItem.id ? ' · ' + _delItem.id : ''))
  history.splice(index, 1)
  save()
  resetHistoryHarian()
  renderHistoryPage("all")
  hitungOmzet()
  // Sync ke Firebase setelah hapus
  try{
    if(window._fbDb){
      window._fbDb.ref('transaksiHistory').set(JSON.stringify(history)).catch(()=>{})
    }
  }catch(e){}
}


