function renderHistoryPage(mode = "all"){

  // ── Baca & merge dari Firebase di background (non-blocking) ──
  // Render lokal DULU agar halaman langsung tampil, Firebase merge di background
  if(mode === "all" && window._fbDb && !window._historyFbSyncing){
    window._historyFbSyncing = true
    try{
      window._fbDb.ref('transaksiHistory').once('value').then(snap => {
        window._historyFbSyncing = false
        if(!snap.exists()){ return }
        try{
          const raw = snap.val()
          const fbHistory = typeof raw === 'string' ? JSON.parse(raw) : (Array.isArray(raw) ? raw : [])
          if(!fbHistory.length){ return }
          let changed = false
          fbHistory.forEach(fbItem => {
            const exists = history.some(l =>
              (l.id && l.id === fbItem.id) ||
              (l.ts && l.ts === fbItem.ts && l.tv === fbItem.tv)
            )
            if(!exists){ history.push(fbItem); changed = true }
          })
          if(!changed){ return }
          history.sort((a,b) => (b.ts||0) - (a.ts||0))
          // Pakai _origSetItem agar tidak trigger Firebase sync balik (circular write)
          _origSetItem('ps_history', JSON.stringify(history))
          if(typeof hitungOmzet === 'function') hitungOmzet()
          // Update tampilan tanpa re-render penuh — cukup update omzet strip
          // renderHistoryPage('all') dihapus — mencegah recursive loop
        }catch(e){ window._historyFbSyncing = false }
      }).catch(()=>{ window._historyFbSyncing = false })
    }catch(e){ window._historyFbSyncing = false }
    // TIDAK return di sini — lanjut render lokal terlebih dahulu
  }

  const sourceRaw = mode === "today" ? [...historyToday] : [...history]

  let filtered = [...sourceRaw]
  const modeLabel = mode === "today" ? "Transaksi Hari Ini" : "Riwayat Transaksi"
  
  const subLabel = mode === "today"
  ? "Daftar transaksi hari ini dengan info omzet kemarin dan hitung mundur reset otomatis."
  : "Semua transaksi tersimpan, lengkap dengan filter, pencarian, edit, hapus, backup, restore, dan export Excel."

  const noteHtml = mode === "today"
  ? `
      <div class="history-operator-note">
        <strong>Note Operator:</strong><br>
        Halaman ini hanya menampilkan transaksi hari ini.<br>
        Data transaksi hari ini akan reset otomatis pada jam 00:00.<br>
        <div class="history-reset-live">
          Reset dalam: <span id="historyResetCountdown">00:00:00</span>
        </div>
      </div>
    `
    : `
      <div class="history-operator-note">
        <strong>Note Operator:</strong><br>
        Halaman ini menyimpan semua transaksi yang pernah masuk ke sistem.
      </div>
    `

  const stats = getHistoryStats(history)

  const toolbarHtml = `
    <input type="hidden" id="historyModeInput" value="${mode}">

    <div class="history-toolbar">
      <div class="history-search-box">
        <input type="text" id="historySearchInput" placeholder="Cari TV / tipe / mode / tanggal..." oninput="applyHistoryFilter()">
      </div>

      ${mode === "all" ? `
        <div class="history-date-filter">
          <input type="date" id="historyStartDate" onchange="applyHistoryFilter()">
          <input type="date" id="historyEndDate" onchange="applyHistoryFilter()">
        </div>
        <div class="date-filter-note" style="flex-basis:100%;">
          📅 <strong>Catatan:</strong> Isi <strong>Tanggal Mulai</strong> dan <strong>Tanggal Akhir</strong> untuk menyaring transaksi berdasarkan rentang waktu tertentu. Kosongkan keduanya untuk menampilkan semua data. Filter tanggal bisa dikombinasikan dengan pencarian teks di atas.
        </div>
      ` : `
        <div class="history-date-filter single-note-filter">
          <div class="history-today-badge">Only Today</div>
        </div>
      `}

<div class="history-export-group">
  ${mode === "all" ? `
    <button class="history-export-btn" onclick="exportHistoryToExcel()">📊 Export Excel</button>
    <button class="history-export-btn" onclick="backupHistoryData()">💾 Backup Transaksi</button>
    <button class="history-export-btn" onclick="openHistoryBackupRestore()">📂 Upload Backup</button>
    <input type="file" id="historyBackupRestoreInput" accept=".json" style="display:none;">
  ` : ""}
</div>
    </div>
  `

  const summaryHtml = mode === "today" ? `
  <div class="history-summary-grid">
    <div class="history-summary-card">
      <div class="history-summary-label">Total Pendapatan</div>
      <div class="history-summary-value">${formatRupiah(stats.totalPendapatan)}</div>
    </div>
  </div>
` : `
  <div class="history-summary-grid">
    <div class="history-summary-card">
      <div class="history-summary-label">Total Pendapatan</div>
      <div class="history-summary-value">${formatRupiah(stats.totalPendapatan)}</div>
    </div>

    <div class="history-summary-card">
      <div class="history-summary-label">Omzet Bulanan</div>
      <div class="history-summary-value">${formatRupiah(stats.omzetBulanan)}</div>
    </div>

    <div class="history-summary-card">
      <div class="history-summary-label">Omzet Tahunan</div>
      <div class="history-summary-value">${formatRupiah(stats.omzetTahunan)}</div>
    </div>
  </div>
`


  // -- buildCards dengan pagination --
  const buildCards = (list, page) => {
    if(!list.length){
      return `<div class="history-empty">Belum ada data transaksi.</div>`
    }

    const totalPages = Math.ceil(list.length / HIST_PER_PAGE)
    const safePage = Math.max(1, Math.min(page, totalPages))
    const start = (safePage - 1) * HIST_PER_PAGE
    const slice = list.slice(start, start + HIST_PER_PAGE)

    const cardsHtml = slice.map((item) => `
          <div class="history-page-card">
            <div class="history-card-top">
              <h4>${item.mode==='top_up_saldo' ? '🎫 SALDO' : 'TV '+(item.tv||'-')}</h4>
              <span class="history-mode-badge" style="${_modeBadgeStyle(item.mode)}">${_modeBadgeLabel(item.mode)}</span>
            </div>
            ${item.id ? `
            <div class="history-page-row">
              <div class="history-page-label" style="color:var(--text-muted);font-size:10px;">ID Transaksi</div>
              <div class="history-page-value" style="font-size:10px;font-family:'Courier New',monospace;color:var(--cyan-accent,#00f5ff);letter-spacing:0.5px;">${item.id}</div>
            </div>` : ''}
            ${item.mode==='top_up_saldo'&&item.saldoMenit ? `
            <div class="history-page-row">
              <div class="history-page-label">Top Up</div>
              <div class="history-page-value" style="color:#00f5ff;font-weight:700;">+${item.saldoMenit} mnt (${item.saldoJenis||item.type||'-'})</div>
            </div>` : ''}
            <div class="history-page-row">
              <div class="history-page-label">Tipe</div>
              <div class="history-page-value">${item.type || "-"}</div>
            </div>
            <div class="history-page-row">
              <div class="history-page-label">Tanggal</div>
              <div class="history-page-value">${item.date || "-"}</div>
            </div>
            <div class="history-page-row">
              <div class="history-page-label">Main</div>
              <div class="history-page-value">${formatRupiah(item.totalMain || 0)}</div>
            </div>
            <div class="history-page-row">
              <div class="history-page-label">Tambahan</div>
              <div class="history-page-value">${formatRupiah(item.totalTambahan || 0)}</div>
            </div>
            <div class="history-page-row">
              <div class="history-page-label">Grand Total</div>
              <div class="history-page-value history-page-total">${formatRupiah(item.total || 0)}</div>
            </div>
            ${(item.diskon>0||item.potongPoin>0) ? `
              <div class="history-page-row" style="border-top:1px dashed rgba(0,245,255,0.10);margin-top:4px;padding-top:4px;">
                <div class="history-page-label" style="color:var(--text-dim);font-size:10px;">Subtotal</div>
                <div class="history-page-value" style="font-size:11px;text-decoration:line-through;color:var(--text-dim);">${formatRupiah(item.totalSebelumDiskon||item.total)}</div>
              </div>
            ` : ''}
            ${item.diskon > 0 ? `
              <div class="history-page-row">
                <div class="history-page-label" style="color:var(--lime-accent);font-size:10px;">Diskon</div>
                <div class="history-page-value" style="color:var(--lime-accent);font-size:11px;">-${formatRupiah(item.diskon)}</div>
              </div>
            ` : ''}
            ${item.potongPoin > 0 ? `
              <div class="history-page-row">
                <div class="history-page-label" style="color:var(--orange-warn);font-size:10px;">⭐ Tukar Poin</div>
                <div class="history-page-value" style="color:var(--orange-warn);font-size:11px;">-${formatRupiah(item.potongPoin)}</div>
              </div>
            ` : ''}
            ${item.memberNama ? `
              <div class="history-page-row">
                <div class="history-page-label" style="color:var(--text-muted);font-size:10px;">👤 Member</div>
                <div class="history-page-value" style="font-size:11px;">${escapeHTML(item.memberNama)}</div>
              </div>
            ` : ''}
            ${item.poinDapat > 0 ? `
              <div class="history-page-row">
                <div class="history-page-label" style="color:var(--text-muted);font-size:10px;">Poin Dapat</div>
                <div class="history-page-value" style="color:var(--orange-warn);font-size:11px;">+${item.poinDapat} poin</div>
              </div>
            ` : ''}
            <div class="history-page-row">
              <div class="history-page-label">Pembayaran</div>
              <div class="history-page-value">${item.paymentMethod ? getPaymentLabel(item.paymentMethod) : '💵 Cash'}</div>
            </div>
            <div class="history-card-actions">
              <button class="history-action-btn" onclick="editHistoryItem(${sourceRaw.indexOf(item)}, '${mode}')">✏️ Edit</button>
              <button class="history-action-btn history-action-delete" onclick="showDeleteHistoryModal(${sourceRaw.indexOf(item)}, '${mode}')">🗑 Hapus</button>
              <button class="history-print-btn" onclick="printHistoryReceipt(${sourceRaw.indexOf(item)}, '${mode}')">🧾 Cetak Struk</button>
            </div>
          </div>
    `).join("")

    const paginatorHtml = totalPages > 1 ? `
      <div class="hist-paginator">
        <button class="hist-page-btn" onclick="goHistoryPage('${mode}',${safePage - 1})" ${safePage <= 1 ? 'disabled' : ''}>◀ Prev</button>
        <span class="hist-page-info">Halaman <strong>${safePage}</strong> / ${totalPages}</span>
        <button class="hist-page-btn" onclick="goHistoryPage('${mode}',${safePage + 1})" ${safePage >= totalPages ? 'disabled' : ''}>Next ▶</button>
      </div>
      <div class="hist-trx-count">${list.length} TRANSAKSI</div>
    ` : `
      <div class="hist-paginator-simple">${list.length} TRANSAKSI</div>
    `

    return `
      <div class="history-page-grid">${cardsHtml}</div>
      ${paginatorHtml}
    `
  }

  const _curPage = window._histPage[mode] || 1
  showInternalPage(
    modeLabel,
    subLabel,
    `
      ${noteHtml}
      ${summaryHtml}
      ${toolbarHtml}
      <div id="historyResultWrapper">
        ${buildCards(filtered.slice().reverse(), _curPage)}
      </div>

      <div id="deleteModalHistory" class="delete-modal">
        <div class="delete-modal-box">
          <div class="delete-modal-title">⚠️ Konfirmasi Hapus</div>
          <div class="delete-modal-text" id="deleteModalHistoryText">Yakin ingin menghapus transaksi ini?</div>
          <div class="delete-modal-note">Data tidak bisa dikembalikan</div>
          <div class="delete-modal-actions">
            <button class="delete-btn-no" onclick="closeDeleteModalHistory()">Batal</button>
            <button class="delete-btn-yes" onclick="confirmDeleteHistory()">Hapus</button>
          </div>
        </div>
      </div>
    `
  )
  try{
    const pv = document.getElementById('pageView')
    if(pv){ const b=document.createElement('div'); b.innerHTML=_fbCloudStatusBadge('transaksiHistory'); pv.insertBefore(b.firstElementChild||b,pv.children[1]||null) }
  }catch(e){}
  if(mode === "today"){
    updateHistoryResetCountdown()

    if(window.historyResetCountdownInterval){
      clearInterval(window.historyResetCountdownInterval)
    }

    window.historyResetCountdownInterval = setInterval(() => {
      updateHistoryResetCountdown()
    }, 1000)
  }else{
    if(window.historyResetCountdownInterval){
      clearInterval(window.historyResetCountdownInterval)
      window.historyResetCountdownInterval = null
    }
  }
}













