function _berikanBonusWaktu(tvUnit){
  const jam   = parseInt(document.getElementById('bonusJam')?.value||'0')
  const menit = parseInt(document.getElementById('bonusMenit')?.value||'0')
  const totalMenit = (jam*60) + menit

  if(totalMenit <= 0){ showPopup({typeNotif:'warning',message:'⚠️ Isi durasi bonus dulu'}); return }

  document.getElementById('bonusWaktuPopup')?.remove()

  if(!state[tvUnit] || state[tvUnit].mode !== 'countdown') return

  const detikBonus = totalMenit * 60

  // Tambah ke duration — timer langsung bertambah
  state[tvUnit].duration += detikBonus

  // Catat bonus di state agar tidak dihitung di harga saat stop
  state[tvUnit]._bonusDetik = (state[tvUnit]._bonusDetik || 0) + detikBonus

  save()
  syncNativeCountdownAlarms()

  addOperatorLog(_getCurrentRole(), 'bonus_waktu',
    'TV '+tvUnit+' · +'+(jam?jam+'j ':'')+totalMenit+'m bonus gratis'+(state[tvUnit].namaPelanggan?' · '+state[tvUnit].namaPelanggan:''))

  showPopup({typeNotif:'success',
    message: '🎁 Bonus '+(jam?jam+'j ':'')+totalMenit+'m diberikan!\nTV '+tvUnit+(state[tvUnit].namaPelanggan?'\n⭐ '+state[tvUnit].namaPelanggan:'')+'\n💰 Tidak dihitung di transaksi'})
}

function addTime(i,min){

if(state[i].mode!="countdown") return

// ❌ jika waktu sudah habis tidak boleh tambah waktu
if(state[i].expired){
showPopup({
typeNotif:"warning",
message:"Waktu sudah habis, silakan stop transaksi."
})
return
}

state[i].duration += min*60

addOperatorLog(_getCurrentRole(), 'add_time', `TV ${i} · +${min} menit`)
save()
syncNativeCountdownAlarms()

}

