function startCountdown(i){

if(state[i].start) return

// Baca dari localStorage key khusus — Firebase tidak bisa sentuh key ini
if(!state[i].duration){
  showPopup({
    typeNotif: "warning",
    message: "Masukkan menit dulu sebelum mulai countdown"
  })
  return
}

// Wajib pilih status bayar sebelum start
if(!state[i]._bayarStatus){
  showPopup({ typeNotif:'warning', message:'Pilih status pembayaran dulu (Belum Bayar / Sudah Bayar)' })
  document.getElementById('btnBelumBayar'+i)?.scrollIntoView({behavior:'smooth',block:'center'})
  return
}

state[i].mode="countdown"
state[i].start=Date.now()
state[i].expired=false
scheduleNativeAlarm(i, Date.now() + (state[i].duration * 1000))
state[i].price = getConsolePriceByType(state[i].type)

// Update DOM dengan null-safe — tidak crash jika DOM belum siap
const _sb = document.getElementById("startBtn"+i)
const _tb = document.getElementById("stopBtn"+i)
const _ib = document.getElementById("input"+i)
if(_sb) _sb.disabled = true
if(_tb) _tb.disabled = false
if(_ib) _ib.disabled = true
setDropDisabled("modeWrap"+i, true)
setDropDisabled("typeWrap"+i, true)
_setTvCtrlDisabled(i, true)
if(!Array.isArray(state[i].items)){
  state[i].items = []
}
saveNow()
syncNativeCountdownAlarms()

// Direct write ke Firebase — TV overlay langsung aktif tanpa delay
if(_fbDb && _fbOnline){
  _fbDb.ref("settings/activeSessions/" + i).set({
    active:        true,
    mode:          "countdown",
    start:         state[i].start,
    duration:      state[i].duration || 0,
    expired:       false,
    type:          state[i].type || "",
    price:         state[i].price || 0,
    namaPelanggan: state[i].namaPelanggan || _loadNamaPelanggan(i) || ""
  })
}

addOperatorLog(_getCurrentRole(), 'start_countdown', 'TV ' + i + ' · ' + Math.floor((state[i].duration||0)/60) + ' menit · ' + (state[i].type||'-'))
setTimeout(_syncActiveSessionsToFirebase, 300)

}

function stopCountdown(i){
  let cardEl = document.getElementById("card" + i)
  if(cardEl){
    cardEl.classList.remove("billing-active-card")
  }

  if(!state[i] || !state[i].start) return
  tempStateBackup = JSON.parse(JSON.stringify(state[i]))

  let diff = Math.floor((Date.now() - state[i].start) / 1000)
  if(diff < 0) diff = 0

  let durasiAwal = state[i].duration
  let durasiPakai = Math.min(diff, durasiAwal)
  if(!isFinite(durasiPakai) || durasiPakai < 0) durasiPakai = 0

  // Fallback: ambil harga dari type, state.price, atau dropdown
  const typeElC = document.getElementById("type" + i)
  const resolvedTypeC = state[i].type || (typeElC ? typeElC.value : "") || "PS3"
  if(!state[i].type) state[i].type = resolvedTypeC
  // Bonus waktu gratis: dikurangi dari DURASI TOTAL (bukan dari elapsed)
  // agar harga dihitung dari durasi asli yang dibeli customer
  const _bonusDetik = state[i]._bonusDetik || 0
  const durasiOriginal = Math.max(0, durasiAwal - _bonusDetik)
  let jam = Math.ceil(durasiOriginal / 3600)
  let priceC = state[i].price || getConsolePriceByType(resolvedTypeC)
  let total = jam * priceC

  addOperatorLog(_getCurrentRole(), 'stop_countdown', 'TV ' + i + ' · ' + (state[i].type||'-') + ' · ' + Math.floor(durasiAwal/60) + ' menit')
if(_fbDb) _fbDb.ref("settings/activeSessions/" + (i)).set({ active: true, mode: "processing", processing: true })

  const _snapNamaCd = (document.getElementById("namaPelanggan"+i)?.value.trim()) || state[i].namaPelanggan || _loadNamaPelanggan(i) || ""
if(_snapNamaCd) sessionStorage.setItem("_pending_nama_tv_"+i, _snapNamaCd)
else sessionStorage.removeItem("_pending_nama_tv_"+i)

  // ── Cek apakah sesi ini memakai saldo waktu ──
  const _isSaldoSesi = !!(state[i]._saldoId && state[i]._saldoMenit)
  const _saldoIdSnap    = state[i]._saldoId    || null
  const _saldoMenitSnap = state[i]._saldoMenit || 0
  const _saldoPsTypeSnap= state[i]._saldoPsType|| null
  // Jika pakai saldo: total = 0, tidak perlu bayar cash
  if(_isSaldoSesi){ total = 0; jam = 0 }

pendingTransaction = {
    tv:i,
    mode:"countdown",
    type:state[i].type,
    jam,
    total,
    durasi: durasiPakai,
    date:new Date().toLocaleString(),
    day:new Date().toDateString(),
    ts: Date.now(),
    items: Array.isArray(state[i].items) ? [...state[i].items] : [],
    _itemsAtStop: Array.isArray(state[i].items) ? [...state[i].items] : [],
    paymentMethod: _isSaldoSesi ? "saldo_waktu" : "cash",
    cashAmount: 0,
    bayarStatus: state[i]._bayarStatus || 'belum',
    namaPelanggan: (document.getElementById("namaPelanggan"+i)?.value.trim()) || state[i].namaPelanggan || _loadNamaPelanggan(i) || "",
    _saldoId:     _saldoIdSnap,
    _saldoMenit:  _saldoMenitSnap,
    _saldoPsType: _saldoPsTypeSnap,
  }
  const oldType = state[i].type
const oldItems = Array.isArray(state[i].items) ? [...state[i].items] : []
  // Hitung sisa waktu SEBELUM state direset
  const sisaDetikStop = Math.max(0, Math.floor((durasiAwal || 0) - (durasiPakai || 0)))

cancelNativeAlarm(i)
state[i] = {
  mode: null,
  start: null,
  type: oldType,
  duration: 0,
  expired: false,
  items: oldItems
}

  showPopup({
    tv: i,
    mode: "countdown",
    type: state[i].type,
    durasi: durasiPakai,
    total: total
  })

  // Tawaran simpan waktu — inject ke dalam popup proses transaksi (bukan floating toast)

  save()
  syncNativeCountdownAlarms()

  document.getElementById("input"+i).disabled = false
  document.getElementById("input"+i).value = ""

  document.getElementById("status"+i).innerText="TERSEDIA"
  document.getElementById("status"+i).style.color="#00ff88"
  document.getElementById("billTimer"+i).innerText="00:00:00"
  document.getElementById("startBtn"+i).disabled = false
  document.getElementById("stopBtn"+i).disabled = true
  setDropDisabled("modeWrap"+i, false)
  setDropDisabled("typeWrap"+i, false)
  _setTvCtrlDisabled(i, false)
  _resetIdleBtn(i)
  document.getElementById("modePrice"+i).innerText = ""
  document.getElementById("billTimer"+i)?.classList.remove("timer-active")
  document.getElementById("billTimer"+i)?.classList.add("timer-idle")
  document.getElementById("modeSection"+i)?.classList.remove("active-mode")

  renderPesananTV(i)

  let cardElReset = document.getElementById("card" + i)
  if(cardElReset){
    cardElReset.classList.remove("warning-card")
    cardElReset.classList.remove("expired-card")
  }

  cekAlarmGlobal()
  syncNativeCountdownAlarms()
}


// ── Billing effect state cache — hindari classList ops berulang ──
const _billingState = {}   // _billingState[i] = true/false terakhir

// ── Alarm throttle — cek setiap 5 detik, bukan tiap detik ────
let _alarmThrottleTick = 0

// ═══════════════════════════════════════════════════════════════
// MASTER TICK — satu setInterval 1 s menggantikan 2 timer terpisah
// (timer TV + realtimeTransaksi digabung jadi 1 loop)
// ═══════════════════════════════════════════════════════════════
setInterval(()=>{

  const now = Date.now()
  let aktif=0, bill=0, count=0

  // ── 1. UPDATE SEMUA TIMER TV ─────────────────────────────────
  for(let i=1;i<=units;i++){
    const s = state[i]
    if(!s) continue

    // Pakai cache DOM — tidak ada getElementById di sini
    const dom = _tvDom[i]
    if(!dom || !dom.status || !dom.timer) continue

    const {status:statusEl, timer:timerEl, price:priceEl,
           stopBtn, card:cardEl, mode:modeEl,
           btn30, btn60, resetBtn} = dom

    // ════════════════════════════════════════
    // MODE BILLING
    // ════════════════════════════════════════
    if(s.mode === "billing"){
      // setBillingEffect hanya jika state berubah
      if(!_billingState[i]){
        cardEl && cardEl.classList.add("billing-active-card")
        _billingState[i] = true
      }
      aktif++; bill++

      const diff     = Math.floor((now - s.start) / 1000)
      const newTimer = format(diff)

      if(timerEl.textContent !== newTimer)  timerEl.textContent = newTimer
      if(statusEl.textContent !== "BERMAIN"){ statusEl.textContent="BERMAIN"; statusEl.style.color="#00aaff" }

      if(!timerEl.classList.contains("timer-active")){
        timerEl.classList.add("timer-active")
        timerEl.classList.remove("timer-idle")
      }
      if(modeEl && !modeEl.classList.contains("active-mode")) modeEl.classList.add("active-mode")

      const jam      = Math.ceil(diff / 3600)
      const total    = jam * (s.price || getConsolePriceByType(s.type))
      const priceStr = "Rp " + total.toLocaleString("id-ID")
      if(priceEl && priceEl.textContent !== priceStr) priceEl.textContent = priceStr

      if(stopBtn && stopBtn.disabled) stopBtn.disabled = false
    }

    // ════════════════════════════════════════
    // MODE COUNTDOWN
    // ════════════════════════════════════════
    else if(s.mode === "countdown"){
      // setBillingEffect hanya jika state berubah
      if(_billingState[i]){
        cardEl && cardEl.classList.remove("billing-active-card")
        _billingState[i] = false
      }

      // Harga berdasarkan durasi asli (dikurangi bonus waktu gratis)
      const _bonusD  = s._bonusDetik || 0
      const durAsli  = Math.max(0, s.duration - _bonusD - Math.floor((Date.now()-s.start)/1000) + Math.floor((Date.now()-s.start)/1000))
      const jam      = Math.ceil(Math.max(0, s.duration - _bonusD) / 3600)
      const total    = jam * (s.price || getConsolePriceByType(s.type))
      const priceStr = "Rp " + total.toLocaleString("id-ID")
      if(priceEl && priceEl.textContent !== priceStr) priceEl.textContent = priceStr

      let diff = Math.floor((now - s.start) / 1000)
      if(diff < 0) diff = 0
      let sisa = s.duration - diff
      if(sisa < 0 || !isFinite(sisa)) sisa = 0

      // ── Saat waktu habis (satu kali saja) ──────────────
      if(sisa <= 0 && !s.expired){
        s.expired = true
        if(timerEl.textContent !== "00:00:00") timerEl.textContent = "00:00:00"
        if(statusEl.textContent !== "WAKTU HABIS"){ statusEl.textContent="WAKTU HABIS"; statusEl.style.color="#ff3333" }
        // Suara pengumuman TTS
        _speakAlarm('TV ' + i + ' waktu habis')
        // Auto matikan TV via ESP32
        const _esp32ip = getEsp32IP(i)
        if(_esp32ip){ fetch('http://'+_esp32ip+'/power', {signal:AbortSignal.timeout(5000)}).catch(()=>{}) }
        if(stopBtn && stopBtn.disabled) stopBtn.disabled = false
        if(btn30)    btn30.disabled    = true
        if(btn60)    btn60.disabled    = true
        if(resetBtn) resetBtn.disabled = true
        hitungOmzet()
        saveNow()
      }
      // ── Countdown masih berjalan ───────────────────────
      else if(!s.expired){
        const newTimer = format(sisa)
        if(timerEl.textContent !== newTimer) timerEl.textContent = newTimer
        if(statusEl.textContent !== "BERMAIN"){ statusEl.textContent="BERMAIN"; statusEl.style.color="#00aaff" }
        if(!timerEl.classList.contains("timer-active")){
          timerEl.classList.add("timer-active")
          timerEl.classList.remove("timer-idle")
        }
        if(modeEl && !modeEl.classList.contains("active-mode")) modeEl.classList.add("active-mode")
        aktif++; count++
        if(btn30 && btn30.disabled) btn30.disabled = false
        if(btn60 && btn60.disabled) btn60.disabled = false
      }
      // ── Sudah expired ──────────────────────────────────
      else {
        if(timerEl.textContent !== "00:00:00") timerEl.textContent = "00:00:00"
        if(statusEl.textContent !== "WAKTU HABIS"){ statusEl.textContent="WAKTU HABIS"; statusEl.style.color="#ff3333" }
        if(stopBtn && stopBtn.disabled) stopBtn.disabled = false
      }

      // Card warning/expired class — hanya update jika perlu
      if(cardEl){
        const wasWarn    = cardEl.classList.contains("warning-card")
        const wasExpired = cardEl.classList.contains("expired-card")
        const nowExpired = !!s.expired
        const nowWarn    = !nowExpired && sisa > 0 && sisa <= 300
        if(nowExpired && !wasExpired){ cardEl.classList.add("expired-card"); cardEl.classList.remove("warning-card") }
        if(!nowExpired && wasExpired)  cardEl.classList.remove("expired-card")
        if(nowWarn    && !wasWarn)     cardEl.classList.add("warning-card")
        if(!nowWarn   && wasWarn)      cardEl.classList.remove("warning-card")
      }
    }

    // ════════════════════════════════════════
    // MODE NULL (idle)
    // ════════════════════════════════════════
    else {
      if(_billingState[i]){
        cardEl && cardEl.classList.remove("billing-active-card")
        _billingState[i] = false
      }
    }
  }

  // ── 2. DASHBOARD COUNTERS ────────────────────────────────────
  const tvEl    = _tvDom._tvAktif
  const billEl  = _tvDom._billingAktif
  const countEl = _tvDom._countdownAktif
  if(tvEl    && tvEl.textContent    !== String(aktif)) tvEl.textContent    = aktif
  if(billEl  && billEl.textContent  !== String(bill))  billEl.textContent  = bill
  if(countEl && countEl.textContent !== String(count)) countEl.textContent = count

  // ── 3. CLOCK (gabung — hapus setInterval terpisah) ──────────
  const d    = new Date()
  const hari = ["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"]
  const bln  = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"]
  const clockStr =
    hari[d.getDay()] + ", " + d.getDate() + " " + bln[d.getMonth()] + " " + d.getFullYear() +
    " | " + String(d.getHours()).padStart(2,"0") + ":" +
            String(d.getMinutes()).padStart(2,"0") + ":" +
            String(d.getSeconds()).padStart(2,"0")
  const clockEl = _tvDom._realtimeEl || document.getElementById("realtimeTanggal")
  if(clockEl && clockEl.textContent !== clockStr) clockEl.textContent = clockStr

  // ── 4. ALARM CHECK — throttle 1x tiap 5 detik ───────────────
  if(++_alarmThrottleTick >= 5){
    _alarmThrottleTick = 0
    cekAlarmGlobal()
  }

},1000)



function hitungOmzet(){
  let total = 0
  historyToday.forEach(h=>{ total += Number(h.total)||0 })
  const str = "Rp " + total.toLocaleString("id-ID")
  const el = document.getElementById("omzetHari")
  if(el && el.innerText !== str) el.innerText = str
}


function dashSearchTV(query){
  query = (query || "").trim()

  // Stop live update timer jika ada
  if(window._tvSearchCardTimer){
    clearInterval(window._tvSearchCardTimer)
    window._tvSearchCardTimer = null
  }

  // Kosong → tampilkan semua card normal
  if(!query){
    const container = document.getElementById("units")
    if(container){
      container.querySelectorAll(".card[id^='card']").forEach(c => {
        c.style.display = ""
        c.style.opacity = ""
      })
    }
    return
  }

  const num = parseInt(query, 10)
  if(isNaN(num) || num < 1 || num > units) return

  // Hitung page yang mengandung TV ini
  const targetPage = Math.ceil(num / TV_PER_PAGE)
  if(tvCurrentPage !== targetPage){
    tvCurrentPage = targetPage
    createUI()
  }

  // Sembunyikan card lain, tampilkan card target
  const container = document.getElementById("units")
  if(!container) return

  container.querySelectorAll(".card[id^='card']").forEach(card => {
    const tvNum = parseInt(card.id.replace("card",""), 10)
    if(!isNaN(tvNum) && tvNum === num){
      card.style.display = ""
      card.style.opacity = "1"
      setTimeout(() => {
        card.scrollIntoView({ behavior: "smooth", block: "center" })
      }, 80)
    } else {
      card.style.display = "none"
    }
  })
}



function clearHistory(){

  if(!confirmClearHistory){
    confirmClearHistory = true

    showPopup({
typeNotif:"warning",
message:"Klik lagi untuk menghapus semua transaksi"
})

    setTimeout(()=>{
      confirmClearHistory = false
    },5000)

    return
  }

  confirmClearHistory = false

  history = []
historyToday = []
historyTodayDate = new Date().toDateString()
save()
  
  hitungOmzet()

  showPopup({
    typeNotif:"success",
    message:"Semua transaksi berhasil dihapus"
  })

}


// -- Inisialisasi app setelah login berhasil --------------
// ============================================================
// FREE UNIT LIMIT ENFORCER
// ============================================================
function _enforceFreeUnitLimit(){
  if(!_isFreeMode()) return
  if(units <= FREE_TV_MAX) return
  const oldUnits = units
  units = FREE_TV_MAX
  localStorage.setItem("ps_units", JSON.stringify(units))
  if(window._fbDb && window._fbOnline) window._fbDb.ref("settings/totalTV").set(units)
  console.warn("[Astrophile] Free mode: units dikurangi dari " + oldUnits + " ke " + FREE_TV_MAX)
  setTimeout(()=>{ showPopup({ typeNotif:"warning", message:"\u26a0\ufe0f Lisensi PRO tidak aktif.\nJumlah TV dikurangi dari " + oldUnits + " ke " + FREE_TV_MAX + " unit (batas FREE).\n\nUpgrade ke PRO untuk unit tak terbatas." }) }, 1500)
}
// ============================================================

function _initAppAfterLogin(){
  _enforceFreeUnitLimit()
  showDashboardView()
  createUI()
  hitungOmzet()
  updateAdminStatusIndicator()
  tryLoadPrinterMacFromBridge()
  refreshPrinterStatusUI()
  syncNativeCountdownAlarms()
  document.addEventListener("visibilitychange", () => {
    pushNativePageVisibility()
    // Sync saat app kembali ke foreground
    if(document.visibilityState === "visible"){
      setTimeout(_syncActiveSessionsToFirebase, 500)
      _bersihkanBookingSelesai()
    }
  })
  window.addEventListener("focus", () => { pushNativePageVisibility() })
  // Monitor expiry license
  setTimeout(initLicenseExpiryMonitor, 2000)
  // Sync state ke Firebase saat pertama buka
  setTimeout(() => {
    _syncActiveSessionsToFirebase()
    _bersihkanBookingSelesai()
    _initTournFirebaseListener()
  }, 1500)
  // Load ESP32 IPs dari Firebase
  loadEsp32IPsFromFirebase()
  // Load semua data dari Firebase
  _fbSyncLoadAll()
  // Load saved times dari Firebase
  if(window._fbDb){
    window._fbDb.ref('settings/savedTimes').on('value', snap => {
      const data = snap.val()
      if(Array.isArray(data)) localStorage.setItem('ps_saved_times', JSON.stringify(data))
    })
  }
  // Sembunyikan loading screen setelah app siap
  if(typeof hideLoadingScreen === 'function') hideLoadingScreen()

  // Timer cek booking upcoming setiap 30 detik
  setInterval(_checkUpcomingBookings, 30000)
  setTimeout(_checkUpcomingBookings, 3000)
  // Update indikator booking di TV card setiap detik
  setInterval(_updateBookingIndicators, 1000)
}
// Auto-save saat navigasi — tidak perlu popup native browser karena data sudah tersimpan otomatis
window.addEventListener('beforeunload', function(){
  saveNow()
})

window.onload = function(){
  resetHistoryHarian()
  applySavedDashboardTheme()
  applySavedTheme()
  applySavedJudul()
  applySavedFontSize()
  // Langsung ke login — Firebase opsional
  if(!window._appRole){
    showLoginScreen()
    return
  }
  _initAppAfterLogin()
  pushNativePageVisibility()

  document.addEventListener("visibilitychange", () => {
    pushNativePageVisibility()
  })
  window.addEventListener("focus", () => {
    pushNativePageVisibility()
  })
  window.addEventListener("blur", () => {
    pushNativePageVisibility()
  })
  window.addEventListener("pageshow", () => {
    pushNativePageVisibility()
  })
  window.addEventListener("pagehide", pushNativePageVisibility)
}

function backupPin(){

let pin = localStorage.getItem("ps_lock_pin")

if(!pin){
showPopup({
  typeNotif:"warning",
  message:"PIN belum dibuat"
})
return
}

let data = {
admin_pin: pin
}

  androidDownload("backup_pin_admin.json", JSON.stringify(data), "application/json")

  showPopup({
    typeNotif:"success",
    message:"Backup PIN berhasil diunduh"
  })
}

document.addEventListener("change",function(e){

  // restore PIN operator
  if(e.target.id === "restorePinFile"){

    let file = e.target.files[0]
    if(!file) return

    let reader = new FileReader()

    reader.onload = function(){
      restorePinOperatorFromText(reader.result)
    }

    reader.readAsText(file)
  }

  // restore PIN super admin
if(e.target.id === "restoreSuperAdminPinFile"){

  let file = e.target.files[0]
  if(!file) return

  let reader = new FileReader()

  reader.onload = function(){
    restoreSuperAdminPinFromText(reader.result)
  }

  reader.readAsText(file)
}
if(e.target.id === "historyBackupRestoreInput" || e.target.id === "historyBackupRestoreInputPopup"){
  const file = e.target.files[0]
  if(!file) return

  restoreHistoryFromFile(file)
  e.target.value = ""
}
if(e.target.id === "restoreAllDataFile"){
  const file = e.target.files[0]
  if(!file) return

  restoreAllDataFromFile(file)
  e.target.value = ""
}
})

