                'padding:5px 16px;border-radius:20px;margin-bottom:8px;' +
                'background:rgba(255,26,80,0.10);' +
                'border:1px solid rgba(255,26,80,0.35);' +
                'font-family:\'Orbitron\',monospace;font-size:9px;font-weight:700;' +
                'letter-spacing:1.5px;color:#ff6688;' +
                'animation:_licFadeUp 0.5s ease 1.1s both;">' +
                  '⚠ VERIFIKASI GAGAL' +
                '</div>' +

                // Reason
                '<div style="position:relative;z-index:2;' +
                'font-family:\'Rajdhani\',sans-serif;font-size:12px;' +
                'color:rgba(255,102,136,0.65);' +
                'animation:_licFadeUp 0.5s ease 1.3s both;">' +
                  reason +
                '</div>' +

                // Bottom glow line
                '<div style="position:absolute;bottom:0;left:0;right:0;height:1px;' +
                'background:linear-gradient(90deg,transparent,#ff1a50,transparent);' +
                'opacity:0.5;"></div>' +

              '</div>'

