function saveHarga(){
  for(let i=1;i<=units;i++){
    if(state[i] && state[i].start){
      showPopup({
        typeNotif:"warning",
        message:"Masih ada TV yang sedang bermain. Stop semua TV sebelum mengubah harga."
      })
      return
    }
  }

  const newPrices = []

  for(let i = 0; i < prices.length; i++){
    const namaEl = document.getElementById(`consoleNama${i}`)
    const hargaEl = document.getElementById(`consoleHarga${i}`)

    if(!namaEl || !hargaEl) continue

    const nama = namaEl.value.trim()
    const harga = Number(hargaEl.value)

    if(nama === ""){
      showPopup({
        typeNotif:"warning",
        message:"Nama jenis konsol tidak boleh kosong."
      })
      return
    }

    if(!Number.isFinite(harga) || harga < 0){
      showPopup({
        typeNotif:"warning",
        message:"Harga harus berupa angka yang valid."
      })
      return
    }

    newPrices.push({
      id: "console_" + i + "_" + Date.now(),
      nama,
      harga
    })
  }

  if(newPrices.length === 0){
    showPopup({
      typeNotif:"warning",
      message:"Belum ada data jenis konsol yang bisa disimpan."
    })
    return
  }

  prices = newPrices
  save()
  createUI()

  showPopup({
    typeNotif:"success",
    message:"Daftar jenis PS dan harga berhasil diperbarui."
  })
}
function saveTV(){
  let jumlah = Number(document.getElementById("jumlahTV").value)

  if(!jumlah || jumlah < 1){
    showPopup({ typeNotif:"warning", message:"Jumlah TV tidak valid. Masukkan minimal 1 unit TV." })
    return
  }

  if(_isFreeMode() && jumlah > FREE_TV_MAX){
    showUpgradePopup({
      reason: `Versi Gratis hanya mendukung maksimal ${FREE_TV_MAX} unit TV.`,
      hint: 'Upgrade ke PRO untuk mengelola unit TV tak terbatas sesuai kapasitas rental kamu.'
    })
    document.getElementById("jumlahTV").value = FREE_TV_MAX
    return
  }

  if(jumlah === units){
    showPopup({ typeNotif:"warning", message:"Jumlah TV belum berubah." })
    return
  }

  units = jumlah
  tvCurrentPage = 1
  save()

  // Sync jumlah TV ke Firebase supaya halaman booking pelanggan sinkron
  // Simpan lokal dulu, Firebase menyusul jika sudah terkoneksi
  localStorage.setItem("ps_units", JSON.stringify(jumlah))
  if(_fbDb) _fbDb.ref("settings/totalTV").set(jumlah)

  showPopup({ typeNotif:"success", message:`Jumlah TV berhasil diperbarui menjadi ${jumlah} unit.` })

  setTimeout(()=>{ createUI() }, 300)
}

function savePin(){

  let newPin = document.getElementById("newPin")
  let confirmPin = document.getElementById("confirmPin")
  let notif = document.getElementById("menuNotif")

  if(!newPin || !confirmPin || !notif) return

  let pin1 = newPin.value.trim()
  let pin2 = confirmPin.value.trim()

  if(pin1 === "" || pin2 === ""){
    notif.style.display = "block"
    notif.style.color = "#ffaa00"
    notif.innerText = "⚠️ PIN belum diisi"
    return
  }

  if(!/^[0-9]{4,6}$/.test(pin1)){
    notif.style.display = "block"
    notif.style.color = "#ff4444"
    notif.innerText = "❌ PIN harus 4 sampai 6 angka"
    return
  }

  if(pin1 !== pin2){
    notif.style.display = "block"
    notif.style.color = "#ff4444"
    notif.innerText = "❌ Konfirmasi PIN tidak sama"
    return
  }

  LOCK_PIN = pin1
localStorage.setItem("ps_lock_pin", encodePIN(LOCK_PIN))

  notif.style.display = "block"
  notif.style.color = "#00ff88"
  notif.innerText = "✅ PIN Operator berhasil diupdate"

  addOperatorLog(_getCurrentRole(), 'ganti_pin', 'PIN Operator diperbarui')

  newPin.value = ""
  confirmPin.value = ""
}
