function updateAdminStatusIndicator(){
  let el = document.getElementById("adminStatusIndicator")
  if(!el) return

  const role = window._appRole || (superAdminUnlocked ? 'owner' : 'operator')

  if(role === 'owner' || superAdminUnlocked){
    el.className = "mode-indicator mode-owner"
    el.innerHTML = `<span class="mode-indicator-dot"></span><span class="mode-indicator-text">MODE OWNER</span>`
  } else {
    el.className = "mode-indicator mode-operator"
    el.innerHTML = `<span class="mode-indicator-dot"></span><span class="mode-indicator-text">MODE OPERATOR</span>`
  }
}

function toggleSidebar(){
  document.getElementById("sidebar").classList.toggle("open")
  document.getElementById("sidebarOverlay").classList.toggle("active")
}

function closeSidebar(){
  document.getElementById("sidebar").classList.remove("open")
  document.getElementById("sidebarOverlay").classList.remove("active")
}

function lockSuperAdminAccess(){
  superAdminUnlocked = false
  updateAdminStatusIndicator()
  if((localStorage.getItem("ps_lock_mode") || "pin") === "auto") initAutoLock()

  let catUpdate = document.getElementById("cat-update")
  let catTransaksi = document.getElementById("cat-transaksi")

  if(catUpdate) catUpdate.classList.remove("open")
  if(catTransaksi) catTransaksi.classList.remove("open")

  const toggles = document.querySelectorAll(".menu-category-toggle")
  toggles.forEach(btn => btn.classList.remove("is-open"))

  showPopup({
    typeNotif:"success",
    message:"Akses Super Admin berhasil dikunci kembali"
  })

  closeSidebar()
}

