function toggleCategory(id, btn){

let menu = document.getElementById(id)
if(!menu) return

const isAlreadyOpen = menu.classList.contains("open")

// Tutup semua kategori lain yang sedang terbuka
document.querySelectorAll(".menu-category-toggle.is-open").forEach(otherBtn => {
  if(otherBtn !== btn){
    otherBtn.classList.remove("is-open")
    const otherId = otherBtn.getAttribute("onclick")?.match(/toggleCategory\(['"]([^'"]+)['"]/)?.[1]
      || otherBtn.dataset.categoryId
    if(otherId){
      const otherMenu = document.getElementById(otherId)
      if(otherMenu) otherMenu.classList.remove("open")
    }
  }
})

if(isAlreadyOpen){
  menu.classList.remove("open")
  if(btn) btn.classList.remove("is-open")
}else{
  menu.classList.add("open")
  if(btn) btn.classList.add("is-open")
}

}



function persistRuntimeSettingsForBackup(){
  try{ save() }catch(err){}
  try{ localStorage.setItem("ps_lock_pin", encodePIN(LOCK_PIN || "1234")) }catch(err){}
  try{ localStorage.setItem("ps_superadmin_pin", encodePIN(SUPER_ADMIN_PIN || "9999")) }catch(err){}
  try{ localStorage.setItem(PRINTER_MAC_KEY, getSavedPrinterMac() || "") }catch(err){}
  try{ localStorage.setItem(PRINTER_STATUS_KEY, JSON.stringify(printerStatusState || {})) }catch(err){}
}

function collectFullBackupPayload(){
  persistRuntimeSettingsForBackup()

  const storage = {}
  FULL_BACKUP_STORAGE_KEYS.forEach(key => {
    const value = localStorage.getItem(key)
    if(value !== null){
      storage[key] = value
    }
  })

  return {
    app: "Astrophile PlayStation Billing",
    type: "full_backup",
    version: 1,
    exportedAt: new Date().toISOString(),
    storage
  }
}

function backupAllData(){
  const payload = collectFullBackupPayload()
  androidDownload(FULL_BACKUP_FILE_NAME, JSON.stringify(payload, null, 2), "application/json")
  addOperatorLog(_getCurrentRole(), 'backup_data', 'Backup semua data')
  showPopup({
    typeNotif:"success",
    message:"Backup semua data berhasil dibuat"
  })
}

function openRestoreAllData(){
  if(requestNativeRestoreFile("all_data")) return
  const input = document.getElementById("restoreAllDataFile")
  if(input) input.click()
}

function applyRestoredStorageMap(storageMap){
  FULL_BACKUP_STORAGE_KEYS.forEach(key => localStorage.removeItem(key))
  Object.keys(storageMap || {}).forEach(key => {
    const value = storageMap[key]
    if(value !== null && value !== undefined){
      localStorage.setItem(key, String(value))
    }
  })
}

function restoreAllDataFromFile(file){
  if(!file) return

  const reader = new FileReader()
  reader.onload = function(){
    restoreAllDataFromText(reader.result)
  }
  reader.readAsText(file)
}

function backupData(){
  backupAllData()
}


  

