// ===== PIN LOCK SCREEN =====

function lockScreen(){
const lock = document.getElementById("lockScreen")
const input = document.getElementById("lockPinInput")
const msg = document.getElementById("lockPinMsg")

if(lock){
lock.classList.add("visible")
updateLockClock()
}

if(input) input.value = ""
if(msg) msg.innerText = ""
}

function unlockScreen(){
  const lock = document.getElementById("lockScreen")
  const input = document.getElementById("lockPinInput")
  const msg = document.getElementById("lockPinMsg")

  if(!input || !lock) return

  if(input.value === LOCK_PIN){
    lock.classList.remove("visible")
    input.value = ""
    if(msg) msg.innerText = ""
    return
  }

  if(input.value === SUPER_ADMIN_PIN){
    superAdminUnlocked = true
    updateAdminStatusIndicator()
    clearAutoLock()
    lock.classList.remove("visible")
    input.value = ""
    if(msg) msg.innerText = ""
    return
  }

  if(msg) msg.innerText = "PIN salah, coba lagi"
  input.value = ""
}

function pressPin(num){
const input = document.getElementById("lockPinInput")
const msg = document.getElementById("lockPinMsg")
if(!input) return

if(input.value.length >= 6) return
input.value += num
if(msg) msg.innerText = ""
}

function clearPin(){
const input = document.getElementById("lockPinInput")
const msg = document.getElementById("lockPinMsg")
if(input) input.value = ""
if(msg) msg.innerText = ""
}

document.addEventListener("keydown", function(e){

const lock = document.getElementById("lockScreen")
if(!lock || !lock.classList.contains("visible")) return

if(e.key === "Enter"){
unlockScreen()
}

})

function updateLockClock(){

  let now = new Date()

  let jam = String(now.getHours()).padStart(2,"0")
let menit = String(now.getMinutes()).padStart(2,"0")
let detik = String(now.getSeconds()).padStart(2,"0")

  let hari = ["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"]
  let bulan = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"]

  let tanggal =
  hari[now.getDay()] + ", " +
  now.getDate() + " " +
  bulan[now.getMonth()] + " " +
  now.getFullYear()

  let timeEl = document.getElementById("lockTime")
  let dateEl = document.getElementById("lockDate")

  if(timeEl) timeEl.innerText = jam + ":" + menit + ":" + detik
  if(dateEl) dateEl.innerText = tanggal

}
