// ── Cek Semua ESP32 Quick ──
function cekSemuaEsp32Quick(){
  const btn = document.getElementById('esp32CheckBtn')
  if(btn){ btn.textContent = '⏳'; btn.disabled = true }

  const ips = window._esp32IPs || {}
  const keys = Object.keys(ips)

  if(keys.length === 0){
    showToast('⚠️ Belum ada ESP32 yang diset')
    if(btn){ btn.textContent = '📡'; btn.disabled = false }
    return
  }

  let done = 0
  let online = 0
  let offline = 0

  keys.forEach(n => {
    const ip = ips[n]
    if(!ip){ done++; offline++; check(); return }
    fetch('http://'+ip+'/status', {signal: AbortSignal.timeout(3000)})
      .then(r=>r.json())
      .then(d=>{ if(d.ok) online++; else offline++; done++; check() })
      .catch(()=>{ offline++; done++; check() })
  })

  function check(){
    if(done < keys.length) return
    if(btn){ btn.textContent = '📡'; btn.disabled = false }
    const msg = online === keys.length
      ? '📡 Semua ESP32 online (' + online + '/' + keys.length + ')'
      : '📡 ESP32: ' + online + ' online, ' + offline + ' offline'
    showToast(msg)
  }
}

