function simpanJudulBilling(){
  // Cek apakah Free dan sudah pernah edit sebelumnya
  if(_isFreeMode() && localStorage.getItem(FREE_JUDUL_KEY) === "1"){
    showUpgradePopup({
      reason: 'Versi Gratis hanya bisa mengubah judul billing 1 kali.',
      hint: 'Upgrade ke PRO untuk mengubah judul kapan saja tanpa batas.'
    })
    return
  }

  const top = document.getElementById("inputJudulTop")?.value.trim() || "ASTROPHILE"
  const bottom = document.getElementById("inputJudulBottom")?.value.trim() || "PLAYSTATION BILLING"
  const namaToko = document.getElementById("inputNamaToko")?.value.trim() || ""

  localStorage.setItem("ps_title_top", top)
  localStorage.setItem("ps_title_bottom", bottom)
  localStorage.setItem("ps_nama_toko", namaToko)
  if(_isFreeMode()) localStorage.setItem(FREE_JUDUL_KEY, "1")  // tandai sudah pernah edit

  // Sync nama toko ke Firebase supaya Android TV bisa baca
  if(window._fbDb && namaToko){
    window._fbDb.ref("settings/namaToko").set(namaToko)
      .catch(e => console.warn("Gagal sync namaToko ke Firebase:", e))
  }

  applySavedJudul()
  closePopup()
  showPopup({ typeNotif:"success", message:"✅ Judul billing & nama toko berhasil diperbarui!" })
}

function resetJudulBilling(){
  localStorage.removeItem("ps_title_top")
  localStorage.removeItem("ps_title_bottom")
  localStorage.removeItem("ps_nama_toko")
  if(window._fbDb){
    window._fbDb.ref("settings/namaToko").remove()
      .catch(e => console.warn("Gagal hapus namaToko dari Firebase:", e))
  }
  applySavedJudul()
  closePopup()
  showPopup({ typeNotif:"success", message:"🔄 Judul billing direset ke default" })
}

