// ── Kurangi stok otomatis saat transaksi disimpan ──
// ── Real-time stock helper ──
// delta: negatif = kurangi, positif = tambah kembali
function _ubahStokItem(jenis, id, delta){
  if(!jenis || !id || delta === 0) return
  const key = jenis === 'minuman' ? 'ps_minuman' : 'ps_makanan'
  const list = JSON.parse(localStorage.getItem(key)) || []
  let changed = false
  list.forEach(m => {
    if(m.id === id && m.stock !== '' && m.stock !== null && m.stock !== undefined){
      m.stock = Math.max(0, Number(m.stock) + delta)
      changed = true
    }
  })
  if(changed) localStorage.setItem(key, JSON.stringify(list))
}

function renderMenuOptions(list){
  if(!Array.isArray(list) || list.length === 0){
    return `<option value="">Belum ada data</option>`
  }
  
  

  return `
    <option value="">Pilih menu</option>
    ${list.map(item => `
      <option value="${item.id}">
        ${item.nama} - Rp ${(Number(item.harga) || 0).toLocaleString("id-ID")}
      </option>
    `).join("")}
  `
}

function getWaktuRealtime(){
  const now = new Date()

  const tanggal = now.toLocaleDateString("id-ID", {
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric"
  })

  const jam = now.toLocaleTimeString("id-ID")

  return {
    tanggal,
    jam
  }
}

function escapeHTML(str){
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

