function pilihMetodePembayaran(metode){
  if(!pendingTransaction) return
  pendingTransaction.paymentMethod = metode

  // Update button active states
  const btns = { cash:'payBtnCash', transfer:'payBtnTransfer', qris:'payBtnQris', dana:'payBtnDana', ovo:'payBtnOvo', gopay:'payBtnGopay' }
  Object.keys(btns).forEach(k => {
    const el = document.getElementById(btns[k])
    if(el) el.classList.toggle('active', k === metode)
  })

  // Show/hide cash input
  const cashWrap = document.getElementById('cashInputWrap')
  if(cashWrap) cashWrap.style.display = (metode === 'cash') ? 'block' : 'none'

  const kembalianBox = document.getElementById('kembalianBox')
  if(kembalianBox) kembalianBox.style.display = 'none'

  // Show/hide QRIS panel
  const qrisPanel = document.getElementById('qrisPanel')
  if(qrisPanel){
    qrisPanel.style.display = (metode === 'qris') ? 'block' : 'none'
    if(metode === 'qris') _loadQrisImage()
  }

  // Reset input kalau ganti ke non-cash
  if(metode !== 'cash'){
    const ci = document.getElementById('cashInputAmount')
    if(ci){ ci.value = ''; ci.style.borderColor = ''; }
    if(pendingTransaction) pendingTransaction.cashAmount = 0
  }
}

function _loadQrisImage(){
  const qrisUrl = localStorage.getItem('qris_image_url') || ''
  const wrap = document.getElementById('qrisImgWrap')
  if(!wrap) return

  if(qrisUrl){
    // Gunakan Image object untuk cek dulu apakah bisa dimuat
    const img = new Image()
    img.onload = function(){
      wrap.innerHTML = ''
      const el = document.createElement('img')
      el.src = qrisUrl
      el.style.cssText = 'width:180px;height:180px;border-radius:12px;border:2px solid rgba(255,107,0,0.30);object-fit:contain;background:#fff;display:block;'
      wrap.appendChild(el)
    }
    img.onerror = function(){
      wrap.innerHTML = '<div style="width:180px;height:180px;border-radius:12px;border:2px dashed rgba(255,107,0,0.30);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;"><div style="font-size:32px;opacity:0.5;">&#128247;</div><div style="font-size:10px;color:rgba(255,107,0,0.60);text-align:center;">Gambar tidak bisa dimuat</div></div>'
    }
    img.src = qrisUrl

    // Tampil loading sementara
    wrap.innerHTML = '<div style="width:180px;height:180px;border-radius:12px;border:2px solid rgba(255,107,0,0.18);display:flex;align-items:center;justify-content:center;"><div style="font-size:11px;color:rgba(255,107,0,0.50);">Memuat...</div></div>'
  } else {
    wrap.innerHTML = '<div style="width:180px;height:180px;border-radius:12px;border:2px dashed rgba(255,107,0,0.28);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;"><div style="font-size:32px;opacity:0.45;">&#128247;</div><div style="font-size:10px;color:rgba(255,107,0,0.50);text-align:center;padding:0 12px;line-height:1.5;">Belum ada gambar QRIS<br><span style=\"color:rgba(0,245,255,0.55);\">Pengaturan &#8594; QRIS</span></div></div>'
  }
}

function konfirmasiQRIS(){
  if(!pendingTransaction) return
  pendingTransaction.qrisKonfirmasi = true

  // Update button UI — jangan tutup popup transaksi
  const btn = document.querySelector('#qrisPanel button[onclick="konfirmasiQRIS()"]')
  if(btn){
    btn.innerHTML = '✅ SUDAH DIKONFIRMASI'
    btn.style.background = 'linear-gradient(135deg,rgba(0,255,136,0.20),rgba(0,200,100,0.12))'
    btn.style.borderColor = 'rgba(0,255,136,0.45)'
    btn.style.color = '#00ff88'
    btn.disabled = true
  }

  // Tampil notif kecil di dalam panel QRIS saja
  const panel = document.getElementById('qrisPanel')
  if(panel){
    const notif = document.createElement('div')
    notif.style.cssText = 'margin-top:8px;padding:8px 12px;border-radius:10px;'+
      'background:rgba(0,255,136,0.08);border:1px solid rgba(0,255,136,0.22);'+
      'font-size:11px;color:#00ff88;text-align:center;'
    notif.textContent = '🎉 Pembayaran dikonfirmasi — klik Simpan Transaksi'
    panel.appendChild(notif)
    setTimeout(() => notif.remove(), 4000)
  }
}

function hitungKembalian(){
  if(!pendingTransaction) return
  const inputEl = document.getElementById('cashInputAmount')
  const kembalianBox = document.getElementById('kembalianBox')
  if(!inputEl || !kembalianBox) return

  const items = Array.isArray(pendingTransaction.items) ? pendingTransaction.items : []
  const totalTambahan = items.reduce((sum, item) => sum + (Number(item.harga) || 0), 0)
  const grandTotal = (pendingTransaction.total || 0) + totalTambahan

  // Baca angka dari value yg mungkin sudah diformat dengan titik
  const uangMasuk = Number(String(inputEl.value).replace(/\./g,'').replace(/[^0-9]/g,'')) || 0
  pendingTransaction.cashAmount = uangMasuk

  // Gunakan grand total setelah diskon & tukar poin
  const { grand: grandFinalNow } = _hitungGrandTrx()
  const realGrand = grandFinalNow

  if(uangMasuk >= realGrand){
    const kembalian = uangMasuk - realGrand
    kembalianBox.style.display = 'block'
    kembalianBox.innerHTML = `Kembalian: <strong>Rp ${kembalian.toLocaleString('id-ID')}</strong>`
  } else if(uangMasuk > 0){
    kembalianBox.style.display = 'block'
    kembalianBox.innerHTML = `<span style="color:#ff6688;">Kurang: Rp ${(realGrand - uangMasuk).toLocaleString('id-ID')}</span>`
  } else {
    kembalianBox.style.display = 'none'
  }
}

// -- Format input uang jadi Rupiah otomatis (12.500 → 12.500) --
function formatRupiahInput(el){
  if(!el) return
  // Ambil hanya angka
  let raw = String(el.value).replace(/[^0-9]/g,'')
  if(raw === ''){ el.value = ''; return }
  // Tambah titik ribuan
  let formatted = ''
  let rev = raw.split('').reverse()
  for(let i = 0; i < rev.length; i++){
    if(i > 0 && i % 3 === 0) formatted = '.' + formatted
    formatted = rev[i] + formatted
  }
  // Jaga posisi kursor
  const selStart = el.selectionStart
  const oldLen = el.value.length
  el.value = formatted
  const newLen = formatted.length
  try{ el.setSelectionRange(selStart + (newLen - oldLen), selStart + (newLen - oldLen)) }catch(e){}
}

function getPaymentLabel(metode){
  const svgDana  = `<svg width="36" height="16" viewBox="0 0 80 28" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:middle;margin-right:4px;"><rect width="80" height="28" rx="6" fill="#108EE9"/><text x="40" y="20" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="16" fill="white">DANA</text></svg>`
  const svgOvo   = `<svg width="36" height="16" viewBox="0 0 80 28" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:middle;margin-right:4px;"><rect width="80" height="28" rx="14" fill="#4C3494"/><text x="40" y="20" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="16" fill="white">OVO</text></svg>`
  const svgGopay = `<svg width="44" height="16" viewBox="0 0 96 28" fill="none" xmlns="http://www.w3.org/2000/svg" style="vertical-align:middle;margin-right:4px;"><rect width="96" height="28" rx="6" fill="#00AED6"/><text x="48" y="20" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="15" fill="white">GoPay</text></svg>`
  const labels = {
    cash:         '💵 Cash',
    transfer:     '🏦 Transfer',
    qris:         '⬛ QRIS',
    dana:         svgDana + 'Dana',
    ovo:          svgOvo  + 'OVO',
    gopay:        svgGopay + 'GoPay',
    saldo_waktu:  '⏱ Saldo Waktu'
  }
  return labels[metode] || metode
}

// ── Auto-finalize untuk transaksi Rp 0 (saldo waktu member) ──
function _finalizeSaldoWaktuTrx(){
  // Dipanggil saat paymentMethod = 'saldo_waktu' — langsung simpan tanpa popup cash
  if(!pendingTransaction) return
  const items = Array.isArray(pendingTransaction.items) ? pendingTransaction.items : []
  const totalTambahan = items.reduce((sum, it) => sum + (Number(it.harga)||0), 0)
  const grandTotal = totalTambahan  // main = 0, hanya tambahan (minuman/makanan) jika ada

  const finalData = {
    id: 'TRX-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).substring(2,7).toUpperCase(),
    tv: pendingTransaction.tv,
    mode: pendingTransaction.mode,
    type: pendingTransaction.type,
    namaPelanggan: pendingTransaction.namaPelanggan || '',
    jam: pendingTransaction.jam,
    totalMain: 0,
    totalTambahan,
    total: grandTotal,
    items,
    paymentMethod: 'saldo_waktu',
    cashAmount: 0,
    date: pendingTransaction.date,
    day: pendingTransaction.day,
    ts: pendingTransaction.ts || Date.now()
  }

  // Cek limit Free
  if(_isFreeMode() && history.length >= FREE_HISTORY_MAX){
    showPopup({typeNotif:'warning', message:'⚠️ Riwayat transaksi penuh!\nUpgrade PRO untuk simpan lebih banyak.'})
    return
  }

  history.push(finalData)
  historyToday.push(finalData)
  try{ if(window._fbDb) window._fbDb.ref('transaksiHistory').set(JSON.stringify(history)).catch(()=>{}) }catch(e){}

  addOperatorLog(_getCurrentRole(), 'simpan_transaksi', 'TV ' + finalData.tv + ' · Saldo Waktu · ' + (finalData.type||'-'))

  const i = finalData.tv
  const oldType = state[i]?.type || pendingTransaction.type || 'PS3'
  state[i] = { mode:null, start:null, type:oldType, duration:0, expired:false, items:[], namaPelanggan:'' }
  _clearNamaPelanggan(i)

  const _doneTV = pendingTransaction?.tv
  pendingTransaction = null
  tempStateBackup = null

  saveNow(); createUI(); hitungOmzet(); closePopup()
  if(_doneTV !== undefined) setTimeout(_syncActiveSessionsToFirebase, 300)
  showPopup({ typeNotif:'success', message:'✅ Sesi selesai!\n⏱ Dibayar dengan Saldo Waktu' })
}

function simpanTransaksiFinal(){
  if(!pendingTransaction) return

  // Cek status bayar — tidak boleh simpan jika belum bayar
  if((pendingTransaction.bayarStatus || 'belum') === 'belum'){
    // Tampilkan pesan di dalam popup tanpa tutup popup
    let errEl = document.getElementById('_bayarErrMsg')
    if(!errEl){
      errEl = document.createElement('div')
      errEl.id = '_bayarErrMsg'
      errEl.style.cssText = `
        background:rgba(255,40,40,0.15);border:1px solid rgba(255,80,80,0.40);
        border-radius:10px;padding:10px 14px;margin:8px 0;
        font-family:'Rajdhani',sans-serif;font-size:13px;font-weight:700;
        color:#ff4d6d;text-align:center;letter-spacing:0.5px;
        animation:shake 0.4s ease;
      `
      errEl.textContent = '⚠️ Konfirmasi pembayaran dulu sebelum simpan!'
      const btnRow = document.querySelector('.transaksi-popup-actions')
      if(btnRow) btnRow.parentNode.insertBefore(errEl, btnRow)
    }
    // Highlight tombol SUDAH BAYAR
    const btnSudah = document.getElementById('popupBtnSudah')
    if(btnSudah){
      btnSudah.style.boxShadow = '0 0 18px rgba(0,255,136,0.7)'
      btnSudah.style.borderColor = 'rgba(0,255,136,0.8)'
      setTimeout(()=>{ btnSudah.style.boxShadow=''; btnSudah.style.borderColor='' }, 1500)
    }
    // Auto hapus pesan setelah 3 detik
    setTimeout(()=>{ if(errEl && errEl.parentNode) errEl.parentNode.removeChild(errEl) }, 3000)
    return
  }

  // Hapus pesan error jika ada
  const errEl = document.getElementById('_bayarErrMsg')
  if(errEl && errEl.parentNode) errEl.parentNode.removeChild(errEl)

  // -- Validasi Cash: wajib isi nominal + tidak boleh kurang dari grand total --
  const _metode = pendingTransaction.paymentMethod || 'cash'
  // Saldo waktu: sudah bayar di muka, skip validasi cash
  if(_metode === 'saldo_waktu') return _finalizeSaldoWaktuTrx()
  if(_metode === 'cash'){
    const _cashVal = Number(pendingTransaction.cashAmount) || 0

    // Hitung grand total dulu untuk validasi
    const _itemsCheck = Array.isArray(pendingTransaction.items) ? pendingTransaction.items : []
    const _tambahanCheck = _itemsCheck.reduce((sum, item) => sum + (Number(item.harga) || 0), 0)
    // Gunakan _hitungGrandTrx agar sudah termasuk diskon & tukar poin
    const { grand: _grandTotalCheck } = _hitungGrandTrx()

    const inputEl = document.getElementById('cashInputAmount')
    const kembalianBox = document.getElementById('kembalianBox')

    if(_cashVal <= 0){
      if(inputEl){
        inputEl.style.borderColor = 'rgba(255,26,80,0.6)'
        inputEl.focus()
        setTimeout(()=>{ inputEl.style.borderColor = '' }, 2500)
      }
      if(kembalianBox){
        kembalianBox.style.display = 'block'
        kembalianBox.innerHTML = '<span style="color:#ff6688;">⚠️ Isi nominal uang Cash pelanggan dulu!</span>'
      }
      return
    }

    if(_cashVal < _grandTotalCheck){
      if(inputEl){
        inputEl.style.borderColor = 'rgba(255,26,80,0.6)'
        inputEl.focus()
        setTimeout(()=>{ inputEl.style.borderColor = '' }, 2500)
      }
      if(kembalianBox){
        kembalianBox.style.display = 'block'
        const _kurang = (_grandTotalCheck - _cashVal).toLocaleString('id-ID')
        kembalianBox.innerHTML = '<span style="color:#ff6688;">❌ Uang kurang Rp ' + _kurang + ' - tidak bisa simpan!</span>'
      }
      return
    }
  }

  const items = Array.isArray(pendingTransaction.items) ? pendingTransaction.items : []
  const totalTambahan = items.reduce((sum, item) => sum + (Number(item.harga) || 0), 0)

  // -- Hitung grand total (diskon + tukar poin) --
  const _selMember = pendingTransaction.selectedMember || null
  const { grand:_grandFinal, diskon:_diskon, potongPoin:_potongPoin, raw:_grandRaw } = _hitungGrandTrx()

  const finalData = {
    id: 'TRX-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).substring(2,7).toUpperCase(),
    tv: pendingTransaction.tv,
    mode: pendingTransaction.mode,
    type: pendingTransaction.type,
    namaPelanggan: pendingTransaction.namaPelanggan
      || (pendingTransaction.tv !== undefined ? sessionStorage.getItem("_pending_nama_tv_"+pendingTransaction.tv)||"" : "")
      || "",
    jam: pendingTransaction.jam,
    totalMain: pendingTransaction.total || 0,
    totalTambahan,
    total: _grandFinal,
    totalSebelumDiskon: _grandRaw,
    diskon: _diskon,
    potongPoin: _potongPoin,
    items,
    paymentMethod: pendingTransaction.paymentMethod || 'cash',
    cashAmount: pendingTransaction.cashAmount || 0,
    memberId: _selMember?.id || null,
    memberNama: _selMember?.nama || null,
    date: pendingTransaction.date,
    day: pendingTransaction.day,
    ts: pendingTransaction.ts || Date.now()
  }

  // -- Update poin member --
  if(_selMember){
    const poinCfg   = JSON.parse(localStorage.getItem('ps_poin_konfig')||'{"poinPerRibu":1,"nilaiTukar":1000}')
    const nilaiTukar= Number(poinCfg.nilaiTukar)||1000
    const members   = JSON.parse(localStorage.getItem('ps_members')||'[]')
    const idx       = members.findIndex(m=>m.id===_selMember.id)

    if(idx !== -1){
      let poinSekarang = members[idx].poin || 0

      // Kurangi poin jika ditukar
      if(pendingTransaction.tukarPoin && _potongPoin > 0){
        const poinDipakai = Math.ceil(_potongPoin / nilaiTukar)
        poinSekarang = Math.max(0, poinSekarang - poinDipakai)
        finalData.poinDipakai = poinDipakai
      }

      // Tambah poin dari transaksi (hanya jika tidak tukar poin)
      let poinDapat = 0
      if(!pendingTransaction.tukarPoin){
        poinDapat = Math.floor(_grandFinal / 1000) * (poinCfg.poinPerRibu||1)
        poinSekarang += poinDapat
      }

      members[idx].poin       = poinSekarang
      members[idx].totalTrx   = (members[idx].totalTrx||0) + 1
      members[idx].totalOmzet = (members[idx].totalOmzet||0) + _grandFinal
      localStorage.setItem('ps_members', JSON.stringify(members))
      finalData.poinDapat = poinDapat
    }
  }

  // -- Cek limit riwayat Free (max 20) --
  if(_isFreeMode() && history.length >= FREE_HISTORY_MAX){
    // Simpan finalData ke window sementara agar bisa dicoba lagi setelah hapus
    window._pendingFinalData = finalData
    window._pendingTVBackup  = tempStateBackup

    // Ambil transaksi terlama untuk info hapus
    const oldest = history[history.length - 1]
    const oldestInfo = oldest
      ? `TV ${oldest.tv} · ${oldest.type || '-'} · ${oldest.date || '-'}`
      : '-'

    showUpgradePopup({
      reason: `Riwayat transaksi sudah penuh (${FREE_HISTORY_MAX} data di Versi Gratis).`,
      hint: `Transaksi baru tidak bisa disimpan. Hapus salah satu riwayat lama atau upgrade ke PRO.`,
      extraHtml: `
      <div style="margin-bottom:14px;padding:10px 13px;
        background:rgba(255,26,80,0.07);border:1px solid rgba(255,26,80,0.18);
        border-radius:var(--radius-sm);font-size:11px;color:#ff6688;line-height:1.7;text-align:left;">
        <div style="font-family:'Orbitron',monospace;font-size:8px;letter-spacing:2px;
          color:rgba(255,102,136,0.60);margin-bottom:5px;">TRANSAKSI TERLAMA</div>
        ${escapeHTML(oldestInfo)}
      </div>
      <button onclick="hapusTransaksiTerlamaLaluSimpan()"
        style="width:100%;margin:0 0 10px;padding:12px;
        background:linear-gradient(135deg,rgba(255,26,80,0.14),rgba(255,100,0,0.10));
        border-color:rgba(255,26,80,0.36);color:#ff6688;
        font-family:'Orbitron',monospace;font-size:10px;font-weight:700;letter-spacing:1.5px;">
        🗑 HAPUS TERLAMA &amp; SIMPAN TRANSAKSI INI
      </button>`
    })
    // Jangan kembalikan state dulu — nanti ditangani hapusTransaksiTerlamaLaluSimpan
    pendingTransaction = null
    tempStateBackup = null
    return
  }

  history.push(finalData)
  historyToday.push(finalData)

  if(pendingTransaction && pendingTransaction.tv !== undefined){
    sessionStorage.removeItem("_pending_nama_tv_"+pendingTransaction.tv)
  }

  // ── Tulis history ke Firebase client (untuk sync HP lain) ──
  // Hanya menulis sekali, tidak ada listener aktif → tidak ada lag
  try{
    if(window._fbDb){
      window._fbDb.ref('transaksiHistory').set(JSON.stringify(history)).catch(()=>{})
    }
  }catch(e){}

  addOperatorLog(_getCurrentRole(), 'simpan_transaksi', 'TV ' + finalData.tv + ' · ' + (finalData.type||'-') + ' · Rp ' + (finalData.total||0).toLocaleString('id-ID'))

const i = finalData.tv

const oldType = state[i]?.type || pendingTransaction.type || "PS3"

state[i] = {
  mode:null,
  start:null,
  type:oldType,
  duration:0,
  expired:false,
  items:[],
  namaPelanggan:''  // ← clear nama pelanggan setelah transaksi selesai
}

// Hapus nama pelanggan dari localStorage juga
_clearNamaPelanggan(i)

const _doneTV = pendingTransaction?.tv
pendingTransaction = null
tempStateBackup = null

saveNow()
createUI()
hitungOmzet()

// Update booking status → "selesai" di Firebase agar Netlify tahu TV sudah bebas
if(_doneTV !== undefined){
  const today = new Date().toISOString().split("T")[0]
  bookings.forEach(b => {
    // Hanya mark "aktif" sebagai selesai — jangan sentuh "upcoming" (belum datang)
    if(b.tv === _doneTV &&
      b.status === "aktif" &&
      b.tanggal === today){
      b.status = "selesai"
      saveBookings()
      _fbSetBooking(b)
    }
  })
}
// Eksplisit clear TV di Firebase — hapus processing/reserved
if(_fbDb && _doneTV !== undefined){
  _fbDb.ref("settings/activeSessions/" + _doneTV).set({ active: false })
  // Reset status bayar untuk sesi berikutnya
  _resetBayarStatus(_doneTV)
}
setTimeout(_syncActiveSessionsToFirebase, 500)
closePopup()

  showPopup({
  typeNotif:"transaction_saved",
  message:"Transaksi berhasil disimpan",
  grandTotal: finalData.total
})
}

function batalkanTransaksiPopup(){
  if(pendingTransaction){
    // Hitung item yang ditambah DALAM popup (selisih vs snapshot saat stop)
    const atStop = pendingTransaction._itemsAtStop || []
    const current = pendingTransaction.items || []

    // Buat count map snapshot saat stop
    const snapMap = {}
    atStop.forEach(x => {
      const k = (x.jenis||'') + '|' + (x.id||'')
      snapMap[k] = (snapMap[k] || 0) + 1
    })

    // Buat count map current
    const currMap = {}
    current.forEach(x => {
      const k = (x.jenis||'') + '|' + (x.id||'')
      currMap[k] = (currMap[k] || 0) + 1
    })

    // Restore stok untuk item yang ditambah di popup (currMap > snapMap)
    Object.keys(currMap).forEach(k => {
      const diff = (currMap[k] || 0) - (snapMap[k] || 0)
      if(diff > 0){
        const [jenis, id] = k.split('|')
        _ubahStokItem(jenis, id, +diff)
      }
    })
  }
  pendingTransaction = null
  closePopup()
}

function tambahItemPopup(jenis){
  if(!pendingTransaction) return

  const sourceList = jenis === "minuman" ? getMinumanList() : getMakananList()
  const selectId = jenis === "minuman" ? "popupMinumanSelect" : "popupMakananSelect"
  const selectEl = document.getElementById(selectId)

  if(!selectEl || !selectEl.value) return

  const selected = sourceList.find(item => item.id === selectEl.value)
  if(!selected) return

  pendingTransaction.items.push({
    jenis,
    id: selected.id,
    nama: selected.nama,
    harga: Number(selected.harga) || 0
  })
  _ubahStokItem(jenis, selected.id, -1)

  selectEl.value = ""
  addOperatorLog(_getCurrentRole(), 'tambah_pesanan', 'Popup · ' + selected.nama + ' · ' + formatRupiah(Number(selected.harga)||0))
  renderPesananPopup()
}

function hapusItemPopup(index){
  if(!pendingTransaction || !Array.isArray(pendingTransaction.items)) return

  pendingTransaction.items.splice(index, 1)
  renderPesananPopup()
}




function renderPesananPopup(){
  if(!pendingTransaction) return

  const listEl = document.getElementById("popupPesananList")
  const summaryEl = document.getElementById("popupPesananSummary")
  if(!listEl || !summaryEl) return

  const items = (pendingTransaction.items || []).filter(x=> x && (x.nama||x.id))

  if(items.length === 0){
    listEl.innerHTML = `<div style="font-size:12px;color:var(--text-dim);text-align:center;padding:8px;">
      Belum ada tambahan pesanan</div>`
  } else {
    // Group by id+jenis — normalize key
    const groups = {}
    items.forEach((item) => {
      const keyId   = String(item.id  || item.nama || '').trim()
      const keyJns  = String(item.jenis || '').trim()
      const key     = keyId + '||' + keyJns
      if(!groups[key]){
        groups[key] = { item, qty:0, hargaSatuan: Number(item.harga)||0 }
      }
      groups[key].qty++
    })

    listEl.innerHTML = Object.values(groups).map(g => {
      const icon  = g.item.jenis === 'minuman' ? '🥤' : '🍔'
      const total = g.qty * g.hargaSatuan
      const safeId = escapeHTML(String(g.item.id || g.item.nama || ''))
      const safeJns = escapeHTML(String(g.item.jenis || ''))
      return `
      <div style="display:flex;align-items:center;gap:10px;
        padding:9px 12px;margin-bottom:6px;
        background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.10);
        border-radius:var(--radius-md);">
        <div style="flex:1;min-width:0;">
          <div style="font-size:13px;font-weight:600;color:var(--text-primary);
            white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
            ${icon} ${escapeHTML(g.item.nama)}
          </div>
          <div style="display:flex;align-items:center;gap:6px;margin-top:3px;">
            ${g.qty > 1 ? `<span style="background:rgba(0,245,255,0.16);color:var(--primary);
              font-family:'Orbitron',monospace;font-size:9px;font-weight:700;
              padding:2px 8px;border-radius:20px;border:1px solid rgba(0,245,255,0.26);">
              x${g.qty}</span>` : ''}
            <span style="font-family:'Orbitron',monospace;font-size:11px;color:var(--lime-accent);">
              ${formatRupiah(total)}
            </span>
            ${g.qty > 1 ? `<span style="font-size:9px;color:var(--text-dim);">
              (${formatRupiah(g.hargaSatuan)}/pcs)</span>` : ''}
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:5px;flex-shrink:0;">
          <button type="button"
            onclick="kurangSatuItemPopup('${safeId}','${safeJns}')"
            style="width:30px;height:30px;border-radius:50%;margin:0;padding:0;
            background:rgba(255,26,80,0.12);border:1px solid rgba(255,26,80,0.26);
            color:#ff6688;font-size:18px;font-weight:700;line-height:1;
            cursor:pointer;">−</button>
          <span style="font-family:'Orbitron',monospace;font-size:14px;font-weight:700;
            color:var(--primary);min-width:22px;text-align:center;">${g.qty}</span>
          <button type="button"
            onclick="tambahSatuItemPopup('${safeId}','${safeJns}')"
            style="width:30px;height:30px;border-radius:50%;margin:0;padding:0;
            background:rgba(0,245,255,0.10);border:1px solid rgba(0,245,255,0.22);
            color:var(--primary);font-size:18px;font-weight:700;line-height:1;
            cursor:pointer;">+</button>
        </div>
      </div>`
    }).join('')
  }

  const totalTambahan = items.reduce((sum, item) => sum + (Number(item.harga) || 0), 0)
  const { grand } = _hitungGrandTrx()

  summaryEl.innerHTML = `
    <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px;">
      <span style="color:var(--text-muted);">Total Main</span>
      <strong>${formatRupiah(pendingTransaction.total||0)}</strong>
    </div>
    ${totalTambahan>0?`<div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px;">
      <span style="color:var(--text-muted);">Total Tambahan</span>
      <strong>${formatRupiah(totalTambahan)}</strong>
    </div>`:''}
    <div class="popup-grand-total">Grand Total: ${formatRupiah(grand)}</div>
  `
}

function kurangSatuItemPopup(itemId, jenis){
  if(!pendingTransaction) return
  const items = pendingTransaction.items
  for(let n = items.length-1; n >= 0; n--){
    const x = items[n]
    if(String(x.id||x.nama||'').trim() === String(itemId||'').trim() &&
       String(x.jenis||'').trim() === String(jenis||'').trim()){
      items.splice(n, 1)
      _ubahStokItem(jenis, itemId, +1)
      break
    }
  }
  renderPesananPopup()
  if(pendingTransaction.selectedMember) updateGrandTotalWithDiskon(pendingTransaction.selectedMember)
}

function tambahSatuItemPopup(itemId, jenis){
  if(!pendingTransaction) return
  const existing = pendingTransaction.items.find(x=>
    String(x.id||x.nama||'').trim() === String(itemId||'').trim() &&
    String(x.jenis||'').trim() === String(jenis||'').trim()
  )
  if(existing){
    pendingTransaction.items.push({...existing})
    _ubahStokItem(jenis, itemId, -1)
    renderPesananPopup()
    if(pendingTransaction.selectedMember) updateGrandTotalWithDiskon(pendingTransaction.selectedMember)
  }
}

function updatePesananPopup(){
  renderPesananPopup()
}

