function tampilkanPreviewGambarMinuman(src){
  const box = document.getElementById("previewGambarMinuman")
  const img = document.getElementById("imgPreviewMinuman")

  if(!box || !img) return

  if(src){
    img.src = src
    box.style.display = "block"
  }else{
    img.src = ""
    box.style.display = "none"
  }
}

function compressGambarMinuman(file, maxWidth = 600, quality = 0.7){
  return new Promise((resolve, reject) => {
    if(!file){
      resolve("")
      return
    }

    const reader = new FileReader()

    reader.onload = function(event){
      const img = new Image()

      img.onload = function(){
        let width = img.width
        let height = img.height

        if(width > maxWidth){
          height = Math.round((height * maxWidth) / width)
          width = maxWidth
        }

        const canvas = document.createElement("canvas")
        canvas.width = width
        canvas.height = height

        const ctx = canvas.getContext("2d")
        if(!ctx){
          reject(new Error("Canvas tidak didukung"))
          return
        }

        ctx.drawImage(img, 0, 0, width, height)

        const compressedBase64 = canvas.toDataURL("image/jpeg", quality)
        resolve(compressedBase64)
      }

      img.onerror = reject
      img.src = event.target.result
    }

    reader.onerror = reject
    reader.readAsDataURL(file)
  })
}

