function simpanDataBaruMinuman(data){
  // -- Cek limit Free (max 5 item) --
  if(_isFreeMode() && minumanList.length >= FREE_KANTIN_MAX){
    showUpgradePopup({
      reason: `Versi Gratis hanya mendukung maksimal ${FREE_KANTIN_MAX} menu minuman.`,
      hint: 'Upgrade PRO untuk menu minuman tak terbatas lengkap dengan foto produk.'
    })
    return
  }

  const waktu = getWaktuRealtime()

  minumanList.push({
    id: generateIdMinuman(),
    nama: data.nama,
    harga: data.harga,
    stock: data.stock,
    gambar: _isFreeMode() ? "" : (data.gambar || ""),  // Free: no gambar
    tanggal: waktu.tanggal,
    jam: waktu.jam,
    isEdited: false
  })

  simpanDataMinuman()
  pageMinuman = 1
  tampilkanMinuman()
  resetFormMinuman(false)
  tampilkanNotif("✅ Data minuman berhasil ditambahkan", "#00ff88")
}

function confirmDuplicateMinuman(){
  if(!pendingDuplicateDataMinuman) return

  simpanDataBaruMinuman(pendingDuplicateDataMinuman)
  closeDuplicateModalMinuman()
}

function closeDeleteModalMinuman(){
  const modal = document.getElementById("deleteModalMinuman")
  if(modal){
    modal.classList.remove("show")
  }
  pendingDeleteIdMinuman = null
}

function confirmDeleteMinuman(){
  if(!pendingDeleteIdMinuman){
    closeDeleteModalMinuman()
    return
  }

  minumanList = minumanList.filter(item => item.id !== pendingDeleteIdMinuman)
  simpanDataMinuman()

  const data = getFilteredMinuman()
  const totalPage = Math.max(1, Math.ceil(data.length / limitMinuman))

  if(pageMinuman > totalPage){
    pageMinuman = totalPage
  }

  if(pageMinuman < 1){
    pageMinuman = 1
  }

  tampilkanMinuman()
  resetFormMinuman(false)
  closeDeleteModalMinuman()
  tampilkanNotif("🗑️ Data berhasil dihapus", "#00ff88")
}

