let notifTimeoutMakanan = null
let notifFadeTimeoutMakanan = null

function tampilkanNotifMakanan(text, color){
  const notifEl = document.getElementById("notifMakanan")
  if(!notifEl) return

  clearTimeout(notifTimeoutMakanan)
  clearTimeout(notifFadeTimeoutMakanan)

  notifEl.style.display = "block"
  notifEl.style.color = color
  notifEl.innerText = text

  notifEl.style.opacity = "0"
  notifEl.style.transform = "translateY(-5px)"

  setTimeout(() => {
    notifEl.style.opacity = "1"
    notifEl.style.transform = "translateY(0)"
  }, 10)

  notifTimeoutMakanan = setTimeout(() => {

    notifEl.style.opacity = "0"
    notifEl.style.transform = "translateY(-5px)"

    notifFadeTimeoutMakanan = setTimeout(() => {
      notifEl.style.display = "none"
      notifEl.innerText = ""
    }, 500)

  }, 4500)
}



