function simpanDataBaruMakanan(data){
  // -- Cek limit Free (max 5 item) --
  if(_isFreeMode() && makananList.length >= FREE_KANTIN_MAX){
    showUpgradePopup({
      reason: `Versi Gratis hanya mendukung maksimal ${FREE_KANTIN_MAX} menu makanan.`,
      hint: 'Upgrade PRO untuk menu makanan tak terbatas lengkap dengan foto produk.'
    })
    return
  }

  const waktu = getWaktuRealtime()

  makananList.push({
    id: generateIdMakanan(),
    nama: data.nama,
    harga: data.harga,
    stock: data.stock,
    gambar: _isFreeMode() ? "" : (data.gambar || ""),  // Free: no gambar
    tanggal: waktu.tanggal,
    jam: waktu.jam,
    isEdited: false
  })

  simpanDataMakanan()
  pageMakanan = 1
  tampilkanMakanan()
  resetFormMakanan(false)
  tampilkanNotifMakanan("✅ Data makanan berhasil ditambahkan", "#00ff88")
}

function confirmDuplicateMakanan(){
  if(!pendingDuplicateDataMakanan) return

  simpanDataBaruMakanan(pendingDuplicateDataMakanan)
  closeDuplicateModalMakanan()
}

function closeDeleteModalMakanan(){
  const modal = document.getElementById("deleteModalMakanan")
  if(modal){
    modal.classList.remove("show")
  }
  pendingDeleteIdMakanan = null
}

function confirmDeleteMakanan(){
  if(!pendingDeleteIdMakanan){
    closeDeleteModalMakanan()
    return
  }

  makananList = makananList.filter(item => item.id !== pendingDeleteIdMakanan)
  simpanDataMakanan()

  const data = getFilteredMakanan()
  const totalPage = Math.max(1, Math.ceil(data.length / limitMakanan))

  if(pageMakanan > totalPage){
    pageMakanan = totalPage
  }

  if(pageMakanan < 1){
    pageMakanan = 1
  }

  tampilkanMakanan()
  resetFormMakanan(false)
  closeDeleteModalMakanan()
  tampilkanNotifMakanan("🗑️ Data berhasil dihapus", "#00ff88")
}

