function cetakStruk(){
  if(!pendingTransaction) return

  const items = pendingTransaction.items || []
  let totalTambahan = items.reduce((sum, item) => sum + (Number(item.harga) || 0), 0)
  let totalAkhir = (pendingTransaction.total || 0) + totalTambahan

  const itemsHtml = items.length === 0
    ? `<div>-</div>`
    : items.map(item => `
        <div style="display:flex;justify-content:space-between;font-size:12px;">
          <span>${item.nama}</span>
          <span>Rp ${item.harga.toLocaleString("id-ID")}</span>
        </div>
      `).join("")

  const html = `
    <div style="text-align:center;margin-bottom:8px;">
      <strong style="font-size:15px;">ASTROPHILE PS</strong><br>
      <span style="font-size:11px;">PLAYSTATION BILLING</span>
    </div>
    <div style="border-top:1px dashed #000;margin:8px 0;"></div>
    <div style="display:flex;justify-content:space-between;font-size:12px;"><span>TV</span><span>${pendingTransaction.tv}</span></div>
    ${pendingTransaction.namaPelanggan ? `<div style="display:flex;justify-content:space-between;font-size:12px;"><span>Pelanggan</span><span><strong>${pendingTransaction.namaPelanggan}</strong></span></div>` : ''}
    <div style="display:flex;justify-content:space-between;font-size:12px;"><span>Mode</span><span>${pendingTransaction.mode}</span></div>
    <div style="display:flex;justify-content:space-between;font-size:12px;"><span>Tipe</span><span>${pendingTransaction.type}</span></div>
    <div style="border-top:1px dashed #000;margin:8px 0;"></div>
    <div style="display:flex;justify-content:space-between;font-size:12px;"><span>Main</span><span>Rp ${(pendingTransaction.total||0).toLocaleString("id-ID")}</span></div>
    ${itemsHtml}
    <div style="border-top:1px dashed #000;margin:8px 0;"></div>
    <div style="display:flex;justify-content:space-between;font-weight:bold;font-size:13px;"><span>Total</span><span>Rp ${totalAkhir.toLocaleString("id-ID")}</span></div>
    <div style="border-top:1px dashed #000;margin:8px 0;"></div>
    <div style="text-align:center;font-size:11px;margin-top:8px;">Terima kasih 🙏</div>
    <div class="struk-close-bar">
      <button onclick="closeStrukModal()">✕ Tutup</button>
      <button class="struk-print" onclick="handlePrintStruk()">🖨️ Print</button>
    </div>
  `
  const textPayload = buildReceiptTextFromData({
    tv: pendingTransaction.tv,
    mode: pendingTransaction.mode,
    type: pendingTransaction.type,
    namaPelanggan: pendingTransaction.namaPelanggan || "",
    date: pendingTransaction.date,
    totalMain: pendingTransaction.total || 0,
    totalTambahan,
    total: totalAkhir,
    items,
    paymentMethod: pendingTransaction.paymentMethod || 'cash',
    cashAmount: pendingTransaction.cashAmount || 0
  })
  setCurrentStrukPayload(`struk_tv_${pendingTransaction.tv || 'x'}`, html, textPayload)
  showStrukModal(html)
}


function bindGambarMinumanChange(){
  const input = document.getElementById("gambarMinuman")
  if(!input || input.dataset.bound === "1") return
  input.dataset.bound = "1"

  // Label klik → Android bridge (Sketchware) atau fallback .click()
  const lbl = document.getElementById("labelGambarMinuman")
  if(lbl && !lbl.dataset.bound){
    lbl.dataset.bound = "1"
    lbl.addEventListener("click", function(e){
      e.preventDefault()
      if(window.Android && typeof window.Android.pickImage === "function"){
        window.Android.pickImage("minuman")
      } else {
        try{ input.click() }catch(err){}
      }
    })
  }

  input.addEventListener("change", async function(e){
    const file = e.target.files && e.target.files[0] ? e.target.files[0] : null

    if(!file){
      tampilkanPreviewGambarMinuman("")
      return
    }

    if(file.size > 500 * 1024){
      tampilkanNotif("❌ Gambar maksimal 500KB", "#ff4444")
      e.target.value = ""
      tampilkanPreviewGambarMinuman("")
      return
    }

    try{
      const compressedBase64 = await compressGambarMinuman(file)
      tampilkanPreviewGambarMinuman(compressedBase64)
      window._nativeImgMinuman = null  // clear native, pakai file input
      const lb = document.getElementById("labelGambarMinuman")
      if(lb) lb.innerHTML = "✅ " + file.name.substring(0,24)
    }catch(error){
      tampilkanNotif("❌ Gagal membaca gambar", "#ff4444")
      e.target.value = ""
      tampilkanPreviewGambarMinuman("")
    }
  })
}

