function batalTransaksi(){
  if(!pendingTransaction) return

  const i = pendingTransaction.tv

  // ── Kembalikan saldo waktu kalau sesi pakai saldo ──
  const _batalSaldoId    = pendingTransaction._saldoId    || state[i]?._saldoId    || null
  const _batalSaldoMenit = pendingTransaction._saldoMenit || state[i]?._saldoMenit || 0
  const _batalSaldoPsType= pendingTransaction._saldoPsType|| state[i]?._saldoPsType|| null
  if(_batalSaldoId && _batalSaldoMenit){
    const p = _getSaldoById(_batalSaldoId)
    if(p){
      if(_batalSaldoPsType && p.saldoPs){
        p.saldoPs[_batalSaldoPsType] = (p.saldoPs[_batalSaldoPsType]||0) + _batalSaldoMenit
        _syncSaldoTotal(p)
      } else {
        p.saldo += _batalSaldoMenit
      }
      p.totalPakai = Math.max(0,(p.totalPakai||0)-_batalSaldoMenit)
      p.riwayat    = p.riwayat||[]
      p.riwayat.push({
        id:_genSaldoId(), ts:Date.now(), aksi:'kembali',
        menit:_batalSaldoMenit, psType:_batalSaldoPsType||null, catatan:'Sesi dibatalkan — saldo dikembalikan'
      })
      saveSaldoWaktu()
    }
    if(state[i]){ state[i]._saldoId = null; state[i]._saldoMenit = null; state[i]._saldoPsType = null }
    pendingTransaction._saldoId     = null
    pendingTransaction._saldoMenit  = null
    pendingTransaction._saldoPsType = null
  }

  if(tempStateBackup){
    state[i] = tempStateBackup
    tempStateBackup = null
  }
  cekAlarmGlobal()

  pendingTransaction = null
  save()
  createUI()
  hitungOmzet()
  closePopup()
  setTimeout(_syncActiveSessionsToFirebase, 300)

  showPopup({
    typeNotif:"success",
    message:"Transaksi dibatalkan, waktu dilanjutkan"
  })
}

