let tournamentConfig = (()=>{
  const base = JSON.parse(localStorage.getItem("ps_tourn_config")) || {
    title: "ASTROPHILE CUP 2026",
    grandPrize: "Rp 500.000",
    mode: "single"
  }
  // Selalu override dari hadiah turna (sumber kebenaran tunggal)
  const h = JSON.parse(localStorage.getItem('ps_hadiah_turna')||'{}')
  if(h.judul)      base.title      = h.judul
  if(h.grandPrize) base.grandPrize = h.grandPrize
  else if(h.total && Number(h.total)>0){
    // Auto-generate label dari total hadiah
    const t = Number(h.total)
    base.grandPrize = 'Rp ' + t.toLocaleString('id-ID')
  }
  return base
})()
let tournamentParticipants = JSON.parse(localStorage.getItem("ps_tourn_participants")) || []
let tournamentBracketState = null
let activeMatchIdTournament = null
let tournamentModeSelected = "single"

function saveTournamentAll() {
  try{
  localStorage.setItem("ps_tourn_config", JSON.stringify(tournamentConfig))
  localStorage.setItem("ps_tourn_participants", JSON.stringify(tournamentParticipants))
  if (tournamentBracketState) {
    localStorage.setItem("ps_tourn_bracket", JSON.stringify(tournamentBracketState))
    // Sync ke Firebase — pakai set (bukan update) agar bracket lama ter-replace penuh
    if(_fbDb && tournamentBracketState.slotId){
      _fbDb.ref("tournamentBracket/" + tournamentBracketState.slotId).set({
        rounds: JSON.stringify(tournamentBracketState.rounds),
        config: tournamentBracketState.config || tournamentConfig,
        participants: tournamentBracketState.participants || tournamentParticipants,
        slotId: tournamentBracketState.slotId,
        slotNama: tournamentBracketState.config?.title || "",
        champion: tournamentBracketState.champion || null,
        createdAt: tournamentBracketState.createdAt || Date.now(),
        updatedAt: Date.now()
      })
    }
  }
  } catch(e){ console.warn("saveTournamentAll error:", e) }
}

function loadTournamentSaved() {
  // Load config dasar
  const savedCfg = localStorage.getItem("ps_tourn_config")
  if (savedCfg) { try { tournamentConfig = JSON.parse(savedCfg) } catch(e){} }
  tournamentModeSelected = tournamentConfig.mode || "single"
  // Load bracket
  const savedBracket = localStorage.getItem("ps_tourn_bracket")
  if (savedBracket) { try { tournamentBracketState = JSON.parse(savedBracket) } catch(e){} }
  // SELALU override judul & hadiah dari ps_hadiah_turna (sumber kebenaran tunggal)
  _syncHadiahToConfig()
}

function _syncHadiahToConfig(){
  const h = JSON.parse(localStorage.getItem('ps_hadiah_turna')||'{}')
  if(h.judul) tournamentConfig.title = h.judul

  // grandPrize: pakai label custom, atau auto-generate dari total uang
  if(h.grandPrize){
    tournamentConfig.grandPrize = h.grandPrize
  } else if(h.total && Number(h.total)>0){
    tournamentConfig.grandPrize = 'Rp ' + Number(h.total).toLocaleString('id-ID')
  }

  // Sync juga ke bracket config (tampil di header bagan)
  if(tournamentBracketState?.config){
    tournamentBracketState.config.title      = tournamentConfig.title
    tournamentBracketState.config.grandPrize = tournamentConfig.grandPrize
  }
}

// -- UTILS --------------------------------------------------
function tournNextPow2(n) { let p=1; while(p<n) p*=2; return p }

function tournShuffle(arr) {
  const a = [...arr]
  for (let i = a.length-1; i > 0; i--) {
    const j = Math.floor(Math.random()*(i+1));
    [a[i],a[j]] = [a[j],a[i]]
  }
  return a
}

function tournGenId() {
  return Date.now().toString(36).slice(-5) + Math.random().toString(36).slice(2,6)
}

function tournRoundName(idx, total) {
  const rem = total - idx
  if (rem === 1) return "FINAL"
  if (rem === 2) return "SEMIFINAL"
  if (rem === 3) return "QUARTERFINAL"
  return "ROUND " + (idx+1)
}

