function renderTournCount() {
  const n = tournamentParticipants.length
  if (n === 0) return 'Tambahkan minimal <b>2 peserta</b> untuk generate bracket'
  const byes = tournNextPow2(n) - n
  const byeText = byes > 0
    ? ` · <span style="color:#ff9a3c">${byes} BYE otomatis</span>`
    : ` · <span style="color:#00ff88">Bracket penuh ✓</span>`
  return `<b>${n}</b> peserta terdaftar${byeText}`
}

function renderTournParticipantItems() {
  if (!tournamentParticipants.length) {
    return `<div class="tourn-empty-list">Belum ada peserta ditambahkan</div>`
  }
  return tournamentParticipants.map((p,i) => `
    <div class="tourn-participant-item">
      <div class="tourn-p-num">${String(i+1).padStart(2,'0')}</div>
      <div class="tourn-p-info">
        <div class="tourn-p-name">${escapeHTML(p.name)}</div>
        <div class="tourn-p-club">🏟️ ${escapeHTML(p.club||'Independent')}</div>
      </div>
      <button class="tourn-p-remove" onclick="removeTournamentParticipant('${p.id}')">✕</button>
    </div>
  `).join('')
}

function refreshTournSetupUI() {
  const listEl = document.getElementById("tournParticipantList")
  const countEl = document.getElementById("tournCountInfo")
  const genBtn = document.getElementById("tournGenerateBtn")
  if (listEl) listEl.innerHTML = renderTournParticipantItems()
  if (countEl) countEl.innerHTML = renderTournCount()
  if (genBtn) {
    if (tournamentParticipants.length < 2) genBtn.classList.add("disabled")
    else genBtn.classList.remove("disabled")
  }
}

function selectTournMode(mode) {
  tournamentModeSelected = mode
  document.querySelectorAll(".tourn-mode-btn").forEach((btn,i) => {
    btn.classList.toggle("active", (i===0&&mode==="single")||(i===1&&mode==="double"))
  })
}

function addTournamentParticipant() {
  const nameEl = document.getElementById("tournAddName")
  const clubEl = document.getElementById("tournAddClub")
  if (!nameEl) return
  const name = nameEl.value.trim()
  const club = clubEl ? clubEl.value.trim() : ""
  if (!name) { showPopup({typeNotif:"warning",message:"Nama peserta tidak boleh kosong"}); return }

  // Cek limit Free
  const maxPeserta = _isFreeMode() ? FREE_BRACKET_MAX : 32
  if (tournamentParticipants.length >= maxPeserta) {
    showUpgradePopup({
        reason: `Versi Gratis hanya mendukung maksimal ${FREE_BRACKET_MAX} peserta turnamen.`,
        hint: 'Upgrade ke PRO untuk mengelola hingga 32 peserta dengan bracket yang lebih seru!'
      })
    return
  }

  if (tournamentParticipants.find(p=>p.name.toLowerCase()===name.toLowerCase())) {
    showPopup({typeNotif:"warning",message:"Nama peserta sudah terdaftar"}); return
  }
  tournamentParticipants.push({ id: tournGenId(), name, club: club||"Independent" })
  saveTournamentAll()
  nameEl.value = ""; if(clubEl) clubEl.value = ""; nameEl.focus()
  refreshTournSetupUI()
}

function removeTournamentParticipant(id) {
  tournamentParticipants = tournamentParticipants.filter(p=>p.id!==id)
  saveTournamentAll()
  refreshTournSetupUI()
}

// -- GENERATE BRACKET ---------------------------------------
function generateTournamentBracket(skipShuffle = false) {
  if (tournamentParticipants.length < 2) {
    showPopup({typeNotif:"warning",message:"Minimal 2 peserta untuk generate bracket"}); return
  }
  const titleEl = document.getElementById("tournTitle") || {value: tournamentConfig.title||''}
  const prizeEl = document.getElementById("tournPrize") || {value: tournamentConfig.grandPrize||''}
  tournamentConfig.mode = tournamentModeSelected
  // Selalu ambil judul & hadiah dari Hadiah Otomatis
  _syncHadiahToConfig()
  saveTournamentAll()

  // skipShuffle = true saat dari manual acak agar urutan dihormati
  const shuffled = skipShuffle ? [...tournamentParticipants] : tournShuffle(tournamentParticipants)
  const size = tournNextPow2(shuffled.length)
  const padded = [...shuffled]
  while(padded.length < size) padded.push({id:"bye_"+tournGenId(),name:"BYE",club:"",isBye:true})

  const rounds = []
  let current = []
  for(let i=0; i<padded.length; i+=2) {
    current.push(createTournMatch(padded[i], padded[i+1]))
  }
  rounds.push(current)
  while(current.length > 1) {
    const next = []
    for(let i=0; i<current.length; i+=2) {
      next.push(createTournMatch(null, null, current[i]?.id, current[i+1]?.id))
    }
    rounds.push(next); current = next
  }
  autoAdvanceTournByes(rounds)

  tournamentBracketState = {
    rounds,
    config: {...tournamentConfig},
    participants: [...tournamentParticipants],
    slotId: tournamentBracketState?.slotId || null,  // jaga slotId agar tidak hilang saat reshuffle
    champion: null,
    createdAt: new Date().toLocaleString("id-ID")
  }
  saveTournamentAll()
  showPopup({typeNotif:"success",message:"Bagan berhasil digenerate! 🎉"})
  setTimeout(()=>{ renderTournamentBracketPage() }, 1500)
}

function createTournMatch(p1, p2, srcAId=null, srcBId=null) {
  return { id:tournGenId(), p1:p1?{...p1}:null, p2:p2?{...p2}:null,
    score1:null, score2:null, winner:null, loser:null, srcAId, srcBId }
}

function autoAdvanceTournByes(rounds) {
  let changed = true
  while(changed) {
    changed = false
    rounds.forEach(round => {
      round.forEach(match => {
        if(match.winner) return
        if(match.p1?.isBye && match.p2 && !match.p2.isBye) {
          match.winner={...match.p2}; match.loser={...match.p1}
          propagateTournWinner(match, rounds); changed=true
        } else if(match.p2?.isBye && match.p1 && !match.p1.isBye) {
          match.winner={...match.p1}; match.loser={...match.p2}
          propagateTournWinner(match, rounds); changed=true
        }
      })
    })
  }
}

function propagateTournWinner(srcMatch, rounds) {
  if(!srcMatch.winner) return
  rounds.forEach(round => {
    round.forEach(m => {
      if(m.srcAId===srcMatch.id && !m.p1) { m.p1={...srcMatch.winner} }
      if(m.srcBId===srcMatch.id && !m.p2) { m.p2={...srcMatch.winner} }
    })
  })
}

// -- BRACKET PAGE -------------------------------------------
function renderTournamentBracketPage() {
  if(!tournamentBracketState) {
    loadTournamentSaved()
    if(!tournamentBracketState) {
      showPopup({typeNotif:"warning",message:"Belum ada bagan. Silakan buat dari menu Update Bracket."}); return
    }
  }
  // Selalu sync judul & hadiah terbaru sebelum render
  _syncHadiahToConfig()
  if(tournamentBracketState?.config) {
    const h = JSON.parse(localStorage.getItem('ps_hadiah_turna')||'{}')
    if(h.judul)      tournamentBracketState.config.title      = h.judul
    if(h.grandPrize) tournamentBracketState.config.grandPrize = h.grandPrize
    else if(h.total) {
      const totalH = Number(h.total)||0
      if(totalH>0) tournamentBracketState.config.grandPrize = formatRupiah(totalH)
    }
  }
  const t = tournamentBracketState
  const rounds = t.rounds
  const cfg = t.config || {}
  const roundNames = rounds.map((_,i)=>tournRoundName(i,rounds.length))

  let totalM=0, doneM=0
  rounds.forEach(round=>round.forEach(m=>{
    if(!m.p1?.isBye && !m.p2?.isBye){ totalM++; if(m.winner) doneM++ }
  }))

  const champion = rounds[rounds.length-1]?.[0]?.winner
  if(champion && !champion.isBye) t.champion = champion

  let roundsHTML = ''
  rounds.forEach((round, ri) => {
    const factor = Math.pow(2, ri)
    const matchH = 116
    const gap = ri===0 ? 14 : factor * matchH - matchH + (factor-1)*14
    const topPad = ri===0 ? 0 : (gap/2)

    roundsHTML += `<div class="tourn-round-col"><div class="tourn-round-label">${roundNames[ri]}</div>`
    roundsHTML += `<div class="tourn-matches-col" style="gap:${gap}px;padding-top:${topPad}px;">`

    round.forEach((match, mi) => {
      const p1=match.p1, p2=match.p2
      const isP1Bye=p1?.isBye, isP2Bye=p2?.isBye
      const isByeMatch=isP1Bye||isP2Bye
      const p1Win=match.winner&&match.winner.id===p1?.id
      const p2Win=match.winner&&match.winner.id===p2?.id
      const done=!!match.winner
      const canClick=p1&&p2&&!isByeMatch&&!done

      roundsHTML += `
      <div class="tourn-match-wrapper">
        <div class="tourn-match-card${done?' match-done':''}${isByeMatch?' match-bye':''}" id="tmatch_${match.id}">
          <div class="match-round-tag">${roundNames[ri].slice(0,4)} · #${String(mi+1).padStart(2,'00')}</div>

          <div class="tourn-player-slot${p1Win?' slot-winner':done&&!p1Win?' slot-loser':''}"
            onclick="${canClick?`openTournScoreModal('${match.id}')`:``}">
            <div class="tplayer-avatar${p1Win?' av-win':''}">${p1&&!isP1Bye?escapeHTML(p1.name.charAt(0).toUpperCase()):'?'}</div>
            <div class="tplayer-info">
              <div class="tplayer-name">${isP1Bye?'- BYE -':(p1?escapeHTML(p1.name):'Menunggu...')}</div>
              ${p1&&!isP1Bye?`<div class="tplayer-club">⚽ ${escapeHTML(p1.club||'')}</div>`:''}
            </div>
            <div class="slot-right-col">
              ${p1Win?`<div class="slot-crown">👑</div>`:''}
              ${done?`<div class="tplayer-score${p1Win?' score-win':''}">${match.score1??''}</div>`:''}
            </div>
          </div>

          <div class="match-divider"></div>

          <div class="tourn-player-slot${p2Win?' slot-winner':done&&!p2Win?' slot-loser':''}"
            onclick="${canClick?`openTournScoreModal('${match.id}')`:``}">
            <div class="tplayer-avatar${p2Win?' av-win':''}">${p2&&!isP2Bye?escapeHTML(p2.name.charAt(0).toUpperCase()):'?'}</div>
            <div class="tplayer-info">
              <div class="tplayer-name">${isP2Bye?'- BYE -':(p2?escapeHTML(p2.name):'Menunggu...')}</div>
              ${p2&&!isP2Bye?`<div class="tplayer-club">⚽ ${escapeHTML(p2.club||'')}</div>`:''}
            </div>
            <div class="slot-right-col">
              ${p2Win?`<div class="slot-crown">👑</div>`:''}
              ${done?`<div class="tplayer-score${p2Win?' score-win':''}">${match.score2??''}</div>`:''}
            </div>
          </div>

          ${!done&&canClick?`<div class="match-click-hint">Tap untuk input skor</div>`:''}
          ${done&&!isByeMatch?`<div class="match-done-strip"></div>`:''}
        </div>
        ${ri<rounds.length-1?`<div class="tourn-connector"></div>`:''}
      </div>`
    })
    roundsHTML += `</div></div>`
    if(ri < rounds.length-1) roundsHTML += `<div class="round-gap-col"></div>`
  })

  const html = `
  <div class="tourn-bracket-page">

    <div class="tourn-header-card">
      <div class="tourn-header-shine"></div>
      <div class="tourn-header-content">
        <div class="tourn-header-eyebrow">⚡ TOURNAMENT BRACKET</div>
        <div class="tourn-header-title">${escapeHTML(cfg.title||'TOURNAMENT')}</div>
        <div class="tourn-header-meta">
          <div class="tourn-meta-chip">
            <span>👥</span><span>${t.participants?.filter(p=>!p.isBye).length||0} Peserta</span>
          </div>
          <div class="tourn-meta-chip">
            <span>📊</span><span>${doneM}/${totalM} Match</span>
          </div>
          <div class="tourn-meta-chip chip-mode">
            <span>${cfg.mode==='double'?'🛡️':'⚔️'}</span>
            <span>${cfg.mode==='double'?'Double':'Single'} Elim</span>
          </div>
          <div class="tourn-meta-chip chip-prize">
            <span>🏆</span><span>${escapeHTML(cfg.grandPrize||'-')}</span>
          </div>
        </div>
      </div>
    </div>

    ${champion&&!champion.isBye?`
    <div class="tourn-champion-card">
      <div class="champ-particles">
        ${Array.from({length:12},(_,i)=>`<div class="champ-particle" style="--i:${i}"></div>`).join('')}
      </div>
      <div class="champ-trophy-icon">🏆</div>
      <div class="champ-label-top">JUARA TURNAMEN</div>
      <div class="champ-winner-name">${escapeHTML(champion.name)}</div>
      <div class="champ-winner-club">🏟️ ${escapeHTML(champion.club||'')}</div>
      <div class="champ-prize-tag">Prize: ${escapeHTML(cfg.grandPrize||'-')}</div>
    </div>`:''}

    <div class="tourn-bracket-actions">
      <button class="tourn-action-btn" onclick="_showManualAcakPopup()">🔀 Acak Manual</button>
      <button class="tourn-action-btn" onclick="resetTournamentScores()">🔄 Reset Skor</button>
      <button class="tourn-action-btn" onclick="syncTournBracketFirebase()">☁️ Sync Firebase</button>
      <button class="tourn-action-btn danger" onclick="clearTournamentBracket()">🗑️ Hapus Bagan</button>
    </div>

    <div class="tourn-bracket-scroll-outer">
      <div class="tourn-bracket-scroll">
        <div class="tourn-rounds-wrap">${roundsHTML}</div>
      </div>
    </div>

    <div class="tourn-created-info">Dibuat: ${t.createdAt||'-'} · Astrophile PS Billing</div>
  </div>`

  showInternalPage("🏆 Bagan Turnamen", escapeHTML(cfg.title||'Tournament Bracket'), html)
}

// -- SCORE MODAL --------------------------------------------
function openTournScoreModal(matchId) {
  const match = findTournMatch(matchId)
  if(!match||match.winner) return
  activeMatchIdTournament = matchId
  const modal = document.getElementById("tournScoreModal")
  if(!modal) return
  document.getElementById("tModalP1Name").textContent = match.p1?.name||"Player 1"
  document.getElementById("tModalP1Club").textContent = match.p1?.club||""
  document.getElementById("tModalP2Name").textContent = match.p2?.name||"Player 2"
  document.getElementById("tModalP2Club").textContent = match.p2?.club||""
  document.getElementById("tScoreP1").value = 0
  document.getElementById("tScoreP2").value = 0
  modal.style.display = "flex"
  setTimeout(()=>document.getElementById("tScoreP1").focus(), 100)
}

function closeTournScoreModal() {
  const modal = document.getElementById("tournScoreModal")
  if(modal) modal.style.display = "none"
  activeMatchIdTournament = null
}

function saveTournScore() {
  if(!activeMatchIdTournament) return
  const match = findTournMatch(activeMatchIdTournament)
  if(!match) return
  const s1 = parseInt(document.getElementById("tScoreP1").value)||0
  const s2 = parseInt(document.getElementById("tScoreP2").value)||0
  if(s1===s2){ showPopup({typeNotif:"warning",message:"Skor tidak boleh seri!"}); return }
  match.score1=s1; match.score2=s2
  match.winner = s1>s2 ? {...match.p1} : {...match.p2}
  match.loser  = s1>s2 ? {...match.p2} : {...match.p1}
  propagateTournWinner(match, tournamentBracketState.rounds)
  const lastRound = tournamentBracketState.rounds[tournamentBracketState.rounds.length-1]
  if(lastRound?.[0]?.winner) tournamentBracketState.champion = lastRound[0].winner
  saveTournamentAll()
  closeTournScoreModal()
  renderTournamentBracketPage()
  showPopup({typeNotif:"success",message:`🏆 ${match.winner.name} menang!`})
}

function findTournMatch(matchId) {
  if(!tournamentBracketState) return null
  for(const round of tournamentBracketState.rounds) {
    const m = round.find(x=>x.id===matchId)
    if(m) return m
  }
  return null
}

let _tournResetConfirm = false
let _tournClearConfirm = false

function resetTournamentScores() {
  if(!_tournResetConfirm) {
    _tournResetConfirm = true
    setTimeout(()=>{ _tournResetConfirm=false },5000)
    showPopup({typeNotif:"warning",message:"Klik lagi untuk reset semua skor turnamen"})
    return
  }
  _tournResetConfirm = false
  generateTournamentBracket()
}

function reshuffleTournament() {
  if(!tournamentParticipants.length) return
  generateTournamentBracket()
  // Force full Firebase replace dengan timestamp baru agar halaman booking ambil yang terbaru
  if(_fbDb && tournamentBracketState && tournamentBracketState.slotId){
    const slotId = tournamentBracketState.slotId
    const nowTs = Date.now()
    tournamentBracketState.createdAt = nowTs  // update timestamp agar sort di netlify ambil ini
    _fbDb.ref("tournamentBracket/" + slotId).set({
      rounds: JSON.stringify(tournamentBracketState.rounds),
      config: tournamentBracketState.config || tournamentConfig,
      participants: tournamentParticipants,
      slotId,
      slotNama: tournamentBracketState.config?.title || "",
      createdAt: nowTs,
      updatedAt: nowTs
    })
    _fbDb.ref("settings/tournStarted").set({ slotId, startedAt: nowTs })
  }
}


// ── Android TV Status Badge ───────────────────────────────────
function initAndroidTvStatusListeners(){
  if(!_fbDb) return
  const numTv = parseInt(localStorage.getItem('jumlahTV')||'5')
  for(let i=1;i<=numTv;i++){
    (function(tvNum){
      _fbDb.ref('settings/tvStatus/'+tvNum).on('value', snap=>{
        const dot   = document.getElementById('tvAndroidDot'+tvNum)
        const label = document.getElementById('tvAndroidLabel'+tvNum)
        if(!dot) return
        if(!snap.exists() || snap.val()?.online === false){
          dot.textContent   = '🔴'
          if(label){ label.style.color = '#ff4d6d' }
          dot.title = 'Android TV offline'
        } else {
          const last    = snap.val()?.lastSeen
          const minsAgo = last ? Math.floor((Date.now()-last)/60000) : null
          dot.textContent   = '🟢'
          if(label){ label.style.color = '#00f5ff' }
          dot.title = 'Android TV online' + (minsAgo!==null ? ` · ${minsAgo < 1 ? 'baru saja' : minsAgo+'m lalu'}` : '')
        }
      })
    })(i)
  }
}

// ── Status Pembayaran (Belum/Sudah Bayar) ───────────────────
function _setBayarStatus(i, status){
  if(!state[i]) state[i] = {}
  state[i]._bayarStatus = status
  localStorage.setItem('ps_state', JSON.stringify(state))

  const btnBelum = document.getElementById('btnBelumBayar'+i)
  const btnSudah = document.getElementById('btnSudahBayar'+i)
  const badge    = document.getElementById('bayarBadge'+i)

  // Update badge di card header
  if(badge){
    if(status === 'belum'){
      badge.style.display      = 'inline-block'
      badge.textContent        = '❌ BELUM BAYAR'
      badge.style.background   = 'rgba(255,40,40,0.15)'
      badge.style.border       = '1px solid rgba(255,80,80,0.35)'
      badge.style.color        = '#ff4d6d'
    } else if(status === 'sudah'){
      badge.style.display      = 'inline-block'
      badge.textContent        = '✅ LUNAS'
      badge.style.background   = 'rgba(0,255,136,0.12)'
      badge.style.border       = '1px solid rgba(0,255,136,0.35)'
      badge.style.color        = '#00ff88'
    } else {
      badge.style.display = 'none'
    }
  }

  if(!btnBelum || !btnSudah) return

  if(status === 'belum'){
    btnBelum.style.background  = 'rgba(255,40,40,0.18)'
    btnBelum.style.color       = '#ff4d6d'
    btnBelum.style.borderColor = 'rgba(255,80,80,0.50)'
    btnSudah.style.background  = 'rgba(0,255,136,0.05)'
    btnSudah.style.color       = 'rgba(0,255,136,0.40)'
    btnSudah.style.borderColor = 'rgba(0,255,136,0.30)'
  } else {
    btnSudah.style.background  = 'rgba(0,255,136,0.15)'
    btnSudah.style.color       = '#00ff88'
    btnSudah.style.borderColor = 'rgba(0,255,136,0.55)'
    btnBelum.style.background  = 'rgba(255,80,80,0.05)'
    btnBelum.style.color       = 'rgba(255,80,80,0.40)'
    btnBelum.style.borderColor = 'rgba(255,80,80,0.30)'
  }
}

function _popupSetBayar(status, silent){
  // Simpan ke pendingTransaction
  if(pendingTransaction) pendingTransaction.bayarStatus = status
  const tvNum = pendingTransaction?.tv
  if(tvNum && state[tvNum]) state[tvNum]._bayarStatus = status

  const btnBelum = document.getElementById('popupBtnBelum')
  const btnSudah = document.getElementById('popupBtnSudah')
  if(!btnBelum || !btnSudah) return

  if(status === 'belum'){
    btnBelum.style.background  = 'rgba(255,40,40,0.18)'
    btnBelum.style.color       = '#ff4d6d'
    btnBelum.style.borderColor = 'rgba(255,80,80,0.50)'
    btnSudah.style.background  = 'rgba(0,255,136,0.05)'
    btnSudah.style.color       = 'rgba(0,255,136,0.40)'
    btnSudah.style.borderColor = 'rgba(0,255,136,0.30)'
  } else {
    btnSudah.style.background  = 'rgba(0,255,136,0.15)'
    btnSudah.style.color       = '#00ff88'
    btnSudah.style.borderColor = 'rgba(0,255,136,0.55)'
    btnBelum.style.background  = 'rgba(255,80,80,0.05)'
    btnBelum.style.color       = 'rgba(255,80,80,0.40)'
    btnBelum.style.borderColor = 'rgba(255,80,80,0.30)'
  }

  // Sync tombol di card TV juga
  if(tvNum) _setBayarStatus(tvNum, status)
}

function _resetBayarStatus(i){
  if(state[i]) state[i]._bayarStatus = null
  const badge    = document.getElementById('bayarBadge'+i)
  const btnBelum = document.getElementById('btnBelumBayar'+i)
  const btnSudah = document.getElementById('btnSudahBayar'+i)
  if(badge) badge.style.display = 'none'
  if(btnBelum){
    btnBelum.style.background  = 'rgba(255,40,40,0.18)'
    btnBelum.style.color       = '#ff4d6d'
    btnBelum.style.borderColor = 'rgba(255,80,80,0.40)'
  }
  if(btnSudah){
    btnSudah.style.background  = 'rgba(0,255,136,0.05)'
    btnSudah.style.color       = 'rgba(0,255,136,0.40)'
    btnSudah.style.borderColor = 'rgba(0,255,136,0.40)'
  }
}

// ── Idle Toggle ───────────────────────────────────────────────
const _idleState = {} // track per TV: true=idle ON, false=idle OFF

function _toggleIdle(i){
  const btn = document.getElementById('tvBtnIdle'+i)
  if(!btn) return
  const isOn = _idleState[i] || false

  if(!isOn){
    // Nyalakan idle
    sendTvCommand(i, 'idle')
    _idleState[i] = true
    btn.textContent = '📺 Idle ON'
    btn.style.background   = 'rgba(0,245,255,0.20)'
    btn.style.borderColor  = 'rgba(0,245,255,0.60)'
    btn.style.color        = '#00f5ff'
    btn.style.boxShadow    = '0 0 10px rgba(0,245,255,0.3)'
  } else {
    // Matikan idle
    sendTvCommand(i, 'idle_off')
    _idleState[i] = false
    btn.textContent = '📺 Idle'
    btn.style.background   = ''
    btn.style.borderColor  = ''
    btn.style.color        = ''
    btn.style.boxShadow    = ''
  }
}

function _resetIdleBtn(i){
  _idleState[i] = false
  const btn = document.getElementById('tvBtnIdle'+i)
  if(!btn) return
  btn.textContent = '📺 Idle'
  btn.style.background = btn.style.borderColor = btn.style.color = btn.style.boxShadow = ''
}

// ── Android TV Control enable/disable ────────────────────────
function _setTvCtrlDisabled(i, disabled){
  const btns = ['tvBtnIdle','tvBtnSleep','tvBtnWake']
  btns.forEach(id=>{
    const el = document.getElementById(id+i)
    if(!el) return
    el.disabled = disabled
    if(disabled){
      el.style.opacity = '0.35'
      el.style.cursor  = 'not-allowed'
      el.title = 'Tidak bisa digunakan saat sesi aktif'
    } else {
      el.style.opacity = '1'
      el.style.cursor  = 'pointer'
      // Restore original titles
      if(id==='tvBtnIdle')  el.title = 'Tampilkan layar idle di Android TV'
      if(id==='tvBtnSleep') el.title = 'Matikan layar Android TV (gelap)'
      if(id==='tvBtnWake')  el.title = 'Nyalakan kembali layar Android TV'
    }
  })
}

// ── TV CONTROL: Idle / Sleep / Wake ──────────────────────────
function sendTvCommand(tvNum, cmd){
  if(!_fbDb){
    showPopup({typeNotif:'warning', message:'Firebase belum terhubung!'})
    return
  }
  const labels = { idle:'📺 Idle', sleep:'🌙 Sleep', wake:'☀️ Wake' }
  _fbDb.ref('settings/tvControl/' + tvNum).set({
    cmd:       cmd,
    updatedAt: Date.now()
  }).then(()=>{
    showPopup({typeNotif:'success', message:`${labels[cmd]||cmd} dikirim ke TV ${tvNum}`})
    // Reset command setelah 3 detik agar tidak terus trigger
    setTimeout(()=>{
      _fbDb.ref('settings/tvControl/' + tvNum + '/cmd').set('none')
    }, 3000)
  }).catch(e=>{
    showPopup({typeNotif:'warning', message:'Gagal kirim perintah: ' + e.message})
  })
}
function _showManualAcakPopup(){
  if(!tournamentParticipants?.length){ showPopup({typeNotif:'warning',message:'⚠️ Belum ada peserta!'}); return }
  document.getElementById('_manualAcakPopup')?.remove()
  window._acakDraftList = [...tournamentParticipants]
  window._acakSelected  = null   // index yang sedang dipilih

  const el = document.createElement('div')
  el.id = '_manualAcakPopup'
  el.style.cssText = 'position:fixed;inset:0;z-index:9500;background:rgba(0,0,0,0.78);display:flex;align-items:flex-end;justify-content:center;backdrop-filter:blur(5px);'

  el.innerHTML = `
    <div style="width:100%;max-width:480px;background:linear-gradient(158deg,#060a16,#04080e);
      border:1px solid rgba(255,204,0,0.22);border-radius:22px 22px 0 0;
      padding:16px 16px 24px;position:relative;max-height:85vh;display:flex;flex-direction:column;
      animation:_swUp 0.3s cubic-bezier(0.34,1.56,0.64,1);">
      <div style="position:absolute;top:0;left:0;right:0;height:3px;border-radius:22px 22px 0 0;
        background:linear-gradient(90deg,#ffcc00,#ff7700,#ffcc00);background-size:220% 100%;animation:rgbBarScroll 3s linear infinite;"></div>

      <!-- Header -->
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;flex-shrink:0;">
        <div style="font-size:20px;">🔀</div>
        <div style="flex:1;">
          <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:900;color:#ffcc00;letter-spacing:2px;">ATUR URUTAN PESERTA</div>
        </div>
        <button onclick="document.getElementById('_manualAcakPopup').remove()"
          style="width:28px;height:28px;border-radius:50%;background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.50);font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;">✕</button>
      </div>

      <!-- Petunjuk -->
      <div id="_acakHint" style="background:rgba(255,204,0,0.07);border:1px solid rgba(255,204,0,0.20);border-radius:10px;padding:9px 12px;margin-bottom:10px;font-size:11px;color:rgba(255,204,0,0.80);text-align:center;flex-shrink:0;">
        👆 Ketuk peserta untuk memilih, lalu ketuk peserta lain untuk tukar posisi
      </div>

      <!-- Tombol acak otomatis -->
      <button onclick="_acakOtomatisDraft()"
        style="padding:10px;border-radius:10px;cursor:pointer;margin-bottom:10px;flex-shrink:0;
        background:rgba(119,0,255,0.10);border:1px solid rgba(119,0,255,0.28);color:#aa66ff;
        font-size:12px;font-weight:700;">🎲 Acak Otomatis</button>

      <!-- Grid list peserta -->
      <div id="_acakListWrap" style="overflow-y:auto;flex:1;min-height:0;"></div>

      <!-- Footer -->
      <div style="display:grid;grid-template-columns:1fr 2fr;gap:8px;margin-top:12px;flex-shrink:0;">
        <button onclick="document.getElementById('_manualAcakPopup').remove()"
          style="padding:13px;border-radius:12px;cursor:pointer;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.60);font-size:13px;font-weight:600;">Batal</button>
        <button onclick="_konfirmasiManualAcak()"
          style="padding:13px;border-radius:12px;cursor:pointer;
          background:linear-gradient(135deg,rgba(255,204,0,0.22),rgba(255,120,0,0.14));
          border:1.5px solid rgba(255,204,0,0.50);color:#ffcc00;
          font-family:'Orbitron',monospace;font-size:10px;font-weight:700;letter-spacing:1.5px;">
          ✅ TERAPKAN & BUAT BAGAN
        </button>
      </div>
    </div>`

  document.body.appendChild(el)
  el.addEventListener('click', e=>{ if(e.target===el) el.remove() })

  // ── Render list per pasangan pertandingan ──
  function refresh(){
    const wrap = document.getElementById('_acakListWrap')
    if(!wrap) return
    const sel = window._acakSelected
    const list = window._acakDraftList||[]

    // Buat pasangan: [0,1], [2,3], [4,5], dst
    const pairs = []
    for(let i=0;i<list.length;i+=2) pairs.push([i, i+1])

    wrap.innerHTML = pairs.map((pair, pi)=>{
      const matchNo = pi + 1
      const rows = pair.map(idx=>{
        const p = list[idx]
        if(!p) return ''
        const isSel    = sel === idx
        const isTarget = sel !== null && !isSel
        const initial  = escapeHTML(p.name?.charAt(0)?.toUpperCase()||'?')

        const rowBg   = isSel ? 'rgba(255,204,0,0.14)' : isTarget ? 'rgba(0,245,255,0.07)' : 'rgba(0,0,0,0.20)'
        const numCol  = isSel ? '#ffcc00' : 'rgba(0,245,255,0.40)'
        const nameCol = isSel ? '#ffcc00' : isTarget ? '#e8f4ff' : 'rgba(168,200,240,0.80)'
        const avBg    = isSel ? '#ffcc00' : 'rgba(0,245,255,0.15)'
        const avCol   = isSel ? '#060a16' : '#00f5ff'
        const avBord  = isSel ? '#ffcc00' : isTarget ? 'rgba(0,245,255,0.45)' : 'rgba(0,245,255,0.22)'

        const badge = isSel
          ? `<span style="font-size:8px;font-family:'Orbitron',monospace;font-weight:700;background:#ffcc00;color:#060a16;border-radius:6px;padding:2px 7px;flex-shrink:0;">PILIH</span>`
          : isTarget
          ? `<span style="font-size:14px;color:rgba(0,245,255,0.50);flex-shrink:0;">↔</span>`
          : `<span style="font-size:9px;font-family:'Orbitron',monospace;color:rgba(0,245,255,0.28);flex-shrink:0;">${idx+1}</span>`

        return `
          <div onclick="_acakTapSlot(${idx})"
            style="display:flex;align-items:center;gap:10px;padding:11px 14px;cursor:pointer;
              background:${rowBg};transition:all 0.15s;
              ${isSel?'box-shadow:inset 0 0 20px rgba(255,204,0,0.10);':''}">
            <div style="width:36px;height:36px;border-radius:50%;flex-shrink:0;
              background:${avBg};border:2px solid ${avBord};
              display:flex;align-items:center;justify-content:center;
              font-family:'Orbitron',monospace;font-size:14px;font-weight:900;color:${avCol};">
              ${isSel?'✓':initial}
            </div>
            <div style="flex:1;min-width:0;">
              <div style="font-weight:700;font-size:14px;color:${nameCol};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(p.name||'-')}</div>
              ${p.club?`<div style="font-size:10px;color:rgba(168,200,240,0.40);margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">⚽ ${escapeHTML(p.club)}</div>`:''}
            </div>
            ${badge}
          </div>`
      }).join(`
        <div style="display:flex;align-items:center;gap:8px;padding:4px 14px;background:rgba(0,0,0,0.20);">
          <div style="flex:1;height:1px;background:rgba(255,255,255,0.05);"></div>
          <div style="font-size:9px;font-family:'Orbitron',monospace;color:rgba(255,255,255,0.18);letter-spacing:2px;">VS</div>
          <div style="flex:1;height:1px;background:rgba(255,255,255,0.05);"></div>
        </div>`)

      return `
        <div style="margin-bottom:10px;">
          <div style="font-size:8px;font-family:'Orbitron',monospace;letter-spacing:2px;color:rgba(0,245,255,0.40);margin-bottom:5px;padding-left:2px;">PERTANDINGAN ${matchNo}</div>
          <div style="border-radius:14px;overflow:hidden;border:1px solid rgba(0,245,255,0.14);">
            ${rows}
          </div>
        </div>`
    }).join('')
  }

  // ── Tap logic ──
  window._acakTapSlot = function(i){
    const sel = window._acakSelected
    if(sel === null){
      // Pilih slot ini
      window._acakSelected = i
      const hintEl = document.getElementById('_acakHint')
      if(hintEl){
        const nama = window._acakDraftList[i]?.name || i+1
        hintEl.innerHTML = `⚡ <strong style="color:#ffcc00;">${escapeHTML(String(nama))}</strong> dipilih — ketuk peserta lain untuk tukar posisi`
      }
    } else if(sel === i){
      // Batal pilih
      window._acakSelected = null
      const hintEl = document.getElementById('_acakHint')
      if(hintEl) hintEl.innerHTML = '👆 Ketuk peserta untuk memilih, lalu ketuk peserta lain untuk tukar posisi'
    } else {
      // Tukar posisi
      const a=window._acakDraftList;[a[sel],a[i]]=[a[i],a[sel]]
      window._acakSelected = null
      const hintEl = document.getElementById('_acakHint')
      if(hintEl) hintEl.innerHTML = `✅ Berhasil ditukar! Ketuk lagi untuk mengatur posisi lain`
    }
    refresh()
  }

  window._acakOtomatisDraft = function(){
    window._acakSelected = null
    const a = window._acakDraftList
    for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]] }
    const hintEl = document.getElementById('_acakHint')
    if(hintEl) hintEl.innerHTML = '🎲 Urutan diacak! Tap peserta untuk sesuaikan manual.'
    refresh()
  }

  window._konfirmasiManualAcak = function(){
    tournamentParticipants = [...window._acakDraftList]
    document.getElementById('_manualAcakPopup')?.remove()
    generateTournamentBracket(true)  // true = skip shuffle, pakai urutan manual
  }

  refresh()
}

function clearTournamentBracket() {
  if(!_tournClearConfirm) {
    _tournClearConfirm = true
    setTimeout(()=>{ _tournClearConfirm=false },5000)
    showPopup({typeNotif:"warning",message:"Klik lagi untuk hapus bagan turnamen"})
    return
  }
  _tournClearConfirm = false

  // Simpan slotId sebelum di-null-kan, untuk hapus dari Firebase
  const slotIdToDelete = tournamentBracketState?.slotId || null

  tournamentBracketState = null
  localStorage.removeItem("ps_tourn_bracket")

  // Hapus dari Firebase agar live bracket di halaman booking ikut hilang
  if(_fbDb && slotIdToDelete){
    _fbDb.ref("tournamentBracket/" + slotIdToDelete).remove()
    _fbDb.ref("settings/tournStarted").remove()
  } else if(_fbDb){
    // Fallback: hapus semua bracket jika slotId tidak diketahui
    _fbDb.ref("tournamentBracket").remove()
    _fbDb.ref("settings/tournStarted").remove()
  }

  showPopup({typeNotif:"success",message:"Bagan turnamen berhasil dihapus"})
  showDashboardView()
}

// Sync / force-clear Firebase bracket dari app
function syncTournBracketFirebase(){
  if(!_fbDb){
    showPopup({typeNotif:"warning", message:"Firebase belum terhubung"})
    return
  }
  if(!tournamentBracketState){
    // Tidak ada bagan lokal — hapus semua bracket di Firebase (cleanup stale data)
    if(!_fbSyncClearConfirm){
      _fbSyncClearConfirm = true
      setTimeout(()=>{ _fbSyncClearConfirm=false }, 5000)
      showPopup({typeNotif:"warning", message:"Tidak ada bagan lokal. Klik lagi untuk hapus semua bracket di Firebase"})
      return
    }
    _fbSyncClearConfirm = false
    _fbDb.ref("tournamentBracket").remove()
    _fbDb.ref("settings/tournStarted").remove()
    showPopup({typeNotif:"success", message:"☁️ Semua bracket lama di Firebase berhasil dihapus"})
    return
  }
  // Ada bagan lokal — push ulang ke Firebase
  const t = tournamentBracketState
  const slotId = t.slotId
  if(!slotId){
    showPopup({typeNotif:"error", message:"SlotId tidak ditemukan di bagan ini"})
    return
  }
  // Hapus bracket lain yang stale dulu
  _fbDb.ref("tournamentBracket").once("value", snap => {
    const all = snap.val() || {}
    Object.keys(all).forEach(k => {
      if(k !== slotId) _fbDb.ref("tournamentBracket/" + k).remove()
    })
  })
  // Push ulang bagan saat ini
  _fbDb.ref("tournamentBracket/" + slotId).set({
    rounds: JSON.stringify(t.rounds),
    config: t.config,
    participants: t.participants,
    createdAt: t.createdAt || Date.now(),
    slotId,
    slotNama: t.config?.title || ""
  })
  _fbDb.ref("settings/tournStarted").set({ slotId, startedAt: Date.now() })
  showPopup({typeNotif:"success", message:"☁️ Bracket berhasil di-sync ke Firebase"})
}
// Share link live bracket ke WhatsApp / clipboard
function shareLiveBracket(){
  const bookingUrl = localStorage.getItem("integrasi_booking_url") || "https://astro-booking-online.netlify.app"
  const url = bookingUrl + "?tab=turnamen"
  const t = tournamentBracketState
  const slotNama = t?.config?.title || "Turnamen"
  const msg = "🏆 *LIVE BRACKET " + slotNama.toUpperCase() + "* 🏆\n\nPantau bagan pertandingan secara real-time!\n🔗 " + url + "\n\n⚡ Update otomatis saat skor diinput oleh operator."
  if(navigator.share){
    navigator.share({ title:"Live Bracket " + slotNama, text:msg, url })
  } else {
    // Fallback: copy link + popup WA
    navigator.clipboard?.writeText(url).then(()=>{
      showPopup({typeNotif:"success", message:"✅ Link disalin! Buka WA untuk bagikan."})
    })
    const waUrl = "https://api.whatsapp.com/send?text=" + encodeURIComponent(msg)
    window.open(waUrl, "_blank")
  }
}

// Set status "preparing" di Firebase agar halaman booking tampilkan animasi menunggu
function _setBracketPreparing(slotId){
  if(!_fbDb){
    showPopup({typeNotif:"warning", message:"Firebase belum terhubung"})
    return
  }
  const s = tournSlots.find(x => x.id === slotId)
  if(!s){ showPopup({typeNotif:"error", message:"Slot tidak ditemukan"}); return }
  // Hapus bracket lama jika ada, set tournStarted tanpa bracket data
  _fbDb.ref("tournamentBracket/" + slotId).remove()
  _fbDb.ref("settings/tournStarted").set({ slotId, startedAt: Date.now(), preparing: true })
  showPopup({typeNotif:"success", message:"📡 Status 'Persiapan Bracket' sudah tayang di halaman booking!"})
}

let _fbSyncClearConfirm = false

// Share link live bracket
function shareLiveBracket(){
  const bookingUrl = localStorage.getItem("integrasi_booking_url") || "https://astro-booking-online.netlify.app"
  const url = bookingUrl + "?tab=turnamen"
  const t = tournamentBracketState
  const slotNama = t && t.config && t.config.title ? t.config.title : "Turnamen"
  const msg = "🏆 *LIVE BRACKET " + slotNama.toUpperCase() + "* 🏆\n\nPantau bagan pertandingan secara real-time!\n🔗 " + url + "\n\n⚡ Update otomatis saat skor diinput oleh operator."
  if(navigator.share){
    navigator.share({ title: "Live Bracket " + slotNama, text: msg, url })
  } else {
    const waUrl = "https://api.whatsapp.com/send?text=" + encodeURIComponent(msg)
    window.open(waUrl, "_blank")
    navigator.clipboard && navigator.clipboard.writeText(url).then(function(){
      showPopup({typeNotif:"success", message:"✅ Link disalin! Pesan WA sudah dibuka."})
    })
  }
}

// Set status persiapan bracket di Firebase
function _setBracketPreparing(slotId){
  if(!_fbDb){ showPopup({typeNotif:"warning", message:"Firebase belum terhubung"}); return }
  const s = tournSlots.find(function(x){ return x.id === slotId })
  if(!s){ showPopup({typeNotif:"error", message:"Slot tidak ditemukan"}); return }
  _fbDb.ref("tournamentBracket/" + slotId).remove()
  _fbDb.ref("settings/tournStarted").set({ slotId: slotId, startedAt: Date.now(), preparing: true })
  showPopup({typeNotif:"success", message:"📡 Status persiapan sudah tayang di halaman booking!"})
}

// Close tournament modal on ESC / backdrop
document.addEventListener("keydown", function(e) {
  if(e.key==="Escape" && activeMatchIdTournament) closeTournScoreModal()
  if(e.key==="Enter" && activeMatchIdTournament) saveTournScore()
})
document.addEventListener("click", function(e) {
  const modal = document.getElementById("tournScoreModal")
  if(modal && e.target===modal) closeTournScoreModal()
})


// ============================================================
//  LOCK MODE SYSTEM
// ============================================================

function selectLockMode(mode){
  document.querySelectorAll(".lock-mode-option").forEach(el => el.classList.remove("selected"))
  const target = document.getElementById("lockModeOpt" + mode.charAt(0).toUpperCase() + mode.slice(1))
  if(target) target.classList.add("selected")

  const radio = document.querySelector(`input[name="lockModeRadio"][value="${mode}"]`)
  if(radio) radio.checked = true
}

function saveLockMode(){
  const radio = document.querySelector("input[name='lockModeRadio']:checked")
  if(!radio) return

  const mode = radio.value
  localStorage.setItem("ps_lock_mode", mode)

  if(mode === "auto"){
    initAutoLock()
  } else {
    clearAutoLock()
  }

  showPopup({ typeNotif:"success", message:`Mode kunci diset ke: ${mode.toUpperCase()}` })
}

let autoLockTimer = null
let autoLockTimeout = 5 * 60 * 1000 // 5 minutes

function initAutoLock(){
  clearAutoLock()
  resetAutoLockTimer()
  document.addEventListener("mousemove", resetAutoLockTimer)
  document.addEventListener("keydown", resetAutoLockTimer)
  document.addEventListener("click", resetAutoLockTimer)
  document.addEventListener("touchstart", resetAutoLockTimer)
}

function clearAutoLock(){
  if(autoLockTimer) clearTimeout(autoLockTimer)
  autoLockTimer = null
  document.removeEventListener("mousemove", resetAutoLockTimer)
  document.removeEventListener("keydown", resetAutoLockTimer)
  document.removeEventListener("click", resetAutoLockTimer)
  document.removeEventListener("touchstart", resetAutoLockTimer)
}

function resetAutoLockTimer(){
  if(superAdminUnlocked) return
  if(autoLockTimer) clearTimeout(autoLockTimer)
  autoLockTimer = setTimeout(() => {
    if(superAdminUnlocked) return
    const lock = document.getElementById("lockScreen")
    if(!lock || !lock.classList.contains("visible")){
      lockScreen()
    }
  }, autoLockTimeout)
}

// Init auto-lock on load if setting is saved
;(function initLockModeOnLoad(){
  const saved = localStorage.getItem("ps_lock_mode") || "pin"
  if(saved === "auto") setTimeout(initAutoLock, 2000)
})()


// ============================================================
//  ABSENSI OPERATOR
// ============================================================

function getAbsensiList(){
  return JSON.parse(localStorage.getItem("ps_absensi")) || []
}

function saveAbsensiList(list){
  localStorage.setItem("ps_absensi", JSON.stringify(list))
}

// Reset absensi harian - berbasis jam 06:00 pagi (bukan tengah malam)
function getAbsensiResetDate(){
  const now = new Date()
  // Jika jam < 06:00, tanggal absensi adalah hari sebelumnya
  if(now.getHours() < 6){
    const prev = new Date(now)
    prev.setDate(prev.getDate() - 1)
    return prev.toDateString()
  }
  return now.toDateString()
}

function getTodayAbsensi(){
  const today = getAbsensiResetDate()
  const list = getAbsensiList()
  return list.find(a => a.date === today) || null
}

// Auto-save absen di jam 06:01 jika operator lupa absen keluar
;(function initAbsensiAutoSave(){
  setInterval(() => {
    const now = new Date()
    if(now.getHours() === 6 && now.getMinutes() === 1){
      const today = getAbsensiResetDate()
      const list = getAbsensiList()
      const idx = list.findIndex(a => a.date === today)
      if(idx !== -1 && list[idx].masuk && !list[idx].keluar){
        const jam = "06:01:00"
        list[idx].keluar = jam + " (Auto)"
        list[idx].keluarTs = now.getTime()
        saveAbsensiList(list)
      }
    }
  }, 30000) // cek tiap 30 detik
})()

function renderAbsensiPage(){
  const todayAbsensi = getTodayAbsensi()
  const now = new Date()
  const namaHari = ["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"]
  const namaBulan = ["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"]
  const tglStr = `${namaHari[now.getDay()]}, ${now.getDate()} ${namaBulan[now.getMonth()]} ${now.getFullYear()}`

  let statusBadge = ""
  let actionBtn = ""
  let keluarInfo = ""
  let namaDisplay = ""

  if(!todayAbsensi){
    statusBadge = `<span class="absensi-status-badge belum">⬜ BELUM ABSEN</span>`
    actionBtn = `
      <div class="absensi-name-wrap">
        <input type="text" id="inputNamaOperator" placeholder="✍️ Ketik nama operator dulu..." style="text-align:center;margin-bottom:6px;">
      </div>
      <button class="absensi-masuk-btn" onclick="absenMasuk()">✅ ABSEN MASUK</button>
    `
  } else if(todayAbsensi.masuk && !todayAbsensi.keluar){
    statusBadge = `<span class="absensi-status-badge hadir">🟢 SEDANG BERTUGAS</span>`
    namaDisplay = todayAbsensi.nama ? `<div class="absensi-nama-display">👤 ${escapeHTML(todayAbsensi.nama)}</div>` : ""
    actionBtn = `
      ${namaDisplay}
      <button class="absensi-keluar-btn" onclick="absenKeluar()">🚪 ABSEN KELUAR</button>
    `
    keluarInfo = `<div style="text-align:center;margin-top:8px;font-size:12px;color:var(--text-muted);">Masuk pukul: <strong style="color:var(--green-primary);">${todayAbsensi.masuk}</strong></div>`
  } else if(todayAbsensi.keluar){
    statusBadge = `<span class="absensi-status-badge pulang">🟡 SUDAH PULANG</span>`
    namaDisplay = todayAbsensi.nama ? `<div class="absensi-nama-display">👤 ${escapeHTML(todayAbsensi.nama)}</div>` : ""
    actionBtn = `
      ${namaDisplay}
      <button disabled style="opacity:0.4;cursor:not-allowed;">✅ ABSEN SUDAH DICATAT</button>
    `
    keluarInfo = `
      <div style="text-align:center;margin-top:8px;font-size:12px;color:var(--text-muted);">
        Masuk: <strong style="color:var(--green-primary);">${todayAbsensi.masuk}</strong>
        &nbsp;|&nbsp; Keluar: <strong style="color:var(--orange-warn);">${todayAbsensi.keluar}</strong>
      </div>
    `
  }

  // Riwayat absensi - ambil 20 terakhir
  const allAbsensi = getAbsensiList().slice(-20).reverse()
  const recordsHtml = allAbsensi.length === 0
    ? `<div class="history-empty">Belum ada riwayat absensi.</div>`
    : `<div class="absensi-records-grid">
        ${allAbsensi.map(a => {
          let dur = ""
          if(a.masukTs && a.keluarTs){
            const diff = Math.floor((a.keluarTs - a.masukTs) / 1000)
            const h = Math.floor(diff/3600)
            const m = Math.floor((diff%3600)/60)
            dur = `${h}j ${m}m`
          }
          return `
          <div class="absensi-record-card">
            <div class="absensi-record-header">
              <div class="absensi-record-date">${a.date}</div>
              ${a.keluar ? `<span class="absensi-status-badge pulang" style="font-size:8px;padding:3px 8px;">SELESAI</span>` : `<span class="absensi-status-badge hadir" style="font-size:8px;padding:3px 8px;">BERTUGAS</span>`}
            </div>
            ${a.nama ? `<div style="font-size:11px;color:var(--primary);margin-bottom:6px;">👤 ${escapeHTML(a.nama)}</div>` : ""}
            <div class="absensi-record-row">
              <div class="absensi-record-label">Jam Masuk</div>
              <div class="absensi-record-value">${a.masuk || "-"}</div>
            </div>
            <div class="absensi-record-row">
              <div class="absensi-record-label">Jam Keluar</div>
              <div class="absensi-record-value">${a.keluar || "-"}</div>
            </div>
            ${dur ? `<div class="absensi-record-duration">⏱️ Durasi Kerja: ${dur}</div>` : ""}
          </div>`
        }).join("")}
      </div>`

  const html = `
  <div class="absensi-page">
    <div class="absensi-header-card">
      <div class="absensi-header-icon">📋</div>
      <div>
        <div class="absensi-header-title">ABSENSI OPERATOR</div>
        <div class="absensi-header-sub">Reset setiap hari pukul 06:00 pagi · Auto-save jam 06:01</div>
      </div>
    </div>

    <div class="absensi-today-card">
      <div class="absensi-date-row">
        <div class="absensi-date-label">HARI INI</div>
        <div class="absensi-date-value">${tglStr}</div>
      </div>
      <div class="absensi-live-time" id="absensiLiveClock">--:--:--</div>
      <div style="text-align:center;margin-bottom:10px;">${statusBadge}</div>
      ${keluarInfo}
      ${actionBtn}
    </div>

    <div style="margin-top:20px;">
      <div style="font-family:'Orbitron',monospace;font-size:10px;letter-spacing:2px;color:var(--text-muted);margin-bottom:10px;">RIWAYAT ABSENSI</div>
      ${recordsHtml}
    </div>
  </div>
  `

  showInternalPage("📋 Absensi Operator", "Kelola absensi masuk dan keluar harian", html)
  startAbsensiClock()
}

function startAbsensiClock(){
  if(window._absensiClockInterval) clearInterval(window._absensiClockInterval)
  window._absensiClockInterval = setInterval(() => {
    const el = document.getElementById("absensiLiveClock")
    if(!el){ clearInterval(window._absensiClockInterval); return }
    const now = new Date()
    el.textContent = `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}:${String(now.getSeconds()).padStart(2,"0")}`
  }, 1000)
}

function absenMasuk(){
  const namaEl = document.getElementById("inputNamaOperator")
  const nama = namaEl ? namaEl.value.trim() : ""

  if(!nama){
    showPopup({ typeNotif:"warning", message:"⚠️ Masukkan nama operator dulu sebelum absen!" })
    return
  }

  const today = getAbsensiResetDate()
  const now = new Date()
  const jam = `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}:${String(now.getSeconds()).padStart(2,"0")}`

  const list = getAbsensiList()
  const existing = list.find(a => a.date === today)

  if(existing && existing.masuk){
    showPopup({ typeNotif:"warning", message:"Kamu sudah absen masuk hari ini." })
    return
  }

  const newRecord = { date: today, nama, masuk: jam, masukTs: now.getTime(), keluar: null, keluarTs: null }
  list.push(newRecord)
  saveAbsensiList(list)

  addOperatorLog(_getCurrentRole(), 'absen_masuk', nama + ' · pukul ' + jam)

  showPopup({ typeNotif:"success", message:`✅ Absen masuk berhasil - ${nama} - pukul ${jam}` })
  setTimeout(() => { renderAbsensiPage() }, 1800)
}

function absenKeluar(){
  const today = getAbsensiResetDate()
  const now = new Date()
  const jam = `${String(now.getHours()).padStart(2,"0")}:${String(now.getMinutes()).padStart(2,"0")}:${String(now.getSeconds()).padStart(2,"0")}`

  const list = getAbsensiList()
  const idx = list.findIndex(a => a.date === today)

  if(idx === -1 || !list[idx].masuk){
    showPopup({ typeNotif:"warning", message:"Absen masuk belum dicatat." })
    return
  }

  if(list[idx].keluar){
    showPopup({ typeNotif:"warning", message:"Kamu sudah absen keluar hari ini." })
    return
  }

  list[idx].keluar = jam
  list[idx].keluarTs = now.getTime()
  saveAbsensiList(list)

  const diff = Math.floor((now.getTime() - list[idx].masukTs) / 1000)
  const h = Math.floor(diff/3600)
  const m = Math.floor((diff%3600)/60)

  addOperatorLog(_getCurrentRole(), 'absen_keluar', (list[idx].nama||'') + ' · pukul ' + jam + ' · kerja ' + h + 'j ' + m + 'm')

  showPopup({ typeNotif:"success", message:`🚪 Absen keluar pukul ${jam}. Total kerja: ${h}j ${m}m` })
  setTimeout(() => { renderAbsensiPage() }, 1800)
}


// ============================================================
//  HASIL ABSENSI OPERATOR (Fitur Update menu)
// ============================================================

function renderHasilAbsensiPage(){
  const list = getAbsensiList().slice().reverse()
  const namaHari = ["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"]

  let totalHariMasuk = 0
  let totalDurasi = 0

  list.forEach(a => {
    if(a.masuk) totalHariMasuk++
    if(a.masukTs && a.keluarTs) totalDurasi += (a.keluarTs - a.masukTs)
  })

  const avgDur = totalHariMasuk > 0 ? Math.floor(totalDurasi / totalHariMasuk / 1000) : 0
  const avgH = Math.floor(avgDur / 3600)
  const avgM = Math.floor((avgDur % 3600) / 60)

  const recordsHtml = list.length === 0
    ? `<div class="history-empty">Belum ada data absensi operator.</div>`
    : `<div class="absensi-records-grid" id="hasilAbsensiGrid">
        ${list.map((a, i) => {
          let dur = "-"
          let durSec = 0
          if(a.masukTs && a.keluarTs){
            durSec = Math.floor((a.keluarTs - a.masukTs) / 1000)
            const h = Math.floor(durSec/3600)
            const m = Math.floor((durSec%3600)/60)
            dur = `${h}j ${m}m`
          }
          const statusColor = a.keluar ? "pulang" : (a.masuk ? "hadir" : "belum")
          return `
          <div class="absensi-record-card">
            <div class="absensi-record-header">
              <div class="absensi-record-date" style="font-size:11px;">${a.date}</div>
              <span class="absensi-status-badge ${statusColor}" style="font-size:8px;padding:3px 8px;">
                ${a.keluar ? "SELESAI" : a.masuk ? "AKTIF" : "ABSEN"}
              </span>
            </div>
            ${a.nama ? `<div style="font-size:11px;color:var(--primary);margin-bottom:6px;font-family:'Orbitron',monospace;">👤 ${escapeHTML(a.nama)}</div>` : ""}
            <div class="absensi-record-row">
              <div class="absensi-record-label">Jam Masuk</div>
              <div class="absensi-record-value" style="color:var(--green-primary);">${a.masuk || "-"}</div>
            </div>
            <div class="absensi-record-row">
              <div class="absensi-record-label">Jam Keluar</div>
              <div class="absensi-record-value" style="color:var(--orange-warn);">${a.keluar || "-"}</div>
            </div>
            <div class="absensi-record-row" style="border-bottom:none;">
              <div class="absensi-record-label">Durasi Kerja</div>
              <div class="absensi-record-value">${dur}</div>
            </div>
            <div style="display:flex;gap:6px;margin-top:10px;">
              <button class="history-action-btn history-action-delete" style="flex:1;margin:0;" onclick="hapusAbsensiRecord(${list.length - 1 - i})">🗑 Hapus</button>
              <button class="history-export-btn" style="flex:1;margin:0;" onclick="exportAbsensiSingle(${list.length - 1 - i})">📥 Export</button>
            </div>
          </div>`
        }).join("")}
      </div>`

  const html = `
  <div class="absensi-page">
    <div class="absensi-header-card">
      <div class="absensi-header-icon">📊</div>
      <div>
        <div class="absensi-header-title">HASIL ABSENSI OPERATOR</div>
        <div class="absensi-header-sub">Rekap data kehadiran dan jam kerja operator</div>
      </div>
    </div>

    <div class="hasil-absensi-summary">
      <div class="hasil-absensi-stat">
        <div class="hasil-absensi-stat-num">${list.length}</div>
        <div class="hasil-absensi-stat-label">Total Hari</div>
      </div>
      <div class="hasil-absensi-stat">
        <div class="hasil-absensi-stat-num">${totalHariMasuk}</div>
        <div class="hasil-absensi-stat-label">Hari Masuk</div>
      </div>
      <div class="hasil-absensi-stat">
        <div class="hasil-absensi-stat-num">${list.length - totalHariMasuk}</div>
        <div class="hasil-absensi-stat-label">Tidak Masuk</div>
      </div>
      <div class="hasil-absensi-stat">
        <div class="hasil-absensi-stat-num">${avgH}j ${avgM}m</div>
        <div class="hasil-absensi-stat-label">Rata-rata Kerja</div>
      </div>
    </div>

    <div class="hasil-absensi-filter">
      <input type="text" id="hasilAbsensiSearch" placeholder="🔎 Cari tanggal / status..." oninput="filterHasilAbsensi()">
      <input type="date" id="hasilAbsensiStart" onchange="filterHasilAbsensi()">
      <input type="date" id="hasilAbsensiEnd" onchange="filterHasilAbsensi()">
      <button style="flex:0 0 auto;padding:10px 16px;margin:0;width:auto;" onclick="exportSemuaAbsensi()">📥 Export Semua</button>
    </div>

    <div id="hasilAbsensiResult">
      ${recordsHtml}
    </div>
  </div>
  `

  showInternalPage("📊 Hasil Absensi Operator", "Rekap kehadiran lengkap dengan filter dan export", html)
}

function filterHasilAbsensi(){
  const search = (document.getElementById("hasilAbsensiSearch")?.value || "").toLowerCase().trim()
  const start = document.getElementById("hasilAbsensiStart")?.value || ""
  const end = document.getElementById("hasilAbsensiEnd")?.value || ""

  let list = getAbsensiList().slice().reverse()

  if(search){
    list = list.filter(a => a.date.toLowerCase().includes(search) || (a.masuk||"").includes(search) || (a.keluar||"").includes(search))
  }
  if(start){
    const sd = new Date(start); sd.setHours(0,0,0,0)
    list = list.filter(a => new Date(a.date) >= sd)
  }
  if(end){
    const ed = new Date(end); ed.setHours(23,59,59,999)
    list = list.filter(a => new Date(a.date) <= ed)
  }

  const wrapper = document.getElementById("hasilAbsensiResult")
  if(!wrapper) return

  if(!list.length){
    wrapper.innerHTML = `<div class="history-empty">Data tidak ditemukan.</div>`
    return
  }

  wrapper.innerHTML = `<div class="absensi-records-grid">
    ${list.map((a, i) => {
      let dur = "-"
      if(a.masukTs && a.keluarTs){
        const diff = Math.floor((a.keluarTs - a.masukTs) / 1000)
        dur = `${Math.floor(diff/3600)}j ${Math.floor((diff%3600)/60)}m`
      }
      const statusColor = a.keluar ? "pulang" : (a.masuk ? "hadir" : "belum")
      return `
      <div class="absensi-record-card">
        <div class="absensi-record-header">
          <div class="absensi-record-date">${a.date}</div>
          <span class="absensi-status-badge ${statusColor}" style="font-size:8px;padding:3px 8px;">${a.keluar?"SELESAI":a.masuk?"AKTIF":"ABSEN"}</span>
        </div>
        ${a.nama ? `<div style="font-size:11px;color:var(--primary);margin-bottom:6px;font-family:'Orbitron',monospace;">👤 ${escapeHTML(a.nama)}</div>` : ""}
        <div class="absensi-record-row"><div class="absensi-record-label">Masuk</div><div class="absensi-record-value" style="color:var(--green-primary);">${a.masuk||"-"}</div></div>
        <div class="absensi-record-row" style="border:none;"><div class="absensi-record-label">Keluar</div><div class="absensi-record-value" style="color:var(--orange-warn);">${a.keluar||"-"}</div></div>
        <div class="absensi-record-duration">⏱️ ${dur}</div>
      </div>`
    }).join("")}
  </div>`
}

function hapusAbsensiRecord(index){
  const list = getAbsensiList()
  if(!list[index]) return
  list.splice(index, 1)
  saveAbsensiList(list)
  renderHasilAbsensiPage()
  showPopup({ typeNotif:"success", message:"Data absensi berhasil dihapus" })
}

function exportSemuaAbsensi(){
  const list = getAbsensiList()
  if(!list.length){
    showPopup({ typeNotif:"warning", message:"Belum ada data absensi untuk diexport" })
    return
  }

  const header = ["Tanggal","Nama Operator","Jam Masuk","Jam Keluar","Durasi Kerja"]
  const rows = list.map(a => {
    let dur = "-"
    if(a.masukTs && a.keluarTs){
      const diff = Math.floor((a.keluarTs - a.masukTs) / 1000)
      dur = `${Math.floor(diff/3600)}j ${Math.floor((diff%3600)/60)}m`
    }
    return [a.date, a.nama||"-", a.masuk||"-", a.keluar||"-", dur]
  })

  const csv = [header, ...rows].map(r => r.map(v => `"${v}"`).join(",")).join("\n")
  const blob = new Blob([csv], { type:"text/csv;charset=utf-8;" })
  const url = URL.createObjectURL(blob)
  const a = document.createElement("a")
  a.href = url
  a.download = "rekap_absensi_operator.csv"
  a.click()
  URL.revokeObjectURL(url)

  showPopup({ typeNotif:"success", message:"Export absensi berhasil diunduh" })
}

function exportAbsensiSingle(index){
  const list = getAbsensiList()
  const a = list[index]
  if(!a) return

  let dur = "-"
  if(a.masukTs && a.keluarTs){
    const diff = Math.floor((a.keluarTs - a.masukTs) / 1000)
    dur = `${Math.floor(diff/3600)}j ${Math.floor((diff%3600)/60)}m`
  }

  const csv = `"Tanggal","Nama Operator","Jam Masuk","Jam Keluar","Durasi"\n"${a.date}","${a.nama||'-'}","${a.masuk||'-'}","${a.keluar||'-'}","${dur}"`
  const blob = new Blob([csv], { type:"text/csv;charset=utf-8;" })
  const url = URL.createObjectURL(blob)
  const el = document.createElement("a")
  el.href = url
  el.download = `absensi_${a.date.replace(/ /g,"_")}.csv`
  el.click()
  URL.revokeObjectURL(url)
}

// -- NATIVE IMAGE RESULT HANDLER (Sketchware Pro Bridge) ------------------
// Dipanggil dari Android onActivityResult setelah user pilih gambar galeri
window.onNativeImageResult = function(type, dataUrl){
  if(!dataUrl || dataUrl.length < 10) return
  if(type === "minuman"){
    window._nativeImgMinuman = dataUrl
    tampilkanPreviewGambarMinuman(dataUrl)
    const lb = document.getElementById("labelGambarMinuman")
    if(lb) lb.innerHTML = "✅ Gambar dipilih"
  } else if(type === "makanan"){
    window._nativeImgMakanan = dataUrl
    tampilkanPreviewGambarMakanan(dataUrl)
    const lb = document.getElementById("labelGambarMakanan")
    if(lb) lb.innerHTML = "✅ Gambar dipilih"
  } else if(type === "qris"){
    // Simpan base64 QRIS ke localStorage
    localStorage.setItem("qris_image_url", dataUrl)
    // Update preview
    const wrap = document.getElementById("qrisPreviewWrap")
    if(wrap) wrap.innerHTML = `<img src="${dataUrl}" style="width:160px;height:160px;border-radius:12px;border:2px solid rgba(255,107,0,0.35);object-fit:contain;background:#fff;">`
    // Update transaksi panel jika sedang tampil
    const qrisImgWrap = document.getElementById("qrisImgWrap")
    if(qrisImgWrap) qrisImgWrap.innerHTML = `<img src="${dataUrl}" style="width:180px;height:180px;border-radius:12px;border:2px solid rgba(255,107,0,0.30);object-fit:contain;background:#fff;">`
    showPopup({ typeNotif:"success", message:"✅ Foto QRIS berhasil disimpan!" })
  }
}
