function toggleCustomDrop(wrapId){
  const wrap = document.getElementById(wrapId)
  if(!wrap) return
  const list = wrap.querySelector('.custom-drop-list')
  const btn  = wrap.querySelector('.custom-drop-btn')
  if(!list || (btn && btn.disabled)) return

  const isOpen = list.classList.contains('open')

  // Tutup semua dropdown lain dulu
  document.querySelectorAll('.custom-drop-list.open').forEach(el => {
    el.classList.remove('open')
  })
  document.querySelectorAll('.custom-drop-btn.open').forEach(el => {
    el.classList.remove('open')
  })
  // Reset z-index semua card
  document.querySelectorAll('.card.dropdown-open-card').forEach(el => {
    el.classList.remove('dropdown-open-card')
  })

  // Toggle yang diklik
  if(!isOpen){
    list.classList.add('open')
    if(btn) btn.classList.add('open')
    // Elevate parent card agar dropdown tidak tertimpa card di bawahnya
    const parentCard = wrap.closest('.card')
    if(parentCard) parentCard.classList.add('dropdown-open-card')
  }
}

function setCustomDrop(wrapId, labelId, hiddenId, value, label, el){
  // Update nilai hidden input
  const hidden = document.getElementById(hiddenId)
  if(hidden) hidden.value = value

  // Update label yang tampil di tombol
  const lbl = document.getElementById(labelId)
  if(lbl) lbl.textContent = label

  // Update active item
  const wrap = document.getElementById(wrapId)
  if(wrap){
    wrap.querySelectorAll('.custom-drop-item').forEach(x => x.classList.remove('active'))
    if(el) el.classList.add('active')
    wrap.querySelector('.custom-drop-list')?.classList.remove('open')
    wrap.querySelector('.custom-drop-btn')?.classList.remove('open')
  }
}

// Tutup semua dropdown jika klik di luar
document.addEventListener('click', function(e){
  if(!e.target.closest('.custom-dropdown')){
    document.querySelectorAll('.custom-drop-list.open').forEach(el => el.classList.remove('open'))
    document.querySelectorAll('.custom-drop-btn.open').forEach(el => el.classList.remove('open'))
  }
})

// Fix scroll touch di dropdown Pesanan Tambahan (extra-order-section)
// Cegah event touchmove di-intercept halaman utama saat scroll dalam dropdown
document.addEventListener('touchmove', function(e){
  const list = e.target.closest('.extra-order-section .custom-drop-list')
  if(list && list.classList.contains('open')){
    e.stopPropagation()
  }
}, { passive: true })

// Pastikan saat touchstart di dalam dropdown, scroll halaman tidak ikut bergerak
document.addEventListener('touchstart', function(e){
  const list = e.target.closest('.extra-order-section .custom-drop-list')
  if(list && list.classList.contains('open')){
    e.stopPropagation()
  }
}, { passive: true })
// ===========================================================

function setDropDisabled(wrapId, isDisabled){
  const wrap = document.getElementById(wrapId)
  if(!wrap) return
  const btn = wrap.querySelector('.custom-drop-btn')
  if(btn){
    btn.disabled = isDisabled
    btn.style.opacity = isDisabled ? '0.28' : ''
    btn.style.cursor  = isDisabled ? 'not-allowed' : ''
    if(isDisabled){
      wrap.querySelector('.custom-drop-list')?.classList.remove('open')
      btn.classList.remove('open')
    }
  }
  const hidden = wrap.querySelector('input[type=hidden]')
  if(hidden) hidden.disabled = isDisabled
}

function pickTVType(i, nama, el){
  if(!state[i]) return
  state[i].type = nama; save()
  const h = document.getElementById('type'+i); if(h) h.value = nama
  const l = document.getElementById('typeLabel'+i); if(l) l.textContent = nama
  const w = document.getElementById('typeWrap'+i)
  if(w){
    w.querySelectorAll('.custom-drop-item').forEach(x=>x.classList.remove('active'))
    if(el) el.classList.add('active')
    w.querySelector('.custom-drop-list')?.classList.remove('open')
    w.querySelector('.custom-drop-btn')?.classList.remove('open')
  }
  // Sync tipe TV ke Firebase agar halaman booking update real-time
  setTimeout(_syncTVInfoToFirebase, 200)
}

function pickTVMode(i, mode, label, el){
  const h = document.getElementById('modeSelect'+i); if(h) h.value = mode
  const l = document.getElementById('modeLabel'+i); if(l) l.textContent = label
  const w = document.getElementById('modeWrap'+i)
  if(w){
    w.querySelectorAll('.custom-drop-item').forEach(x=>x.classList.remove('active'))
    if(el) el.classList.add('active')
    w.querySelector('.custom-drop-list')?.classList.remove('open')
    w.querySelector('.custom-drop-btn')?.classList.remove('open')
  }
  onModeSelectChange(i)
}

function syncModeDropLabel(i){
  const h = document.getElementById('modeSelect'+i); if(!h) return
  const mode = h.value || 'billing'
  const l = document.getElementById('modeLabel'+i)
  if(l) l.textContent = mode==='countdown' ? '⏳ Mode Countdown' : '⏱ Mode Billing'
  const w = document.getElementById('modeWrap'+i)
  if(w) w.querySelectorAll('.custom-drop-item').forEach(x=>x.classList.toggle('active', x.dataset.val===mode))
}

function pickMenuDropItem(i, jenis, id, label, el){
  const cap = jenis.charAt(0).toUpperCase()+jenis.slice(1)
  const h = document.getElementById('drop'+cap+i); if(h) h.value = id
  const l = document.getElementById('drop'+cap+'Label'+i); if(l) l.textContent = label
  const w = document.getElementById('drop'+cap+'Wrap'+i)
  if(w){
    w.querySelectorAll('.custom-drop-item').forEach(x=>x.classList.remove('active'))
    if(el) el.classList.add('active')
    w.querySelector('.custom-drop-list')?.classList.remove('open')
    w.querySelector('.custom-drop-btn')?.classList.remove('open')
  }
}

function renderCustomMenuDropItems(jenis, tvIndex){
  const list = jenis==='minuman' ? getMinumanList() : getMakananList()
  if(!list||!list.length) return '<div class="custom-drop-item" style="color:var(--text-dim);cursor:default;">- Belum ada '+jenis+' -</div>'
  const cap = jenis.charAt(0).toUpperCase()+jenis.slice(1)
  return list.map(item=>{
    const safeName = item.nama.replace(/'/g,"\'")
    const harga = Number(item.harga).toLocaleString('id-ID')
    const labelStr = safeName+' - Rp '+harga
    return '<div class="custom-drop-item" onclick="pickMenuDropItem('+tvIndex+',\''+jenis+'\',\''+item.id+'\',\''+labelStr+'\',this)">'
      +escapeHTML(item.nama)+' <span style="color:var(--lime-accent);font-size:10px;">Rp '+harga+'</span></div>'
  }).join('')
}

function refreshTVMenuDropdowns(){
  for(let i=1;i<=units;i++){
    const minEl = document.getElementById("dropMinumanList"+i)
    const makEl = document.getElementById("dropMakananList"+i)
    if(minEl) minEl.innerHTML = renderCustomMenuDropItems("minuman", i)
    if(makEl) makEl.innerHTML = renderCustomMenuDropItems("makanan", i)
  }
}
