// ===========================================================
// BAHASA & RESET PENGATURAN HELPERS
// ===========================================================

function setBahasa(lang){
  localStorage.setItem('ps_lang', lang)
  openMenu('bahasa')
  // Simpan untuk dipakai di sesi berikutnya
  showPopup({
    typeNotif: 'success',
    message: lang === 'en'
      ? '✅ Language set to English. Will apply on next session.'
      : '✅ Bahasa diubah ke Indonesia. Berlaku pada sesi berikutnya.'
  })
}

function doReset(tipe){
  if(tipe === 'tampilan'){
    localStorage.removeItem('ps_theme')
    localStorage.removeItem('ps_dashboard_theme')
    localStorage.removeItem('ps_font_size')
    localStorage.removeItem('ps_lang')
    applySavedTheme()
    applySavedFontSize()
    closePopup()
    showPopup({ typeNotif:'success', message:'✅ Tampilan berhasil direset ke default!' })
  } else if(tipe === 'catatan'){
    localStorage.removeItem('ps_catatan')
    closePopup()
    showPopup({ typeNotif:'success', message:'✅ Semua catatan harian telah dihapus!' })
  } else if(tipe === 'semua'){
    localStorage.removeItem('ps_theme')
    localStorage.removeItem('ps_dashboard_theme')
    localStorage.removeItem('ps_font_size')
    localStorage.removeItem('ps_lang')
    localStorage.removeItem('ps_catatan')
    applySavedTheme()
    applySavedFontSize()
    closePopup()
    showPopup({ typeNotif:'success', message:'✅ Semua pengaturan berhasil direset! Data transaksi & PIN aman.' })
  }
}
