function _submitFirebaseSetup(){
  const val = document.getElementById('fbSetupInput')?.value.trim()
  const err = document.getElementById('fbSetupErr')

  if(!val){ if(err) err.textContent = '⚠️ Paste config Firebase dulu'; return }

  // Bersihkan markdown backtick kalau ada
  const clean = val.replace(/```json|```/g, '').trim()

  let cfg = null
  try{ cfg = JSON.parse(clean) } catch(e){
    if(err) err.textContent = '❌ Format JSON tidak valid. Cek kembali.'
    return
  }

  if(!cfg.apiKey || !cfg.databaseURL){
    if(err) err.textContent = '❌ Config tidak lengkap. Harus ada apiKey dan databaseURL.'
    return
  }

  // Simpan ke localStorage
  localStorage.setItem('integrasi_firebase_config', JSON.stringify(cfg))

  if(err){ err.textContent = '✅ Config tersimpan! Menghubungkan...'; err.style.color = '#00ff88' }

  // Restart Firebase dan lanjut ke login
  setTimeout(()=>{
    try{ _initFirebase() } catch(e){}
    setTimeout(()=>{
      // Reset login screen ke normal
      const wrap = document.getElementById('loginMainWrap')
      if(wrap) wrap.innerHTML = `
        <div class="login-pin-title" style="margin-bottom:18px;">MASUK KE SISTEM</div>
        <div style="margin-bottom:12px;">
          <label style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;color:rgba(0,245,255,0.55);display:block;margin-bottom:6px;">👤 USERNAME</label>
          <input type="text" id="loginUsernameInput" placeholder="Masukkan username..." autocomplete="off"
            style="width:100%;padding:12px 14px;border-radius:12px;border:1px solid rgba(0,245,255,0.20);background:rgba(0,245,255,0.04);color:#fff;font-size:14px;outline:none;box-sizing:border-box;font-family:'Rajdhani',sans-serif;letter-spacing:1px;"
            oninput="loginCheckUsername()">
          <div id="loginUsernameHint" style="font-size:10px;color:rgba(168,200,240,0.40);margin-top:4px;min-height:14px;padding-left:2px;"></div>
        </div>
        <div style="margin-bottom:8px;">
          <label style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;color:rgba(0,245,255,0.55);display:block;margin-bottom:6px;">🔑 PIN</label>
          <input type="password" id="loginPinInput" class="login-pin-input" maxlength="6" placeholder="• • • •" readonly>
        </div>
        <div id="loginPinMsg" class="login-pin-msg"></div>
        <div class="login-numpad">
          <button onclick="loginPressPin('1')">1</button>
          <button onclick="loginPressPin('2')">2</button>
          <button onclick="loginPressPin('3')">3</button>
          <button onclick="loginPressPin('4')">4</button>
          <button onclick="loginPressPin('5')">5</button>
          <button onclick="loginPressPin('6')">6</button>
          <button onclick="loginPressPin('7')">7</button>
          <button onclick="loginPressPin('8')">8</button>
          <button onclick="loginPressPin('9')">9</button>
          <button onclick="loginClearPin()">C</button>
          <button onclick="loginPressPin('0')">0</button>
          <button onclick="loginSubmitPin()">OK</button>
        </div>`
      showLoginScreen()
    }, 1500)
  }, 500)
}

function showLoginScreen(){
  if(typeof hideLoadingScreen === 'function') hideLoadingScreen()
  const sc = document.getElementById('loginScreen')
  if(sc) sc.style.display = 'flex'
  document.body.style.overflow = 'hidden'
  window._loginPinBuf = ''
  window._foundUser   = null
  const inp = document.getElementById('loginPinInput')
  if(inp) inp.value = ''
  const msg = document.getElementById('loginPinMsg')
  if(msg) msg.textContent = ''

  // Load users dari localStorage dulu (offline)
  _loadLocalUsers()

  // Kalau Firebase ada → sync users dari Firebase (online)
  if(_fbDb){
    _fbDb.ref('users').once('value', snap => {
      let fbUsers = snap.val()
      // Safety: jika data berupa string (bug lama), parse dulu
      if(typeof fbUsers === 'string'){
        try{ fbUsers = JSON.parse(fbUsers) }catch(e){ fbUsers = null }
      }
      if(fbUsers && typeof fbUsers === 'object' && Object.keys(fbUsers).length > 0){
        // PIN Owner TIDAK diambil dari Firebase — selalu dari localStorage
        // Fallback ke '9999' jika ps_owner_pin belum pernah di-set (fresh install)
        const ownerPinLocal = localStorage.getItem('ps_owner_pin') || '9999'
        window._loginUsers = fbUsers
        // Selalu restore PIN owner
        Object.values(window._loginUsers).forEach(u => {
          if(u.role === 'owner') u.pin = ownerPinLocal
        })
        // Simpan ke localStorage sebagai cache
        localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers))
      }
    })
  }
}

function _loadLocalUsers(){
  // Cek cache users dari Firebase dulu
  const cached = localStorage.getItem('_cached_users')
  if(cached){
    try{
      const parsed = JSON.parse(cached)
      // Jangan pakai cache kosong {} — bisa terjadi akibat race condition Firebase
      if(parsed && Object.keys(parsed).length > 0){
        // Selalu restore PIN owner dari localStorage (fallback 9999 jika belum di-set)
        const ownerPinLocal = localStorage.getItem('ps_owner_pin') || '9999'
        Object.values(parsed).forEach(u => {
          if(u.role === 'owner') u.pin = ownerPinLocal
        })
        window._loginUsers = parsed
        return
      }
    }catch(e){}
  }
  // Kalau belum ada sama sekali atau cache tidak valid → buat owner default lokal
  if(Object.keys(window._loginUsers||{}).length === 0){
    _createDefaultOwnerLocal()
  }
}

function _createDefaultOwnerLocal(){
  // Gunakan PIN dari localStorage jika sudah pernah diset
  const savedPin = localStorage.getItem('ps_owner_pin') || '9999'
  const defaultOwner = {
    id:'owner_default', username:'owner', pin: savedPin,
    role:'owner', aktif:true, createdAt:Date.now()
  }
  window._loginUsers = { owner_default: defaultOwner }
  // Gunakan _origSetItem agar tidak trigger Firebase sync (avoid string overwrite)
  try{ _origSetItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
  // Jika Firebase ada → sync ke Firebase TANPA PIN owner, tulis sebagai object bersih
  if(_fbDb){
    _fbDb.ref('users').set({ owner_default: { ...defaultOwner, pin: '***' } })
  }
}

function hideLoginScreen(){
  const sc = document.getElementById('loginScreen')
  if(sc) sc.style.display = 'none'
  document.body.style.overflow = ''
}

function _loadLoginUsers(){
  if(!_fbDb){
    // Firebase belum ready — retry setelah 1 detik
    setTimeout(_loadLoginUsers, 1000)
    return
  }
  // Gunakan data cache yang sudah diload oleh realtime listener
  if(Object.keys(window._loginUsers).length > 0) return
  // Belum ada cache — load sekali
  _fbDb.ref('users').once('value', snap => {
    window._loginUsers = snap.val() || {}
    if(Object.keys(window._loginUsers).length === 0) _createDefaultOwner()
  })
}

function _createDefaultOwner(){
  // Gunakan PIN dari localStorage jika sudah pernah diset
  const savedPin = localStorage.getItem('ps_owner_pin') || '9999'
  const defaultOwner = { id:'owner_default', username:'owner', pin: savedPin, role:'owner', aktif:true, createdAt:Date.now() }
  window._loginUsers['owner_default'] = defaultOwner
  // Simpan ke localStorage sebagai fallback jika Firebase belum siap
  try{ _origSetItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
  // Sync ke Firebase jika sudah tersambung — PIN TIDAK dikirim ke Firebase
  // Hapus dulu isi lama (bisa berupa string) lalu tulis ulang sebagai object
  if(_fbDb) _fbDb.ref('users').set({ owner_default: { ...defaultOwner, pin: '***' } })
}

function loginCheckUsername(){
  const val = (document.getElementById('loginUsernameInput')?.value||'').trim().toLowerCase()
  const hint = document.getElementById('loginUsernameHint')
  if(!hint) return
  if(!val){ hint.textContent=''; window._foundUser=null; return }
  const found = Object.values(window._loginUsers).find(u => u.username?.toLowerCase()===val && u.aktif!==false)
  if(found){
    // PIN owner selalu dari localStorage — tidak dari Firebase
    // Fallback ke '9999' jika belum pernah di-set
    if(found.role === 'owner'){
      found.pin = localStorage.getItem('ps_owner_pin') || '9999'
    }
    window._foundUser = found
    hint.innerHTML = `<span style="color:#00ff88;">✓ ${found.role==='owner'?'👑 Owner':'👷 Operator'}</span>`
  } else {
    window._foundUser = null
    // Jika Firebase ada & users kosong → kemungkinan belum load
    if(window._fbDb && Object.keys(window._loginUsers||{}).length === 0){
      hint.innerHTML = `<span style="color:rgba(255,200,80,0.70);">⏳ Menunggu koneksi Firebase...</span>`
    } else {
      hint.innerHTML = `<span style="color:rgba(255,100,100,0.60);">Username tidak ditemukan</span>`
    }
  }
}

function backToRoleSelect(){ /* legacy compat */ }
function selectLoginRole(role){ /* legacy compat */ }

function loginPressPin(digit){
  if(window._pinLocked) return
  if(window._loginPinBuf.length >= 6) return
  if(!/^[0-9]$/.test(digit)) return
  window._loginPinBuf += digit
  const inp = document.getElementById('loginPinInput')
  if(inp) inp.value = '•'.repeat(window._loginPinBuf.length)
  _loginAutoCheck()
}

function _loginAutoCheck(){
  const pin = window._loginPinBuf
  if(!pin || pin.length < 4) return
  let user = window._foundUser
  if(!user){
    const val = (document.getElementById('loginUsernameInput')?.value||'').trim().toLowerCase()
    if(!val) return
    user = Object.values(window._loginUsers||{}).find(u=>u.username?.toLowerCase()===val&&u.aktif!==false)
    if(!user) return
  }
  // Selalu restore PIN owner dari localStorage — fallback 9999 jika belum pernah di-set
  if(user.role === 'owner'){
    user.pin = localStorage.getItem('ps_owner_pin') || '9999'
  }
  if(pin === user.pin){ window._foundUser = user; loginSubmitPin(); return }
  if(pin.length >= 6){ loginSubmitPin() }
}

function loginClearPin(){
  window._loginPinBuf = ''
  const inp = document.getElementById('loginPinInput')
  if(inp) inp.value = ''
  const msg = document.getElementById('loginPinMsg')
  if(msg) msg.textContent = ''
}

function loginSubmitPin(){
  try{
  const msg = document.getElementById('loginPinMsg')
  const inp = document.getElementById('loginPinInput')
  const pin = window._loginPinBuf
  if(!pin){ if(msg) msg.textContent='Masukkan PIN'; return }

  if(!window._foundUser){
    const val = (document.getElementById('loginUsernameInput')?.value||'').trim().toLowerCase()
    if(!val){ if(msg){msg.textContent='⚠️ Masukkan username dulu';msg.style.color='#ffcc00'} window._loginPinBuf='';if(inp)inp.value='';return }
    const found = Object.values(window._loginUsers).find(u=>u.username?.toLowerCase()===val&&u.aktif!==false)
    if(!found){ if(msg){msg.textContent='❌ Username tidak ditemukan';msg.style.color='#ff4d6d'} window._loginPinBuf='';if(inp)inp.value='';return }
    window._foundUser = found
  }

  const user = window._foundUser
  // Selalu restore PIN owner dari localStorage — fallback 9999 jika belum pernah di-set
  if(user.role === 'owner'){
    user.pin = localStorage.getItem('ps_owner_pin') || '9999'
  }
  if(pin !== user.pin){
    window._pinAttempts = (window._pinAttempts||0)+1
    const sisa = 5-window._pinAttempts
    if(msg){ msg.textContent = sisa>0?`❌ PIN salah! Sisa ${sisa} percobaan`:'🔒 Terlalu banyak percobaan!'; msg.style.color='#ff4d6d' }
    if(inp){ inp.style.animation='pinShake 0.4s ease'; setTimeout(()=>{inp.style.animation=''},500) }
    if(window._pinAttempts>=5){
      window._pinLocked=true
      const btns=document.querySelectorAll('.login-numpad button')
      btns.forEach(b=>b.disabled=true)
      let s=30; if(msg) msg.textContent=`🔒 Dikunci ${s} detik`
      const t=setInterval(()=>{ s--; if(msg) msg.textContent=`🔒 Dikunci ${s} detik`
        if(s<=0){ clearInterval(t);window._pinLocked=false;window._pinAttempts=0;btns.forEach(b=>b.disabled=false);if(msg){msg.textContent='';msg.style.color=''} }
      },1000)
    }
    window._loginPinBuf=''; if(inp) inp.value=''; return
  }

  // ✅ Login berhasil
  window._pinAttempts=0
  window._appRole = user.role
  window._appUser = user
  if(user.role==='owner') window.superAdminUnlocked=true

  // Sync users ke localStorage cache
  if(window._loginUsers){
    localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers))
  }

  if(_fbDb){
    _fbDb.ref('users/'+user.id+'/lastLogin').set(Date.now())
    _fbDb.ref('userLogs/'+user.id).push({action:'login',username:user.username,role:user.role,at:Date.now()})
  }
  addOperatorLog(user.role,'login',user.username)

  // Update tampilan user di sidebar
  const uInfo = document.getElementById('sidebarUserInfo')
  const uName = document.getElementById('sidebarUserName')
  const uRole = document.getElementById('sidebarUserRole')
  const uAvatar = document.getElementById('sidebarUserAvatar')
  if(uInfo){ uInfo.style.display='block' }
  if(uName) uName.textContent = user.username.toUpperCase()
  if(uRole) uRole.textContent = user.role === 'owner' ? 'OWNER' : 'OPERATOR'
  if(uAvatar) uAvatar.textContent = user.role === 'owner' ? '👑' : '👷'
  if(uInfo && user.role === 'owner'){
    uInfo.style.background = 'rgba(255,0,212,0.06)'
    uInfo.style.borderColor = 'rgba(255,0,212,0.20)'
    if(uName) uName.style.color = '#ff66e8'
  }

  // Info jika Firebase belum dikonfigurasi (opsional)
  if(window._fbConfigEmpty){
    setTimeout(()=>{
      showPopup({typeNotif:'info', message:'ℹ️ Firebase belum dikonfigurasi.\nData tersimpan di HP ini (localStorage).\n\nJika ingin sync realtime antar device,\nbuka Sistem → Integrasi Firebase.'})
    }, 2000)
  }

  // Peringatan jika masih pakai PIN default
  if(user.pin === '9999' && user.role === 'owner'){
    setTimeout(()=>{
      showPopup({typeNotif:'warning', message:'⚠️ PIN Owner masih default (9999)!\nSegera ganti di Sistem → Ganti PIN Owner.'})
    }, 2000)
  }

  applyRoleAccess(user.role)
  } catch(e){ console.warn('Login error:', e); const m=document.getElementById('loginPinMsg'); if(m){m.textContent='❌ Terjadi error, coba lagi'; m.style.color='#ff4d6d'} }
  updateAdminStatusIndicator()
  hideLoginScreen()
  _initAppAfterLogin()
}

function applyRoleAccess(role){
  const body = document.body
  if(role === 'owner'){
    body.classList.add('role-owner')
    body.classList.remove('role-operator')
  } else {
    body.classList.add('role-operator')
    body.classList.remove('role-owner')
  }
  updateLoginBadgeSidebar(role)
}

function updateLoginBadgeSidebar(role){
  const ind = document.getElementById('adminStatusIndicator')
  if(!ind) return
  if(role === 'owner'){
    ind.className = 'mode-indicator mode-owner'
    ind.innerHTML = '<span class="mode-indicator-dot"></span><span class="mode-indicator-text">MODE OWNER</span>'
  } else {
    ind.className = 'mode-indicator mode-operator'
    ind.innerHTML = '<span class="mode-indicator-dot"></span><span class="mode-indicator-text">MODE OPERATOR</span>'
  }
}

