  const role = window._appRole || 'operator'
  addOperatorLog(role, 'logout')

  // Simpan state billing saat ini ke localStorage sebelum logout
  // agar timer countdown tetap tersimpan & bisa dilanjutkan saat login lagi
  save()
  // Native alarm tetap berjalan di background (tidak dibatalkan)
  // sehingga countdown & notif tetap aktif walau layar terkunci

