function showLogoutDialog(tvAktif){
  const role = window._appRole || 'operator'
  const roleLabel = role==='owner' ? '👑 OWNER' : '👷 OPERATOR'
  const roleColor = role==='owner' ? '#ff66e8' : '#00f5ff'

  const warningHtml = tvAktif > 0 ? `
    <div style="background:rgba(255,154,60,0.08);border:1px solid rgba(255,154,60,0.24);
      border-radius:var(--radius-sm);padding:10px 14px;margin-bottom:10px;
      display:flex;align-items:flex-start;gap:10px;">
      <span style="font-size:20px;flex-shrink:0;">⚠️</span>
      <div style="font-size:11px;color:var(--orange-warn);line-height:1.6;">
        <strong>${tvAktif} TV masih aktif!</strong><br>
        <span style="color:rgba(200,160,80,0.80);">
          Jangan khawatir — state billing otomatis tersimpan.<br>
          Timer & countdown tetap berjalan di background.<br>
          Login lagi → semua langsung dilanjutkan.
        </span>
      </div>
    </div>` : `
    <div style="background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.12);
      border-radius:var(--radius-sm);padding:10px 14px;margin-bottom:10px;
      display:flex;align-items:center;gap:10px;">
      <span style="font-size:18px;">✅</span>
      <div style="font-size:11px;color:var(--text-muted);line-height:1.5;">
        Tidak ada billing aktif. Aman untuk logout.
      </div>
    </div>`

  const el = document.getElementById('logoutDialog')
  const content = document.getElementById('logoutDialogContent')
  if(!el || !content) return

  content.innerHTML = `
    <div style="text-align:center;margin-bottom:16px;">
      <div style="font-size:36px;margin-bottom:8px;">⏻</div>
      <div style="font-family:'Orbitron',monospace;font-size:14px;font-weight:700;
        color:var(--text-primary);letter-spacing:2px;margin-bottom:4px;">LOGOUT</div>
      <div style="font-size:11px;color:var(--text-muted);">
        Sesi saat ini:
        <span style="font-family:'Orbitron',monospace;font-size:11px;font-weight:700;
          color:${roleColor};">${roleLabel}</span>
      </div>
    </div>

    ${warningHtml}

    <div style="font-size:12px;color:var(--text-secondary);text-align:center;margin-bottom:20px;">
      Yakin ingin logout dari sesi ini?
    </div>

    <div style="display:flex;gap:10px;">
      <button onclick="closeLogoutDialog()"
        style="flex:1;margin:0;padding:12px;
        background:rgba(255,255,255,0.04);border-color:rgba(255,255,255,0.12);
        color:var(--text-muted);font-family:'Orbitron',monospace;
        font-size:11px;letter-spacing:1px;">
        BATAL
      </button>
      <button onclick="_doLogout()"
        style="flex:1;margin:0;padding:12px;
        background:linear-gradient(135deg,rgba(255,26,80,0.16),rgba(180,0,40,0.12));
        border-color:rgba(255,26,80,0.36);color:#ff6688;
        font-family:'Orbitron',monospace;font-size:11px;letter-spacing:1px;font-weight:700;">
        ⏻ LOGOUT
      </button>
    </div>
  `

  el.style.display = 'flex'
  requestAnimationFrame(()=>{
    el.style.opacity = '1'
    const box = document.getElementById('logoutDialogBox')
    if(box) box.style.transform = 'scale(1)'
  })
}

function closeLogoutDialog(){
  const el = document.getElementById('logoutDialog')
  if(!el) return
  el.style.opacity = '0'
  const box = document.getElementById('logoutDialogBox')
  if(box) box.style.transform = 'scale(0.95)'
  setTimeout(()=>{ el.style.display='none' }, 300)
}

