function _getEmergencyCode(){
  // Delegasikan ke fungsi private di dalam _LIC (salt tidak diekspos)
  return window._LIC ? window._LIC.emergencyCode() : 'DEADBEEF'
}

;(function(){
  var _tapCount = 0
  var _tapTimer = null
  window._ownerTapCount = function(){
    _tapCount++
    clearTimeout(_tapTimer)
    _tapTimer = setTimeout(function(){ _tapCount = 0 }, 2000)
    if(_tapCount >= 7){
      _tapCount = 0
      clearTimeout(_tapTimer)
      _showOwnerEmergencyReset()
    }
  }
})()

