function _submitOwnerEmergReset(){
  const newPin     = (document.getElementById('_emergNewPin')?.value||'').trim()
  const confirmPin = (document.getElementById('_emergConfirmPin')?.value||'').trim()
  const msg        = document.getElementById('_emergMsg')

  function err(t){ if(msg){ msg.textContent=t; msg.style.color='#ff4d6d' } }

  if(!newPin || newPin.length < 4){ err('⚠️ PIN minimal 4 digit'); return }
  if(newPin.length > 6){ err('⚠️ PIN maksimal 6 digit'); return }
  if(!/^[0-9]+$/.test(newPin)){ err('⚠️ PIN hanya boleh angka'); return }
  if(newPin === '9999' || newPin === '1234' || newPin === '0000'){ err('⚠️ PIN terlalu mudah ditebak'); return }
  if(newPin !== confirmPin){ err('❌ Konfirmasi PIN tidak cocok'); return }

  // Simpan ke localStorage
  localStorage.setItem('ps_owner_pin', newPin)
  try{ localStorage.setItem('ps_superadmin_pin', encodePIN ? encodePIN(newPin) : newPin) }catch(e){}

  // Update _loginUsers
  if(window._loginUsers){
    Object.values(window._loginUsers).forEach(u => { if(u.role==='owner') u.pin = newPin })
    try{ localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
  }
  if(window._foundUser && window._foundUser.role==='owner') window._foundUser.pin = newPin

  if(msg){ msg.textContent='✅ PIN Owner berhasil direset!'; msg.style.color='#00ff88' }

  setTimeout(()=>{
    document.getElementById('_ownerEmergReset')?.remove()
    // Arahkan ke input PIN login
    const inp = document.getElementById('loginPinInput')
    if(inp){ inp.value=''; inp.focus() }
    window._loginPinBuf = ''
    showPopup({ typeNotif:'success', message:'✅ PIN Owner berhasil direset!\nSilakan login dengan PIN baru.' })
  }, 1000)
}

function showForgotPin(){
  const role   = window._loginRole || 'operator'
  const pinWrap= document.getElementById('loginPinWrap')
  const fgWrap = document.getElementById('loginForgotWrap')
  const badge  = document.getElementById('forgotRoleBadge')

  if(pinWrap) pinWrap.style.display = 'none'
  if(fgWrap)  fgWrap.style.display  = 'block'

  if(badge){
    badge.textContent = role === 'owner' ? '👑 OWNER / SUPER ADMIN' : '👷 OPERATOR'
    badge.style.background   = role === 'owner' ? 'rgba(255,0,212,0.12)' : 'rgba(0,245,255,0.12)'
    badge.style.borderColor  = role === 'owner' ? 'rgba(255,0,212,0.30)' : 'rgba(0,245,255,0.28)'
    badge.style.color        = role === 'owner' ? '#ff66e8' : 'var(--primary)'
  }

  // Kosongkan form
  const inputs = ['forgotCodeInput','forgotNewPin','forgotConfirmPin']
  inputs.forEach(id => { const el=document.getElementById(id); if(el) el.value='' })
  const msg = document.getElementById('forgotMsg')
  if(msg) msg.textContent = ''
}

function hideForgotPin(){
  const pinWrap= document.getElementById('loginPinWrap')
  const fgWrap = document.getElementById('loginForgotWrap')
  if(fgWrap)  fgWrap.style.display  = 'none'
  if(pinWrap) pinWrap.style.display = 'block'
  window._loginPinBuf = ''
  const inp = document.getElementById('loginPinInput')
  if(inp) inp.value = ''
}

function submitForgotPin(){
  const role        = window._loginRole || 'operator'
  const codeInput   = document.getElementById('forgotCodeInput')?.value.trim().toUpperCase()
  const newPin      = document.getElementById('forgotNewPin')?.value.trim()
  const confirmPin  = document.getElementById('forgotConfirmPin')?.value.trim()
  const msg         = document.getElementById('forgotMsg')

  // Validasi kode darurat
  const correctCode = _getEmergencyCode()
  if(codeInput !== correctCode){
    if(msg){ msg.textContent = '❌ Kode darurat salah!'; msg.style.color='var(--red-danger)' }
    const inp = document.getElementById('forgotCodeInput')
    if(inp){ inp.style.borderColor='rgba(255,26,80,0.6)'; setTimeout(()=>inp.style.borderColor='',1500) }
    return
  }

  // Validasi PIN baru
  if(!newPin || newPin.length < 4){
    if(msg){ msg.textContent = '⚠️ PIN minimal 4 digit'; msg.style.color='var(--orange-warn)' }
    return
  }
  if(newPin.length > 6){
    if(msg){ msg.textContent = '⚠️ PIN maksimal 6 digit'; msg.style.color='var(--orange-warn)' }
    return
  }
  if(!/^[0-9]+$/.test(newPin)){
    if(msg){ msg.textContent = '⚠️ PIN hanya boleh angka'; msg.style.color='var(--orange-warn)' }
    return
  }
  if(newPin !== confirmPin){
    if(msg){ msg.textContent = '❌ Konfirmasi PIN tidak cocok'; msg.style.color='var(--red-danger)' }
    return
  }

  // Simpan PIN baru
  if(role === 'owner'){
    SUPER_ADMIN_PIN = newPin
    try{ localStorage.setItem('ps_superadmin_pin', encodePIN(newPin)) }catch(e){}
    // Simpan juga ke ps_owner_pin (sistem login baru)
    localStorage.setItem('ps_owner_pin', newPin)
    // Update _loginUsers agar langsung bisa login tanpa reload
    if(window._loginUsers){
      Object.values(window._loginUsers).forEach(u => {
        if(u.role === 'owner') u.pin = newPin
      })
      try{ localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
    }
    if(window._foundUser && window._foundUser.role === 'owner'){
      window._foundUser.pin = newPin
    }
  } else {
    LOCK_PIN = newPin
    try{ localStorage.setItem('ps_lock_pin', encodePIN(newPin)) }catch(e){}
    // Update _loginUsers untuk operator
    if(window._foundUser) window._foundUser.pin = newPin
    if(window._loginUsers){
      Object.values(window._loginUsers).forEach(u => {
        if(u.role !== 'owner' && u.username?.toLowerCase() === (window._foundUser?.username||'').toLowerCase()){
          u.pin = newPin
        }
      })
      try{ localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
    }
  }

  if(msg){ msg.textContent = '✅ PIN berhasil direset!'; msg.style.color='var(--cyan-accent)' }

  setTimeout(()=>{
    hideForgotPin()
    // Langsung ke PIN input dengan PIN baru
    window._loginPinBuf = ''
    const inp = document.getElementById('loginPinInput')
    if(inp) inp.value = ''
    if(msg) msg.textContent = ''
  }, 1200)
}

// Fungsi untuk owner lihat kode darurat dari dalam app (menu tentang app)
function getEmergencyCodeDisplay(){
  return _getEmergencyCode()
}

// Salin Device ID ke clipboard
function salinDeviceId(){
  const did = window._LIC ? window._LIC.getDeviceId() : ''
  if(!did) return

  const doToast = () => {
    const toast = document.getElementById('didCopyToast')
    if(toast){
      toast.style.display = 'block'
      setTimeout(()=>{ toast.style.display = 'none' }, 2000)
    }
  }

  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(did).then(doToast).catch(()=>{ _salinFallback(did); doToast() })
  } else {
    _salinFallback(did); doToast()
  }
}

// Salin kode darurat ke clipboard — dengan toast inline (tanpa popup)
function salinKodeDarurat(){
  const code = _getEmergencyCode()

  const doToast = () => {
    const toast = document.getElementById('kodeDaruratToast')
    if(toast){
      toast.style.display = 'block'
      setTimeout(()=>{ toast.style.display = 'none' }, 2200)
    }
  }

  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(code).then(doToast).catch(()=>{
      _salinFallback(code); doToast()
    })
  } else {
    _salinFallback(code); doToast()
  }
}

function _salinFallback(text){
  try{
    const ta = document.createElement('textarea')
    ta.value = text
    ta.style.cssText = 'position:fixed;opacity:0;top:0;left:0;'
    document.body.appendChild(ta)
    ta.focus(); ta.select()
    document.execCommand('copy')
    document.body.removeChild(ta)
  }catch(e){}
}
