// -- Nama Custom TV --
function simpanNamaTV(totalUnits){
  // Load existing data (preserve pages not currently shown)
  const tvNames = JSON.parse(localStorage.getItem('ps_tv_names')||'{}')
  const n = totalUnits || units
  for(let i=1;i<=n;i++){
    const el = document.getElementById('tvNameInput'+i)
    if(el){
      const val = el.value.trim()
      if(val) tvNames[i] = val
      else delete tvNames[i]

    }
  }
  localStorage.setItem('ps_tv_names', JSON.stringify(tvNames))
  // Update nama di card TV yang tampil
  for(let i=1;i<=units;i++){
    const cards = document.querySelectorAll('#card'+i+' .tv-title')
    cards.forEach(el=>{ el.textContent = tvNames[i] || 'TV '+i })
  }
  closePopup()
  showPopup({ typeNotif:'success', message:'Nama TV berhasil disimpan!' })
}

function resetNamaTV(){
  localStorage.removeItem('ps_tv_names')
  for(let i=1;i<=units;i++){
    const cards = document.querySelectorAll('#card'+i+' .tv-title')
    cards.forEach(el=>{ el.textContent = 'TV '+i })
  }
  closePopup()
  showPopup({ typeNotif:'success', message:'✅ Nama TV direset ke default' })
}

// Ambil nama TV (dipakai di tempat lain)
function getTVName(i){
  const tvNames = JSON.parse(localStorage.getItem('ps_tv_names')||'{}')
  return tvNames[i] || 'TV '+i
}

// -- Tarif VIP --
function simpanTarifVIP(totalUnits){
  // Load existing data (preserve data from other pages)
  const tvTarif = JSON.parse(localStorage.getItem('ps_tv_tarif')||'{}')
  const n = totalUnits || units
  for(let i=1;i<=n;i++){
    const el = document.getElementById('tvTarifInput'+i)
    if(el){
      // Strip dots from Rupiah format id-ID (e.g. "50.000" → 50000)
      const raw = String(el.value).replace(/\./g,'').replace(/[^0-9]/g,'')
      if(raw && Number(raw)>0) tvTarif[i] = Number(raw)
      else delete tvTarif[i]
    }
  }
  localStorage.setItem('ps_tv_tarif', JSON.stringify(tvTarif))
  closePopup()
  setTimeout(()=>{ createUI() }, 100)
  showPopup({ typeNotif:'success', message:'Tarif VIP berhasil disimpan!' })
}

function resetTarifVIP(){
  localStorage.removeItem('ps_tv_tarif')
  closePopup()
  setTimeout(()=>{ createUI() }, 100)
  showPopup({ typeNotif:'success', message:'Tarif VIP direset ke default' })
}

// Ambil harga TV (pakai VIP jika ada)
function getHargaTV(i, type){
  const tvTarif = JSON.parse(localStorage.getItem('ps_tv_tarif')||'{}')
  if(tvTarif[i] && Number(tvTarif[i]) > 0) return Number(tvTarif[i])
  return getConsolePriceByType(type)
}

// -- Hadiah Turnamen --
function simpanHadiahTurna(){
  const judul      = document.getElementById('hadiahJudul')?.value.trim() || ''
  const grandPrize = document.getElementById('hadiahGrandPrize')?.value.trim() || ''
  // Parse total hadiah: bisa format "500.000" atau angka biasa
  const rawTotal   = (document.getElementById('hadiahTotal')?.value||'').replace(/\D/g,'')
  const total      = rawTotal || ''
  const nj         = window._jumlahJuaraAktif || 3
  const ket        = document.getElementById('hadiahKet')?.value||''

  // Kumpulkan persen per juara (hanya yang aktif)
  const split = {1:0, 2:0, 3:0}
  let totalPct = 0
  for(let n=1; n<=nj; n++){
    const p = Number(document.getElementById('hadiah'+n+'Pct')?.value)||0
    split[n] = p
    totalPct += p
  }

  if(totalPct > 100){
    showPopup({ typeNotif:'warning', message:'Total pembagian '+totalPct+'% melebihi 100%!' })
    return
  }

  const data = { judul, grandPrize, total, jumlahJuara:nj, split, keterangan:ket }
  localStorage.setItem('ps_hadiah_turna', JSON.stringify(data))

  // Sync ke tournamentConfig & bracket
  _syncHadiahToConfig()
  saveTournamentAll()

  closePopup()
  showPopup({ typeNotif:'success', message:'Hadiah & judul turnamen disimpan!' })
}

