function cariMemberTrx(query){
  const resultEl = document.getElementById('memberSearchResultTrx')
  const clearBtn = document.getElementById('clearMemberTrx')
  if(!resultEl) return

  if(!query || query.trim() === ''){
    resultEl.style.display = 'none'
    if(clearBtn) clearBtn.style.display = 'none'
    return
  }

  if(clearBtn) clearBtn.style.display = 'block'

  const members = getMemberList()
  const q = query.toLowerCase()
  const found = members.filter(m=>
    m.nama.toLowerCase().includes(q) || (m.hp||'').includes(q)
  ).slice(0,6)

  if(!found.length){
    resultEl.style.display = 'block'
    resultEl.innerHTML = '<div style="padding:12px 14px;font-size:12px;color:var(--text-dim);">Member tidak ditemukan</div>'
    return
  }

  const diskonCfg = JSON.parse(localStorage.getItem('ps_diskon_konfig')||'{"aktif":false,"persen":0,"minPoin":0}')

  resultEl.style.display = 'block'
  resultEl.innerHTML = found.map(m=>{
    const eligible = diskonCfg.aktif && (m.poin||0) >= (diskonCfg.minPoin||0)
    const diskonText = eligible
      ? `<span style="color:var(--lime-accent);font-size:9px;margin-left:4px;">-${diskonCfg.persen}% diskon</span>`
      : ''
    return `
      <div onclick="pilihMemberTrx('${m.id}')"
        style="display:flex;align-items:center;gap:10px;padding:10px 14px;
        border-bottom:1px solid rgba(0,245,255,0.06);cursor:pointer;
        transition:background .15s;"
        onmouseover="this.style.background='rgba(0,245,255,0.07)'"
        onmouseout="this.style.background=''">
        <div style="width:32px;height:32px;border-radius:50%;flex-shrink:0;
          background:linear-gradient(135deg,rgba(0,245,255,0.14),rgba(119,0,255,0.10));
          border:1.5px solid rgba(0,245,255,0.22);
          display:flex;align-items:center;justify-content:center;
          font-family:'Orbitron',monospace;font-size:12px;font-weight:700;
          color:var(--primary);">${m.nama.charAt(0).toUpperCase()}</div>
        <div style="flex:1;">
          <div style="font-size:12px;font-weight:600;color:var(--text-primary);">
            ${escapeHTML(m.nama)} ${diskonText}
          </div>
          <div style="font-size:10px;color:var(--text-muted);">
            ⭐ ${m.poin||0} poin${m.hp?' · '+m.hp:''}
          </div>
        </div>
      </div>
    `
  }).join('')
}

function pilihMemberTrx(memberId){
  const members = JSON.parse(localStorage.getItem('ps_members')||'[]')
  const m = members.find(x=>x.id===memberId)
  if(!m) return

  if(pendingTransaction) pendingTransaction.selectedMember = m

  // Sembunyikan hasil cari
  const resultEl = document.getElementById('memberSearchResultTrx')
  const searchEl = document.getElementById('memberSearchTrx')
  if(resultEl) resultEl.style.display = 'none'
  if(searchEl) searchEl.value = m.nama

  // Tampilkan info member terpilih
  tampilMemberTerpilihTrx(m)

  // Update grand total display dengan diskon
  updateGrandTotalWithDiskon(m)
}

function tampilMemberTerpilihTrx(m){
  const el = document.getElementById('memberSelectedTrx')
  if(!el) return

  const diskonCfg = JSON.parse(localStorage.getItem('ps_diskon_konfig')||'{"aktif":false,"persen":0,"minPoin":0}')
  const eligible   = diskonCfg.aktif && (m.poin||0) >= (diskonCfg.minPoin||0)
  const poinCfg    = JSON.parse(localStorage.getItem('ps_poin_konfig')||'{"poinPerRibu":1,"nilaiTukar":1000}')
  const nilaiTukar = Number(poinCfg.nilaiTukar)||1000

  const items = Array.isArray(pendingTransaction?.items) ? pendingTransaction.items : []
  const totalTambahan = items.reduce((s,i)=>s+(Number(i.harga)||0),0)
  let grand = (pendingTransaction?.total||0) + totalTambahan
  if(eligible) grand = Math.max(0, grand - Math.round(grand*(diskonCfg.persen||0)/100))

  const poinMember    = m.poin || 0
  const nilaiPoin     = poinMember * nilaiTukar   // nilai poin dalam Rp
  const maxPoinPotong = Math.min(nilaiPoin, grand) // tidak boleh melebihi grand total
  const tukarAktif    = pendingTransaction?.tukarPoin || false
  const poinDapat     = tukarAktif ? 0 : Math.floor(grand/1000)*(poinCfg.poinPerRibu||1)

  el.style.display = 'block'
  el.innerHTML = `
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
      <span style="font-size:20px;">👤</span>
      <div style="flex:1;">
        <div style="font-size:13px;font-weight:700;color:var(--text-primary);">
          ${escapeHTML(m.nama)}
        </div>
        <div style="font-size:10px;color:var(--text-muted);">
          ⭐ <strong style="color:var(--orange-warn);">${poinMember}</strong> poin
          &nbsp;·&nbsp; nilai = ${formatRupiah(nilaiPoin)}
        </div>
      </div>
      ${eligible
        ? `<span style="font-family:'Orbitron',monospace;font-size:10px;font-weight:700;
            padding:3px 9px;border-radius:20px;
            background:rgba(204,255,0,0.12);border:1px solid rgba(204,255,0,0.26);
            color:var(--lime-accent);">-${diskonCfg.persen}%</span>`
        : ''
      }
    </div>

    ${poinMember > 0 ? `
    <div style="border-top:1px solid rgba(0,245,255,0.08);padding-top:8px;">
      ${tukarAktif ? `
        <div style="display:flex;align-items:center;justify-content:space-between;
          padding:8px 10px;border-radius:var(--radius-sm);
          background:rgba(204,255,0,0.08);border:1px solid rgba(204,255,0,0.22);
          margin-bottom:6px;">
          <div>
            <div style="font-size:11px;font-weight:700;color:var(--lime-accent);">
              ✅ Tukar ${poinMember} poin
            </div>
            <div style="font-size:10px;color:var(--text-muted);">
              Potongan: -${formatRupiah(maxPoinPotong)}
            </div>
          </div>
          <button onclick="batalTukarPoin()" style="width:auto;margin:0;padding:4px 10px;
            font-size:10px;border-radius:8px;
            background:rgba(255,26,80,0.12);border-color:rgba(255,26,80,0.26);
            color:#ff6688;">Batal</button>
        </div>
      ` : `
        <button onclick="aktifkanTukarPoin()" style="width:100%;margin:0;padding:9px 12px;
          background:linear-gradient(135deg,rgba(255,204,0,0.12),rgba(204,255,0,0.10));
          border:1px solid rgba(255,204,0,0.28);border-radius:var(--radius-sm);
          color:var(--orange-warn);font-family:'Orbitron',monospace;
          font-size:10px;font-weight:700;letter-spacing:1px;cursor:pointer;">
          ⭐ TUKAR ${poinMember} POIN = -${formatRupiah(maxPoinPotong)}
        </button>
      `}
      ${!tukarAktif && poinDapat>0 ? `
        <div style="text-align:center;font-size:10px;color:var(--text-dim);margin-top:6px;">
          Jika tidak tukar → dapat +${poinDapat} poin dari transaksi ini
        </div>
      ` : ''}
    </div>
    ` : `
    <div style="font-size:10px;color:var(--text-dim);
      border-top:1px solid rgba(0,245,255,0.06);padding-top:6px;">
      Belum punya poin. Selesaikan transaksi untuk kumpulkan poin.
    </div>
    `}
  `
}

function _hitungGrandTrx(){
  // Hitung grand total dengan diskon & tukar poin
  const m         = pendingTransaction?.selectedMember
  const items     = Array.isArray(pendingTransaction?.items) ? pendingTransaction.items : []
  const tambahan  = items.reduce((s,i)=>s+(Number(i.harga)||0),0)
  let grand       = (pendingTransaction?.total||0) + tambahan

  const diskonCfg = JSON.parse(localStorage.getItem('ps_diskon_konfig')||'{"aktif":false,"persen":0,"minPoin":0}')
  const poinCfg   = JSON.parse(localStorage.getItem('ps_poin_konfig')||'{"poinPerRibu":1,"nilaiTukar":1000}')
  const nilaiTukar= Number(poinCfg.nilaiTukar)||1000

  let diskon = 0
  let potongPoin = 0

  if(m){
    // Diskon %
    if(diskonCfg.aktif && (m.poin||0) >= (diskonCfg.minPoin||0)){
      diskon = Math.round(grand * (diskonCfg.persen||0) / 100)
    }
    grand = Math.max(0, grand - diskon)

    // Tukar poin
    if(pendingTransaction?.tukarPoin && (m.poin||0) > 0){
      potongPoin = Math.min((m.poin||0) * nilaiTukar, grand)
      grand = Math.max(0, grand - potongPoin)
    }
  }

  return { grand, diskon, potongPoin, raw:(pendingTransaction?.total||0)+tambahan }
}

function updateGrandTotalWithDiskon(m){
  const { grand, diskon, potongPoin, raw } = _hitungGrandTrx()
  const gtEl = document.querySelector('.popup-grand-total')
  if(!gtEl) return

  const diskonCfg = JSON.parse(localStorage.getItem('ps_diskon_konfig')||'{"aktif":false,"persen":0,"minPoin":0}')

  let html = ''
  if(diskon > 0 || potongPoin > 0){
    html += `<span style="text-decoration:line-through;color:var(--text-dim);font-size:12px;">Grand Total: ${formatRupiah(raw)}</span><br>`
    if(diskon > 0)
      html += `<span style="color:var(--lime-accent);font-size:11px;">Diskon ${diskonCfg.persen}%: -${formatRupiah(diskon)}</span><br>`
    if(potongPoin > 0)
      html += `<span style="color:var(--orange-warn);font-size:11px;">⭐ Tukar poin: -${formatRupiah(potongPoin)}</span><br>`
    html += `<span style="color:var(--primary);font-size:16px;font-weight:700;">Grand Total: ${formatRupiah(grand)}</span>`
  } else {
    html = `Grand Total: ${formatRupiah(raw)}`
  }
  gtEl.innerHTML = html
}

function aktifkanTukarPoin(){
  if(!pendingTransaction?.selectedMember) return
  pendingTransaction.tukarPoin = true
  const m = pendingTransaction.selectedMember
  tampilMemberTerpilihTrx(m)
  updateGrandTotalWithDiskon(m)
  // Update kembalian juga
  hitungKembalian()
}

function batalTukarPoin(){
  if(!pendingTransaction) return
  pendingTransaction.tukarPoin = false
  const m = pendingTransaction.selectedMember
  if(m){
    tampilMemberTerpilihTrx(m)
    updateGrandTotalWithDiskon(m)
  }
  hitungKembalian()
}

function clearMemberTrx(){
  if(pendingTransaction) pendingTransaction.selectedMember = null
  const searchEl = document.getElementById('memberSearchTrx')
  const resultEl = document.getElementById('memberSearchResultTrx')
  const selEl    = document.getElementById('memberSelectedTrx')
  const clearBtn = document.getElementById('clearMemberTrx')
  if(searchEl){ searchEl.value = ''; searchEl.focus() }
  if(resultEl) resultEl.style.display = 'none'
  if(selEl)    selEl.style.display = 'none'
  if(clearBtn) clearBtn.style.display = 'none'

  // Restore grand total normal
  if(pendingTransaction){
    const items = Array.isArray(pendingTransaction.items) ? pendingTransaction.items : []
    const totalTambahan = items.reduce((s,i)=>s+(Number(i.harga)||0),0)
    const grand = (pendingTransaction.total||0) + totalTambahan
    const gtEl = document.querySelector('.popup-grand-total')
    if(gtEl) gtEl.textContent = 'Grand Total: Rp '+grand.toLocaleString('id-ID')
  }
}
