// ============================================================
// Hapus transaksi terlama lalu simpan transaksi pending (dari popup upgrade)
// ============================================================
function hapusTransaksiTerlamaLaluSimpan(){
  const finalData = window._pendingFinalData
  if(!finalData){ closePopup(); return }

  // Hapus yang paling lama (elemen terakhir array — LIFO)
  if(history.length > 0){
    const removed = history.pop()
    // Sync historyToday jika ada
    const idxToday = historyToday.findIndex(h =>
      h.tv === removed.tv && h.date === removed.date && h.total === removed.total)
    if(idxToday !== -1) historyToday.splice(idxToday, 1)
  }

  // Simpan transaksi baru
  history.push(finalData)
  historyToday.push(finalData)

  addOperatorLog(_getCurrentRole(), 'simpan_transaksi', 'TV ' + finalData.tv + ' · ' + (finalData.type||'-') + ' · Rp ' + (finalData.total||0).toLocaleString('id-ID') + ' (riwayat lama dihapus)')

  // Reset state TV
  const i = finalData.tv
  const oldType = state[i]?.type || finalData.type || "PS3"
  state[i] = { mode:null, start:null, type:oldType, duration:0, expired:false, items:[] }

  window._pendingFinalData = null
  window._pendingTVBackup  = null

  save()
  resetHistoryHarian()
  hitungOmzet()
  createUI()
  closePopup()
  cekAlarmGlobal()

  showPopup({
    typeNotif: 'success',
    message: '✅ Transaksi berhasil disimpan (1 riwayat lama dihapus otomatis).'
  })
}
