function simpanCatatan(){
  const inputEl = document.getElementById('inputCatatan')
  if(!inputEl) return
  const text = inputEl.value.trim()
  if(!text){
    showPopup({ typeNotif:'warning', message:'Tulis catatan dulu sebelum simpan.' })
    return
  }

  const notes = JSON.parse(localStorage.getItem('ps_catatan')||'[]')

  if(_isFreeMode() && notes.length >= FREE_CATATAN_MAX){
    showUpgradePopup({
      reason: `Versi Gratis hanya menyimpan maksimal ${FREE_CATATAN_MAX} catatan harian.`,
      hint: 'Hapus catatan lama yang sudah tidak diperlukan, atau upgrade PRO untuk catatan tak terbatas.'
    })
    return
  }

  const now = new Date()
  const waktu = now.toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}) +
    ' · ' + now.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'})

  notes.unshift({ text, waktu, ts: now.getTime() })
  localStorage.setItem('ps_catatan', JSON.stringify(notes))

  inputEl.value = ''
  _refreshCatatan()
  showPopup({ typeNotif:'success', message:'Catatan disimpan!' })
}

function hapusCatatan(idx){
  const notes = JSON.parse(localStorage.getItem('ps_catatan')||'[]')
  notes.splice(idx, 1)
  localStorage.setItem('ps_catatan', JSON.stringify(notes))
  _refreshCatatan()
}

function hapusSemuaCatatan(){
  if(!confirm('Hapus semua catatan?')) return
  localStorage.setItem('ps_catatan', '[]')
  _refreshCatatan()
}

function _refreshCatatan(){
  const _allNotes = JSON.parse(localStorage.getItem('ps_catatan')||'[]')
  const notes = (_isFreeMode() && _allNotes.length > FREE_CATATAN_MAX) ? _allNotes.slice(0, FREE_CATATAN_MAX) : _allNotes
  const container = document.getElementById('daftarCatatan')
  const countEl   = document.getElementById('catatanCount')
  const hapusBtn  = document.getElementById('hapusSemuaBtn')

  if(countEl) countEl.textContent = 'CATATAN TERSIMPAN ('+notes.length+')'
  if(hapusBtn) hapusBtn.style.display = notes.length>0 ? 'block' : 'none'

  if(!container) return
  if(notes.length === 0){
    container.innerHTML = `<div style="text-align:center;padding:20px;color:var(--text-dim);
      font-family:'Orbitron',monospace;font-size:11px;letter-spacing:1px;">
      Belum ada catatan</div>`
    return
  }
  container.innerHTML = notes.map((note, idx)=>`
    <div style="display:flex;align-items:flex-start;gap:8px;padding:10px 12px;
      background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.10);
      border-radius:var(--radius-sm);margin-bottom:7px;">
      <div style="flex:1;font-size:13px;color:var(--text-primary);line-height:1.6;">
        ${escapeHTML(note.text)}
        <div style="font-size:10px;color:var(--text-dim);margin-top:4px;
          font-family:'Orbitron',monospace;">${note.waktu||''}</div>
      </div>
      <button onclick="hapusCatatan(${idx})" style="width:auto;margin:0;padding:4px 8px;
        font-size:11px;background:rgba(255,26,80,0.10);border-color:rgba(255,26,80,0.22);
        color:#ff6688;border-radius:8px;flex-shrink:0;">✕</button>
    </div>
  `).join('')
}
