// ============================================================
// SIDEBAR DRAG — Long press 750ms pada item menu untuk susun ulang
// Hanya sub-item dalam kategori yang bisa di-drag (bukan header kategori)
// ============================================================
;(function(){
  const LONG_PRESS = 750
  const MOVE_THRESH = 10

  let phase = 'idle'
  let timer = null, dragBtn = null, dragContainer = null, ghostEl = null
  let px = 0, py = 0, ghostOffY = 0

  function getXY(e){
    const t = e.touches?.[0] || e.changedTouches?.[0] || e
    return { x: t.clientX||0, y: t.clientY||0 }
  }

  // Ambil semua sibling button dalam container yang sama
  function getSiblings(container){
    return Array.from(container.querySelectorAll(':scope > button'))
  }

  function getDropTarget(container, cy){
    for(const btn of getSiblings(container)){
      if(btn === dragBtn) continue
      const r = btn.getBoundingClientRect()
      if(cy < r.top + r.height * 0.5) return btn
    }
    return null
  }

  function showLine(container, target){
    rmLine()
    const ln = document.createElement('div')
    ln.id = '_sdrLine'
    ln.style.cssText = 'height:2px;margin:1px 4px;border-radius:2px;pointer-events:none;' +
      'background:linear-gradient(90deg,transparent,#00f5ff 30%,#ff00d4 70%,transparent);' +
      'box-shadow:0 0 8px rgba(0,245,255,0.55);'
    if(target) container.insertBefore(ln, target)
    else container.appendChild(ln)
  }

  function rmLine(){ const l=document.getElementById('_sdrLine'); if(l)l.remove() }

  function makeGhost(el){
    const r = el.getBoundingClientRect()
    const g = el.cloneNode(true)
    g.id = '_sdrGhost'
    g.style.cssText = `position:fixed;z-index:99998;pointer-events:none;
      left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;
      opacity:0.80;background:rgba(0,245,255,0.14);
      border:2px dashed rgba(0,245,255,0.55);border-radius:8px;
      box-shadow:0 4px 24px rgba(0,0,0,0.70);transform:scale(1.02);`
    document.body.appendChild(g)
    return g
  }

  function startDrag(btn, container, startY){
    phase = 'dragging'
    if(navigator.vibrate) navigator.vibrate([20,15,35])

    dragBtn = btn
    dragContainer = container
    dragBtn._savedCSS = dragBtn.style.cssText
    dragBtn.style.opacity = '0.25'
    dragBtn.style.outline = '1.5px dashed rgba(0,245,255,0.45)'

    const r = dragBtn.getBoundingClientRect()
    ghostOffY = startY - r.top
    ghostEl = makeGhost(dragBtn)
    ghostEl.style.top = (startY - ghostOffY) + 'px'

    document.addEventListener('touchmove', onMove, { passive:false })
    document.addEventListener('mousemove', onMove)
  }

  function drop(cy){
    const target = getDropTarget(dragContainer, cy)
    if(target !== dragBtn && target !== dragBtn?.nextElementSibling){
      if(target) dragContainer.insertBefore(dragBtn, target)
      else dragContainer.appendChild(dragBtn)
      if(navigator.vibrate) navigator.vibrate(20)
    }
    cleanup()
  }

  function cleanup(){
    rmLine()
    if(ghostEl){ ghostEl.remove(); ghostEl=null }
    if(dragBtn){ dragBtn.style.cssText = dragBtn._savedCSS||''; dragBtn=null }
    dragContainer = null
    document.removeEventListener('touchmove', onMove)
    document.removeEventListener('mousemove', onMove)
    phase = 'idle'
  }

  function onDown(e){
    if(phase !== 'idle') return
    // Hanya aktif pada button di dalam menu-category-content
    const btn = e.target.closest('.menu-category-content > button')
    if(!btn || e.target.tagName==='INPUT' || e.target.tagName==='TEXTAREA') return

    const container = btn.closest('.menu-category-content')
    if(!container || getSiblings(container).length < 2) return  // tidak perlu drag kalau cuma 1 item

    const { x, y } = getXY(e)
    px = x; py = y; phase = 'pressing'

    timer = setTimeout(()=>{
      if(phase !== 'pressing') return
      startDrag(btn, container, py)
      document.addEventListener('touchend', onUp, { once:true })
      document.addEventListener('mouseup', onUp, { once:true })
    }, LONG_PRESS)
  }

  function onMove(e){
    const { x, y } = getXY(e)
    if(phase === 'pressing'){
      if(Math.abs(x-px)>MOVE_THRESH || Math.abs(y-py)>MOVE_THRESH){
        clearTimeout(timer); phase='idle'
      }
      return
    }
    if(phase !== 'dragging') return
    e.preventDefault()
    if(ghostEl) ghostEl.style.top = (y - ghostOffY) + 'px'
    const t = getDropTarget(dragContainer, y)
    showLine(dragContainer, t)
  }

  function onUp(e){
    clearTimeout(timer)
    if(phase === 'dragging') drop(getXY(e).y)
    else phase = 'idle'
  }

  document.addEventListener('DOMContentLoaded', ()=>{
    document.addEventListener('touchstart', onDown, { passive:true })
    document.addEventListener('mousedown', onDown)
    document.addEventListener('touchend', e=>{ clearTimeout(timer); if(phase==='pressing') phase='idle' })
    document.addEventListener('mouseup', e=>{ clearTimeout(timer); if(phase==='pressing') phase='idle' })
  })
})()
