// ============================================================
// ANTI-LAG SCROLL — pause animasi GPU-heavy saat scroll aktif
// Mencegah browser repaint card::after & tv-title tiap frame
// selama user scroll. Animasi resume otomatis 200ms setelah
// scroll berhenti (tidak terasa secara visual).
// Kompatibel dengan Android WebView (Sketchware Pro):
// mendengarkan 'scroll' di window + document sebagai fallback.
// ============================================================
;(function(){
  var _st;
  var _body = document.body;
  function _onScroll(){
    _body.classList.add('is-scrolling');
    clearTimeout(_st);
    _st = setTimeout(function(){ _body.classList.remove('is-scrolling'); }, 200);
  }
  // window scroll (desktop + modern WebView)
  window.addEventListener('scroll', _onScroll, { passive: true });
  // document scroll fallback (beberapa versi Android WebView lama)
  document.addEventListener('scroll', _onScroll, { passive: true });
})();
