// FITUR 2 — NOTIFIKASI SESI HAMPIR HABIS
// ============================================================

const _notifFiredSet = new Set()

function _cekNotifHampirHabis(){
  for(let i = 1; i <= units; i++){
    const s = state[i]
    if(!s || s.mode !== "countdown" || !s.start || s.expired) continue
    const sisa = s.duration - Math.floor((Date.now() - s.start) / 1000)
    if(sisa <= 0) continue

    // Trigger saat masuk zona ≤ 5 menit
    if(sisa <= 300){
      const key = `${i}_${s.start}_5min`
      if(!_notifFiredSet.has(key)){
        _notifFiredSet.add(key)
        _tampilkanNotifHampirHabis(i, sisa)
      }
    }
    // Trigger saat masuk zona ≤ 1 menit
    if(sisa <= 60){
      const key = `${i}_${s.start}_1min`
      if(!_notifFiredSet.has(key)){
        _notifFiredSet.add(key)
        _tampilkanNotifHampirHabis(i, sisa)
      }
    }
  }
}

function _tampilkanNotifHampirHabis(tvIndex, sisaDetik){
  const menit   = Math.ceil(sisaDetik / 60)
  const kritis  = sisaDetik <= 60
  const warna   = kritis ? "#ff1a50" : "#ffcc00"
  const warnaRGB= kritis ? "255,26,80" : "255,204,0"
  const icon    = kritis ? "🚨" : "⏳"
  const judul   = kritis ? "WAKTU HAMPIR HABIS!" : "SISA " + menit + " MENIT"
  const sub     = kritis
    ? `TV ${tvIndex} tinggal kurang dari 1 menit`
    : `TV ${tvIndex} — segera ingatkan pelanggan`

  // Hapus notif lama untuk TV yang sama jika ada
  const oldEl = document.getElementById("nhh_tv_" + tvIndex)
  if(oldEl) oldEl.remove()

  const el = document.createElement("div")
  el.id = "nhh_tv_" + tvIndex
  el.className = "nhh-premium" + (kritis ? " nhh-kritis" : "")
  el.style.setProperty("--nhh-color", warna)
  el.style.setProperty("--nhh-rgb", warnaRGB)

  el.innerHTML = `
    <div class="nhh-p-glow"></div>
    <div class="nhh-p-bar-wrap">
      <div class="nhh-p-bar" id="nhhBar_${tvIndex}"></div>
    </div>
    <div class="nhh-p-body">
      <div class="nhh-p-icon-wrap">
        <div class="nhh-p-icon">${icon}</div>
        <div class="nhh-p-tv-badge">TV ${tvIndex}</div>
      </div>
      <div class="nhh-p-content">
        <div class="nhh-p-title">${judul}</div>
        <div class="nhh-p-sub">${sub}</div>
      </div>
      <button class="nhh-p-close" onclick="document.getElementById('nhh_tv_${tvIndex}')?.remove()">✕</button>
    </div>
  `

  document.body.appendChild(el)
  setTimeout(() => el.classList.add("nhh-p-show"), 10)

  // Animasi progress bar
  const bar = document.getElementById("nhhBar_" + tvIndex)
  if(bar){
    bar.style.transition = "none"
    bar.style.width = "100%"
    setTimeout(() => {
      bar.style.transition = "width 7s linear"
      bar.style.width = "0%"
    }, 50)
  }

  // Auto dismiss setelah 7 detik
  const timer = setTimeout(() => {
    el.classList.remove("nhh-p-show")
    setTimeout(() => el.remove(), 500)
  }, 7000)
  el._dismissTimer = timer

  // Getar
  if(navigator.vibrate) navigator.vibrate(kritis ? [300,100,300,100,300] : [200,100,200])

  // Suara pengumuman TTS
  if(kritis){
    _speakAlarm('TV ' + tvIndex + ' tersisa 1 menit lagi')
  } else {
    _speakAlarm('TV ' + tvIndex + ' tersisa 5 menit lagi')
  }
}

// Cek setiap 15 detik
setInterval(_cekNotifHampirHabis, 15000)


