let _custDisplayInterval = null

function bukaCustomerDisplay(){
  if(document.getElementById("customerDisplayOverlay")){
    document.getElementById("customerDisplayOverlay").remove()
    return
  }

  const overlay = document.createElement("div")
  overlay.id = "customerDisplayOverlay"
  overlay.className = "cust-display-overlay"
  overlay.innerHTML = `
    <div class="cust-display-header">
      <div class="cust-header-left">
        <div class="cust-display-brand" id="custBrand">ASTROPHILE</div>
        <div class="cust-display-sub">PLAYSTATION BILLING</div>
      </div>
      <div class="cust-display-clock" id="custClock"></div>
      <button class="cust-display-close" onclick="tutupCustomerDisplay()">✕</button>
    </div>
    <div class="cust-display-body" id="custDisplayBody">
    </div>
    <div class="cust-display-footer">
      <div id="custFooterStatus">Menampilkan sesi aktif secara real-time</div>
    </div>
  `
  document.body.appendChild(overlay)
  setTimeout(() => overlay.classList.add("cust-display-visible"), 10)

  // Load judul rental
  const titleTop = localStorage.getItem("ps_title_top") || "ASTROPHILE"
  const brandEl = document.getElementById("custBrand")
  if(brandEl) brandEl.textContent = titleTop

  _updateCustomerDisplay()
  _custDisplayInterval = setInterval(_updateCustomerDisplay, 1000)
}

function tutupCustomerDisplay(){
  clearInterval(_custDisplayInterval)
  _custDisplayInterval = null
  const el = document.getElementById("customerDisplayOverlay")
  if(!el) return
  el.classList.remove("cust-display-visible")
  setTimeout(() => el.remove(), 350)
}

function _updateCustomerDisplay(){
  const body    = document.getElementById("custDisplayBody")
  const clockEl = document.getElementById("custClock")
  if(!body) return

  // Update jam
  const now  = new Date()
  const jamStr = now.getHours().toString().padStart(2,"0") + ":" +
                 now.getMinutes().toString().padStart(2,"0") + ":" +
                 now.getSeconds().toString().padStart(2,"0")
  if(clockEl) clockEl.textContent = jamStr

  // Kumpulkan semua TV aktif
  const aktifList = []
  for(let i = 1; i <= units; i++){
    const s = state[i]
    if(!s || !s.mode || !s.start) continue

    let sisaStr    = "–"
    let statusLabel = "BERMAIN"
    let urgent     = false
    let sisaDetik  = 0
    let timerColor = "normal" // normal | green | yellow | red

    if(s.mode === "countdown"){
      const sisa = s.duration - Math.floor((Date.now() - s.start) / 1000)
      if(s.expired || sisa <= 0){
        sisaStr     = "HABIS"
        statusLabel = "WAKTU HABIS"
        urgent      = true
        timerColor  = "red"
      } else {
        sisaDetik   = sisa
        sisaStr     = format(Math.max(0, sisa))
        urgent      = sisa <= 300
        statusLabel = urgent ? "HAMPIR HABIS" : "BERMAIN"
        timerColor  = sisa > 300 ? "green" : "yellow"
      }
    } else if(s.mode === "billing"){
      const diff  = Math.floor((Date.now() - s.start) / 1000)
      sisaStr     = format(diff)
      statusLabel = "BILLING"
      timerColor  = "billing"
    }

    const modeLabelText = s.mode === "billing" ? "⏱ BILLING" : "⏳ COUNTDOWN"
    const elapsedDetik  = s.mode === "billing" ? Math.floor((Date.now() - s.start) / 1000) : 0
    aktifList.push({ tv: i, type: s.type || "–", mode: s.mode, sisaStr, statusLabel, urgent, timerColor, modeLabelText, sisaDetik, elapsedDetik, startTs: s.start })
  }

  // ── SORT: countdown urgent → countdown normal → billing lama → billing baru ──
  aktifList.sort((a, b) => {
    // 1. Waktu habis paling atas
    const aHabis = a.statusLabel === "WAKTU HABIS" ? 0 : 1
    const bHabis = b.statusLabel === "WAKTU HABIS" ? 0 : 1
    if(aHabis !== bHabis) return aHabis - bHabis

    // 2. Countdown sebelum billing
    if(a.mode === "countdown" && b.mode !== "countdown") return -1
    if(a.mode !== "countdown" && b.mode === "countdown") return  1

    // 3. Sesama countdown → sisa paling sedikit dulu (paling urgent)
    if(a.mode === "countdown" && b.mode === "countdown")
      return a.sisaDetik - b.sisaDetik

    // 4. Sesama billing → yang sudah lama main dulu, baru mulai di bawah
    return b.elapsedDetik - a.elapsedDetik
  })

  // ── Grid: max 2 kolom di portrait agar tidak terpotong ──
  const cols = aktifList.length === 1 ? 1 : 2

  if(aktifList.length === 0){
    body.innerHTML = `
      <div class="cust-display-empty">
        <div style="font-size:72px;margin-bottom:16px;">🎮</div>
        <div style="font-family:'Orbitron',monospace;font-size:18px;letter-spacing:4px;color:rgba(0,245,255,0.40);">TIDAK ADA SESI AKTIF</div>
      </div>
    `
    return
  }

  body.innerHTML = `
    <div class="cust-display-grid cust-display-grid-${cols}">
      ${aktifList.map(item => `
        <div class="cust-display-card ${item.urgent ? 'cust-urgent' : ''} ${item.statusLabel === 'WAKTU HABIS' ? 'cust-expired' : ''} cust-card-clickable"
             onclick="navigasiKeTVCard(${item.tv})">
          <div class="cust-card-tap-hint">TAP</div>
          <div class="cust-card-header-row">
            <div class="cust-card-tv">TV ${item.tv}</div>
            <div class="cust-card-mode-badge cust-mode-${item.mode}">${item.modeLabelText}</div>
          </div>
          <div class="cust-card-type">${escapeHTML(item.type)}</div>
          <div class="cust-card-timer cust-timer-${item.timerColor}">${item.sisaStr}</div>
          <div class="cust-card-status">${item.statusLabel}</div>
        </div>
      `).join("")}
    </div>
  `
}

