let hutangList = JSON.parse(localStorage.getItem("ps_hutang")) || []

function saveHutang(){
  localStorage.setItem("ps_hutang", JSON.stringify(hutangList))
}

function generateHutangId(){
  return "HT" + Date.now().toString(36).toUpperCase()
}

function renderHutangPage(){
  closeSidebar()

  const totalAktif  = hutangList.filter(h => h.status !== "lunas").reduce((s,h) => s + (h.sisa||h.nominal||0), 0)
  const totalLunas  = hutangList.filter(h => h.status === "lunas").length
  const jumlahAktif = hutangList.filter(h => h.status !== "lunas").length

  // Sort: aktif dulu, lalu lunas
  const sorted = [...hutangList].sort((a,b) => {
    if(a.status === "lunas" && b.status !== "lunas") return 1
    if(a.status !== "lunas" && b.status === "lunas") return -1
    return new Date(b.createdAt) - new Date(a.createdAt)
  })

  function hutangCard(h){
    const aktif   = h.status !== "lunas"
    const sisa    = h.sisa !== undefined ? h.sisa : h.nominal
    const lunas   = h.status === "lunas"
    return `
    <div class="hutang-card ${lunas ? 'hutang-lunas' : ''}">
      <div class="hutang-card-header">
        <div class="hutang-card-nama">${escapeHTML(h.nama)}</div>
        <span class="hutang-status-badge ${lunas ? 'hstatus-lunas' : 'hstatus-hutang'}">
          ${lunas ? "✅ LUNAS" : "🔴 BELUM LUNAS"}
        </span>
      </div>
      <div class="hutang-card-meta">
        <span>💰 Nominal: <strong>Rp ${(h.nominal||0).toLocaleString("id-ID")}</strong></span>
        ${!lunas ? `<span>📉 Sisa: <strong style="color:#ff6688;">Rp ${(sisa||0).toLocaleString("id-ID")}</strong></span>` : ""}
        <span>📅 ${h.tanggal || "-"}</span>
      </div>
      ${h.catatan ? `<div class="hutang-card-catatan">📝 ${escapeHTML(h.catatan)}</div>` : ""}
      ${h.pembayaran && h.pembayaran.length ? `
        <div class="hutang-bayar-history">
          <div style="font-size:9px;font-family:'Orbitron',monospace;letter-spacing:1px;color:var(--text-muted);margin-bottom:5px;">RIWAYAT BAYAR</div>
          ${h.pembayaran.map(p => `
            <div class="hutang-bayar-row">
              <span>${p.tanggal}</span>
              <span style="color:#00ff88;">+ Rp ${(p.nominal||0).toLocaleString("id-ID")}</span>
            </div>
          `).join("")}
        </div>
      ` : ""}
      <div class="hutang-card-actions">
        ${aktif ? `<button class="hutang-btn-bayar" onclick="openCatatBayar('${h.id}')">💵 Catat Bayar</button>` : ""}
        <button class="hutang-btn-hapus" onclick="hapusHutang('${h.id}')">🗑 Hapus</button>
      </div>
    </div>`
  }

  const emptyHtml = hutangList.length === 0
    ? `<div class="booking-empty" style="padding:48px 16px;text-align:center;">
        <div style="font-size:48px;margin-bottom:12px;">💸</div>
        <div style="font-family:'Orbitron',monospace;font-size:12px;letter-spacing:2px;color:var(--text-muted);">BELUM ADA DATA HUTANG</div>
      </div>` : ""

  const html = `
  <div class="hutang-page">

    <!-- Stats -->
    <div class="hutang-stats-bar">
      <div class="hutang-stat-item">
        <div class="hutang-stat-num" style="color:#ff6688;">${jumlahAktif}</div>
        <div class="hutang-stat-lbl">Belum Lunas</div>
      </div>
      <div class="hutang-stat-item" style="grid-column:span 2;">
        <div class="hutang-stat-num" style="color:#ff6688;font-size:20px;">Rp ${totalAktif.toLocaleString("id-ID")}</div>
        <div class="hutang-stat-lbl">Total Piutang</div>
      </div>
      <div class="hutang-stat-item">
        <div class="hutang-stat-num" style="color:#00ff88;">${totalLunas}</div>
        <div class="hutang-stat-lbl">Sudah Lunas</div>
      </div>
    </div>

    ${emptyHtml}

    <!-- List -->
    <div class="booking-cards-grid">
      ${sorted.map(hutangCard).join("")}
    </div>

    <!-- FAB -->
    <button class="booking-fab" style="background:linear-gradient(135deg,#ff6688,#ff1a50);" onclick="openTambahHutang()">
      <span style="font-size:22px;line-height:1;">＋</span>
      <span style="font-family:'Orbitron',monospace;font-size:10px;letter-spacing:1.5px;">HUTANG</span>
    </button>
  </div>
  `
  showInternalPage("💰 HUTANG PELANGGAN", "Catat & kelola piutang pelanggan", html)
}

