function simpanHutang(){
  const nama    = (document.getElementById("ht_nama")?.value||"").trim()
  const nominal = parseInt((document.getElementById("ht_nominal")?.value||"0").replace(/\./g,""))
  const tanggal = document.getElementById("ht_tanggal")?.value||""
  const catatan = (document.getElementById("ht_catatan")?.value||"").trim()
  const errEl   = document.getElementById("ht_error")

  function showErr(msg){
    if(errEl){ errEl.textContent = "⚠️ " + msg; errEl.style.display = "block" }
  }
  if(!nama){ showErr("Nama pelanggan wajib diisi."); return }
  if(!nominal || nominal <= 0){ showErr("Nominal hutang harus lebih dari 0."); return }

  const newHutang = {
    id: generateHutangId(),
    nama, nominal, sisa: nominal,
    tanggal, catatan,
    status: "hutang",
    pembayaran: [],
    createdAt: new Date().toISOString()
  }
  hutangList.unshift(newHutang)
  saveHutang()
  addOperatorLog(_getCurrentRole(), "tambah_hutang", `${nama} · Rp ${nominal.toLocaleString("id-ID")}`)

  const el = document.getElementById("hutangModalOverlay")
  if(el) el.remove()
  renderHutangPage()
  _showBookingToast(`💰 Hutang "${nama}" Rp ${nominal.toLocaleString("id-ID")} dicatat.`)
}

// ── Modal Catat Bayar ─────────────────────────────────────────
function openCatatBayar(id){
  const h = hutangList.find(x => x.id === id)
  if(!h) return
  const sisa = h.sisa !== undefined ? h.sisa : h.nominal

  const modalHtml = `
  <div id="bayarModalOverlay" style="
    position:fixed;inset:0;z-index:9100;
    display:flex;align-items:center;justify-content:center;
    background:rgba(3,5,12,0.88);
    backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
    padding:16px;" onclick="if(event.target.id==='bayarModalOverlay'){this.remove()}">

    <div class="booking-modal-box" onclick="event.stopPropagation()">
      <div class="booking-modal-header">
        <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:700;letter-spacing:1.5px;color:#00ff88;">
          💵 CATAT PEMBAYARAN
        </div>
        <button onclick="document.getElementById('bayarModalOverlay').remove()" style="background:none;border:none;color:var(--text-muted);font-size:20px;padding:0;width:30px;height:30px;display:flex;align-items:center;justify-content:center;cursor:pointer;">✕</button>
      </div>
      <div class="booking-modal-body">
        <div style="background:rgba(255,26,80,0.06);border:1px solid rgba(255,26,80,0.15);border-radius:var(--radius-sm);padding:12px;margin-bottom:16px;">
          <div style="font-size:11px;color:var(--text-muted);">Hutang atas nama</div>
          <div style="font-size:15px;font-weight:700;color:var(--text-primary);">${escapeHTML(h.nama)}</div>
          <div style="font-size:12px;color:#ff6688;margin-top:4px;">Sisa hutang: <strong>Rp ${sisa.toLocaleString("id-ID")}</strong></div>
        </div>

        <label class="booking-form-label">💵 JUMLAH DIBAYAR (Rp)</label>
        <input id="bayar_nominal" type="text" inputmode="numeric" placeholder="Rp Nominal pembayaran..." oninput="formatRupiahInput(this)" inputmode="numeric" style="margin-bottom:14px;" max="${sisa}">

        <div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap;">
          <button onclick="String(document.getElementById('bayar_nominal').value||'').replace(/\./g,'')='${Math.round(sisa/2)}'" style="flex:1;padding:8px;font-size:11px;background:rgba(0,245,255,0.06);border-color:rgba(0,245,255,0.20);color:var(--primary);">½ Bayar</button>
          <button onclick="String(document.getElementById('bayar_nominal').value||'').replace(/\./g,'')='${sisa}'" style="flex:1;padding:8px;font-size:11px;background:rgba(0,255,136,0.08);border-color:rgba(0,255,136,0.25);color:#00ff88;">LUNAS</button>
        </div>

        <div id="bayar_error" style="display:none;color:var(--red-danger);font-size:11px;text-align:center;margin-bottom:10px;padding:8px;background:rgba(255,26,80,0.08);border-radius:var(--radius-sm);"></div>

        <button onclick="simpanPembayaran('${id}')" style="width:100%;background:linear-gradient(135deg,rgba(0,255,136,0.14),rgba(0,200,100,0.08));border-color:rgba(0,255,136,0.30);color:#00ff88;font-family:'Orbitron',monospace;font-size:11px;letter-spacing:2px;font-weight:700;padding:14px;">
          ✅ SIMPAN PEMBAYARAN
        </button>
      </div>
    </div>
  </div>`
  document.body.insertAdjacentHTML("beforeend", modalHtml)
  setTimeout(() => { const el=document.getElementById("bayar_nominal"); if(el) el.focus() }, 100)
}

function simpanPembayaran(id){
  const h = hutangList.find(x => x.id === id)
  if(!h) return
  const nominal = parseInt((document.getElementById("bayar_nominal")?.value||"0").replace(/\./g,""))
  const errEl   = document.getElementById("bayar_error")
  const sisa    = h.sisa !== undefined ? h.sisa : h.nominal

  if(!nominal || nominal <= 0){
    if(errEl){ errEl.textContent = "⚠️ Nominal bayar harus lebih dari 0"; errEl.style.display = "block" }
    return
  }
  if(nominal > sisa){
    if(errEl){ errEl.textContent = "⚠️ Jumlah bayar melebihi sisa hutang (Rp " + sisa.toLocaleString("id-ID") + ")"; errEl.style.display = "block" }
    return
  }

  const tgl = new Date().toLocaleDateString("id-ID")
  h.pembayaran = h.pembayaran || []
  h.pembayaran.push({ tanggal: tgl, nominal })
  h.sisa = sisa - nominal
  if(h.sisa <= 0){ h.sisa = 0; h.status = "lunas" }

  saveHutang()
  addOperatorLog(_getCurrentRole(), "bayar_hutang", `${h.nama} · bayar Rp ${nominal.toLocaleString("id-ID")} · sisa Rp ${h.sisa.toLocaleString("id-ID")}`)

  const el = document.getElementById("bayarModalOverlay")
  if(el) el.remove()
  renderHutangPage()
  _showBookingToast(h.status === "lunas"
    ? `✅ Hutang "${h.nama}" LUNAS! 🎉`
    : `💵 Pembayaran Rp ${nominal.toLocaleString("id-ID")} dari "${h.nama}" dicatat.`
  )
}

function hapusHutang(id){
  const h = hutangList.find(x => x.id === id)
  if(!h) return
  if(!confirm(`Hapus data hutang atas nama "${h.nama}"?`)) return
  hutangList = hutangList.filter(x => x.id !== id)
  saveHutang()
  renderHutangPage()
  _showBookingToast("🗑️ Data hutang dihapus.")
}

