function _updateHutangBadge(){
  const badge = document.getElementById("hutangBadgeSidebar")
  if(!badge) return
  const count = hutangList.filter(h => h.status !== "lunas").length
  if(count > 0){ badge.textContent = count; badge.style.display = "inline-flex" }
  else badge.style.display = "none"
}

