// ============================================================
// BUG FIX — Lock/unlock semua startBtn saat popup transaksi
// Mencegah operator klik Start TV lain saat transaksi pending
// ============================================================
function _lockAllStartBtns(lock){
  for(let j = 1; j <= units; j++){
    const startBtn = document.getElementById("startBtn" + j)
    if(!startBtn) continue
    if(lock){
      // Redup semua TV yang sedang idle (tidak aktif)
      if(!state[j] || !state[j].start){
        startBtn.disabled = true
        startBtn.classList.add("start-btn-locked")
      }
    } else {
      // Pulihkan: aktifkan kembali yang idle, biarkan yang aktif tetap disabled
      const s = state[j]
      const idle = !s || !s.start
      startBtn.disabled = !idle
      startBtn.classList.remove("start-btn-locked")
    }
  }
}
