// Navigasi dari Layar Pelanggan → card TV di dashboard
// ============================================================
function navigasiKeTVCard(tvNum){
  tutupCustomerDisplay()

  // Pastikan tampilan kembali ke dashboard
  showDashboardView()

  // Beri sedikit waktu overlay hilang, lalu highlight + scroll ke card
  setTimeout(function(){
    // Reset search agar semua card tampil
    const searchInput = document.getElementById("dashTVSearch")
    if(searchInput){
      searchInput.value = ""
      dashSearchTV("")
    }

    // Pindah ke page yang berisi TV ini (jika ada pagination)
    const targetPage = Math.ceil(tvNum / TV_PER_PAGE)
    if(tvCurrentPage !== targetPage){
      tvCurrentPage = targetPage
      createUI()
    }

    // Scroll ke card & beri efek highlight
    setTimeout(function(){
      const card = document.getElementById("card" + tvNum)
      if(!card) return
      card.scrollIntoView({ behavior: "smooth", block: "center" })

      // Flash highlight
      card.classList.add("cust-nav-highlight")
      setTimeout(() => card.classList.remove("cust-nav-highlight"), 1800)
    }, 120)
  }, 380)
}
