// ============================================================
// FONNTE — AUTO WA NOTIFICATION (KIRIM WA OTOMATIS)
// ============================================================
function _getFonnteToken(){ return localStorage.getItem("integrasi_fonnte_token") || "" }

async function _kirimWAFonnte(noWA, pesan){
  let nomor = noWA.toString().replace(/[^0-9]/g,"")
  if(nomor.startsWith("0")) nomor = "62" + nomor.slice(1)
  if(!nomor.startsWith("62")) nomor = "62" + nomor
  try {
    const res = await fetch("https://api.fonnte.com/send", {
      method: "POST",
      headers: { "Authorization": _getFonnteToken(), "Content-Type": "application/json" },
      body: JSON.stringify({ target: nomor, message: pesan, countryCode: "62" })
    })
    const data = await res.json()
    return data.status === true || data.status === "true"
  } catch(e) {
    console.warn("Fonnte error:", e)
    return false
  }
}

async function _kirimWA(noWA, pesan){
  if(!noWA) return
  if(!_getFonnteToken()){
    // Tidak ada token — fallback manual
    window.location.href = "https://wa.me/" + noWA + "?text=" + encodeURIComponent(pesan)
    return
  }
  const berhasil = await _kirimWAFonnte(noWA, pesan)
  if(!berhasil){
    window.location.href = "https://wa.me/" + noWA + "?text=" + encodeURIComponent(pesan)
  }
}
