// PINDAH TV — Pindahkan semua data sesi dari TV asal ke TV tujuan
// ============================================================
function showPindahTVPopup(fromTV){
  const s = state[fromTV]
  // Hanya bisa pindah jika TV sedang aktif (billing/countdown)
  const isAktif = s && s.start && (s.mode === "billing" || s.mode === "countdown") && !s.expired
  if(!isAktif){
    showPopup({ typeNotif:"warning", message:"⚠️ TV "+fromTV+" tidak sedang aktif.\nHanya bisa pindah saat sesi sedang berjalan." })
    return
  }

  document.getElementById('pindahTVPopup')?.remove()
  const el = document.createElement('div')
  el.id = 'pindahTVPopup'
  el.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(2,5,16,0.90);backdrop-filter:blur(10px);padding:20px;'

  // Buat daftar TV tujuan yang TERSEDIA (tidak aktif, tidak locked)
  const available = []
  for(let tv = 1; tv <= units; tv++){
    if(tv === fromTV) continue
    if(lockedTVs.includes(tv)) continue
    const st = state[tv]
    const stAktif = st && st.start && (st.mode === "billing" || st.mode === "countdown") && !st.expired
    if(stAktif) continue  // sedang aktif
    available.push(tv)
  }

  const modeLabel = s.mode === 'countdown' ? '⏳ Countdown' : '⏱ Billing'
  const namaP     = s.namaPelanggan || _loadNamaPelanggan(fromTV) || '-'
  const nowMs     = Date.now()
  const elapsed   = s.start ? Math.floor((nowMs - s.start) / 1000) : 0
  const elapsedStr = Math.floor(elapsed/3600).toString().padStart(2,'0') + ':' +
                     Math.floor((elapsed%3600)/60).toString().padStart(2,'0') + ':' +
                     (elapsed%60).toString().padStart(2,'0')

  el.innerHTML = `
    <div style="background:linear-gradient(145deg,#070f1c,#0d1a2e);
      border:1px solid rgba(0,245,255,0.22);border-radius:20px;
      padding:24px;width:100%;max-width:400px;
      box-shadow:0 20px 60px rgba(0,0,0,0.70);">

      <!-- Header -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">
        <div>
          <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:700;
            color:#00f5ff;letter-spacing:2px;margin-bottom:3px;">⇄ PINDAH TV</div>
          <div style="font-size:11px;color:rgba(168,200,240,0.45);">Pindahkan sesi aktif ke unit lain</div>
        </div>
        <button onclick="document.getElementById('pindahTVPopup').remove()"
          style="width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.05);
          border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.55);font-size:16px;
          display:flex;align-items:center;justify-content:center;">✕</button>
      </div>

      <!-- Info TV Asal -->
      <div style="background:rgba(0,245,255,0.05);border:1px solid rgba(0,245,255,0.16);
        border-radius:14px;padding:14px;margin-bottom:16px;">
        <div style="font-family:'Orbitron',monospace;font-size:8px;letter-spacing:2px;
          color:rgba(0,245,255,0.50);margin-bottom:10px;">📺 TV ASAL</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
          <div>
            <div style="font-size:10px;color:rgba(168,200,240,0.40);margin-bottom:2px;">Unit</div>
            <div style="font-family:'Orbitron',monospace;font-size:16px;font-weight:900;color:#00f5ff;">TV ${fromTV}</div>
          </div>
          <div>
            <div style="font-size:10px;color:rgba(168,200,240,0.40);margin-bottom:2px;">Mode</div>
            <div style="font-size:13px;font-weight:700;color:#e8f4ff;">${modeLabel}</div>
          </div>
          <div>
            <div style="font-size:10px;color:rgba(168,200,240,0.40);margin-bottom:2px;">Pelanggan</div>
            <div style="font-size:13px;font-weight:700;color:#e8f4ff;">${namaP}</div>
          </div>
          <div>
            <div style="font-size:10px;color:rgba(168,200,240,0.40);margin-bottom:2px;">Durasi Berjalan</div>
            <div style="font-family:'Orbitron',monospace;font-size:13px;font-weight:700;color:#ffcc00;">${elapsedStr}</div>
          </div>
        </div>
        ${s.items && s.items.length ? `
        <div style="margin-top:10px;padding-top:10px;border-top:1px solid rgba(0,245,255,0.10);
          font-size:11px;color:rgba(168,200,240,0.50);">
          🛒 ${s.items.length} pesanan tambahan ikut dipindah
        </div>` : ''}
      </div>

      <!-- Pilih TV tujuan -->
      <div style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;margin-bottom:10px;">PINDAH KE UNIT</div>

      ${available.length === 0 ? `
        <div style="text-align:center;padding:20px;color:rgba(255,100,100,0.60);font-size:13px;">
          ⚠️ Tidak ada unit yang tersedia.<br>
          <span style="font-size:11px;color:rgba(168,200,240,0.35);">Semua TV sedang aktif atau terkunci.</span>
        </div>` :
        `<div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px;">
          ${available.map(tv => `
            <button onclick="_eksekusiPindahTV(${fromTV},${tv})"
              style="padding:12px 18px;border-radius:14px;cursor:pointer;
              background:rgba(0,245,255,0.08);border:1px solid rgba(0,245,255,0.25);
              font-family:'Orbitron',monospace;font-size:13px;font-weight:700;color:#00f5ff;
              transition:all .2s;min-width:70px;"
              onmousedown="this.style.transform='scale(0.92)'"
              onmouseup="this.style.transform='scale(1)'"
              ontouchstart="this.style.transform='scale(0.92)'"
              ontouchend="this.style.transform='scale(1)'">
              TV ${tv}
            </button>`).join('')}
        </div>

        <div style="font-size:11px;color:rgba(168,200,240,0.35);text-align:center;">
          Semua data (timer, pesanan, nama pelanggan) akan dipindah.<br>
          TV asal akan direset ke <strong style="color:rgba(0,255,136,0.60);">TERSEDIA</strong>.
        </div>`
      }
    </div>
  `

  document.body.appendChild(el)
  el.onclick = e => { if(e.target === el) el.remove() }
}

function _eksekusiPindahTV(fromTV, toTV){
  document.getElementById('pindahTVPopup')?.remove()

  const src = state[fromTV]
  const srcAktif = src && src.start && (src.mode === "billing" || src.mode === "countdown") && !src.expired
  if(!srcAktif){
    showPopup({ typeNotif:"warning", message:"⚠️ TV asal sudah tidak aktif." }); return
  }

  const dst = state[toTV]
  const dstAktif = dst && dst.start && (dst.mode === "billing" || dst.mode === "countdown") && !dst.expired
  if(dstAktif){
    showPopup({ typeNotif:"warning", message:"⚠️ TV "+toTV+" sedang dipakai." }); return
  }

  // ── Ambil semua data dari TV asal ──
  const dataPindah = {
    active:      src.active,
    mode:        src.mode,
    start:       src.start,
    duration:    src.duration,
    expired:     src.expired,
    type:        src.type,
    price:       src.price,
    items:       Array.isArray(src.items) ? [...src.items] : [],
    namaPelanggan: src.namaPelanggan || _loadNamaPelanggan(fromTV) || "",
    _bonusDetik: src._bonusDetik || 0
  }

  // ── Reset TV asal ──
  const oldType = src.type
  state[fromTV] = {
    mode: null, start: null, type: oldType,
  }
  _clearNamaPelanggan(fromTV)

  // ── Terapkan ke TV tujuan ──
  state[toTV] = { ...dataPindah }

  // Simpan nama pelanggan ke TV tujuan
  if(dataPindah.namaPelanggan){
    _simpanNamaPelanggan(toTV, dataPindah.namaPelanggan)
  }

  // ── Sync Firebase — ATOMIC: satu write agar listener tidak terima data setengah jadi ──
  if(_fbDb && _fbOnline){
    _fbDb.ref("settings/activeSessions").update({
      // Reset TV asal
      [fromTV]: {
        active: false, mode: null, start: null, duration: 0, type: oldType
      },
      // Set TV tujuan — termasuk _bonusDetik agar bonus tidak hilang
      [toTV]: {
        active:       true,
        mode:         dataPindah.mode,
        start:        dataPindah.start,
        duration:     dataPindah.duration,
        expired:      dataPindah.expired,
        type:         dataPindah.type,
        price:        dataPindah.price || 0,
        _bonusDetik:  dataPindah._bonusDetik || 0,
        namaPelanggan: dataPindah.namaPelanggan
      }
    })
  }

  // ── Update konsol yang sudah ada di DOM ──
  const typeLbl = document.getElementById("typeLabel" + toTV)
  if(typeLbl) typeLbl.textContent = dataPindah.type

  const namaEl = document.getElementById("namaPelanggan" + toTV)
  if(namaEl) namaEl.value = dataPindah.namaPelanggan

  const namaElFrom = document.getElementById("namaPelanggan" + fromTV)
  if(namaElFrom) namaElFrom.value = ""

  // ── Log ──
  addOperatorLog(_getCurrentRole(), 'pindah_tv',
    "TV " + fromTV + " → TV " + toTV +
    (dataPindah.namaPelanggan ? " · " + dataPindah.namaPelanggan : "") +
    " · " + (dataPindah.mode === 'countdown' ? 'Countdown' : 'Billing')
  )

  // ── Reset penuh TV asal di state & DOM cache ──
  _billingState[fromTV] = false
  const domFrom = _tvDom[fromTV]
  if(domFrom){
    if(domFrom.card){
      domFrom.card.classList.remove("billing-active-card","countdown-active-card","tv-locked")
    }
    if(domFrom.status){
      domFrom.status.textContent = "TERSEDIA"
      domFrom.status.style.color = "#00ff88"
    }
    if(domFrom.timer){
      domFrom.timer.textContent = "00:00:00"
      domFrom.timer.className   = "timer timer-idle"
      domFrom.timer.removeAttribute("data-mode")
      domFrom.timer.removeAttribute("data-start")
      domFrom.timer.removeAttribute("data-duration")
    }
    if(domFrom.stopBtn) domFrom.stopBtn.disabled = true
    const startFrom = document.getElementById("startBtn" + fromTV)
    if(startFrom) startFrom.disabled = false
    // Sembunyikan countdown extras
    const cdExtra = document.getElementById("countdownExtraWrap" + fromTV)
    if(cdExtra) cdExtra.style.display = "none"
    const cdInput = document.getElementById("countdownInputWrap" + fromTV)
    if(cdInput) cdInput.style.display = "none"
    // Reset mode label
    const modeLabel = document.getElementById("modeLabel" + fromTV)
    if(modeLabel) modeLabel.textContent = "⏱ Mode Billing"
    const modeHidden = document.getElementById("modeSelect" + fromTV)
    if(modeHidden) modeHidden.value = "billing"
    // Reset pesanan summary
    const pesSum = document.getElementById("pesananSummary" + fromTV)
    if(pesSum) pesSum.textContent = "Total Tambahan: Rp 0"
    // Kosongkan item list UI
    const itemList = document.getElementById("itemList" + fromTV)
    if(itemList) itemList.innerHTML = "<div style='color:rgba(168,200,240,0.35);font-size:12px;'>Belum ada pesanan</div>"
    // Reset nama pelanggan input
    const namaElFrom = document.getElementById("namaPelanggan" + fromTV)
    if(namaElFrom) namaElFrom.value = ""
  }
  // Kosongkan items di state fromTV
  state[fromTV].items = []

  // ── Rebuild createUI untuk refresh tampilan bersih kedua card ──
  createUI()

  // ── Isi ulang field TV tujuan setelah createUI ──
  setTimeout(() => {
    const namaElTo = document.getElementById("namaPelanggan" + toTV)
    if(namaElTo) namaElTo.value = dataPindah.namaPelanggan || ""

    const typeLblTo = document.getElementById("typeLabel" + toTV)
    if(typeLblTo) typeLblTo.textContent = dataPindah.type || ""

    // Update pesanan summary TV tujuan
    const items = dataPindah.items || []
    const totalTambahan = items.reduce((s,x) => s + (Number(x.harga)||0), 0)
    const pesSumTo = document.getElementById("pesananSummary" + toTV)
    if(pesSumTo) pesSumTo.textContent = "Total Tambahan: " + formatRupiah(totalTambahan)

    // Render item list TV tujuan
    const itemListTo = document.getElementById("itemList" + toTV)
    if(itemListTo && items.length){
      itemListTo.innerHTML = items.map(x =>
        '<div style="display:flex;justify-content:space-between;font-size:12px;padding:4px 0;border-bottom:1px solid rgba(255,255,255,0.05);"><span>' + (x.nama||'-') + '</span><span>' + formatRupiah(x.harga||0) + '</span></div>'
      ).join("")
    }
  }, 300)

  showPopup({
    typeNotif: "success",
    message: "✅ Sesi berhasil dipindah!\n" +
      "TV " + fromTV + " → TV " + toTV +
      (dataPindah.namaPelanggan ? "\nPelanggan: " + dataPindah.namaPelanggan : "") +
      "\nTimer & pesanan tetap berjalan."
  })
}
