function _simpanNamaPelanggan(tvNum, nama){
  if(!state[tvNum]) state[tvNum] = {}
  state[tvNum].namaPelanggan = nama.trim()
  const key = "ps_nama_pelanggan_tv" + tvNum
  if(nama.trim()) localStorage.setItem(key, nama.trim())
  else localStorage.removeItem(key)
  try{ localStorage.setItem("ps_state", JSON.stringify(state)) }catch(e){}
}

function _loadNamaPelanggan(tvNum){
  // Prioritas: Firebase (di state), fallback localStorage
  const key = "ps_nama_pelanggan_tv" + tvNum
  return (state[tvNum]?.namaPelanggan) || localStorage.getItem(key) || ''
}

// Bersihkan nama pelanggan saat TV stop
function _clearNamaPelanggan(tvNum){
  if(state[tvNum]) state[tvNum].namaPelanggan = ''
  localStorage.removeItem("ps_nama_pelanggan_tv" + tvNum)
  if(_fbDb && _fbOnline) _fbDb.ref("activeSessions/tv" + tvNum + "/namaPelanggan").remove()
  const el = document.getElementById('namaPelanggan' + tvNum)
  if(el) el.value = ''
}

function _updateBookingIndicators(){
  const now   = Date.now()
  const today = new Date().toISOString().split('T')[0]

  for(let i = 1; i <= units; i++){
    const statusEl = document.getElementById('status' + i)
    if(!statusEl) continue

    // Skip jika TV sedang aktif billing/countdown
    const s = state[i]
    if(s && s.mode && s.start && !s.expired) continue
    if(lockedTVs.includes(i)) continue

    // Cari booking upcoming untuk TV ini hari ini (HANYA upcoming yg sudah disetujui, bukan pending)
    const bk = bookings.find(b =>
      b.tv === i &&
      b.tanggal === today &&
      b.status === 'upcoming'
    )

    if(!bk){
      // Tidak ada booking — pastikan status TERSEDIA
      if(statusEl.innerText.includes('BOOKING') || statusEl.innerText.includes('MENUNGGU')){
        statusEl.innerText = 'TERSEDIA'
        statusEl.style.color = '#00ff88'
      }
      continue
    }

    const jamTiba  = _parseJamMulai(bk)
    if(!jamTiba) continue
    const graceEnd = new Date(jamTiba.getTime() + 600000)
    const jamStr   = _jamMulaiStr(bk)

    if(now < jamTiba.getTime()){
      // Belum waktunya — tampilkan jam booking
      statusEl.innerHTML = `📅 BOOKING ${jamStr}`
      statusEl.style.color = '#ffcc00'
    } else if(now < graceEnd.getTime()){
      // Sudah waktunya, dalam grace period
      const sisaDetik = Math.ceil((graceEnd.getTime() - now) / 1000)
      const mm = Math.floor(sisaDetik / 60).toString().padStart(2,'0')
      const ss = (sisaDetik % 60).toString().padStart(2,'0')
      statusEl.innerHTML = `⏳ MENUNGGU ${mm}:${ss}`
      statusEl.style.color = '#ff9a3c'
    } else {
      // Grace habis — sudah dibatal oleh timer
      statusEl.innerText = 'TERSEDIA'
      statusEl.style.color = '#00ff88'
    }
  }
}

function _checkUpcomingBookings(){
  if(!_fbDb) return
  const now   = Date.now()
  const today = new Date().toISOString().split('T')[0]
  let changed = false

  bookings.forEach(b => {
    if(b.status !== 'upcoming' && b.status !== 'pending') return
    if(b.tanggal !== today) return

    const jamTiba  = _parseJamMulai(b)
    if(!jamTiba) return
    const graceEnd = new Date(jamTiba.getTime() + 600000) // +10 menit

    // Lewat 10 menit grace → otomatis batal
    if(now > graceEnd.getTime()){
      b.status = 'batal'
      saveBookings()
      _fbSetBooking(b)
      changed = true
      showPopup({ typeNotif:'warning',
        message:`⏰ Booking otomatis dibatalkan\n\nTV ${b.tv} — ${b.nama}\nPelanggan tidak datang dalam 10 menit.` })
    }
    // Jam tiba tapi belum grace habis → tampilkan notif jika belum pernah
    else if(now >= jamTiba.getTime()){
      const notifKey = '_notif_' + b.id
      if(!sessionStorage.getItem(notifKey)){
        sessionStorage.setItem(notifKey, '1')
        showPopup({ typeNotif:'info',
          message:`🔔 Waktu booking tiba!\n\nTV ${b.tv} — ${b.nama}\nJam: ${b.jamMulai?.includes('T') ? b.jamMulai.split('T')[1].slice(0,5) : b.jamMulai}\n\nPelanggan seharusnya sudah datang.\nKlik "Pelanggan Datang" di reservasi.` })
      }
    }
  })

  if(changed) createUI()
}

function _bersihkanBookingSelesai(){
  if(!_fbDb) return
  const today = new Date().toISOString().split("T")[0]
  let changed = false

  bookings.forEach(b => {
    if(b.status === "batal" || b.status === "selesai" || b.status === "menunggu") return
    if(b.tanggal !== today) return

    const tvState = state[b.tv]
    const tvAktif = tvState && tvState.mode && tvState.start && !tvState.expired

    // Jika TV tidak aktif tapi booking masih "aktif"/"upcoming" → update ke selesai
    if(!tvAktif && (b.status === "aktif" || b.status === "upcoming")){
      // Hanya selesaikan jika jam datang + durasi sudah lewat
      const jamDatang  = _parseJamMulai(b)
      const graceEnd   = new Date(jamDatang.getTime() + 600000) // +10 menit
      if(Date.now() > graceEnd.getTime()){
        b.status = "selesai"
        saveBookings()
        _fbSetBooking(b)
        changed = true
      }
    }
  })

  if(changed) console.log("Booking lama dibersihkan dari Firebase")
}
