// ============================================================
// RESTORE BUTTON STATES SETELAH APP DIBUKA ULANG
// Pastikan Start/Stop button sesuai state aktual dari localStorage
// ============================================================
function _restoreButtonStates(){
  for(let i = 1; i <= units; i++){
    const s = state[i]
    const startBtn = document.getElementById("startBtn" + i)
    const stopBtn  = document.getElementById("stopBtn"  + i)
    const inputEl  = document.getElementById("input"    + i)

    if(!startBtn || !stopBtn) continue

    const isActive = s && s.mode && s.start

    if(isActive){
      // Sesi aktif — disable Start, enable Stop
      startBtn.disabled = true
      stopBtn.disabled  = false
      if(inputEl) inputEl.disabled = true
      setDropDisabled("modeWrap" + i, true)
      setDropDisabled("typeWrap" + i, true)
    } else {
      // Idle — enable Start, disable Stop
      startBtn.disabled = false
      stopBtn.disabled  = true
    }
  }
}
