// ============================================================
// BOOKING ONLINE — ON/OFF TOGGLE
// ============================================================
function _getBookingStatus(){
  return localStorage.getItem("booking_online_status") !== "off"  // default ON
}

function _setBookingStatus(onOff){
  localStorage.setItem("booking_online_status", onOff ? "on" : "off")
  // Sync ke Firebase
  if(_fbDb) _fbDb.ref("settings/bookingOnline").set(onOff ? "on" : "off")
  _updateBookingToggleUI()
}

function _updateBookingToggleUI(){
  const isOn = _getBookingStatus()

  // Sidebar toggle label
  const toggleEl = document.getElementById("bookingOnlineToggle")
  const toggleLabel = document.getElementById("bookingOnlineLabel")
  if(toggleEl) toggleEl.checked = isOn
  if(toggleLabel){
    toggleLabel.textContent = isOn ? "BOOKING ONLINE: ON" : "BOOKING ONLINE: OFF"
    toggleLabel.style.color = isOn ? "#00ff88" : "#ff1a50"
  }

  // Settings page button (renderPengaturanBookingPage)
  const btnLabel = document.getElementById("bkOnlineBtnLabel")
  if(btnLabel){
    btnLabel.textContent = isOn ? "🟢 ON — Klik untuk OFF" : "🔴 OFF — Klik untuk ON"
  }

  // Settings page status badge jika ada
  const statusBadge = document.getElementById("bkOnlineStatusBadge")
  if(statusBadge){
    statusBadge.textContent = isOn ? "🟢 AKTIF" : "🔴 TUTUP"
    statusBadge.style.color = isOn ? "#00ff88" : "#ff1a50"
  }
}

function toggleBookingOnline(){
  const isOn = _getBookingStatus()
  const newState = !isOn
  _showConfirm(
    newState
      ? "Aktifkan halaman booking online?\nPelanggan bisa kembali membuat booking."
      : "Tutup halaman booking online?\nPelanggan tidak bisa membuat booking baru.",
    () => {
      _setBookingStatus(newState)
      showPopup({
        typeNotif: newState ? "success" : "warning",
        message: newState
          ? "✅ Booking online AKTIF!\nHalaman pelanggan sudah bisa diakses."
          : "🔴 Booking online DITUTUP.\nHalaman pelanggan tidak bisa booking."
      })
    }
  )
}
