function renderQrisPage(){
  closeSidebar()
  const savedUrl = localStorage.getItem('qris_image_url') || ''
  const hasImg   = savedUrl.length > 10

  const previewHtml = hasImg
    ? `<img src="${savedUrl}" style="width:200px;height:200px;border-radius:14px;border:2px solid rgba(255,107,0,0.40);object-fit:contain;background:#fff;">`
    : `<div style="width:200px;height:200px;margin:0 auto;border-radius:14px;border:2px dashed rgba(255,107,0,0.28);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;"><div style="font-size:44px;opacity:0.35;">\u{1F4F7}</div><div style="font-size:11px;color:rgba(255,107,0,0.45);">Belum ada foto QRIS</div></div>`

  const hapusBtn = hasImg
    ? `<button onclick="_hapusQRIS()" style="width:100%;padding:11px;border-radius:12px;background:rgba(255,26,80,0.08);border:1px solid rgba(255,26,80,0.20);color:rgba(255,100,120,0.70);font-family:'Orbitron',monospace;font-size:9px;font-weight:700;letter-spacing:1.5px;cursor:pointer;">\u{1F5D1}\uFE0F HAPUS FOTO QRIS</button>`
    : ''

  const html = `
  <div style="padding:20px 16px 40px;max-width:600px;margin:0 auto;">
    <div style="background:rgba(0,0,0,0.30);border:1px solid rgba(255,107,0,0.18);border-radius:18px;padding:24px;margin-bottom:18px;text-align:center;">
      <div style="font-size:9px;letter-spacing:2.5px;color:rgba(255,107,0,0.50);font-family:'Orbitron',monospace;margin-bottom:16px;">\u25FC PREVIEW QRIS</div>
      <div id="qrisPreviewWrap" style="display:flex;justify-content:center;margin-bottom:16px;">${previewHtml}</div>
      <button onclick="_piliGambarQRIS()" style="width:100%;padding:14px;border-radius:14px;background:linear-gradient(135deg,rgba(255,107,0,0.18),rgba(255,60,0,0.10));border:1px solid rgba(255,107,0,0.38);color:#ff8c00;font-family:'Orbitron',monospace;font-size:11px;font-weight:700;letter-spacing:2px;cursor:pointer;margin-bottom:${hasImg?'10px':'0'};">\u{1F4F7} PILIH FOTO DARI GALERI</button>
      ${hapusBtn}
    </div>
    <div style="background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.10);border-radius:14px;padding:14px 16px;">
      <div style="font-size:11px;color:rgba(168,200,240,0.55);line-height:1.8;">
        \u{1F4CC} Foto QRIS disimpan di HP, tidak dikirim ke internet.<br>
        \u{1F4CC} Saat operator pilih QRIS di transaksi, foto ini muncul untuk di-scan pelanggan.
      </div>
    </div>
  </div>`

  showInternalPage("\u25FC PENGATURAN QRIS", "Foto QRIS untuk pembayaran pelanggan", html)
}

function _piliGambarQRIS(){
  if(window.Android && typeof window.Android.pickImage === "function"){
    window.Android.pickImage("qris")
  } else {
    showPopup({ typeNotif:"warning", message:"\u26A0\uFE0F Fitur ini hanya tersedia di aplikasi Android." })
  }
}

function _hapusQRIS(){
  _showConfirm("Hapus foto QRIS?", () => {
    localStorage.removeItem("qris_image_url")
    // Update preview langsung tanpa re-render halaman
    const wrap = document.getElementById("qrisPreviewWrap")
    if(wrap){
      wrap.innerHTML = `<div style="width:200px;height:200px;margin:0 auto;border-radius:14px;border:2px dashed rgba(255,107,0,0.28);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;"><div style="font-size:44px;opacity:0.35;">&#128247;</div><div style="font-size:11px;color:rgba(255,107,0,0.45);">Belum ada foto QRIS</div></div>`
    }
    // Sembunyikan tombol hapus
    const hapusBtn = document.querySelector('[onclick="_hapusQRIS()"]')
    if(hapusBtn) hapusBtn.style.display = "none"
    showPopup({ typeNotif:"success", message:"Foto QRIS dihapus." })
  })
}
