function _getOperatorWA(){
  return localStorage.getItem("booking_site_wa") || ""
}

function _simpanBookingTitle(){
  const nama     = document.getElementById("inp_site_nama")?.value.trim()     || "ASTROPHILE"
  const subtitle = document.getElementById("inp_site_subtitle")?.value.trim() || "PLAYSTATION BILLING"
  const tagline  = document.getElementById("inp_site_tagline")?.value.trim()  || "Booking slot PS favoritmu"

  const waRaw = document.getElementById("inp_site_wa")?.value.trim().replace(/[\s\-().]/g,"") || ""
  const waNum = waRaw.startsWith("0") ? "62"+waRaw.slice(1) : waRaw.startsWith("62") ? waRaw : waRaw ? "62"+waRaw : ""

  localStorage.setItem("booking_site_nama",     nama)
  localStorage.setItem("booking_site_subtitle", subtitle)
  localStorage.setItem("booking_site_tagline",  tagline)
  if(waNum) localStorage.setItem("booking_site_wa", waNum)

  // Sync ke Firebase agar halaman Netlify bisa baca
  if(_fbDb){
    _fbDb.ref("settings/siteBookingNama").set(nama)
    _fbDb.ref("settings/siteBookingSubtitle").set(subtitle)
    _fbDb.ref("settings/siteBookingTagline").set(tagline)
    if(waNum) _fbDb.ref("settings/siteBookingWA").set(waNum)
    const panduanTV = document.getElementById("inp_panduan_tv")?.value.trim()
    if(panduanTV) _fbDb.ref("settings/panduanBookingTV").set(panduanTV)
  }

  showPopup({ typeNotif:"success", message:"✅ Judul halaman booking disimpan!\nHalaman pelanggan akan otomatis update." })
}

