// ============================================================
// PENGELUARAN — Catatan Harian Pemasukan & Pengeluaran
// ============================================================
let pengeluaranList = JSON.parse(localStorage.getItem("ps_pengeluaran") || "[]")

function savePengeluaran(){
  // Gunakan localStorage.setItem (override) — otomatis sync ke Firebase sebagai JSON string
  // JANGAN pakai _fbDb.ref().set(array) langsung karena Firebase konversi array → object
  localStorage.setItem("ps_pengeluaran", JSON.stringify(pengeluaranList))
}

function _loadPengeluaranFromFirebase(){
  if(!_fbDb) return
  _fbDb.ref("pengeluaran").once("value", snap => {
    const val = snap.val()
    if(!val) return
    try{
      // Parse jika string, langsung pakai jika array
      const parsed = typeof val === 'string' ? JSON.parse(val) : (Array.isArray(val) ? val : Object.values(val))
      if(Array.isArray(parsed) && parsed.length > 0){
        pengeluaranList = parsed
        // Gunakan _origSetItem agar tidak trigger push balik ke Firebase
        _origSetItem("ps_pengeluaran", JSON.stringify(pengeluaranList))
      }
    }catch(e){}
  })
}

function _getPemasukanTanggal(tanggalStr){
  // Gabung history & historyToday tapi deduplikasi berdasarkan ID
  const seen = new Set()
  const allH = [...(history||[]), ...(historyToday||[])].filter(item => {
    const key = item.id || item.timestamp || JSON.stringify(item)
    if(seen.has(key)) return false
    seen.add(key)
    return true
  })
  return allH.filter(item => {
    const d = _parseItemDate(item)
    if(!d) return false
    const tgl = [d.getFullYear(), String(d.getMonth()+1).padStart(2,'0'), String(d.getDate()).padStart(2,'0')].join('-')
    return tgl === tanggalStr
  }).reduce((sum, item) => sum + (Number(item.total)||0), 0)
}

