// ============================================================
let saldoWaktuList = JSON.parse(localStorage.getItem('ps_saldo_waktu') || '[]')
if(!Array.isArray(saldoWaktuList)) saldoWaktuList = Object.values(saldoWaktuList||{})
// Gunakan _origSetItem agar tidak overwrite Firebase saat startup
_origSetItem('ps_saldo_waktu', JSON.stringify(saldoWaktuList))

function saveSaldoWaktu(){
  if(!Array.isArray(saldoWaktuList)) saldoWaktuList = []
  localStorage.setItem('ps_saldo_waktu', JSON.stringify(saldoWaktuList))
}

function _genSaldoId(){
  return 'sw_' + Date.now() + '_' + Math.random().toString(36).slice(2,6)
}

function _getSaldoByNama(nama){
  return saldoWaktuList.find(s => s.nama?.toLowerCase() === nama?.toLowerCase())
}

function _getSaldoById(id){
  return saldoWaktuList.find(s => s.id === id)
}

// ── HELPER: total saldo semua PS (atau fallback ke field lama) ──
function _getTotalSaldo(p){
  if(p.saldoPs && Object.keys(p.saldoPs).length > 0)
    return Object.values(p.saldoPs).reduce((s,v)=>s+(v||0),0)
  return p.saldo||0
}
// ── HELPER: saldo untuk 1 jenis PS ──
function _getSaldoForPs(p, psType){
  if(!p.saldoPs) return 0
  return p.saldoPs[psType]||0
}
// ── HELPER: sinkronisasi p.saldo = jumlah semua saldoPs ──
function _syncSaldoTotal(p){
  if(p.saldoPs)
    p.saldo = Object.values(p.saldoPs).reduce((s,v)=>s+(v||0),0)
}
// ── HELPER: semua nama jenis PS dari config harga ──
function _getPsTypes(){
  return (Array.isArray(prices)?prices:[]).map(p=>p.nama).filter(Boolean)
}

