let _pglKatIdx = 0
function _selectPglKat(idx){
  _pglKatIdx = idx
  document.getElementById('pgl_kat_idx').value = idx
  _PGL_KATEGORI.forEach((_,i) => {
    const btn = document.getElementById('pglKat_'+i)
    if(!btn) return
    if(i === idx){
      btn.style.background = "rgba(255,26,80,0.16)"
      btn.style.border = "1px solid rgba(255,26,80,0.40)"
      btn.style.color = "#ff6688"
    } else {
      btn.style.background = "rgba(0,0,0,0.25)"
      btn.style.border = "1px solid rgba(255,255,255,0.10)"
      btn.style.color = "rgba(168,200,240,0.50)"
    }
  })
}

function _simpanPengeluaran(){
  const nominal = parseInt(String(document.getElementById('pgl_nominal')?.value||'').replace(/\./g,'') || '0')
  const desk    = document.getElementById('pgl_desk')?.value.trim() || ''
  const tanggal = document.getElementById('pgl_tanggal')?.value || ''
  const katIdx  = parseInt(document.getElementById('pgl_kat_idx')?.value || '0')
  const kat     = _PGL_KATEGORI[katIdx]
  const err     = document.getElementById('pgl_err')

  if(!nominal || nominal <= 0){ err.textContent='⚠️ Nominal harus lebih dari 0'; err.style.display='block'; return }
  if(!tanggal){ err.textContent='⚠️ Tanggal wajib diisi'; err.style.display='block'; return }

  const now = new Date()
  const waktu = now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0')

  const entry = {
    id:       'PGL-'+Date.now(),
    tanggal,
    waktu,
    kategori: kat.label,
    emoji:    kat.emoji,
    deskripsi: desk || kat.label,
    nominal,
    createdAt: Date.now()
  }

  pengeluaranList.push(entry)
  savePengeluaran()
  addOperatorLog(_getCurrentRole(), 'tambah_pengeluaran', `${kat.emoji} ${entry.deskripsi} - ${formatRupiah(nominal)}`)

  document.getElementById('tambahPglPopup')?.remove()
  showPopup({ typeNotif:'success', message:`✅ Pengeluaran dicatat!\n${kat.emoji} ${entry.deskripsi}\n${formatRupiah(nominal)}` })
  renderPengeluaranPage()
}

function _hapusPengeluaran(id){
  _showConfirm('Hapus catatan pengeluaran ini?', () => {
    pengeluaranList = pengeluaranList.filter(p => p.id !== id)
    savePengeluaran()
    renderPengeluaranPage()
    showPopup({ typeNotif:'success', message:'🗑️ Pengeluaran dihapus.' })
  })
}
