let _tplKatIdx = 0
function _selectTplKat(idx){
  _tplKatIdx = idx
  document.getElementById('tpl_kat_idx').value = idx
  _PGL_KATEGORI.forEach((_,i)=>{
    const b=document.getElementById('tplKat_'+i); if(!b) return
    b.style.background = i===idx?'rgba(255,26,80,0.16)':'rgba(0,0,0,0.25)'
    b.style.border     = i===idx?'1px solid rgba(255,26,80,0.40)':'1px solid rgba(255,255,255,0.10)'
    b.style.color      = i===idx?'#ff6688':'rgba(168,200,240,0.50)'
  })
}

function _simpanTemplate(){
  const desk  = document.getElementById('tpl_desk')?.value.trim()
  const nom   = parseInt((document.getElementById('tpl_nominal')?.value||'0').replace(/\./g,''))
  const kIdx  = parseInt(document.getElementById('tpl_kat_idx')?.value||'0')
  const kat   = _PGL_KATEGORI[kIdx]
  if(!desk){ showPopup({ typeNotif:'warning', message:'⚠️ Nama template wajib diisi' }); return }
  if(!nom||nom<=0){ showPopup({ typeNotif:'warning', message:'⚠️ Nominal harus lebih dari 0' }); return }
  pglTemplates.push({ id:'TPL-'+Date.now(), kategori:kat.label, emoji:kat.emoji, deskripsi:desk, nominal:nom })
  savePglTemplates()
  document.getElementById('templatePopup')?.remove()
  showPopup({ typeNotif:'success', message:'✅ Template "'+desk+'" disimpan!' })
}

function _pakaiTemplate(id){
  const t = pglTemplates.find(x=>x.id===id)
  if(!t) return
  const now = new Date()
  const todayStr = [now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-')
  const waktu = now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0')
  const entry = { id:'PGL-'+Date.now(), tanggal:todayStr, waktu, kategori:t.kategori, emoji:t.emoji, deskripsi:t.deskripsi, nominal:t.nominal, createdAt:Date.now() }
  pengeluaranList.push(entry)
  savePengeluaran()
  document.getElementById('templatePopup')?.remove()
  showPopup({ typeNotif:'success', message:'✅ '+t.emoji+' '+t.deskripsi+'\nRp '+t.nominal.toLocaleString('id-ID')+' dicatat hari ini!' })
  renderPengeluaranPage()
}

function _hapusTemplate(id){
  pglTemplates = pglTemplates.filter(t=>t.id!==id)
  savePglTemplates()
  _showTemplatePopup()
}

// ── 5. RINGKASAN BULAN VS BULAN ──
function _getRingkasanBulan(tahun, bulan){
  const prefix = `${tahun}-${String(bulan).padStart(2,'0')}`
  const pglBulan  = pengeluaranList.filter(p=>p?.tanggal?.startsWith(prefix))
  const pengeluaran = pglBulan.reduce((s,p)=>s+(Number(p.nominal)||0),0)

  // Pemasukan dari history
  const allH = [...(history||[]),...(historyToday||[])]
  let pemasukan = 0
  allH.forEach(item=>{
    const d=_parseItemDate(item); if(!d) return
    if(d.getFullYear()===tahun && d.getMonth()+1===bulan) pemasukan+=(Number(item.total)||0)
  })
  return { pemasukan, pengeluaran, laba: pemasukan-pengeluaran, prefix }
}

function _buildRingkasanBulanHtml(){
  const now = new Date()
  const m   = now.getMonth()+1
  const y   = now.getFullYear()
  const prevM = m===1?12:m-1
  const prevY = m===1?y-1:y

  const curr = _getRingkasanBulan(y, m)
  const prev = _getRingkasanBulan(prevY, prevM)

  const bulanNama = (y,m)=>new Date(y,m-1,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'})

  function diffStr(a,b){
    if(b===0) return ''
    const pct = Math.round((a-b)/b*100)
    return `<span style="font-size:9px;color:${pct>=0?'#00ff88':'#ff4d6d'};margin-left:4px;">${pct>=0?'▲':'▼'}${Math.abs(pct)}%</span>`
  }

  return `
  <div style="background:rgba(6,10,22,0.90);border:1px solid rgba(119,0,255,0.18);
    border-radius:16px;padding:16px;margin-bottom:16px;">
    <div style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;
      color:rgba(200,150,255,0.60);margin-bottom:14px;">📊 BULAN INI VS BULAN LALU</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:12px;">
      <div style="font-size:10px;color:rgba(168,200,240,0.40);text-align:center;padding:4px;">
        ${bulanNama(prevY,prevM)}
      </div>
      <div style="font-size:10px;color:rgba(0,245,255,0.60);text-align:center;padding:4px;font-weight:700;">
        ${bulanNama(y,m)} ← Ini
      </div>
    </div>
    ${[['PEMASUKAN','pemasukan','#00f5ff'],['PENGELUARAN','pengeluaran','#ff4d6d'],['LABA','laba',curr.laba>=0?'#00ff88':'#ff4d6d']].map(([lbl,key,color])=>`
    <div style="display:grid;grid-template-columns:1fr auto 1fr;gap:8px;align-items:center;margin-bottom:10px;">
      <div style="text-align:right;">
        <div style="font-size:9px;color:rgba(168,200,240,0.35);">${lbl}</div>
        <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:700;color:rgba(200,200,220,0.60);">
          ${formatRupiah(Math.abs(prev[key]))}</div>
      </div>
      <div style="text-align:center;color:rgba(168,200,240,0.20);font-size:14px;">→</div>
      <div style="text-align:left;">
        <div style="font-size:9px;color:${color};opacity:.70;">${lbl}</div>
        <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:700;color:${color};display:flex;align-items:center;">
          ${formatRupiah(Math.abs(curr[key]))}${key==='pemasukan'||key==='pengeluaran'?diffStr(curr[key],prev[key]):''}
        </div>
      </div>
    </div>`).join('')}
  </div>`
}
// ============================================================
// MENU PEMASUKAN — Catatan Pemasukan Tambahan (Non-sesi PS)
// Contoh: penjualan minuman, snack, jasa lain, dll
// ============================================================
let pemasukanList = JSON.parse(localStorage.getItem("ps_pemasukan_tambahan") || "[]")

function savePemasukan(){
  // Gunakan localStorage.setItem (override) — otomatis sync ke Firebase sebagai JSON string
  localStorage.setItem("ps_pemasukan_tambahan", JSON.stringify(pemasukanList))
}

function _loadPemasukanFromFirebase(){
  if(!_fbDb) return
  _fbDb.ref("pemasukanTambahan").once("value", snap => {
    const val = snap.val()
    if(!val) return
    try{
      const parsed = typeof val === 'string' ? JSON.parse(val) : (Array.isArray(val) ? val : Object.values(val))
      if(Array.isArray(parsed) && parsed.length > 0){
        pemasukanList = parsed
        // Gunakan _origSetItem agar tidak trigger push balik ke Firebase
        _origSetItem("ps_pemasukan_tambahan", JSON.stringify(pemasukanList))
      }
    }catch(e){}
  })
}

const _PMK_KATEGORI = [
  { emoji:"🥤", label:"Minuman" },
  { emoji:"🍟", label:"Makanan" },
  { emoji:"🎮", label:"Rental PS" },
  { emoji:"🖨️", label:"Print/Scan" },
  { emoji:"💳", label:"Top Up/Jasa" },
  { emoji:"📦", label:"Lain-lain" },
]

function renderPemasukanPage(opts){
  try{
  closeSidebar()
  // Safety: pastikan pemasukanList selalu array
  if(!Array.isArray(pemasukanList)) pemasukanList = Object.values(pemasukanList||{})

  const now      = new Date()
  const todayStr = [now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-')
  const curFilter = opts?.filter || window._pmkFilter || 'today'
  window._pmkFilter = curFilter

  function fmtDate(d){ return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-') }

  function getDates(){
    const d = []
    if(curFilter === 'today') return [todayStr]
    if(curFilter === '7days'){
      for(let i=6;i>=0;i--){ const dt=new Date(now); dt.setDate(dt.getDate()-i); d.push(fmtDate(dt)) }
    } else if(curFilter === 'bulan'){
      const y=now.getFullYear(), m=now.getMonth()
      const days=new Date(y,m+1,0).getDate()
      for(let i=1;i<=days;i++) d.push(`${y}-${String(m+1).padStart(2,'0')}-${String(i).padStart(2,'0')}`)
    } else if(curFilter==='custom' && window._pmkFrom && window._pmkTo){
      const s=new Date(window._pmkFrom+'T00:00:00')
      const e=new Date(window._pmkTo+'T00:00:00')
      if(isNaN(s.getTime())||isNaN(e.getTime())||s>e) return []
      let dt=new Date(s), count=0
      while(dt<=e && count<366){ d.push(fmtDate(dt)); dt.setDate(dt.getDate()+1); count++ }
    }
    return d
  }

  const dates = getDates()
  let totalPS = 0, totalTambahan = 0
  const rows = []
  const katMap = {}

  dates.forEach(tgl => {
    const psHari   = _getPemasukanTanggal(tgl)   // dari sesi PS (histori)
    const pmkHari  = pemasukanList.filter(p => p.tanggal === tgl)
    const tambahan = pmkHari.reduce((s,p) => s+(Number(p.nominal)||0), 0)
    totalPS       += psHari
    totalTambahan += tambahan
    pmkHari.forEach(p => { katMap[p.kategori] = (katMap[p.kategori]||0) + (Number(p.nominal)||0) })
    if(psHari===0 && tambahan===0) return
    const tglObj = new Date(tgl+'T00:00:00')
    rows.push({ tgl, tglFmt:tglObj.toLocaleDateString('id-ID',{weekday:'short',day:'numeric',month:'short'}),
      isToday:tgl===todayStr, psHari, tambahan, total:psHari+tambahan, entries:pmkHari })
  })

  const grandTotal = totalPS + totalTambahan
  const katEntries = Object.entries(katMap).sort((a,b)=>b[1]-a[1])
  const maxKat     = katEntries[0]?.[1] || 1
  const katEmojis  = Object.fromEntries(_PMK_KATEGORI.map(k=>[k.label,k.emoji]))

  const breakdownHtml = katEntries.length ? `
  <div style="background:rgba(6,10,22,0.90);border:1px solid rgba(0,245,255,0.12);
    border-radius:16px;padding:16px;margin-bottom:16px;">
    <div style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;
      color:rgba(0,245,255,0.55);margin-bottom:14px;">📊 SUMBER PEMASUKAN TAMBAHAN</div>
    ${katEntries.map(([kat,nom])=>`
      <div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;">
          <span style="font-size:12px;color:rgba(200,220,240,0.80);">${katEmojis[kat]||'📦'} ${kat}</span>
          <span style="font-family:'Orbitron',monospace;font-size:11px;font-weight:700;color:#00f5ff;">
            ${formatRupiah(nom)}</span>
        </div>
        <div style="height:5px;border-radius:4px;background:rgba(255,255,255,0.06);overflow:hidden;">
          <div style="height:100%;border-radius:4px;width:${Math.round(nom/maxKat*100)}%;
            background:linear-gradient(90deg,#00f5ff,#7700ff);transition:width .5s;"></div>
        </div>
      </div>`).join('')}
  </div>` : ''

  const html = `
  <div style="padding:16px 16px 100px;max-width:600px;margin:0 auto;">

    <!-- Filter -->
    <div style="display:flex;gap:5px;margin-bottom:12px;flex-wrap:wrap;align-items:center;">
      ${[['today','Hari Ini'],['7days','7 Hari'],['bulan','Bulan Ini'],['custom','📅']].map(([v,l])=>`
        <button onclick="window._pmkFilter='${v}';${v==='custom'?'_showPmkCustomFilter()':'renderPemasukanPage()'}"
          style="padding:8px 14px;border-radius:20px;font-size:11px;font-weight:700;
          ${v===curFilter
            ?'background:rgba(0,245,255,0.14);border:1px solid rgba(0,245,255,0.42);color:#00f5ff;'
            :'background:rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.08);color:rgba(168,200,240,0.45);'}">
          ${l}</button>`).join('')}
      <button onclick="_showTambahPemasukanPopup()" title="Tambah Pemasukan"
        style="margin-left:auto;padding:8px 14px;border-radius:20px;font-size:11px;font-weight:700;
        background:rgba(0,245,255,0.10);border:1px solid rgba(0,245,255,0.28);color:#00f5ff;">
        ➕ TAMBAH</button>
    </div>

    <!-- Summary 3 cards -->
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px;">
      <div style="background:rgba(0,245,255,0.06);border:1px solid rgba(0,245,255,0.18);
        border-radius:14px;padding:14px 8px;text-align:center;">
        <div style="font-size:8px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
          letter-spacing:1px;margin-bottom:5px;">SESI PS</div>
        <div style="font-family:'Orbitron',monospace;font-size:11px;font-weight:900;color:#00f5ff;">
          ${formatRupiah(totalPS)}</div>
        <div style="font-size:9px;color:rgba(0,245,255,0.35);margin-top:3px;">Rental</div>
      </div>
      <div style="background:rgba(119,0,255,0.06);border:1px solid rgba(119,0,255,0.20);
        border-radius:14px;padding:14px 8px;text-align:center;">
        <div style="font-size:8px;color:rgba(200,150,255,0.60);font-family:'Orbitron',monospace;
          letter-spacing:1px;margin-bottom:5px;">TAMBAHAN</div>
        <div style="font-family:'Orbitron',monospace;font-size:11px;font-weight:900;color:#cc88ff;">
          ${formatRupiah(totalTambahan)}</div>
        <div style="font-size:9px;color:rgba(200,150,255,0.35);margin-top:3px;">Non-PS</div>
      </div>
      <div style="background:rgba(0,255,136,0.06);border:1px solid rgba(0,255,136,0.20);
        border-radius:14px;padding:14px 8px;text-align:center;">
        <div style="font-size:8px;color:rgba(0,255,136,0.60);font-family:'Orbitron',monospace;
          letter-spacing:1px;margin-bottom:5px;">TOTAL</div>
        <div style="font-family:'Orbitron',monospace;font-size:11px;font-weight:900;color:#00ff88;">
          ${formatRupiah(grandTotal)}</div>
        <div style="font-size:9px;color:rgba(0,255,136,0.35);margin-top:3px;">Semua</div>
      </div>
    </div>

    <!-- Breakdown kategori tambahan -->
    ${breakdownHtml}

    <!-- Timeline -->
    <div style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;
      color:rgba(168,200,240,0.35);margin-bottom:10px;">📋 RIWAYAT PEMASUKAN</div>

    ${rows.length===0?`
      <div style="text-align:center;padding:48px 20px;">
        <div style="font-size:44px;margin-bottom:14px;opacity:0.35;">💰</div>
        <div style="font-family:'Orbitron',monospace;font-size:10px;letter-spacing:2px;
          color:rgba(168,200,240,0.35);">BELUM ADA DATA</div>
      </div>`:
    [...rows].reverse().map(r=>`
      <div style="margin-bottom:12px;">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
          <span style="font-family:'Orbitron',monospace;font-size:8px;font-weight:700;
            color:${r.isToday?'#00f5ff':'rgba(168,200,240,0.35)'};letter-spacing:1.5px;">
            ${r.isToday?'📅 HARI INI':r.tglFmt.toUpperCase()}</span>
          <div style="flex:1;height:1px;background:rgba(255,255,255,0.04)"></div>
        </div>
        <div style="background:rgba(6,10,22,0.90);
          border:1px solid ${r.isToday?'rgba(0,245,255,0.14)':'rgba(255,255,255,0.05)'};
          border-radius:14px;overflow:hidden;">
          <!-- Summary bar -->
          <div style="display:flex;align-items:center;padding:10px 14px;gap:8px;
            border-bottom:${r.entries.length?'1px solid rgba(255,255,255,0.05)':'none'};">
            <div style="display:flex;align-items:center;gap:5px;flex:1;">
              <span style="font-size:10px;color:rgba(0,245,255,0.50);">🎮</span>
              <span style="font-size:11px;color:rgba(168,200,240,0.60);">PS</span>
              <span style="font-size:12px;font-weight:700;color:#e8f4ff;">${formatRupiah(r.psHari)}</span>
            </div>
            <div style="display:flex;align-items:center;gap:5px;flex:1;">
              <span style="font-size:10px;color:rgba(200,150,255,0.50);">➕</span>
              <span style="font-size:11px;color:rgba(168,200,240,0.60);">Lain</span>
              <span style="font-size:12px;font-weight:700;color:#e8f4ff;">${formatRupiah(r.tambahan)}</span>
            </div>
            <div style="padding:4px 10px;border-radius:20px;
              background:rgba(0,255,136,0.10);border:1px solid rgba(0,255,136,0.25);">
              <span style="font-family:'Orbitron',monospace;font-size:9px;font-weight:700;
                color:#00ff88;">${formatRupiah(r.total)}</span>
            </div>
          </div>
          <!-- Entries tambahan -->
          ${r.entries.map(e=>`
            <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;
              border-bottom:1px solid rgba(255,255,255,0.03);">
              <div style="width:34px;height:34px;border-radius:10px;flex-shrink:0;
                background:rgba(119,0,255,0.10);border:1px solid rgba(119,0,255,0.20);
                display:flex;align-items:center;justify-content:center;font-size:16px;">
                ${e.emoji||'📦'}</div>
              <div style="flex:1;min-width:0;">
                <div style="font-size:13px;font-weight:700;color:#e8f4ff;
                  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
                  ${escapeHTML(e.deskripsi||e.kategori)}</div>
                <div style="font-size:11px;color:rgba(168,200,240,0.40);margin-top:1px;">
                  ${e.kategori}${e.waktu?' · '+e.waktu:''}</div>
              </div>
              <div style="text-align:right;flex-shrink:0;">
                <div style="font-family:'Orbitron',monospace;font-size:12px;font-weight:900;
                  color:#cc88ff;">+${formatRupiah(Number(e.nominal)||0)}</div>
                <button onclick="_hapusPemasukan('${e.id}')"
                  style="font-size:11px;color:rgba(200,150,255,0.35);margin-top:2px;
                  background:none;border:none;cursor:pointer;padding:2px;">🗑</button>
              </div>
            </div>`).join('')}
        </div>
      </div>`).join('')}
  </div>`

  showInternalPage("💰 PEMASUKAN", "Pemasukan sesi PS & pendapatan tambahan", html)
  try{
    const pv = document.getElementById('pageView')
    if(pv){ const b=document.createElement('div'); b.innerHTML=_fbCloudStatusBadge('pemasukanTambahan'); pv.insertBefore(b.firstElementChild||b,pv.children[1]||null) }
  }catch(e){}

  // FAB
  const fab = document.createElement('button')
  fab.onclick = _showTambahPemasukanPopup
  fab.title   = 'Tambah Pemasukan'
  fab.style.cssText = 'position:fixed;bottom:28px;right:20px;z-index:100;width:56px;height:56px;border-radius:50%;background:linear-gradient(135deg,#00f5ff,#7700ff);border:none;box-shadow:0 4px 24px rgba(0,245,255,0.40);font-size:24px;display:flex;align-items:center;justify-content:center;transition:transform .2s;color:#fff;'
  fab.textContent = '+'
  fab.onmousedown = ()=>fab.style.transform='scale(0.88)'
  fab.onmouseup   = ()=>fab.style.transform='scale(1)'
  fab.ontouchstart= ()=>fab.style.transform='scale(0.88)'
  fab.ontouchend  = ()=>fab.style.transform='scale(1)'
  setTimeout(()=>{ document.querySelectorAll('button[data-fab]').forEach(b=>b.remove()); fab.setAttribute('data-fab','1'); const pg=document.getElementById('mainContent')||document.querySelector('.internal-page'); if(pg) pg.appendChild(fab) },100)
  }catch(err){
    console.error('[Pemasukan] Error:', err)
    showInternalPage('💰 PEMASUKAN','Error',`<div style="padding:20px;color:#ff6688;font-family:monospace;font-size:12px;word-break:break-all;">${err?.message||err}</div>`)
  }
}

function _showPmkCustomFilter(){
  document.getElementById('pmkCustomPopup')?.remove()
  const el = document.createElement('div')
  el.id = 'pmkCustomPopup'
  el.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;background:rgba(2,5,16,0.88);backdrop-filter:blur(8px);padding:24px;'
  const from = window._pmkFrom||'', to = window._pmkTo||''
  el.innerHTML = `
    <div style="background:linear-gradient(145deg,#070f1c,#0d1a2e);border:1px solid rgba(0,245,255,0.22);
      border-radius:20px;padding:24px;width:100%;max-width:380px;">
      <div style="font-family:'Orbitron',monospace;font-size:11px;font-weight:700;
        color:#00f5ff;letter-spacing:2px;margin-bottom:18px;">📅 RENTANG TANGGAL</div>
      <label style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;display:block;margin-bottom:6px;">DARI</label>
      <input id="pmk_from" type="date" value="${from}"
        style="width:100%;padding:11px 14px;border-radius:10px;margin-bottom:12px;
        border:1px solid rgba(0,245,255,0.20);background:rgba(0,245,255,0.04);
        color:#fff;font-size:13px;outline:none;box-sizing:border-box;">
      <label style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;display:block;margin-bottom:6px;">SAMPAI</label>
      <input id="pmk_to" type="date" value="${to}"
        style="width:100%;padding:11px 14px;border-radius:10px;margin-bottom:20px;
        border:1px solid rgba(0,245,255,0.20);background:rgba(0,245,255,0.04);
        color:#fff;font-size:13px;outline:none;box-sizing:border-box;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <button onclick="document.getElementById('pmkCustomPopup').remove();window._pmkFilter='today';renderPemasukanPage()"
          style="padding:12px;border-radius:12px;background:rgba(255,255,255,0.03);
          border:1px solid rgba(255,255,255,0.08);color:rgba(168,200,240,0.55);font-size:12px;">
          Batal</button>
        <button onclick="_applyPmkCustom()"
          style="padding:12px;border-radius:12px;background:rgba(0,245,255,0.10);
          border:1px solid rgba(0,245,255,0.35);color:#00f5ff;
          font-family:'Orbitron',monospace;font-size:9px;font-weight:700;letter-spacing:1px;">
          ✅ TERAPKAN</button>
      </div>
    </div>`
  document.body.appendChild(el)
  el.onclick = e=>{ if(e.target===el){ el.remove(); window._pmkFilter='today'; renderPemasukanPage() } }
}

function _applyPmkCustom(){
  const from = document.getElementById('pmk_from')?.value
  const to   = document.getElementById('pmk_to')?.value
  if(!from||!to){ showPopup({ typeNotif:'warning', message:'⚠️ Pilih tanggal dari dan sampai' }); return }
  if(from>to){ showPopup({ typeNotif:'warning', message:'⚠️ Tanggal dari harus sebelum sampai' }); return }
  window._pmkFilter='custom'; window._pmkFrom=from; window._pmkTo=to
  document.getElementById('pmkCustomPopup')?.remove()
  renderPemasukanPage()
}

function _showTambahPemasukanPopup(){
  document.getElementById('tambahPmkPopup')?.remove()
  const el = document.createElement('div')
  el.id = 'tambahPmkPopup'
  el.style.cssText = 'position:fixed;inset:0;z-index:9999;display:flex;align-items:flex-end;justify-content:center;background:rgba(2,5,16,0.88);backdrop-filter:blur(8px);'
  const now = new Date()
  const todayStr = [now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-')

  el.innerHTML = `
    <div style="background:linear-gradient(145deg,#070f1c,#0d1a2e);
      border:1px solid rgba(0,245,255,0.22);border-bottom:none;
      border-radius:24px 24px 0 0;width:100%;max-width:520px;
      padding:0 20px 36px;max-height:88vh;overflow-y:auto;
      box-shadow:0 -20px 60px rgba(0,0,0,0.70);">
      <div style="height:3px;border-radius:24px 24px 0 0;margin:0 -20px 20px;
        background:linear-gradient(90deg,transparent,rgba(0,245,255,0.70),rgba(119,0,255,0.50),transparent);"></div>
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
        <div>
          <div style="font-family:'Orbitron',monospace;font-size:13px;font-weight:700;
            color:#00f5ff;letter-spacing:1.5px;">💰 TAMBAH PEMASUKAN</div>
          <div style="font-size:11px;color:rgba(168,200,240,0.40);margin-top:2px;">
            Catat pendapatan di luar sesi PS</div>
        </div>
        <button onclick="document.getElementById('tambahPmkPopup').remove()"
          style="width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,0.05);
          border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.55);font-size:16px;
          display:flex;align-items:center;justify-content:center;">✕</button>
      </div>

      <!-- Kategori chips grid -->
      <div style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;margin-bottom:8px;">KATEGORI</div>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:16px;">
        ${_PMK_KATEGORI.map((k,i)=>`
          <button onclick="_selectPmkKat(${i})" id="pmkKat_${i}"
            style="padding:10px 4px;border-radius:12px;
            display:flex;flex-direction:column;align-items:center;gap:4px;
            ${i===0
              ?'background:rgba(0,245,255,0.12);border:1px solid rgba(0,245,255,0.38);color:#00f5ff;'
              :'background:rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.45);'}">
            <span style="font-size:22px;">${k.emoji}</span>
            <span style="font-size:10px;font-weight:700;">${k.label}</span>
          </button>`).join('')}
      </div>
      <input type="hidden" id="pmk_kat_idx" value="0">

      <!-- Nominal -->
      <div style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;margin-bottom:6px;">NOMINAL (Rp)</div>
      <div style="display:flex;align-items:center;
        background:rgba(0,245,255,0.04);border:1px solid rgba(0,245,255,0.20);
        border-radius:12px;padding:4px 14px;margin-bottom:14px;">
        <span style="font-size:13px;color:rgba(0,245,255,0.40);padding-right:10px;
          border-right:1px solid rgba(0,245,255,0.15);">Rp</span>
        <input id="pmk_nominal" type="text" inputmode="numeric" min="0" placeholder="Rp 50.000" oninput="formatRupiahInput(this)"
          style="flex:1;background:transparent;border:none;outline:none;
          color:#00f5ff;font-size:16px;font-weight:700;padding:10px 0 10px 12px;
          font-family:'Orbitron',monospace;">
      </div>

      <!-- Deskripsi -->
      <div style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;margin-bottom:6px;">DESKRIPSI (OPSIONAL)</div>
      <input id="pmk_desk" type="text" placeholder="Mis: jual minuman, print dokumen..."
        style="width:100%;padding:12px 14px;border-radius:12px;
        border:1px solid rgba(0,245,255,0.16);background:rgba(0,245,255,0.04);
        color:#fff;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:14px;">

      <!-- Tanggal -->
      <div style="font-size:10px;color:rgba(0,245,255,0.55);font-family:'Orbitron',monospace;
        letter-spacing:1px;margin-bottom:6px;">TANGGAL</div>
      <input id="pmk_tanggal" type="date" value="${todayStr}"
        style="width:100%;padding:12px 14px;border-radius:12px;
        border:1px solid rgba(0,245,255,0.16);background:rgba(0,245,255,0.04);
        color:#fff;font-size:13px;outline:none;box-sizing:border-box;margin-bottom:20px;">

      <div id="pmk_err" style="display:none;color:#ff6688;font-size:12px;margin-bottom:12px;
        padding:10px;background:rgba(255,26,80,0.08);border-radius:10px;"></div>

      <div style="display:grid;grid-template-columns:1fr 2fr;gap:10px;">
        <button onclick="document.getElementById('tambahPmkPopup').remove()"
          style="padding:14px;border-radius:14px;background:rgba(255,255,255,0.03);
          border:1px solid rgba(255,255,255,0.08);color:rgba(168,200,240,0.55);font-size:13px;">
          Batal</button>
        <button onclick="_simpanPemasukan()"
          style="padding:14px;border-radius:14px;
          background:linear-gradient(135deg,rgba(0,245,255,0.16),rgba(119,0,255,0.10));
          border:1px solid rgba(0,245,255,0.40);color:#00f5ff;
          font-family:'Orbitron',monospace;font-size:10px;font-weight:700;letter-spacing:1.5px;">
          💾 SIMPAN PEMASUKAN</button>
      </div>
    </div>`

  document.body.appendChild(el)
  el.onclick = e=>{ if(e.target===el) el.remove() }
  setTimeout(()=>document.getElementById('pmk_nominal')?.focus(), 200)
}

let _pmkKatIdx = 0
function _selectPmkKat(idx){
  _pmkKatIdx = idx
  document.getElementById('pmk_kat_idx').value = idx
  _PMK_KATEGORI.forEach((_,i)=>{
    const b=document.getElementById('pmkKat_'+i); if(!b) return
    b.style.background = i===idx?'rgba(0,245,255,0.12)':'rgba(0,0,0,0.25)'
    b.style.border     = i===idx?'1px solid rgba(0,245,255,0.38)':'1px solid rgba(255,255,255,0.10)'
    b.style.color      = i===idx?'#00f5ff':'rgba(168,200,240,0.45)'
  })
}

function _simpanPemasukan(){
  const nominal = parseInt(String(document.getElementById('pmk_nominal')?.value||'').replace(/\./g,'')||'0')
  const desk    = document.getElementById('pmk_desk')?.value.trim()||''
  const tanggal = document.getElementById('pmk_tanggal')?.value||''
  const katIdx  = parseInt(document.getElementById('pmk_kat_idx')?.value||'0')
  const kat     = _PMK_KATEGORI[katIdx]
  const err     = document.getElementById('pmk_err')

  if(!nominal||nominal<=0){ err.textContent='⚠️ Nominal harus lebih dari 0'; err.style.display='block'; return }
  if(!tanggal){ err.textContent='⚠️ Tanggal wajib diisi'; err.style.display='block'; return }

  const now = new Date()
  const waktu = now.getHours().toString().padStart(2,'0')+':'+now.getMinutes().toString().padStart(2,'0')

  const entry = {
    id: 'PMK-'+Date.now(), tanggal, waktu,
    kategori: kat.label, emoji: kat.emoji,
    deskripsi: desk||kat.label, nominal, createdAt: Date.now()
  }

  pemasukanList.push(entry)
  savePemasukan()
  addOperatorLog(_getCurrentRole(), 'tambah_pemasukan', `${kat.emoji} ${entry.deskripsi} - ${formatRupiah(nominal)}`)
  document.getElementById('tambahPmkPopup')?.remove()
  showPopup({ typeNotif:'success', message:`✅ Pemasukan dicatat!\n${kat.emoji} ${entry.deskripsi}\n${formatRupiah(nominal)}` })
  renderPemasukanPage()
}

function _hapusPemasukan(id){
  _showConfirm('Hapus catatan pemasukan ini?', ()=>{
    pemasukanList = pemasukanList.filter(p=>p.id!==id)
    savePemasukan()
    renderPemasukanPage()
    showPopup({ typeNotif:'success', message:'🗑️ Pemasukan dihapus.' })
  })
}
