function _testFirebaseKoneksi(){
  const apiKeyEl   = document.getElementById("inp_fb_apikey")
  const dbUrlEl    = document.getElementById("inp_fb_dburl")
  const apiKey  = apiKeyEl  ? apiKeyEl.value.trim()  : (_getFirebaseConfig()||{}).apiKey  || ""
  const dbUrl   = dbUrlEl   ? dbUrlEl.value.trim()   : (_getFirebaseConfig()||{}).databaseURL || ""

  const el = document.getElementById("fb_status_indicator")
  function setStatus(txt, color){ if(el){ el.textContent=txt; el.style.color=color; el.style.display="block" } }

  // Validasi format dasar
  if(!apiKey || !dbUrl){
    showPopup({ typeNotif:"warning", message:"💾 Simpan & Terapkan dahulu,\nbaru cek koneksi." })
    return
  }
  if(!apiKey.startsWith("AIza")){
    setStatus("🔴 API Key tidak valid (harus diawali AIza...)", "#ff1a50")
    return
  }
  if(!dbUrl.includes("firebaseio.com") && !dbUrl.includes("firebasedatabase.app")){
    setStatus("🔴 URL tidak valid. Harus .firebaseio.com atau .firebasedatabase.app", "#ff1a50")
    return
  }

  setStatus("⏳ Mengecek koneksi...", "#ffcc00")

  // Test: fetch ke endpoint REST Firebase — hanya 200/401/403 = database ada
  const testUrl = dbUrl.replace(/\/+$/, "") + "/.json"
  fetch(testUrl, { signal: AbortSignal.timeout(8000) })
    .then(r => {
      if(r.status === 200 || r.status === 401 || r.status === 403){
        // Database ada dan merespon = berhasil terhubung
        setStatus("🟢 Firebase Terhubung! Database ditemukan.", "#00ff88")
      } else if(r.status === 404){
        setStatus("🔴 Database tidak ditemukan. Cek Database URL kamu.", "#ff1a50")
      } else {
        setStatus("🔴 Respons tidak valid (status " + r.status + ")", "#ff1a50")
      }
    })
    .catch(e => {
      if(e.name === "TimeoutError"){
        setStatus("🔴 Timeout — koneksi terlalu lama", "#ff1a50")
      } else {
        setStatus("🔴 Tidak dapat terhubung ke Firebase", "#ff1a50")
      }
    })
}

function _testFonnteKoneksi(){
  const token = _getFonnteToken()
  if(!token){
    showPopup({ typeNotif:"warning", message:"💾 Simpan & Terapkan dahulu,\nbaru cek koneksi." })
    return
  }
  const el = document.getElementById("fonnte_status_indicator")
  if(el){ el.textContent = "⏳ Mengecek..."; el.style.color = "#ffcc00"; el.style.display = "block" }

  // Gunakan endpoint /device untuk validasi token
  fetch("https://api.fonnte.com/device", {
    method: "POST",
    headers: {
      "Authorization": token,
      "Content-Type": "application/json"
    }
  })
  .then(r => r.json())
  .then(data => {
    if(el){
      // Jika ada response apapun (bukan network error) = token valid dan terhubung
      if(data.status === false && data.reason){
        el.textContent = "🔴 " + data.reason
        el.style.color = "#ff1a50"
      } else {
        // Ada nama device = berhasil
        const deviceName = data.name || data.device || ""
        el.textContent = "🟢 Terhubung!" + (deviceName ? " · " + deviceName : "")
        el.style.color = "#00ff88"
      }
    }
  })
  .catch(e => {
    if(el){
      el.textContent = "🔴 Gagal konek ke Fonnte"
      el.style.color = "#ff1a50"
    }
  })
}

