function _simpanIntegrasi(){
  const fonnteToken = document.getElementById("inp_fonnte_token")?.value.trim() || ""
  const apiKey      = document.getElementById("inp_fb_apikey")?.value.trim() || ""
  const databaseURL = document.getElementById("inp_fb_dburl")?.value.trim() || ""
  const authDomain  = document.getElementById("inp_fb_auth")?.value.trim() || ""
  const projectId   = document.getElementById("inp_fb_project")?.value.trim() || ""
  const appId       = document.getElementById("inp_fb_appid")?.value.trim() || ""

  const fbDiisi = apiKey || databaseURL || projectId
  const fbLengkap = apiKey && databaseURL && projectId

  // Validasi: jika ada Firebase yang diisi tapi tidak lengkap
  if(fbDiisi && !fbLengkap){
    showPopup({ typeNotif:"warning", message:"⚠️ Firebase belum lengkap!\nMinimal isi: API Key, Database URL, dan Project ID." })
    return
  }

  // Validasi: jika semua kosong
  if(!fonnteToken && !fbLengkap){
    showPopup({ typeNotif:"warning", message:"⚠️ Semua form masih kosong!\nIsi minimal satu bagian sebelum menyimpan." })
    return
  }

  // Simpan Fonnte
  if(fonnteToken){
    localStorage.setItem("integrasi_fonnte_token", fonnteToken)
  } else {
    localStorage.removeItem("integrasi_fonnte_token")
  }

  // Simpan Firebase
  if(fbLengkap){
    // Validasi format URL
    if(!databaseURL.includes("firebaseio.com") && !databaseURL.includes("firebasedatabase.app")){
      showPopup({ typeNotif:"warning", message:"⚠️ Database URL tidak valid!\nHarus mengandung firebaseio.com atau firebasedatabase.app" })
      return
    }
    const newConfig = {
      apiKey, authDomain,
      databaseURL, projectId,
      storageBucket: projectId + ".firebasestorage.app",
      appId
    }
    localStorage.setItem("integrasi_firebase_config", JSON.stringify(newConfig))
    showPopup({ typeNotif:"success", message:"✅ Semua pengaturan disimpan!\nAplikasi akan restart." })
    setTimeout(() => location.reload(), 2000)
  } else {
    // Hanya Fonnte yang disimpan
    showPopup({ typeNotif:"success", message:"✅ Token Fonnte disimpan!" })
  }
}

function _resetIntegrasi(){
  _showConfirm("Kosongkan semua form integrasi?", () => {
  // Kosongkan form saja, tidak hapus localStorage
  const fields = ["inp_fonnte_token","inp_fb_apikey","inp_fb_dburl","inp_fb_auth","inp_fb_project","inp_fb_appid"]
  fields.forEach(id => { const el = document.getElementById(id); if(el) el.value = "" })
  // Reset status indicators
  const si = document.getElementById("fonnte_status_indicator")
  const fi = document.getElementById("fb_status_indicator")
  if(si){ si.textContent = ""; si.style.display = "none" }
  if(fi){ fi.textContent = ""; fi.style.display = "none" }
  showPopup({ typeNotif:"info", message:"🗑️ Semua form dikosongkan." })
  })
}
