// ── Firebase Config ──────────────────────────────────────────
// Firebase config — bisa diubah via Pengaturan Integrasi
function _getFirebaseConfig(){
  const saved = localStorage.getItem("integrasi_firebase_config")
  if(saved){ try{ return JSON.parse(saved) }catch(e){} }
  // Tidak ada config default — pembeli harus isi via Sistem → Integrasi Firebase
  return null
}
const _fbConfig = _getFirebaseConfig() || {}

// Jika config kosong, tampilkan peringatan setup setelah login
window._fbConfigEmpty = !_getFirebaseConfig()

let _fbApp = null
let _fbDb  = null
let _fbBookingRef = null
let _fbOnline = false

function _initFirebase(){
  const cfg = _getFirebaseConfig()
  if(!cfg || !cfg.apiKey || !cfg.databaseURL){
    console.warn("Firebase: belum dikonfigurasi. Buka Sistem → Integrasi.")
    return
  }
  try {
    // Compat v9: cek via firebase.apps array
    const apps = (typeof firebase !== 'undefined') ? (firebase.apps || []) : []
    if(apps.length === 0){
      _fbApp = firebase.initializeApp(cfg)
    } else {
      // Sudah ada app — pakai yang ada
      _fbApp = apps[0]
      // Jika databaseURL beda (user ganti config), delete & reinit
      if(_fbApp.options.databaseURL !== cfg.databaseURL){
        _fbApp.delete().then(() => {
          _fbApp = null; _fbDb = null
          setTimeout(_initFirebase, 300)
        })
        return
      }
    }
    // Compat v9: database() adalah method dari app instance
    _fbDb = _fbApp.database()
    window._fbDb = _fbDb  // expose ke window
    _fbBookingRef = _fbDb.ref("bookings")

    // Listen status Android TV per unit
    setTimeout(initAndroidTvStatusListeners, 1000)

    // Sync jumlah TV saat init
    _fbDb.ref("settings/totalTV").once("value", snap => {
      if(!snap.val()) _fbDb.ref("settings/totalTV").set(units)
    })

    // ── RESTORE DATA SAAT INSTALL BARU ──────────────────────────
    // Load riwayat transaksi dari Firebase → merge ke lokal
    // Berguna saat reinstall: data cloud langsung kembali
    _fbDb.ref('transaksiHistory').once('value', snap => {
      if(!snap.exists()) return
      try{
        const raw = snap.val()
        const fbHistory = typeof raw === 'string' ? JSON.parse(raw) : (Array.isArray(raw) ? raw : [])
        if(!fbHistory.length) return
        let changed = false
        fbHistory.forEach(fbItem => {
          const exists = history.some(l =>
            (l.id && l.id === fbItem.id) ||
            (l.ts && l.ts === fbItem.ts && l.tv === fbItem.tv)
          )
          if(!exists){ history.push(fbItem); changed = true }
        })
        if(!changed) return
        history.sort((a,b) => (b.ts||0)-(a.ts||0))
        _origSetItem('ps_history', JSON.stringify(history))
        resetHistoryHarian()
        if(typeof hitungOmzet === 'function') hitungOmzet()
        console.log('[Astrophile] History dipulihkan dari Firebase:', fbHistory.length, 'transaksi')
      }catch(e){ console.warn('Restore history error:', e) }
    })

    // Load saved times & WA templates dari Firebase saat init
    _fbDb.ref('settings/savedTimes').once('value', snap => {
      if(snap.val()) saveSavedTimes(Array.isArray(snap.val()) ? snap.val() : Object.values(snap.val()))
    })
    _loadWATemplatesFromFirebase()

    // Booking online status — real-time listener (bukan once, agar sync multi-device)
    _fbDb.ref("settings/bookingOnline").on("value", snap => {
      if(snap.val() !== null){
        localStorage.setItem("booking_online_status", snap.val())
      } else {
        _fbDb.ref("settings/bookingOnline").set("on")
      }
      _updateBookingToggleUI()
    })

    // Deteksi status koneksi
    _fbDb.ref(".info/connected").on("value", snap => {
      _fbOnline = snap.val() === true
      _updateFbStatusBadge()
      // Update subtitle booking page jika sedang terbuka
      const subEl = document.querySelector(".page-view-subtitle")
      if(subEl && document.getElementById("bookingPageContainer")){
        subEl.textContent = "Reservasi real-time · " + (_fbOnline ? "🟢 Terhubung" : "🔴 Offline")
      }
    })

    // Listener realtime — sinkron dari Firebase ke lokal
    // Track booking IDs yang sudah diketahui (untuk deteksi booking baru)
    let _knownBookingIds = new Set(bookings.map(b => b.id))

    _fbBookingRef.on("value", snap => {
      const data = snap.val()
      if(data){
        const fbList = Object.values(data)

        // Deteksi booking BARU dari pelanggan
        fbList.forEach(b => {
          if(!_knownBookingIds.has(b.id) && b.source === "pelanggan"){
            _knownBookingIds.add(b.id)
            _tampilkanNotifBookingBaru(b)
          } else {
            _knownBookingIds.add(b.id)
          }
        })

        // Deteksi booking yang di-batal OTOMATIS oleh netlify (terlambat)
        fbList.forEach(fbB => {
          if(fbB.batalReason === "terlambat" && fbB.status === "batal"){
            const lokal = bookings.find(b => b.id === fbB.id)
            if(lokal && lokal.status !== "batal"){
              // Reset activeSessions TV ini — jangan reset kalau sedang billing/countdown beneran
              if(_fbDb){
                _fbDb.ref("settings/activeSessions/" + fbB.tv).once("value", snap2 => {
                  const sess2 = snap2.val() || {}
                  const isRealSession = sess2.active && sess2.start && (sess2.mode === "billing" || sess2.mode === "countdown")
                  if(!isRealSession){
                    _fbDb.ref("settings/activeSessions/" + fbB.tv).set({ active: false })
                    if(state[fbB.tv]) state[fbB.tv] = { active: false }
                    localStorage.setItem("ps_state", JSON.stringify(state))
                  }
                })
              }
              // Kirim WA otomatis ke pelanggan
              if(fbB.noWA){
                const titleTop = localStorage.getItem("ps_title_top") || "ASTROPHILE"
                const pesan = `⏰ *BOOKING OTOMATIS DIBATALKAN*\n\n` +
                  `Halo ${fbB.nama}, kamu terlambat lebih dari 10 menit dari jam kedatangan.\n\n` +
                  `📺 TV ${fbB.tv} · Jam ${fbB.jamMulai}\n` +
                  `🔖 Kode: ${fbB.id}\n\n` +
                  `Booking kamu otomatis dibatalkan karena melebihi batas toleransi.\n` +
                  `Silakan booking ulang jika masih ingin main. 🎮\n` +
                  `_— ${titleTop}_`
                _kirimWA(fbB.noWA, pesan)
              }
            }
          }
        })

        // Gabungkan: firebase jadi sumber kebenaran
        bookings = fbList.sort((a,b) => new Date(b.createdAt) - new Date(a.createdAt))
        localStorage.setItem("ps_bookings", JSON.stringify(bookings))
      } else {
        bookings.forEach(b => _fbBookingRef.child(b.id).set(b))
      }
      _updateBookingSidebarBadge()
      if(document.getElementById("bookingPageContainer")){
        renderBookingPage()
      }
    })

    // ── Real-time listener activeSessions → sync ke state lokal ──
    _fbDb.ref("settings/activeSessions").on("value", snap => {
      const fbSessions = snap.val() || {}
      // Update state lokal dengan data Firebase — JAGA type agar tidak hilang
      Object.keys(fbSessions).forEach(tvKey => {
        const tv = parseInt(tvKey)
        if(fbSessions[tvKey]){
          const fb       = fbSessions[tvKey]
          const existing = state[tv] || {}

          // Jika Firebase punya sesi aktif dengan start time BERBEDA dari lokal
          // → Firebase adalah sumber kebenaran (misal setelah pindah TV)
          const fbIsNewerSession = fb.active && fb.start && fb.start !== existing.start

          state[tv] = {
            ...fb,
            // Type & price: pakai Firebase jika sesi baru, pakai lokal jika sama sesi
            type:  fbIsNewerSession ? (fb.type || existing.type || null)
                                    : (existing.type || fb.type || null),
            price: fbIsNewerSession ? (fb.price || 0)
                                    : (existing.price || fb.price || 0),
            // Items selalu dari lokal (lebih lengkap, Firebase tidak sync items realtime)
            items: existing.items || fb.items || [],
            duration: existing.duration ?? fb.duration ?? 0,
            namaPelanggan: existing.namaPelanggan || fb.namaPelanggan || '',
            // _bonusDetik: pakai dari Firebase jika ada, fallback ke lokal
            _bonusDetik: (fb._bonusDetik !== undefined ? fb._bonusDetik : null)
                         ?? (existing._bonusDetik || 0),
            // _saldoId & _saldoMenit: lokal only — jangan pernah ditimpa Firebase
            _saldoId:    existing._saldoId    || null,
            _saldoMenit: existing._saldoMenit || 0,
            _saldoPsType:existing._saldoPsType|| null
          }
        } else {
          if(state[tv]) state[tv].active = false
        }
      })
      localStorage.setItem("ps_state", JSON.stringify(state))
      // Re-render booking page jika sedang terbuka
      if(document.getElementById("bookingPageContainer")){
        renderBookingPage()
      }
    })

    console.log("✅ Firebase Booking terhubung")
    // Sync info TV (tipe + harga) saat pertama connect
    setTimeout(_syncTVInfoToFirebase, 1000)


    // Realtime listener untuk users — sync login data
    _fbDb.ref('users').on('value', snap => {
      let data = snap.val()
      // Safety: jika data berupa string (bug lama _cached_users sync), parse dulu
      if(typeof data === 'string'){
        try{ data = JSON.parse(data) }catch(e){ data = null }
      }
      if(data && typeof data === 'object' && Object.keys(data).length > 0){
        // PIN Owner TIDAK diambil dari Firebase — selalu dari localStorage
        // Fallback ke '9999' jika ps_owner_pin belum pernah di-set (fresh install)
        const ownerPinLocal = localStorage.getItem('ps_owner_pin') || '9999'
        window._loginUsers = data
        // Selalu restore PIN owner — jangan andalkan kondisi karena ps_owner_pin bisa null
        Object.values(window._loginUsers).forEach(u => {
          if(u.role === 'owner') u.pin = ownerPinLocal
        })
        localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers))
      } else {
        // Belum ada user → buat owner default
        _createDefaultOwner()
      }
    })
  } catch(e){
    console.warn("Firebase init gagal:", e)
    _fbOnline = false
  }
}

function _updateFbStatusBadge(){
  const el = document.getElementById("fbSyncStatus")
  if(!el) return
  el.textContent = _fbOnline ? "🟢 Sinkron" : "🔴 Offline"
  el.style.color  = _fbOnline ? "#00ff88" : "#ff6688"
}

// ── Booking Data ──────────────────────────────────────────────
let bookings = JSON.parse(localStorage.getItem("ps_bookings")) || []

function saveBookings(){
  localStorage.setItem("ps_bookings", JSON.stringify(bookings))
  _updateBookingSidebarBadge()
}

// Push ke Firebase (tambah/update)
function _fbSetBooking(b){
  if(_fbDb && _fbOnline){
    _fbBookingRef.child(b.id).set(b)
  }
}
// Hapus dari Firebase
function _fbRemoveBooking(id){
  if(_fbDb && _fbOnline){
    _fbBookingRef.child(id).remove()
  }
}

function generateBookingId(){
  return "BK" + Date.now().toString(36).toUpperCase()
}

function _updateBookingSidebarBadge(){
  const badge = document.getElementById("bookingBadgeSidebar")
  if(!badge) return
  const now = new Date()
  const todayStr = now.toDateString()
  const count = bookings.filter(b => {
    if(b.status === "batal" || b.status === "selesai") return false
    const d = _parseJamMulai(b)
    return d.toDateString() === todayStr
  }).length
  if(count > 0){ badge.textContent = count; badge.style.display = "inline-flex" }
  else badge.style.display = "none"
}

function formatTanggalBooking(dateStr){
  const namaBulan = ["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agt","Sep","Okt","Nov","Des"]
  const namaHari  = ["Min","Sen","Sel","Rab","Kam","Jum","Sab"]
  const d = new Date(dateStr + "T00:00:00")
  return `${namaHari[d.getDay()]}, ${d.getDate()} ${namaBulan[d.getMonth()]} ${d.getFullYear()}`
}

// Helper: parse jamMulai dengan benar
// jamMulai bisa berupa "15:31" (lama) atau "2026-04-30T15:31" (dari Netlify)
function _parseJamMulai(b){
  if(!b || !b.jamMulai) return null
  // Jika sudah full datetime (dari Netlify)
  if(b.jamMulai.includes('T') && b.jamMulai.length > 10){
    return new Date(b.jamMulai)
  }
  // Format lama: "HH:MM" — gabung dengan tanggal
  return new Date((b.tanggal||'') + 'T' + b.jamMulai)
}

function _jamMulaiStr(b){
  // Ambil HH:MM saja dari jamMulai
  if(!b || !b.jamMulai) return '-'
  if(b.jamMulai.includes('T')) return b.jamMulai.split('T')[1]?.slice(0,5) || '-'
  return b.jamMulai.slice(0,5)
}

function getBookingStatus(b){
  if(b.status === "batal")    return "batal"
  if(b.status === "selesai")  return "selesai"
  if(b.status === "menunggu") return "menunggu"
  if(b.status === "upcoming") return "upcoming"
  if(b.status === "aktif")    return "aktif"
  if(b.status === "pending")  return "pending"  // ← dari Netlify, menunggu persetujuan
  return "pending"  // default unknown = pending, bukan selesai
}

// ── Halaman Booking ───────────────────────────────────────────
function renderBookingPage(){
  closeSidebar()

  // Auto-update status selesai
  let changed = false
  bookings.forEach(b => {
    if(b.status !== "batal" && b.status !== "selesai" && b.status !== "pending"){
      const s = getBookingStatus(b)
      if(s === "selesai"){ b.status = "selesai"; changed = true }
      else if(s === "aktif" && b.status !== "aktif"){ b.status = "aktif"; changed = true }
    }
  })
  if(changed){ saveBookings(); bookings.forEach(b => _fbSetBooking(b)) }

  const now      = new Date()
  const todayStr = now.toDateString()
  const sortOrder = { menunggu:0, upcoming:1, aktif:2, selesai:3, batal:4 }
  const sorted = [...bookings].sort((a,b) => {
    const sa = sortOrder[getBookingStatus(a)] ?? 9
    const sb = sortOrder[getBookingStatus(b)] ?? 9
    if(sa !== sb) return sa - sb
    // Dalam status yang sama: terbaru di atas
    return new Date(b.createdAt||0) - new Date(a.createdAt||0)
  })

  const todayAll    = sorted.filter(b => new Date(b.tanggal + "T00:00:00").toDateString() === todayStr)
  // Booking menunggu hari ini sudah masuk di menungguList global, pisahkan dari todayList biasa
  // FIX: exclude "pending" juga agar tidak double muncul di bawah (sudah ada di BARU MASUK)
  const todayList   = todayAll.filter(b => b.status !== "menunggu" && b.status !== "pending")
  const futureList  = sorted.filter(b => new Date(b.tanggal + "T00:00:00") > now && new Date(b.tanggal + "T00:00:00").toDateString() !== todayStr && b.status !== "batal")
  const pastList    = sorted.filter(b => (getBookingStatus(b) === "selesai" || b.status === "batal") && new Date(b.tanggal + "T00:00:00").toDateString() !== todayStr).slice(0,10)
  // Semua booking menunggu konfirmasi (hari ini maupun kemarin) — termasuk pending dari Netlify
  const menungguList = sorted.filter(b => b.status === "menunggu" || b.status === "pending")
  // Booking sudah disetujui (upcoming/aktif) dari hari sebelumnya — jangan hilang!
  const upcomingPastList = sorted.filter(b =>
    (b.status === "upcoming" || b.status === "aktif") &&
    new Date(b.tanggal + "T00:00:00").toDateString() !== todayStr
  )

  function bookingCard(b){
    const status = getBookingStatus(b)
    const statusCfg = {
      menunggu: { label:"🔔 MENUNGGU",   cls:"booking-status-upcoming" },
      upcoming: { label:"✅ DISETUJUI",  cls:"booking-status-aktif"    },
      aktif:    { label:"🟢 AKTIF",      cls:"booking-status-aktif"    },
      selesai:  { label:"☑️ SELESAI",    cls:"booking-status-selesai"  },
      batal:    { label:"❌ DIBATALKAN", cls:"booking-status-batal"    },
      pending:  { label:"🔔 MENUNGGU",   cls:"booking-status-upcoming" },
    }

    // Grace = 10 menit setelah JAM DATANG pelanggan
    // Timer hanya muncul SETELAH jam datang terlewati
    const GRACE_DETIK = 600
    const hasGrace = (status === "upcoming") && b.tanggal && b.jamMulai
    let graceDetik    = 0
    let beforeArrival = false
    let graceStartMs  = 0
    if(hasGrace){
      const jamDatang  = _parseJamMulai(b)
      const nowMs      = Date.now()
      // Grace SELALU dari jamMulai — operator bisa setujui kapan saja
      graceStartMs = jamDatang.getTime()
      const graceEnd = new Date(graceStartMs + 600000)
      if(nowMs < graceStartMs){
        beforeArrival = true
        graceDetik    = 0
      } else {
        graceDetik = Math.max(0, Math.floor((graceEnd - nowMs) / 1000))
      }
    }
    const sc = statusCfg[status] || statusCfg.menunggu
    const canCancel  = (status === "upcoming" || status === "aktif")
    const isMenunggu = (status === "menunggu")

    // Tombol "Pelanggan Datang" saat dalam grace period
    const nowMs      = Date.now()
    const _graceStart = graceStartMs || _parseJamMulai(b).getTime()
    const graceEndMs  = _graceStart + 600000
    const isUpcomingArrival = (status === "upcoming") && nowMs >= _graceStart && nowMs <= graceEndMs

    // Cek sesi aktif di TV ini untuk timer real-time
    const s = state[b.tv]
    const hasSession = s && s.mode && s.start
    const isTransaksi = s && s.mode === "processing"
    const timerDataAttr = hasSession
      ? `data-bk-tv="${b.tv}" data-bk-mode="${s.mode}" data-bk-start="${s.start}" data-bk-dur="${s.duration||0}"`
      : ""
    const modeLabelTxt = isTransaksi ? "⏳ TRANSAKSI"
      : hasSession ? (s.mode === "billing" ? "⏱ BILLING" : "⏳ COUNTDOWN")
      : ""

    // Status TERLAMBAT: grace habis dan booking masih upcoming
    const isTerlambat = (status === "upcoming") && !beforeArrival && graceDetik <= 0

    // Tentukan warna aksen kartu berdasarkan status
    const cardAccent = {
      menunggu: "255,204,0",
      upcoming: "0,255,136",
      aktif:    "0,245,255",
      selesai:  "0,245,255",
      batal:    "255,26,80"
    }[status] || "0,245,255"

    return `
    <div class="bk-premium-card bk-card-${status}">

      <!-- ── Top bar warna ── -->
      <div class="bk-top-bar" style="background:linear-gradient(90deg,transparent,rgba(${cardAccent},0.80),transparent);"></div>

      <!-- ── Header: TV + Session ── -->
      <div class="bk-header">
        <div class="bk-tv-label">TV ${b.tv}</div>
        ${hasSession ? `
          <div class="bk-session-row">
            <span class="bk-session-badge" style="color:${s.mode==='billing'?'#ff00d4':'#cc88ff'};border-color:${s.mode==='billing'?'rgba(255,0,212,0.35)':'rgba(119,0,255,0.40)'};">
              ${modeLabelTxt}
            </span>
            <span class="bk-session-timer" ${timerDataAttr}>–</span>
          </div>` : ""}
      </div>

      <!-- ── Nama pelanggan + Status ── -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">
        <div class="bk-nama" style="margin-bottom:0;">${escapeHTML(b.nama)}</div>
        <span class="bk-status-chip bk-chip-${status}">${sc.label}</span>
      </div>

      <!-- ── Grace period timer ── -->
      ${hasGrace && beforeArrival ? `
        <div class="bk-arrival-info">
          <span class="bk-arrival-icon">📍</span>
          <span class="bk-arrival-text">Pelanggan dijadwalkan datang jam <strong>${_jamMulaiStr(b)}</strong></span>
          <span class="bk-arrival-hint">Batas toleransi hingga ${(()=>{ const d=_parseJamMulai(b); d.setMinutes(d.getMinutes()+10); return d.getHours().toString().padStart(2,"0")+":"+d.getMinutes().toString().padStart(2,"0") })()}</span>
        </div>` : ""}
      ${hasGrace && !beforeArrival && graceDetik > 0 ? `
        <div class="bk-grace-block" id="graceTimer_${b.id}"
          data-jamdatang="${_parseJamMulai(b)?.toISOString()||''}"
          data-bid="${b.id}">
          <div class="bk-grace-left">
            <div class="bk-grace-label">⚠️ PELANGGAN BELUM DATANG</div>
            <div class="bk-grace-hint">Batal otomatis jika tidak datang</div>
          </div>
          <div class="bk-grace-count">${_formatDetik(graceDetik)}</div>
        </div>` : ""}
      ${hasGrace && !beforeArrival && graceDetik <= 0 ? `
        <div class="bk-grace-expired-block">⛔ MELEWATI BATAS — AUTO CANCEL</div>` : ""}

      ${isTerlambat ? `
        <div style="background:rgba(255,26,80,0.10);border:1px solid rgba(255,26,80,0.30);border-radius:10px;padding:8px 12px;margin-bottom:8px;font-family:'Orbitron',monospace;font-size:10px;font-weight:700;color:#ff4d6d;letter-spacing:1px;display:flex;align-items:center;gap:6px;">
          🔴 TERLAMBAT — BOOKING DIBATALKAN OTOMATIS
        </div>` : ""}

      ${isTransaksi ? `
        <div style="background:rgba(255,204,0,0.08);border:1px solid rgba(255,204,0,0.28);border-radius:10px;padding:8px 12px;margin-bottom:8px;font-family:'Orbitron',monospace;font-size:10px;font-weight:700;color:#ffcc00;letter-spacing:1px;display:flex;align-items:center;gap:6px;">
          ⏳ TV SEDANG DALAM PROSES TRANSAKSI
        </div>` : ""}

      <!-- ── Info grid ── -->
      <div class="bk-info-grid">
        <div class="bk-info-item">
          <div class="bk-info-label">📅 Tanggal</div>
          <div class="bk-info-val">${formatTanggalBooking(b.tanggal)}</div>
        </div>
        <div class="bk-info-item">
          <div class="bk-info-label">🕐 Jam Datang</div>
          <div class="bk-info-val bk-info-highlight">${b.jamMulai}</div>
        </div>
        ${b.noWA ? `
        <div class="bk-info-item">
          <div class="bk-info-label">📱 WhatsApp</div>
          <div class="bk-info-val">+${b.noWA}</div>
        </div>` : ""}
        <div class="bk-info-item">
          <div class="bk-info-label">🔖 Kode Booking</div>
          <div class="bk-info-val bk-info-code">${b.id}</div>
        </div>
      </div>

      ${b.catatan ? `
      <div class="bk-catatan-block">
        <span class="bk-catatan-icon">📝</span>
        <span>${escapeHTML(b.catatan)}</span>
      </div>` : ""}

      <!-- ── Action buttons ── -->
      <div class="bk-actions">
        ${isMenunggu ? `
          <button class="bk-btn bk-btn-setuju" onclick="_setujuiBooking('${b.id}')">✅ Setujui</button>
          <button class="bk-btn bk-btn-tolak"  onclick="_tolakBooking('${b.id}')">❌ Tolak</button>
        ` : isUpcomingArrival ? `
          <button class="bk-btn bk-btn-datang" onclick="_pelangganDatang('${b.id}')">🟢 Pelanggan Datang</button>
          <button class="bk-btn bk-btn-batal"  onclick="batalBooking('${b.id}')" style="flex:1;">❌</button>
        ` : canCancel ? `
          <button class="bk-btn bk-btn-batal" onclick="batalBooking('${b.id}')">❌ Batalkan</button>
        ` : ""}
        ${b.noWA ? `
          <button class="bk-btn" onclick="_hubungiPelanggan('${b.noWA}','${b.nama}')"
            style="background:rgba(37,211,102,0.10);border:1px solid rgba(37,211,102,0.30);color:#25d366;padding:8px 12px;border-radius:10px;font-size:13px;cursor:pointer;">
            💬
          </button>` : ""}
        <button class="bk-btn bk-btn-hapus" onclick="hapusBooking('${b.id}')">🗑</button>
      </div>

    </div>`
  }

  function sectionMenunggu(list){
    if(!list.length) return ""
    const dpNominalApp = parseInt(localStorage.getItem("dp_nominal") || "10000")
    const items = list.map(b => {
      // Cek apakah kena DP
      const jamBookingMs = _parseJamMulai(b)?.getTime() || 0
      const sess = state[b.tv] || {}
      const isCountdown = sess.mode === "countdown" && sess.start && sess.duration
      const refMs = isCountdown ? (sess.start + sess.duration * 1000) : Date.now()
      const berlakuDP = jamBookingMs > 0 && (jamBookingMs - refMs) / 60000 > 60

      // Format no WA untuk tampil
      const waDisplay = b.noWA ? "+" + b.noWA : null

      return `
      <div style="background:rgba(255,204,0,0.05);border:1px solid rgba(255,204,0,0.18);
        border-radius:16px;margin-bottom:10px;overflow:hidden;">

        <!-- Top: nama + tombol aksi -->
        <div style="display:flex;align-items:center;gap:10px;padding:12px 14px 10px;">
          <div style="width:38px;height:38px;border-radius:10px;background:rgba(255,204,0,0.12);
            border:1px solid rgba(255,204,0,0.30);display:flex;align-items:center;justify-content:center;
            font-size:16px;flex-shrink:0;">📺</div>
          <div style="flex:1;min-width:0;">
            <div style="font-weight:700;font-size:14px;color:#fff;
              white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${b.nama}</div>
            <div style="font-size:11px;color:rgba(168,200,240,0.55);margin-top:1px;">
              TV ${b.tv} · Jam Datang <strong style="color:#ffcc00;">${_jamMulaiStr(b)}</strong>
            </div>
          </div>
          <div style="display:flex;gap:6px;flex-shrink:0;">
            <button onclick="_setujuiBooking('${b.id}')"
              style="padding:8px 12px;border-radius:10px;font-size:13px;font-weight:700;cursor:pointer;
              background:rgba(0,255,136,0.12);border:1px solid rgba(0,255,136,0.35);color:#00ff88;">✅</button>
            <button onclick="_tolakBooking('${b.id}')"
              style="padding:8px 10px;border-radius:10px;font-size:13px;cursor:pointer;
              background:rgba(255,26,80,0.10);border:1px solid rgba(255,26,80,0.30);color:#ff4d6d;">❌</button>
            ${b.noWA ? `<button onclick="_hubungiPelanggan('${b.noWA}','${b.nama}')"
              style="padding:8px 10px;border-radius:10px;font-size:13px;cursor:pointer;
              background:rgba(37,211,102,0.10);border:1px solid rgba(37,211,102,0.30);color:#25d366;">💬</button>` : ""}
          </div>
        </div>

        <!-- Bottom: No WA + DP badge -->
        <div style="display:flex;align-items:center;justify-content:space-between;
          padding:8px 14px 4px;border-top:1px solid rgba(255,204,0,0.08);gap:8px;">
          ${waDisplay ? `
          <div style="display:flex;align-items:center;gap:6px;font-size:11px;color:rgba(168,200,240,0.55);">
            <span style="font-size:13px;">📱</span>
            <span style="font-family:monospace;letter-spacing:0.5px;">${waDisplay}</span>
          </div>` : `<div></div>`}
          ${berlakuDP ? `
          <div style="display:flex;align-items:center;gap:5px;
            padding:4px 10px;border-radius:20px;
            background:rgba(255,204,0,0.12);border:1px solid rgba(255,204,0,0.30);">
            <span style="font-size:11px;">💰</span>
            <span style="font-family:'Orbitron',monospace;font-size:8px;font-weight:700;
              color:#ffcc00;letter-spacing:0.5px;">WAJIB DP Rp ${dpNominalApp.toLocaleString('id-ID')}</span>
          </div>` : `
          <div style="display:flex;align-items:center;gap:5px;
            padding:4px 10px;border-radius:20px;
            background:rgba(0,255,136,0.06);border:1px solid rgba(0,255,136,0.18);">
            <span style="font-family:'Orbitron',monospace;font-size:8px;font-weight:700;
              color:rgba(0,255,136,0.60);letter-spacing:0.5px;">✓ TANPA DP</span>
          </div>`}
        </div>
        ${b.catatan ? `
        <div style="display:flex;align-items:flex-start;gap:8px;padding:6px 14px 10px;">
          <span style="font-size:12px;flex-shrink:0;opacity:.70;">📝</span>
          <span style="font-size:12px;color:rgba(168,200,240,0.65);line-height:1.5;font-style:italic;">${escapeHTML(b.catatan)}</span>
        </div>` : ""}

      </div>`
    }).join("")
    return `
      <div style="margin-bottom:12px;">
        <div style="font-family:'Orbitron',monospace;font-size:9px;letter-spacing:2px;
          color:rgba(255,204,0,0.60);margin-bottom:10px;display:flex;align-items:center;gap:8px;">
          <span>🔔 BARU MASUK</span>
          <span style="background:rgba(255,204,0,0.15);color:#ffcc00;border-radius:6px;
            padding:2px 7px;font-size:10px;">${list.length}</span>
        </div>
        ${items}
      </div>`
  }

  function section(judul, list){
    if(!list.length) return ""
    return `<div class="booking-section-title">${judul}</div>
    <div class="booking-cards-grid">${list.map(bookingCard).join("")}</div>`
  }

  const emptyHtml = (!todayList.length && !futureList.length && !pastList.length && !menungguList.length && !upcomingPastList.length)
    ? `<div class="booking-empty">
        <div style="font-size:44px;margin-bottom:14px;opacity:0.45;">📋</div>
        <div style="font-family:'Orbitron',monospace;font-size:10px;letter-spacing:2.5px;color:rgba(0,245,255,0.35);margin-bottom:8px;">BELUM ADA BOOKING</div>
        <div style="font-size:12px;color:rgba(168,200,240,0.40);">Booking dari pelanggan akan muncul di sini</div>
      </div>` : ""

  const html = `
  <div class="booking-page" id="bookingPageContainer">
    <!-- Sync status -->
    <div style="text-align:right;font-size:10px;margin-bottom:8px;font-family:'Orbitron',monospace;letter-spacing:1px;">
      <span id="fbSyncStatus">${_fbOnline ? "🟢 Sinkron" : "🔴 Offline"}</span>
    </div>

    <!-- Stats -->
    <div class="booking-stats-bar">
      ${[["menunggu","Menunggu"],["aktif","Aktif"],["selesai","Selesai"],["batal","Dibatalkan"]].map(([s,label]) => {
        const count = bookings.filter(b => getBookingStatus(b) === s).length
        return `<div class="booking-stat-item">
          <div class="booking-stat-num booking-stat-${s==="menunggu"?"upcoming":s}">${count}</div>
          <div class="booking-stat-lbl">${label}</div>
        </div>`
      }).join("")}
    </div>

    ${emptyHtml}
    ${sectionMenunggu(menungguList)}
    ${section("⏳ Disetujui — Menunggu Kedatangan", upcomingPastList)}
    ${section("📅 Hari Ini", todayList)}
    ${section("🔜 Mendatang", futureList)}
    ${section("📁 Riwayat", pastList)}

    <button class="booking-fab" onclick="openTambahBooking()">
      <span style="font-size:22px;line-height:1;">＋</span>
      <span style="font-family:'Orbitron',monospace;font-size:10px;letter-spacing:1.5px;">BOOKING</span>
    </button>
  </div>`

  showInternalPage("📅 BOOKING TV", "Reservasi real-time · " + (_fbOnline ? "🟢 Terhubung" : "🔴 Offline"), html)

  // ── Real-time timer untuk booking card aktif + grace period countdown ──
  if(window._bkTimerInterval) clearInterval(window._bkTimerInterval)
  window._bkTimerInterval = setInterval(() => {
    const now = Date.now()

    // Update timer sesi aktif (billing/countdown)
    document.querySelectorAll(".bk-session-timer[data-bk-mode]").forEach(el => {
      const mode  = el.dataset.bkMode
      const start = parseInt(el.dataset.bkStart || "0")
      const dur   = parseInt(el.dataset.bkDur   || "0")
      let txt = "–", color = "#00ff88"
      if(mode === "countdown"){
        const sisa = Math.max(0, dur - Math.floor((now-start)/1000))
        txt   = sisa <= 0 ? "⏰ HABIS" : _formatDetik(sisa)
        color = sisa <= 0 ? "#ff1a50" : sisa <= 300 ? "#ffcc00" : "#00ff88"
      } else if(mode === "billing"){
        txt   = _formatDetik(Math.floor((now-start)/1000))
        color = "#ff00d4"
      }
      el.textContent = txt
      el.style.color  = color
    })

    // Grace period: selalu dari jamMulai (approvedAt hanya untuk pencatatan)
    document.querySelectorAll(".bk-grace-block[data-jamdatang]").forEach(el => {
      const bid       = el.dataset.bid || ""
      const jamDatang = new Date(el.dataset.jamdatang)
      const graceStart = jamDatang.getTime()  // Grace selalu dari jamMulai
      const graceEnd  = new Date(graceStart + 600000)
      // Jika belum waktu grace mulai, jangan hitung
      if(now < graceStart) return
      const sisa = Math.max(0, Math.floor((graceEnd - now) / 1000))
      const countEl  = el.querySelector(".bk-grace-count") || el
      if(countEl) countEl.textContent = _formatDetik(sisa)

      // Warna berubah sesuai sisa waktu
      const urgency = sisa <= 60 ? "#ff1a50" : sisa <= 180 ? "#ffcc00" : "#00ff88"
      if(countEl) countEl.style.color = urgency
      el.style.borderColor = urgency + "44"

      // Auto cancel saat grace period habis (jam datang + 10 menit)
      if(sisa <= 0 && bid){
        const b2 = bookings.find(x => x.id === bid)
        if(b2 && b2.status === "upcoming"){
          b2.status = "batal"
          saveBookings()
          _fbSetBooking(b2)
          // Kirim WA otomatis ke pelanggan
          if(b2.noWA){
            const titleTop = localStorage.getItem("ps_title_top") || "ASTROPHILE"
            const pesan = encodeURIComponent(
              "❌ *BOOKING OTOMATIS DIBATALKAN*\n\n" +
              "Halo " + b2.nama + ", booking TV " + b2.tv + " jam " + b2.jamMulai +
              " dibatalkan karena tidak datang dalam 10 menit setelah disetujui.\n\n" +
              "🔖 Kode: " + b2.id + "\n" +
              "_— " + titleTop + (_getOperatorWA() ? "\n📱 Hubungi: +"+_getOperatorWA() : "") + "_"
            )
            _kirimWA(b2.noWA, decodeURIComponent(pesan))
          }
          // Re-render halaman booking
          setTimeout(renderBookingPage, 1500)
          _showBookingToast("⏰ Booking " + b2.nama + " (TV " + b2.tv + ") otomatis dibatalkan — terlambat 10 menit")
        }
      }
    })

    // Stop interval jika halaman booking sudah ditutup
    if(!document.getElementById("bookingPageContainer")){
      clearInterval(window._bkTimerInterval)
      window._bkTimerInterval = null
    }
  }, 1000)
}

// ── Modal Tambah Booking ──────────────────────────────────────
function openTambahBooking(){
  const now  = new Date()
  const ymd  = now.toISOString().split("T")[0]
  const hhmm = now.getHours().toString().padStart(2,"0") + ":" + now.getMinutes().toString().padStart(2,"0")
  const tvOptions = Array.from({length: units}, (_,i) => {
    const s2 = state[i+1]
    const now3 = Date.now()
    let label = `TV ${i+1}`
    let disabled = false

    if(s2 && s2.mode && s2.start){
      if(s2.mode === "billing"){
        // Billing: tidak bisa dibooking
        label = `TV ${i+1} ⛔ LOST TIME`
        disabled = true
      } else if(s2.mode === "countdown"){
        // Countdown: bisa dibooking, tapi setelah countdown selesai
        const sisa = Math.max(0, s2.duration - Math.floor((now3-s2.start)/1000))
        const endMs = s2.start + s2.duration*1000
        const endD  = new Date(endMs)
        const endStr = endD.getHours().toString().padStart(2,"0")+":"+endD.getMinutes().toString().padStart(2,"0")
        label = sisa <= 0
          ? `TV ${i+1} ✅ Siap`
          : `TV ${i+1} ⏳ Bebas jam ${endStr}`
        disabled = false
      }
    }
    return `<option value="${i+1}" ${disabled?"disabled style='color:#ff6688;'":""}>${label}</option>`
  }).join("")
  const durasiOptions = [30,60,90,120,150,180,240,300,360,480]
    .map(m => `<option value="${m}" ${m===60?"selected":""}>${m>=60?Math.floor(m/60)+"j"+(m%60?m%60+"m":""):m+"m"}</option>`).join("")

  const modalHtml = `
  <div id="bookingModalOverlay" onclick="closeBookingModal(event)" style="
    position:fixed;inset:0;z-index:9000;display:flex;align-items:center;justify-content:center;
    background:rgba(3,5,12,0.88);backdrop-filter:blur(6px);padding:16px;">
    <div class="booking-modal-box" onclick="event.stopPropagation()">
      <div class="booking-modal-header">
        <div style="font-family:'Orbitron',monospace;font-size:13px;font-weight:700;letter-spacing:2px;color:var(--primary);">📅 TAMBAH BOOKING</div>
        <button onclick="document.getElementById('bookingModalOverlay').remove()" style="background:none;border:none;color:var(--text-muted);font-size:20px;padding:0;width:30px;height:30px;display:flex;align-items:center;justify-content:center;cursor:pointer;">✕</button>
      </div>
      <div class="booking-modal-body">
        <label class="booking-form-label">👤 NAMA PELANGGAN</label>
        <input id="bk_nama" type="text" placeholder="Nama pelanggan..." autocomplete="off" style="margin-bottom:14px;">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
          <div><label class="booking-form-label">📺 UNIT TV</label><select id="bk_tv" style="width:100%;">${tvOptions}</select></div>
          <div><label class="booking-form-label">⏱ DURASI</label><select id="bk_durasi" style="width:100%;">${durasiOptions}</select></div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
          <div><label class="booking-form-label">📅 TANGGAL</label><input id="bk_tanggal" type="date" value="${ymd}" style="width:100%;box-sizing:border-box;"></div>
          <div><label class="booking-form-label">🕐 JAM MULAI</label><input id="bk_jam" type="time" value="${hhmm}" style="width:100%;box-sizing:border-box;"></div>
        </div>
        <label class="booking-form-label">📝 CATATAN (Opsional)</label>
        <input id="bk_catatan" type="text" placeholder="e.g. main FIFA, bawa teman..." style="margin-bottom:20px;">
        <div id="bk_error" style="display:none;color:var(--red-danger);font-size:11px;text-align:center;margin-bottom:10px;padding:8px;background:rgba(255,26,80,0.08);border-radius:var(--radius-sm);border:1px solid rgba(255,26,80,0.20);"></div>
        <button onclick="simpanBooking()" style="width:100%;background:linear-gradient(135deg,rgba(0,245,255,0.16),rgba(119,0,255,0.12));border-color:rgba(0,245,255,0.35);color:var(--primary);font-family:'Orbitron',monospace;font-size:11px;letter-spacing:2px;font-weight:700;padding:14px;">
          💾 SIMPAN BOOKING
        </button>
      </div>
    </div>
  </div>`
  document.body.insertAdjacentHTML("beforeend", modalHtml)
  setTimeout(() => { const el=document.getElementById("bk_nama"); if(el) el.focus() }, 100)
}

function closeBookingModal(e){
  if(e && e.target && e.target.id !== "bookingModalOverlay") return
  const el = document.getElementById("bookingModalOverlay")
  if(el) el.remove()
}

function simpanBooking(){
  const nama    = (document.getElementById("bk_nama")?.value||"").trim()
  const tv      = parseInt(document.getElementById("bk_tv")?.value||"1")
  const tanggal = document.getElementById("bk_tanggal")?.value||""
  const jam     = document.getElementById("bk_jam")?.value||""
  const durasi  = parseInt(document.getElementById("bk_durasi")?.value||"60")
  const catatan = (document.getElementById("bk_catatan")?.value||"").trim()
  const errEl   = document.getElementById("bk_error")

  function showErr(msg){ if(errEl){ errEl.textContent="⚠️ "+msg; errEl.style.display="block" } }
  if(!nama){ showErr("Nama pelanggan wajib diisi."); return }
  if(!tanggal){ showErr("Tanggal wajib dipilih."); return }
  if(!jam){ showErr("Jam mulai wajib diisi."); return }

  const mulaiBaru   = new Date(tanggal + "T" + jam)
  const selesaiBaru = new Date(mulaiBaru.getTime() + durasi * 60000)
  // Cek jika TV sedang billing (lost time) — tidak bisa dibooking
  const _s = state[tv]
  if(_s && _s.mode === "billing" && _s.start){
    function showErr2(msg){ if(errEl){ errEl.textContent="⚠️ "+msg; errEl.style.display="block" } }
    showErr2("TV " + tv + " sedang bermain mode Billing (Lost Time). Tidak bisa dibooking.")
    return
  }

  // Cek jika booking overlap dengan countdown aktif
  if(_s && _s.mode === "countdown" && _s.start && !_s.expired){
    const countdownEnd = new Date(_s.start + _s.duration*1000)
    if(mulaiBaru < countdownEnd){
      const eH = countdownEnd.getHours().toString().padStart(2,"0")
      const eM = countdownEnd.getMinutes().toString().padStart(2,"0")
      function showErr3(msg){ if(errEl){ errEl.textContent="⚠️ "+msg; errEl.style.display="block" } }
      showErr3("Pilih jam setelah sesi countdown selesai (sesudah " + eH + ":" + eM + ")")
      return
    }
  }

  const konflik = bookings.find(b => {
    if(b.status === "batal" || b.status === "selesai") return false
    if(b.tv !== tv) return false
    const m = _parseJamMulai(b)
    const s = new Date(m.getTime() + b.durasi * 60000)
    return mulaiBaru < s && selesaiBaru > m
  })
  if(konflik){ showErr(`TV ${tv} sudah dibooking atas nama "${konflik.nama}" di waktu tersebut.`); return }

  const newBooking = { id:generateBookingId(), nama, tv, tanggal, jamMulai:jam, durasi, catatan, status:"upcoming", createdAt:new Date().toISOString() }
  bookings.unshift(newBooking)
  saveBookings()
  _fbSetBooking(newBooking)  // sync ke Firebase
  addOperatorLog(_getCurrentRole(), "tambah_booking", `TV ${tv} · ${nama} · ${formatTanggalBooking(tanggal)} ${jam} · ${durasi}m`)

  document.getElementById("bookingModalOverlay")?.remove()
  renderBookingPage()
  _showBookingToast(`✅ Booking TV ${tv} atas nama "${nama}" berhasil disimpan!`)
}

function batalBooking(id){
  const b = bookings.find(x => x.id === id)
  if(!b) return
  _showConfirm(`Batalkan booking TV ${b.tv}?\nPesan WA akan dikirim ke pelanggan.`, () => {
  b.status = "batal"
  saveBookings()
  _fbSetBooking(b)
  addOperatorLog(_getCurrentRole(), 'batal_booking', `TV ${b.tv} · ${b.nama}`)
  if(_fbDb){
    _fbDb.ref("settings/activeSessions/" + b.tv).once("value", snap => {
      const sess = snap.val() || {}
      if(sess.mode === "reserved" || sess.mode === "processing"){
        _fbDb.ref("settings/activeSessions/" + b.tv).set({ active: false })
        // Update state lokal juga
        if(state[b.tv]) state[b.tv] = { ...state[b.tv], active: false, mode: null, start: null }
        localStorage.setItem("ps_state", JSON.stringify(state))
      }
    })
  }

  addOperatorLog(_getCurrentRole(), "batal_booking", `TV ${b.tv} · ${b.nama}`)

  // Kirim WA ke pelanggan jika ada noWA
  if(b.noWA){
    const titleTop = localStorage.getItem("booking_site_wa_nama") || localStorage.getItem("ps_title_top") || "ASTROPHILE"
    const jamStrB = b.jamMulai?.includes("T") ? b.jamMulai.split("T")[1]?.slice(0,5) : (b.jamMulai || "")
    const pesanBatal = _isiTemplate(_getWATemplate("batal"), {
      nama: b.nama, tv: b.tv, jam: jamStrB,
      tanggal: b.tanggal, kode: b.id, toko: titleTop, wa: _getOperatorWA()
    })
    _kirimWA(b.noWA, pesanBatal)
  }

  renderBookingPage()
  _showBookingToast("❌ Booking dibatalkan! WA otomatis dikirim.")
  })
}

function hapusBooking(id){
  const b = bookings.find(x => x.id === id)
  if(!b) return
  _showConfirm(`Hapus booking TV ${b.tv} atas nama "${b.nama}"?\nData akan dihapus permanen.`, () => {
  const idx = bookings.findIndex(x => x.id === id)
  if(idx === -1) return
  bookings.splice(idx, 1)
  saveBookings()
  _fbRemoveBooking(id)
  renderBookingPage()
  _showBookingToast("🗑️ Booking dihapus.")
  })
}

function _showBookingToast(msg){
  // Reuse existing toast function
  if(typeof _showHutangToast === "function"){ _showHutangToast(msg); return }
  const el = document.createElement("div")
  el.className = "booking-toast"
  el.textContent = msg
  document.body.appendChild(el)
  setTimeout(() => el.classList.add("booking-toast-show"), 10)
  setTimeout(() => { el.classList.remove("booking-toast-show"); setTimeout(()=>el.remove(),400) }, 3000)
}

// ── Init Firebase saat app load ───────────────────────────────
// Dipanggil SEGERA agar _fbDb siap sebelum login screen
;(function(){
  try{ _initFirebase() }catch(e){ console.warn('Firebase early init:', e) }
})()

window.addEventListener("load", function(){
  // Retry bertahap: 800ms, 2s, 5s — pastikan Firebase SDK sudah load
  function _fbRetry(attempt){
    if(_fbDb) { _updateBookingSidebarBadge(); return }
    try{ _initFirebase() }catch(e){}
    if(_fbDb) { _updateBookingSidebarBadge(); return }
    if(attempt < 3) setTimeout(() => _fbRetry(attempt + 1), attempt === 1 ? 1200 : 3000)
  }
  setTimeout(() => _fbRetry(1), 800)
})

