// ============================================================
// NOTIFIKASI BOOKING BARU DARI PELANGGAN + HAPUS
// ============================================================
function _tampilkanNotifBookingBaru(b){
  const mulai = _parseJamMulai(b)
  const tgl   = mulai.toLocaleDateString("id-ID", {day:"numeric", month:"short"})
  const noWA  = b.noWA || ""

  // Kirim notifikasi Android (muncul di status bar HP)
  try {
    const notifTitle = "📅 Booking Baru Masuk!"
    const notifMsg   = "TV " + b.tv + " · " + b.nama + " · Datang jam " + b.jamMulai
    if(typeof Android !== "undefined" && Android.showBookingNotification){
      Android.showBookingNotification(notifTitle, notifMsg)
    }
  } catch(e) {}

  document.getElementById("notifBooking_" + b.id)?.remove()

  const el = document.createElement("div")
  el.id = "notifBooking_" + b.id
  el.className = "notif-booking-baru"
  el.innerHTML = `
    <div class="nbb-glow"></div>
    <div class="nbb-bar-wrap"><div class="nbb-bar" id="nbbBar_${b.id}"></div></div>
    <div class="nbb-body">
      <div class="nbb-icon">📅</div>
      <div class="nbb-content">
        <div class="nbb-title">BOOKING BARU MASUK!</div>
        <div class="nbb-detail">
          <strong>TV ${b.tv}</strong> · ${b.nama}<br>
          ${tgl} · Datang jam ${b.jamMulai}
          ${noWA ? `<br>📱 +${noWA}` : ""}
        </div>
      </div>
      <div class="nbb-actions">
        <button class="nbb-btn-terima" onclick="_bukaHalamanBooking()" title="Lihat Booking">📋</button>
        <button class="nbb-btn-close2" onclick="_tutupNotifBooking('${b.id}')" title="Tutup">✕</button>
      </div>
    </div>
  `
  document.body.appendChild(el)
  setTimeout(() => el.classList.add("nbb-show"), 10)

  // Progress bar auto-dismiss 12 detik
  const bar = document.getElementById("nbbBar_" + b.id)
  if(bar){
    bar.style.transition = "none"
    bar.style.width = "100%"
    setTimeout(() => {
      bar.style.transition = "width 12s linear"
      bar.style.width = "0%"
    }, 50)
  }

  const timer = setTimeout(() => {
    el.classList.remove("nbb-show")
    setTimeout(() => el.remove(), 400)
  }, 12000)
  el._t = timer

  if(navigator.vibrate) navigator.vibrate([150, 80, 150, 80, 150])
}

function _pelangganDatang(id){
  const b = bookings.find(x => x.id === id)
  if(!b) return
  _showConfirm(`Konfirmasi "${b.nama}" sudah datang?\nStatus TV ${b.tv} akan jadi AKTIF.`, () => {

  b.status = "aktif"
  b.arrivedAt = Date.now()
  saveBookings()
  _fbSetBooking(b)
  // Tandai TV sebagai "reserved" di Firebase agar Netlify tidak tampilkan TERSEDIA
  if(_fbDb){
    _fbDb.ref("settings/activeSessions/" + b.tv).set({
      active: true,
      mode: "reserved",
      reservedFor: b.nama,
      bookingId: b.id
    })
  }
  addOperatorLog(_getCurrentRole(), "konfirmasi_datang", `TV ${b.tv} · ${b.nama}`)
  renderBookingPage()
  _showBookingToast("🟢 Pelanggan " + b.nama + " dikonfirmasi datang!")
  })
}

function _tutupNotifBooking(id){
  const el = document.getElementById("notifBooking_" + id)
  if(el){ clearTimeout(el._t); el.classList.remove("nbb-show"); setTimeout(()=>el.remove(),300) }
}

function _bukaHalamanBooking(){
  // Tutup semua notif booking
  document.querySelectorAll("[id^='notifBooking_']").forEach(el => {
    el.classList.remove("nbb-show")
    setTimeout(() => el.remove(), 300)
  })
  renderBookingPage()
}

function _setujuiBooking(id){
  const b = bookings.find(x => x.id === id)
  if(!b) return

  // Cek konflik dengan booking upcoming lain di TV yang sama
  const jamB = _parseJamMulai(b)
  const jamBEnd = new Date((jamB?.getTime()||0) + (b.durasi||120)*60000)
  const konflik = bookings.find(x =>
    x.id !== id &&
    x.tv === b.tv &&
    (x.status === 'upcoming' || x.status === 'aktif') &&
    x.tanggal === b.tanggal
  )
  if(konflik){
    const jamK = _parseJamMulai(konflik)
    const jamKEnd = new Date((jamK?.getTime()||0) + (konflik.durasi||120)*60000)
    if(jamB < jamKEnd && jamBEnd > jamK){
      _showConfirm(
        `⚠️ Konflik Booking!\n\nTV ${b.tv} sudah ada booking atas nama "${konflik.nama}" jam ${_jamMulaiStr(konflik)}.\n\nSetujui tetap?`,
        () => _doSetujui(b)
      )
      return
    }
  }

  _doSetujui(b)
}

