function _getWATemplate(type){
  const saved = localStorage.getItem("wa_template_"+type)
  return saved || _WA_DEFAULT[type] || ""
}

function _saveWATemplate(type, text){
  localStorage.setItem("wa_template_"+type, text)
  if(_fbDb) _fbDb.ref("settings/waTemplate/"+type).set(text)
}

function _loadWATemplatesFromFirebase(){
  if(!_fbDb) return
  ;["setujui","tolak","batal"].forEach(type => {
    _fbDb.ref("settings/waTemplate/"+type).once("value", snap => {
      if(snap.val()) localStorage.setItem("wa_template_"+type, snap.val())
    })
  })
}

function _isiTemplate(template, data){
  // Ganti semua placeholder dengan nilai nyata
  return template
    .replace(/{nama}/g,    data.nama    || "")
    .replace(/{tv}/g,      data.tv      || "")
    .replace(/{jam}/g,     data.jam     || "")
    .replace(/{tanggal}/g, data.tanggal || "")
    .replace(/{kode}/g,    data.kode    || "")
    .replace(/{toko}/g,    data.toko    || "ASTROPHILE")
    .replace(/{wa}/g,      data.wa      ? "\n📱 Hubungi: +" + data.wa : "")
}
// ============================================================

function _doSetujui(b){
  _tutupNotifBooking(b.id)

  // Update status + simpan waktu persetujuan (untuk log saja — grace tetap dari jamMulai)
  b.status     = "upcoming"
  b.approvedAt = Date.now()  // Hanya untuk pencatatan, grace dihitung dari jamMulai
  saveBookings()
  _fbSetBooking(b)
  addOperatorLog(_getCurrentRole(), 'setujui_booking', `TV ${b.tv} · ${b.nama} · ${b.jamMulai}`)

  // Kirim WA ke pelanggan (pakai template yang bisa diedit)
  if(b.noWA){
    const titleTop = localStorage.getItem("booking_site_wa_nama") || localStorage.getItem("ps_title_top") || "ASTROPHILE"
    const mulai = _parseJamMulai(b)
    const tgl   = mulai ? mulai.toLocaleDateString("id-ID", {weekday:"long",day:"numeric",month:"long"}) : (b.tanggal || "")
    const jamStr = b.jamMulai?.includes("T") ? b.jamMulai.split("T")[1]?.slice(0,5) : (b.jamMulai || "")
    const pesanLengkap = _isiTemplate(_getWATemplate("setujui"), {
      nama: b.nama, tv: b.tv, jam: jamStr,
      tanggal: tgl, kode: b.id, toko: titleTop, wa: _getOperatorWA()
    })
    _kirimWA(b.noWA, pesanLengkap)
  }

  renderBookingPage()
  _showBookingToast("✅ Booking disetujui! WA otomatis dikirim.")
}

function _hubungiPelanggan(noWA, nama){
  const nomor = noWA.toString().replace(/[^0-9]/g,"")
  const n = nomor.startsWith("62") ? nomor : nomor.startsWith("0") ? "62"+nomor.slice(1) : "62"+nomor
  Android.openUrl("https://wa.me/"+n)
}

function _tolakBooking(id){
  const b = bookings.find(x => x.id === id)
  if(!b) return
  _showConfirm(`Tolak booking TV ${b.tv} atas nama "${b.nama}"?`, () => {
  _tutupNotifBooking(id)

  b.status = "batal"
  saveBookings()
  _fbSetBooking(b)
  addOperatorLog(_getCurrentRole(), 'tolak_booking', `TV ${b.tv} · ${b.nama} · ${b.jamMulai}`)
  if(b.noWA){
    const titleTop = localStorage.getItem("booking_site_wa_nama") || localStorage.getItem("ps_title_top") || "ASTROPHILE"
    const jamStrT = b.jamMulai?.includes("T") ? b.jamMulai.split("T")[1]?.slice(0,5) : (b.jamMulai || "")
    const pesanTolak = _isiTemplate(_getWATemplate("tolak"), {
      nama: b.nama, tv: b.tv, jam: jamStrT,
      tanggal: b.tanggal, kode: b.id, toko: titleTop, wa: _getOperatorWA()
    })
    _kirimWA(b.noWA, pesanTolak)
  }

  renderBookingPage()
  _showBookingToast("❌ Booking ditolak! WA otomatis dikirim.")
  })
}

function _hapus_booking_notif(id){
  _tutupNotifBooking(id)
  hapusBookingById(id)
}

function hapusBookingById(id){
  const idx = bookings.findIndex(x => x.id === id)
  if(idx !== -1) bookings.splice(idx, 1)
  saveBookings()
  _fbRemoveBooking(id)
  if(document.getElementById("bookingPageContainer")) renderBookingPage()
}

// ============================================================
// SYNC SESI AKTIF TV KE FIREBASE (untuk halaman pelanggan)
// ============================================================
function _syncTVInfoToFirebase(){
  if(!_fbDb) return
  const info = {}
  for(let i = 1; i <= units; i++){
    const t = state[i]?.type || (prices[0]?.nama || "PS3")
    const p = getConsolePriceByType(t) || 0
    info[i] = { type: t, price: p }
  }
  _fbDb.ref("settings/tvInfo").set(info)
}

function _syncActiveSessionsToFirebase(){
  try{
  if(!_fbDb) return

  // Baca dulu state "reserved" yang sudah ada di Firebase
  // supaya tidak tertimpa saat sync rutin
  _fbDb.ref("settings/activeSessions").once("value", snap => {
    const existing = snap.val() || {}
    const sessions = {}

    for(let i = 1; i <= units; i++){
      const s = state[i]
      if(s && s.mode && s.start){
        // TV sedang aktif billing/countdown
        sessions[i] = {
          active:        true,
          mode:          s.mode,
          start:         s.start,
          duration:      s.duration||0,
          expired:       !!s.expired,
          type:          s.type || "",
          price:         s.price || 0,
          namaPelanggan: s.namaPelanggan || _loadNamaPelanggan(i) || "",
          _bonusDetik:   s._bonusDetik || 0
        }
      } else if(existing[i] && existing[i].mode === "reserved"){
        // Pertahankan status "reserved" — jangan timpa sampai Start diklik
        sessions[i] = existing[i]
      } else {
        // "processing" tidak dipertahankan — akan di-clear setelah transaksi selesai
        sessions[i] = { active: false }
      }
    }
    _fbDb.ref("settings/activeSessions").set(sessions)
  })
  } catch(e){ console.warn("Sync Firebase error:", e) }
}

function _formatDetik(s){
  if(s < 0) s = 0
  const h = Math.floor(s/3600).toString().padStart(2,"0")
  const m = Math.floor((s%3600)/60).toString().padStart(2,"0")
  const sec = (s%60).toString().padStart(2,"0")
  return h+":"+m+":"+sec
}

// Sync saat START/STOP dan interval 30 detik sebagai backup
setInterval(() => { if(!pendingTransaction) _syncActiveSessionsToFirebase() }, 30000)

// Sync setiap kali sesi mulai/berhenti — hook ke saveNow
const _origSaveNow = saveNow
window.saveNow = function(){
  _origSaveNow()        // simpan localStorage dulu — WAJIB berhasil
  // Skip Firebase sync jika sedang dalam proses transaksi
  // (akan di-sync manual setelah transaksi selesai/dibatalkan)
  if(pendingTransaction) return
  try { _syncActiveSessionsToFirebase() } catch(e) { console.warn("Firebase sync error:", e) }
}

