// ── State ──
let tournSlots = JSON.parse(localStorage.getItem("ps_tourn_slots") || "[]")
let tournPendaftar = JSON.parse(localStorage.getItem("ps_tourn_pendaftar") || "[]")

function saveTournSlots(){
  localStorage.setItem("ps_tourn_slots", JSON.stringify(tournSlots))
  // Sync ke Firebase
  if(_fbDb) _fbDb.ref("tournamentSlots").set(
    tournSlots.map(s=>({...s, pendaftar: tournPendaftar.filter(p=>p.slotId===s.id)}))
  )
}
function saveTournPendaftar(){
  localStorage.setItem("ps_tourn_pendaftar", JSON.stringify(tournPendaftar))
  // Sync ke Firebase — gabungkan slots + pendaftar
  if(_fbDb) _fbDb.ref("tournamentSlots").set(
    tournSlots.map(s=>({...s, pendaftar: tournPendaftar.filter(p=>p.slotId===s.id)}))
  )
}

// ── Sync dari Firebase ke lokal (real-time listener) ──
function _initTournFirebaseListener(){
  if(!_fbDb) return
  _fbDb.ref("tournamentSlots").on("value", snap => {
    const data = snap.val()
    if(!Array.isArray(data)) return

    // Merge: ambil slots dari Firebase, ekstrak pendaftar ke tournPendaftar
    const newSlots = []
    const newPendaftar = []
    data.forEach(s => {
      if(!s || !s.id) return
      const { pendaftar, ...slotData } = s
      newSlots.push(slotData)
      if(Array.isArray(pendaftar)){
        pendaftar.forEach(p => { if(p && p.id) newPendaftar.push(p) })
      }
    })

    // Update lokal hanya jika ada perubahan dari luar (pendaftar online baru)
    const localPIds = new Set(tournPendaftar.map(p=>p.id))
    const newOnline = newPendaftar.filter(p => !localPIds.has(p.id))

    if(newOnline.length > 0){
      tournPendaftar = [...tournPendaftar, ...newOnline]
      localStorage.setItem("ps_tourn_pendaftar", JSON.stringify(tournPendaftar))
      // Notif jika ada pendaftar baru
      newOnline.forEach(p => {
        const s = newSlots.find(x=>x.id===p.slotId)
        showPopup({ typeNotif:"success",
          message:"🏆 Pendaftar turnamen baru!\n" + p.nama + " daftar ke " + (s?.nama||p.slotId) })
        try{ Android.showBookingNotification("🏆 Pendaftar Turnamen!", p.nama + " daftar ke " + (s?.nama||"Turnamen")) }catch(e){}
      })
      // Re-render halaman jika sedang terbuka
      // Auto-refresh halaman yang sedang terbuka
      const pv = document.getElementById("pageView")
      if(pv && pv.style.display !== "none"){
        if(pv.dataset.page && pv.dataset.page.includes("BOOKING SLOT")) renderTournSlotPage()
        if(pv.dataset.page && pv.dataset.page.includes("PESERTA")) {
          // Refresh peserta page - cari slotId dari subtitle
          const sub = document.getElementById("pageViewSubtitle")
          if(sub){
            const match = sub.textContent.match(/\d+\/\d+/)
            // Re-render peserta yang sedang dibuka
            const activePesertaSlot = window._activePesertaSlotId
            if(activePesertaSlot) renderTournPesertaPage(activePesertaSlot)
          }
        }
      }
    }

    // Sync slots juga
    tournSlots = newSlots
    localStorage.setItem("ps_tourn_slots", JSON.stringify(tournSlots))
  })
}

// ── Helper ──
function _getTournSlot(id){ return tournSlots.find(s=>s.id===id) }
function _getTournPendaftar(slotId){ return tournPendaftar.filter(p=>p.slotId===slotId) }
