function _submitGantiPinOwner(){
  const oldPin  = document.getElementById('_po_old')?.value || ''
  const newPin  = document.getElementById('_po_new')?.value || ''
  const confirm = document.getElementById('_po_confirm')?.value || ''
  const err     = document.getElementById('_po_err')
  const user    = window._appUser

  if(!oldPin){ err.textContent='⚠️ Masukkan PIN lama'; return }
  if(oldPin !== user.pin){ err.textContent='❌ PIN lama tidak cocok'; return }
  if(!newPin || newPin.length < 4){ err.textContent='⚠️ PIN baru minimal 4 digit'; return }
  if(newPin.length > 6){ err.textContent='⚠️ PIN maksimal 6 digit'; return }
  if(!/^[0-9]+$/.test(newPin)){ err.textContent='⚠️ PIN hanya boleh angka'; return }
  if(newPin !== confirm){ err.textContent='❌ Konfirmasi PIN tidak cocok'; return }
  if(newPin === '1234' || newPin === '0000' || newPin === '123456'){
    err.textContent='⚠️ PIN terlalu mudah ditebak, pilih PIN lain'; return
  }

  // PIN Owner disimpan HANYA di localStorage — tidak ke Firebase
  localStorage.setItem('ps_owner_pin', newPin)
  window._appUser.pin = newPin
  if(window._loginUsers[user.id]) window._loginUsers[user.id].pin = newPin
  try{ localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers)) }catch(e){}
  document.getElementById('_gantiPinOwnerOverlay')?.remove()
  showPopup({typeNotif:'success', message:'✅ PIN Owner berhasil diubah! (Tersimpan lokal, tidak ke cloud)'})
  addOperatorLog('owner', 'change_pin', user.username)
}

