function _ownerTambahOperator(){
  const username = document.getElementById('newOpUsername')?.value.trim()
  const pin = document.getElementById('newOpPin')?.value.trim()
  if(!username||username.length<3){ showPopup({typeNotif:'warning',message:'⚠️ Username minimal 3 karakter!'}); return }
  if(!pin||pin.length<4){ showPopup({typeNotif:'warning',message:'⚠️ PIN minimal 4 digit!'}); return }
  if(pin.length>6){ showPopup({typeNotif:'warning',message:'⚠️ PIN maksimal 6 digit!'}); return }
  const exists = Object.values(window._loginUsers||{}).find(u=>u.username?.toLowerCase()===username.toLowerCase())
  if(exists){ showPopup({typeNotif:'warning',message:'⚠️ Username sudah dipakai!'}); return }
  const id = 'op_'+Date.now()
  const newOp = { id, username, pin, role:'operator', aktif:true, createdAt:Date.now(), addedBy:window._appUser?.id||'owner' }
  if(_fbDb) _fbDb.ref('users/'+id).set(newOp)
  window._loginUsers[id] = newOp
  localStorage.setItem('_cached_users', JSON.stringify(window._loginUsers))
  showPopup({typeNotif:'success',message:`✅ Operator "${username}" berhasil ditambahkan!`})
  renderOperatorManagePage()
}

function _ownerResetPinOp(id, username){
  _showPrompt(`Reset PIN untuk "${username}"?\nMasukkan PIN baru:`, (newPin)=>{
    if(!newPin||newPin.length<4){ showPopup({typeNotif:'warning',message:'⚠️ PIN minimal 4 digit!'}); return }
    if(newPin.length>6){ showPopup({typeNotif:'warning',message:'⚠️ PIN maksimal 6 digit!'}); return }
    if(_fbDb) _fbDb.ref('users/'+id+'/pin').set(newPin)
    if(window._loginUsers[id]) window._loginUsers[id].pin = newPin
    showPopup({typeNotif:'success',message:`✅ PIN "${username}" berhasil direset!`})
    renderOperatorManagePage()
  })
}

function _ownerToggleOpAktif(id, currentlyAktif){
  const user = window._loginUsers[id]
  const newVal = !currentlyAktif
  if(_fbDb) _fbDb.ref('users/'+id+'/aktif').set(newVal)
  if(window._loginUsers[id]) window._loginUsers[id].aktif = newVal
  showPopup({typeNotif:newVal?'success':'warning',message:`${newVal?'✅ Operator diaktifkan':'🚫 Operator dinonaktifkan'}`})
  renderOperatorManagePage()
}

function _ownerHapusOp(id, username){
  _showConfirm(`Hapus operator "${username}"?\nAkun ini akan dihapus permanen.`,()=>{
    if(_fbDb) _fbDb.ref('users/'+id).remove()
    delete window._loginUsers[id]
    showPopup({typeNotif:'success',message:`🗑️ Operator "${username}" dihapus`})
    renderOperatorManagePage()
  })
}

function _showPrompt(msg, callback){
  const val = window.prompt ? window.prompt(msg) : null
  if(val !== null) callback(val)
}

function renderOperatorManagePage_refresh(){
  if(!_fbDb) return
  _fbDb.ref('users').once('value', snap=>{
    window._loginUsers = snap.val()||{}
    renderOperatorManagePage()
  })
}

function _hapusSlotTourn(id, nama){
  _showConfirm(
    `Hapus slot turnamen "${nama}"?\nSemua data peserta juga akan dihapus.`,
    () => {
      tournSlots = tournSlots.filter(s => s.id !== id)
      tournPendaftar = tournPendaftar.filter(p => p.slotId !== id)
      saveTournSlots()
      saveTournPendaftar()

      if(_fbDb){
        // Hapus bracket dari Firebase
        _fbDb.ref("tournamentBracket/" + id).remove()

        // Hapus tournStarted jika slot ini yang sedang berjalan
        _fbDb.ref("settings/tournStarted").once("value", snap => {
          const started = snap.val()
          if(started && started.slotId === id){
            _fbDb.ref("settings/tournStarted").remove()
          }
        })

        // Hapus deadline countdown & maxPerWA jika tidak ada slot lain yang buka
        const slotsSisa = tournSlots.filter(s => s.status === "buka")
        if(slotsSisa.length === 0){
          // Tidak ada slot lain → hapus deadline dan maxPerWA dari Firebase
          _fbDb.ref("settings/tournDeadline").remove()
          _fbDb.ref("settings/tournMaxPerWA").remove()
        } else {
          // Pakai deadline dari slot yang paling dekat
          const slotDenganDeadline = slotsSisa.filter(s => s.deadlineISO)
          if(slotDenganDeadline.length > 0){
            slotDenganDeadline.sort((a,b) => new Date(a.deadlineISO) - new Date(b.deadlineISO))
            _fbDb.ref("settings/tournDeadline").set(slotDenganDeadline[0].deadlineISO)
            _fbDb.ref("settings/tournMaxPerWA").set(slotDenganDeadline[0].maxPerWA || 1)
          } else {
            _fbDb.ref("settings/tournDeadline").remove()
          }
        }
      }

      showPopup({typeNotif:"success", message:"🗑️ Slot turnamen berhasil dihapus"})
      renderTournSlotPage()
    }
  )
}

function _piliMaxWaTourn(n, btn){
  document.getElementById("ts_maxwa").value = n
  document.querySelectorAll("#maxWaPicker button").forEach(b => {
    b.style.background = "rgba(0,0,0,0.25)"
    b.style.border = "1px solid rgba(255,204,0,0.15)"
    b.style.color = "rgba(168,200,240,0.55)"
  })
  btn.style.background = "rgba(255,204,0,0.20)"
  btn.style.border = "2px solid rgba(255,204,0,0.60)"
  btn.style.color = "#ffcc00"
}

function _simpanPengaturanTourn(){
  const deadline = document.getElementById("ts_deadline")?.value || ""
  const rules    = document.getElementById("ts_rules")?.value.trim() || ""
  const maxPerWA = parseInt(document.getElementById("ts_maxwa")?.value || "2")
  const panduan  = document.getElementById("ts_panduan")?.value.trim() || ""
  if(!_fbDb){
    showPopup({typeNotif:"warning", message:"⚠️ Firebase belum terhubung"}); return
  }
  _fbDb.ref("settings/tournDeadline").set(deadline || null)
  _fbDb.ref("settings/tournRules").set(rules || null)
  _fbDb.ref("settings/tournMaxPerWA").set(maxPerWA)
  _fbDb.ref("settings/tournPanduan").set(panduan || null)
  localStorage.setItem("tourn_maxPerWA", maxPerWA.toString())
  showPopup({typeNotif:"success", message:"✅ Pengaturan turnamen disimpan!"})
}

