function pilihStatusBayarTourn(status, btn){
  document.getElementById("td_bayar_status").value = status
  const btns = {
    belum: document.getElementById("btnBelumBayar"),
    dp:    document.getElementById("btnDPBayar"),
    lunas: document.getElementById("btnLunasBayar")
  }
  const styles = {
    belum: "background:rgba(255,204,0,0.15);border:2px solid rgba(255,204,0,0.50);color:#ffcc00;",
    dp:    "background:rgba(0,245,255,0.15);border:2px solid rgba(0,245,255,0.50);color:#00f5ff;",
    lunas: "background:rgba(0,255,136,0.15);border:2px solid rgba(0,255,136,0.50);color:#00ff88;"
  }
  const offStyle = "background:rgba(0,0,0,0.25);border:1px solid rgba(255,255,255,0.10);color:rgba(168,200,240,0.40);"
  Object.keys(btns).forEach(k => {
    if(btns[k]) btns[k].style.cssText = `padding:10px 6px;border-radius:12px;font-family:'Orbitron',monospace;font-size:9px;font-weight:700;cursor:pointer;${k===status?styles[k]:offStyle}`
  })
}
// Legacy alias
function pilihBayarTourn(bayar, btn){ pilihStatusBayarTourn(bayar?'lunas':'belum', btn) }

function _daftarManualTourn(slotId){
  const s = _getTournSlot(slotId)
  const nama  = document.getElementById("td_nama")?.value.trim()
  const waRaw = document.getElementById("td_wa")?.value.trim().replace(/[\s\-().]/g,"")
  if(!nama){ showPopup({typeNotif:"warning",message:"⚠️ Nama peserta wajib diisi!"}); return }
  if(!waRaw||waRaw.length<8){ showPopup({typeNotif:"warning",message:"⚠️ Nomor WA tidak valid!"}); return }

  const noWA = waRaw.startsWith("0") ? "62"+waRaw.slice(1) : waRaw.startsWith("62") ? waRaw : "62"+waRaw

  // Cek slot penuh
  const list = _getTournPendaftar(slotId)
  if(list.length >= s.maxSlot){
    showPopup({typeNotif:"warning",message:"⚠️ Slot sudah penuh!"}); return
  }

  // Proteksi max pendaftaran per WA (sama dengan setting di pengaturan)
  const maxPerWA = parseInt(localStorage.getItem("tourn_maxPerWA") || "0")
  if(maxPerWA > 0){
    let totalWA = 0
    tournPendaftar.forEach(p => { if(p.noWA === noWA) totalWA++ })
    if(totalWA >= maxPerWA){
      showPopup({typeNotif:"warning", message:`⚠️ Nomor WA +${noWA} sudah terdaftar ${totalWA}x\nMaks ${maxPerWA}x per nomor WA.`})
      return
    }
  }

  const bayarStatus = document.getElementById("td_bayar_status")?.value || "belum"
  const bayar = bayarStatus === "lunas"
  const newP = { id:"TP"+Date.now(), slotId, nama, noWA, bayar, bayarStatus, daftarAt:Date.now(), sumber:"manual" }
  tournPendaftar.push(newP)

  // Auto set penuh hanya jika jumlah DISETUJUI sudah mencapai maxSlot
  const _accCount = _getTournPendaftar(slotId).filter(p => p.status === 'disetujui').length
  if(s.maxSlot > 0 && _accCount >= s.maxSlot) s.status = "penuh"

  saveTournSlots()
  saveTournPendaftar()
  showPopup({typeNotif:"success", message:`✅ ${nama} berhasil didaftarkan!`})
  renderTournPesertaPage(slotId)
}
