(function(){
  'use strict';

  var _exitDialogEl = null;

  // Push satu entry awal agar back button bisa dicegat
  window.history.pushState({_astro: 1}, '');

  window.addEventListener('popstate', function(){
    // Jika dialog keluar sedang tampil, tutup saja (user batalkan)
    if(_exitDialogEl && _exitDialogEl.style.display !== 'none'){
      _hideExitDialog();
      window.history.pushState({_astro: 1}, '');
      return;
    }
    var handled = _handleBack();
    if(handled){
      window.history.pushState({_astro: 1}, '');
    }
  });

  function _el(id){ return document.getElementById(id); }

  function _isVisible(id){
    var el = _el(id);
    return el && el.style.display !== 'none' && el.style.display !== '';
  }

  function _inDom(id){ return !!_el(id); }

  function _hasClass(id, cls){
    var el = _el(id);
    return el && el.classList.contains(cls);
  }

  function _handleBack(){

    // ── 1. Super Admin Popup ──────────────────────────────
    if(_isVisible('superAdminPopup')){
      if(typeof closeSuperAdminPopup === 'function') closeSuperAdminPopup();
      return true;
    }

    // ── 2. Tournament Score Modal ─────────────────────────
    if(_isVisible('tournScoreModal')){
      if(typeof closeTournScoreModal === 'function') closeTournScoreModal();
      return true;
    }

    // ── 3. Hutang Modal ───────────────────────────────────
    if(_inDom('hutangModalOverlay')){
      var hm = _el('hutangModalOverlay');
      if(hm) hm.remove();
      return true;
    }

    // ── 4. Booking Modal ──────────────────────────────────
    if(_inDom('bookingModalOverlay')){
      var bm = _el('bookingModalOverlay');
      if(bm) bm.remove();
      return true;
    }

    // ── 5. Delete / Duplicate Modals ─────────────────────
    if(_isVisible('deleteModalHistory')){
      if(typeof closeDeleteModalHistory === 'function') closeDeleteModalHistory();
      return true;
    }
    if(_isVisible('deleteModalMinuman')){
      if(typeof closeDeleteModalMinuman === 'function') closeDeleteModalMinuman();
      return true;
    }
    if(_isVisible('duplicateModalMinuman')){
      if(typeof closeDuplicateModalMinuman === 'function') closeDuplicateModalMinuman();
      return true;
    }
    if(_isVisible('deleteModalMakanan')){
      if(typeof closeDeleteModalMakanan === 'function') closeDeleteModalMakanan();
      return true;
    }
    if(_isVisible('duplicateModalMakanan')){
      if(typeof closeDuplicateModalMakanan === 'function') closeDuplicateModalMakanan();
      return true;
    }

    // ── 6. Struk Modal ────────────────────────────────────
    if(_isVisible('strukModal')){
      if(typeof closeStrukModal === 'function') closeStrukModal();
      return true;
    }

    // ── 7. Popup / Menu Utama ─────────────────────────────
    var popupNotif = _el('popupNotif');
    if(popupNotif && popupNotif.style.display === 'flex'){
      if(typeof closePopup === 'function') closePopup();
      return true;
    }

    // ── 8. Sidebar ────────────────────────────────────────
    if(_hasClass('sidebar', 'open')){
      if(typeof closeSidebar === 'function') closeSidebar();
      return true;
    }

    // ── 9. Internal Page ──────────────────────────────────
    var pageView = _el('pageView');
    if(pageView && pageView.style.display === 'block'){
      if(typeof showDashboardView === 'function') showDashboardView();
      return true;
    }

    // ── 10. Dashboard → tampilkan dialog konfirmasi keluar ─
    _showExitDialog();
    return true;
  }

  // ── Dialog Konfirmasi Keluar ────────────────────────────
  function _showExitDialog(){
    if(!_exitDialogEl){
      _exitDialogEl = document.createElement('div');
      _exitDialogEl.id = '_astroExitDialog';
      _exitDialogEl.innerHTML = [
        '<div id="_astroExitBox" style="',
          'background:linear-gradient(160deg,#060a16,#0a0f20);',
          'border:1px solid rgba(0,245,255,0.25);',
          'border-radius:24px;',
          'padding:32px 28px 24px;',
          'width:88%;max-width:320px;',
          'text-align:center;',
          'box-shadow:0 0 0 1px rgba(0,245,255,0.06) inset,0 24px 60px rgba(0,0,0,0.80),0 0 40px rgba(0,245,255,0.06);',
          'position:relative;',
          'animation:_exitPop .22s cubic-bezier(.34,1.56,.64,1) both;',
        '">',
          '<div style="font-size:44px;margin-bottom:14px;">🚪</div>',
          '<div style="',
            'font-family:\'Orbitron\',monospace;font-size:13px;font-weight:700;',
            'letter-spacing:2px;color:#00f5ff;margin-bottom:10px;',
          '">KELUAR APLIKASI?</div>',
          '<div style="',
            'font-size:12px;color:rgba(168,200,240,0.65);',
            'line-height:1.7;margin-bottom:26px;',
          '">Yakin ingin menutup<br>Astrophile Billing PS?</div>',
          '<div style="display:flex;gap:12px;">',
            '<button id="_astroExitNo" style="',
              'flex:1;padding:13px 0;border-radius:14px;',
              'background:rgba(255,255,255,0.05);',
              'border:1px solid rgba(255,255,255,0.12);',
              'color:rgba(168,200,240,0.80);',
              'font-family:\'Orbitron\',monospace;font-size:10px;',
              'font-weight:700;letter-spacing:1.5px;cursor:pointer;',
            '">BATAL</button>',
            '<button id="_astroExitYes" style="',
              'flex:1;padding:13px 0;border-radius:14px;',
              'background:linear-gradient(135deg,rgba(255,30,80,0.22),rgba(200,0,50,0.15));',
              'border:1px solid rgba(255,30,80,0.35);',
              'color:#ff4d6d;',
              'font-family:\'Orbitron\',monospace;font-size:10px;',
              'font-weight:700;letter-spacing:1.5px;cursor:pointer;',
            '">KELUAR</button>',
          '</div>',
        '</div>',
        '<style>',
          '@keyframes _exitPop{from{opacity:0;transform:scale(.88)}to{opacity:1;transform:scale(1)}}',
        '</style>'
      ].join('');

      _exitDialogEl.style.cssText = [
        'position:fixed','inset:0','z-index:99999',
        'display:flex','align-items:center','justify-content:center',
        'background:rgba(2,5,12,0.75)',
        'backdrop-filter:blur(6px)',
        '-webkit-backdrop-filter:blur(6px)',
        'transition:opacity 0.2s ease'
      ].join(';');

      document.body.appendChild(_exitDialogEl);

      // Tombol Batal
      document.getElementById('_astroExitNo').addEventListener('click', function(){
        _hideExitDialog();
      });

      // Tombol Keluar — panggil Android bridge untuk finish() activity
      document.getElementById('_astroExitYes').addEventListener('click', function(){
        _hideExitDialog();
        setTimeout(function(){
          try { Android.exitApp(); } catch(e) { window.history.go(-99); }
        }, 120);
      });

      // Klik backdrop = batal
      _exitDialogEl.addEventListener('click', function(e){
        if(e.target === _exitDialogEl) _hideExitDialog();
      });
    }

    _exitDialogEl.style.display = 'flex';
    _exitDialogEl.style.opacity = '1';
  }

  function _hideExitDialog(){
    if(_exitDialogEl){
      _exitDialogEl.style.opacity = '0';
      setTimeout(function(){
        if(_exitDialogEl) _exitDialogEl.style.display = 'none';
      }, 200);
    }
  }

})();
