// ============================================================
// ESP32 DEVICE MONITORING — Realtime Firebase Listener
// Kirim heartbeat dari ESP32 ke Firebase: devices/tvN
// Data: { online, wifi_rssi, uptime, last_seen, tv_power_status, ip_address, hasSignal }
// ============================================================

window._esp32DeviceStatus = {}   // cache: { 1: {...}, 2: {...}, ... }
window._esp32DeviceListeners = {} // track aktif listener per TV
window._esp32OfflineTimers = {}   // timer cek last_seen per TV

// ── Ambil status dari cache ──────────────────────────────────
function getDeviceStatus(tvNum){
  return window._esp32DeviceStatus[tvNum] || null
}

// ── Tentukan badge berdasarkan data device ───────────────────
function _calcDeviceBadge(tvNum){
  const d = window._esp32DeviceStatus[tvNum]
  if(!d) return { dot:'⚫', color:'rgba(168,200,240,0.25)', label:'?', title:'Belum ada data' }

  const now     = Date.now()
  const lastSeen = d.last_seen || 0
  const stale   = (now - lastSeen) > 15000  // > 15 detik = offline

  if(stale || d.online === false){
    return { dot:'🔴', color:'#ff4d6d', label:'OFFLINE', title:'Terakhir terlihat: '+(lastSeen?(Math.round((now-lastSeen)/1000)+'s lalu'):'tidak diketahui') }
  }
  const rssi = typeof d.wifi_rssi === 'number' ? d.wifi_rssi : -100
  if(rssi < -75){
    return { dot:'🟡', color:'#ffcc00', label:'WEAK WiFi', title:'RSSI: '+rssi+' dBm' }
  }
  return { dot:'🟢', color:'#00ff88', label:'ONLINE', title:'RSSI: '+rssi+' dBm · IP: '+(d.ip_address||'-') }
}

// ── Render / update badge di TV card ────────────────────────
function _updateDeviceBadge(tvNum){
  const el = document.getElementById('esp32Badge'+tvNum)
  if(!el) return
  const b = _calcDeviceBadge(tvNum)
  el.textContent = b.dot
  el.title       = b.label + ' · ' + b.title
  el.style.color = b.color
}

// ── Update semua badge (dipanggil setiap 3 detik) ────────────
function _refreshAllDeviceBadges(){
  for(let i = 1; i <= (window.units || 20); i++){
    _updateDeviceBadge(i)
  }
}

// ── Inisialisasi listener Firebase realtime per TV ───────────
function initDeviceMonitoring(){
  if(!window._fbDb){ return }

  const totalTV = window.units || parseInt(localStorage.getItem('ps_total_units')||'0') || 10

  for(let n = 1; n <= totalTV; n++){
    // Hindari double-listener
    if(window._esp32DeviceListeners[n]) continue

    ;(function(tvNum){
      const ref = window._fbDb.ref('devices/tv' + tvNum)
      const listener = ref.on('value', snap => {
        const data = snap.val()
        if(!data){ delete window._esp32DeviceStatus[tvNum]; _updateDeviceBadge(tvNum); return }
        window._esp32DeviceStatus[tvNum] = data
        _updateDeviceBadge(tvNum)
      })
      window._esp32DeviceListeners[tvNum] = listener
    })(n)
  }

  // Polling stale-check setiap 3 detik (last_seen bisa stale walau Firebase nyambung)
  if(!window._esp32BadgeInterval){
    window._esp32BadgeInterval = setInterval(_refreshAllDeviceBadges, 3000)
  }
}

// ── Hentikan semua listener (misalnya saat logout) ───────────
function stopDeviceMonitoring(){
  if(!window._fbDb) return
  const totalTV = window.units || 10
  for(let n = 1; n <= totalTV; n++){
    if(window._esp32DeviceListeners[n]){
      window._fbDb.ref('devices/tv'+n).off('value', window._esp32DeviceListeners[n])
      delete window._esp32DeviceListeners[n]
    }
  }
  if(window._esp32BadgeInterval){ clearInterval(window._esp32BadgeInterval); window._esp32BadgeInterval = null }
}

// ── Inject badge ke TV card header setelah DOM siap ─────────
// Dipanggil setelah buildCards() selesai render card
function injectDeviceBadges(){
  const totalTV = window.units || 10
  for(let i = 1; i <= totalTV; i++){
    if(document.getElementById('esp32Badge'+i)) continue  // sudah ada
    const titleEl = document.querySelector('#card'+i+' .tv-title')
    if(!titleEl) continue

    const badge = document.createElement('span')
    badge.id    = 'esp32Badge'+i
    badge.title = 'Status ESP32 TV '+i+' — klik untuk detail'
    badge.style.cssText = 'font-size:10px;cursor:pointer;margin-left:6px;vertical-align:middle;transition:color 0.5s;'
    badge.textContent   = '⚫'
    badge.onclick = (e) => { e.stopPropagation(); showDeviceDetail(i) }
    titleEl.appendChild(badge)
    _updateDeviceBadge(i)
  }
}

// ── Patch buildCards agar badge ter-inject otomatis ─────────
;(function(){
  const _origBuildCards = window.buildCards
  if(typeof _origBuildCards === 'function'){
    window.buildCards = function(){
      _origBuildCards.apply(this, arguments)
      setTimeout(()=>{ injectDeviceBadges(); initDeviceMonitoring() }, 80)
    }
  } else {
    // Fallback: observasi DOM sampai .card pertama muncul
    const obs = new MutationObserver(() => {
      if(document.querySelector('.card .tv-title')){
        obs.disconnect()
        injectDeviceBadges()
        initDeviceMonitoring()
      }
    })
    obs.observe(document.body, { childList:true, subtree:true })
  }
})()

// ── Hook ke _initFirebase agar monitoring mulai otomatis ─────
;(function(){
  const _origInit = window._initFirebase
  if(typeof _origInit === 'function'){
    window._initFirebase = function(){
      _origInit.apply(this, arguments)
      setTimeout(initDeviceMonitoring, 1500)
    }
  }
})()

// ── Helper: tampilkan detail status device saat badge diklik ─
function showDeviceDetail(tvNum){
  const d = window._esp32DeviceStatus[tvNum]
  const b = _calcDeviceBadge(tvNum)
  if(!d){
    showToast('⚫ ESP32 TV '+tvNum+': belum ada data heartbeat')
    return
  }
  const now    = Date.now()
  const lastSec = d.last_seen ? Math.round((now - d.last_seen)/1000) : '?'
  const uptimeSec = d.uptime || 0
  const uptimeStr = Math.floor(uptimeSec/3600)+'j '+(Math.floor((uptimeSec%3600)/60))+'m'
  showToast(
    b.dot+' TV '+tvNum+' · '+b.label+'\n'+
    '📶 RSSI: '+(d.wifi_rssi||'-')+' dBm\n'+
    '🌐 IP: '+(d.ip_address||'-')+'\n'+
    '⏱ Uptime: '+uptimeStr+'\n'+
    '📺 TV Power: '+(d.tv_power_status?'ON':'OFF')+'\n'+
    '📡 IR Signal: '+(d.hasSignal?'✅':'❌')+'\n'+
    '🕐 Last seen: '+lastSec+'s lalu',
    5000
  )
}

